-- Respiratory System question bank: exactly 750 hand-written NCLEX-style
-- single-best-answer questions, 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Respiratory System/ARDS.html
--   Notes/Respiratory System/Asthma.html
--   Notes/Respiratory System/COPD.html
--   Notes/Respiratory System/Chronic-Bronchitis.html
--   Notes/Respiratory System/Emphysema.html
--   Notes/Respiratory System/Hemothorax-and-Pneumothorax.html
--   Notes/Respiratory System/Incentive-Spirometry-Pulmonary-Hygiene.html
--   Notes/Respiratory System/Mask-Types-and-Respiratory-System.html
--   Notes/Respiratory System/Physiology-of-Breathing.html
--   Notes/Respiratory System/Pleural-Effusion.html
--   Notes/Respiratory System/Pneumonia.html
--   Notes/Respiratory System/Pulmonary-Embolism.html
--   Notes/Respiratory System/Sleep-Apnea.html
--   Notes/Respiratory System/Tracheostomy.html
--   Notes/Respiratory System/Tuberculosis.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (750) exist after insert.
BEGIN;

CREATE TEMP TABLE _resp_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _resp_sources (source_key, source_path, category) VALUES
  ('ards', 'Notes/Respiratory System/ARDS.html', 'Respiratory System NCLEX seed v1 - ARDS'),
  ('asthma', 'Notes/Respiratory System/Asthma.html', 'Respiratory System NCLEX seed v1 - asthma'),
  ('copd', 'Notes/Respiratory System/COPD.html', 'Respiratory System NCLEX seed v1 - COPD'),
  ('bronchitis', 'Notes/Respiratory System/Chronic-Bronchitis.html', 'Respiratory System NCLEX seed v1 - chronic bronchitis'),
  ('emphysema', 'Notes/Respiratory System/Emphysema.html', 'Respiratory System NCLEX seed v1 - emphysema'),
  ('hemo_pneumo', 'Notes/Respiratory System/Hemothorax-and-Pneumothorax.html', 'Respiratory System NCLEX seed v1 - hemothorax and pneumothorax'),
  ('spirometry', 'Notes/Respiratory System/Incentive-Spirometry-Pulmonary-Hygiene.html', 'Respiratory System NCLEX seed v1 - incentive spirometry and pulmonary hygiene'),
  ('masks', 'Notes/Respiratory System/Mask-Types-and-Respiratory-System.html', 'Respiratory System NCLEX seed v1 - oxygen delivery and mask types'),
  ('physiology', 'Notes/Respiratory System/Physiology-of-Breathing.html', 'Respiratory System NCLEX seed v1 - physiology of breathing'),
  ('effusion', 'Notes/Respiratory System/Pleural-Effusion.html', 'Respiratory System NCLEX seed v1 - pleural effusion'),
  ('pneumonia', 'Notes/Respiratory System/Pneumonia.html', 'Respiratory System NCLEX seed v1 - pneumonia'),
  ('pe', 'Notes/Respiratory System/Pulmonary-Embolism.html', 'Respiratory System NCLEX seed v1 - pulmonary embolism'),
  ('sleep_apnea', 'Notes/Respiratory System/Sleep-Apnea.html', 'Respiratory System NCLEX seed v1 - sleep apnea'),
  ('trach', 'Notes/Respiratory System/Tracheostomy.html', 'Respiratory System NCLEX seed v1 - tracheostomy'),
  ('tb', 'Notes/Respiratory System/Tuberculosis.html', 'Respiratory System NCLEX seed v1 - tuberculosis');

CREATE TEMP TABLE _resp_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _resp_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'respiratory system'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Respiratory System"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'respiratory system'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _resp_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Respiratory System subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Respiratory System points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _resp_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Respiratory seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _resp_seed_map) <> 15 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 15 note mappings, found %.',
      (SELECT count(*) FROM _resp_seed_map);
  END IF;

  INSERT INTO _resp_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _resp_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, false, v.display_order, 1, true
  FROM (VALUES
  ('ards', 1, 'A client with sepsis is receiving high-flow oxygen through a nonrebreather mask. Despite increasing the oxygen concentration, the client''s oxygen saturation remains at 84%. Which finding is the most specific indicator that the client is developing ARDS?', '[{"id": "a", "text": "Crackles heard in the lung bases"}, {"id": "b", "text": "Hypoxemia that does not improve with oxygen"}, {"id": "c", "text": "Heart rate increasing to 112/min"}, {"id": "d", "text": "Respiratory rate increasing to 28/min"}]'::jsonb, '["b"]', 'Refractory hypoxemia, low oxygen that does not improve despite high-flow oxygen, is the most specific sign of ARDS. Crackles, tachycardia, and tachypnea occur in ARDS but are not identified as its most specific sign.'),
  ('ards', 2, 'A nurse in a critical care unit is reviewing the histories of four clients. Which condition is the most common cause of ARDS overall?', '[{"id": "a", "text": "Pneumonia"}, {"id": "b", "text": "Pancreatitis"}, {"id": "c", "text": "Sepsis"}, {"id": "d", "text": "Burns"}]'::jsonb, '["c"]', 'Sepsis is the number one most common cause of ARDS overall. Pneumonia is the most common direct (pulmonary) cause, but not the most common cause overall.'),
  ('ards', 3, 'A nurse is teaching a group of students about the causes of ARDS. Which cause should the nurse classify as a direct (pulmonary) cause?', '[{"id": "a", "text": "Aspiration of gastric contents"}, {"id": "b", "text": "Acute pancreatitis"}, {"id": "c", "text": "Massive blood transfusion"}, {"id": "d", "text": "Drug overdose"}]'::jsonb, '["a"]', 'Aspiration of gastric contents directly injures the lung and is a direct (pulmonary) cause. Pancreatitis, massive blood transfusion, and drug overdose are indirect (extrapulmonary) causes.'),
  ('ards', 4, 'A client is admitted with ARDS. Which item in the client''s history represents an indirect (extrapulmonary) cause of ARDS?', '[{"id": "a", "text": "Near-drowning"}, {"id": "b", "text": "Inhalation injury"}, {"id": "c", "text": "Pulmonary contusion"}, {"id": "d", "text": "Extensive burns"}]'::jsonb, '["d"]', 'Burns are listed among the indirect (extrapulmonary) causes of ARDS. Near-drowning, inhalation injury, and pulmonary contusion are direct (pulmonary) causes.'),
  ('ards', 5, 'Which direct (pulmonary) cause of ARDS does the nurse recognize as the most common?', '[{"id": "a", "text": "Near-drowning"}, {"id": "b", "text": "Pneumonia"}, {"id": "c", "text": "Inhalation injury"}, {"id": "d", "text": "Aspiration of gastric contents"}]'::jsonb, '["b"]', 'Pneumonia is the most common direct cause of ARDS. Near-drowning, inhalation injury, and aspiration are also direct causes but are not the most common.'),
  ('ards', 6, 'The family of a client with ARDS asks why the client''s oxygen level stays low even on high levels of oxygen. The nurse''s explanation is based on which underlying process?', '[{"id": "a", "text": "Mucus plugs are blocking the large airways"}, {"id": "b", "text": "Inflammation narrows the bronchial passages"}, {"id": "c", "text": "Fluid leaks from the capillaries into the alveoli"}, {"id": "d", "text": "Air becomes trapped in overinflated alveoli"}]'::jsonb, '["c"]', 'In ARDS, an inflammatory response causes fluid to leak from capillaries into the alveoli; the fluid-filled alveoli produce refractory hypoxemia. The other options do not describe the ARDS process.'),
  ('ards', 7, 'A client is on day 3 after the onset of ARDS. Which finding does the nurse expect during this phase?', '[{"id": "a", "text": "Permanent scar tissue causing severe lung stiffness"}, {"id": "b", "text": "Proliferation of type II pneumocytes as the lung repairs"}, {"id": "c", "text": "Fibroblast formation with gradual lung improvement"}, {"id": "d", "text": "Bilateral infiltrates on chest X-ray with alveolar collapse"}]'::jsonb, '["d"]', 'Days 1–7 are the exudative phase, in which protein-rich fluid leaks into the alveoli, alveoli collapse, and bilateral infiltrates appear on X-ray. Type II pneumocyte proliferation and fibroblasts occur in the proliferative phase, and permanent scarring occurs in the fibrotic phase.'),
  ('ards', 8, 'A client is on day 10 of ARDS. Which description best matches the phase the client is most likely in?', '[{"id": "a", "text": "Capillary injury allows fluid and protein to leak into alveoli"}, {"id": "b", "text": "Type II pneumocytes proliferate and fibroblasts form"}, {"id": "c", "text": "Permanent fibrosis develops with severe lung stiffness"}, {"id": "d", "text": "Refractory hypoxemia first begins to develop"}]'::jsonb, '["b"]', 'Days 7–14 are the proliferative phase, when the lung begins repair, type II pneumocytes proliferate, and fibroblasts form. Capillary leak and the onset of refractory hypoxemia describe the exudative phase (days 1–7).'),
  ('ards', 9, 'A client has had ARDS for 3 weeks, and imaging shows permanent scar tissue in the lungs. The family asks what to expect. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"This phase has a poor outlook, and long-term ventilation may be needed.\""}, {"id": "b", "text": "\"This phase means the lungs are repairing, so recovery is expected soon.\""}, {"id": "c", "text": "\"This phase is the earliest stage, and the fluid will soon be absorbed.\""}, {"id": "d", "text": "\"This phase usually resolves once the lungs become more flexible.\""}]'::jsonb, '["a"]', 'The fibrotic phase (weeks 2–3+) involves permanent scar tissue, severe lung stiffness, a very poor prognosis, and possible long-term ventilation. Lung repair describes the proliferative phase, and fluid leakage describes the early exudative phase.'),
  ('ards', 10, 'A nurse is reviewing the progression of ARDS with a new graduate nurse. Which sequence correctly lists the phases of ARDS from earliest to latest?', '[{"id": "a", "text": "Proliferative, exudative, fibrotic"}, {"id": "b", "text": "Exudative, fibrotic, proliferative"}, {"id": "c", "text": "Exudative, proliferative, fibrotic"}, {"id": "d", "text": "Fibrotic, proliferative, exudative"}]'::jsonb, '["c"]', 'ARDS progresses from the exudative phase (days 1–7) to the proliferative phase (days 7–14) to the fibrotic phase (weeks 2–3+). The other sequences place the phases out of order.'),
  ('ards', 11, 'A mechanically ventilated client with ARDS requires increasingly high pressures to deliver each breath, and the provider describes the lungs as "stiff." The nurse recognizes this as which feature of ARDS?', '[{"id": "a", "text": "Increased functional residual capacity"}, {"id": "b", "text": "Decreased lung compliance"}, {"id": "c", "text": "Refractory hypoxemia"}, {"id": "d", "text": "Widespread atelectasis"}]'::jsonb, '["b"]', 'Decreased lung compliance means the lungs are stiff and hard to ventilate. Refractory hypoxemia refers to oxygen that does not improve, and PEEP increases functional residual capacity rather than ARDS causing it.'),
  ('ards', 12, 'A client admitted with pancreatitis suddenly becomes restless and confused and is pulling at the oxygen tubing. How should the nurse interpret this change?', '[{"id": "a", "text": "A late sign of tissue hypoxia"}, {"id": "b", "text": "An early sign of tissue hypoxia"}, {"id": "c", "text": "An expected reaction to hospitalization"}, {"id": "d", "text": "A sign of improving oxygenation"}]'::jsonb, '["b"]', 'Restlessness and confusion are early signs of hypoxia. Late signs of hypoxia are bradycardia and hypotension, so this change should not be dismissed as expected or as late.'),
  ('ards', 13, 'A nurse auscultates the lungs of a client with ARDS. Which finding does the nurse expect?', '[{"id": "a", "text": "Absent breath sounds on one side only"}, {"id": "b", "text": "Clear breath sounds in all lung fields"}, {"id": "c", "text": "Crackles heard on one side only"}, {"id": "d", "text": "Crackles heard bilaterally"}]'::jsonb, '["d"]', 'Bilateral crackles (rales) are an expected auscultation finding in ARDS. ARDS involves bilateral, diffuse changes, so one-sided findings or clear lungs are not expected.'),
  ('ards', 14, 'A nurse is monitoring a client with ARDS. Which assessment finding indicates late, severe deterioration?', '[{"id": "a", "text": "Cyanosis"}, {"id": "b", "text": "Restlessness"}, {"id": "c", "text": "Confusion"}, {"id": "d", "text": "Anxiety about breathing"}]'::jsonb, '["a"]', 'Cyanosis is identified as a late, severe sign in ARDS. Restlessness and confusion are early hypoxia signs.'),
  ('ards', 15, 'A client in the early stage of ARDS is breathing rapidly. Arterial blood gases show a decreased PaO₂, a decreased PaCO₂, and an alkalotic pH. How should the nurse interpret these results?', '[{"id": "a", "text": "Late respiratory acidosis from fatigue"}, {"id": "b", "text": "Metabolic acidosis from poor perfusion"}, {"id": "c", "text": "Early respiratory alkalosis from hyperventilation"}, {"id": "d", "text": "Normal acid-base balance with hypoxemia"}]'::jsonb, '["c"]', 'Early ARDS produces respiratory alkalosis because the hyperventilating client blows off CO₂, along with a low PaO₂. Respiratory acidosis develops later as the client tires and CO₂ builds up.'),
  ('ards', 16, 'A nurse is caring for a client who has had ARDS for several days and appears increasingly fatigued. Which arterial blood gas change indicates the client is tiring?', '[{"id": "a", "text": "Falling PaCO₂ with respiratory alkalosis"}, {"id": "b", "text": "Rising PaCO₂ with respiratory acidosis"}, {"id": "c", "text": "Rising PaO₂ with a normal pH"}, {"id": "d", "text": "Falling PaCO₂ with a rising PaO₂"}]'::jsonb, '["b"]', 'Late in ARDS, CO₂ builds up as the client tires, causing respiratory acidosis. A falling PaCO₂ with respiratory alkalosis is the early pattern of hyperventilation.'),
  ('ards', 17, 'A client with severe dyspnea has a chest X-ray. Which finding supports a diagnosis of ARDS rather than heart failure (CHF)?', '[{"id": "a", "text": "Bilateral diffuse infiltrates with a normal-sized heart"}, {"id": "b", "text": "Bilateral diffuse infiltrates with an enlarged heart"}, {"id": "c", "text": "A single lobe of consolidation with a normal heart"}, {"id": "d", "text": "Clear lung fields with an enlarged heart"}]'::jsonb, '["a"]', 'ARDS shows "white-out" bilateral diffuse infiltrates with no cardiomegaly, and the absence of cardiomegaly differentiates it from CHF. An enlarged heart would point away from ARDS.'),
  ('ards', 18, 'A client receiving 50% oxygen (FiO₂ 0.50) has a PaO₂ of 80 mmHg. Based on the PaO₂/FiO₂ ratio, how should the nurse classify the severity of this client''s ARDS?', '[{"id": "a", "text": "Does not meet ARDS criteria"}, {"id": "b", "text": "Mild ARDS"}, {"id": "c", "text": "Moderate ARDS"}, {"id": "d", "text": "Severe ARDS"}]'::jsonb, '["c"]', 'The P/F ratio is 80 ÷ 0.50 = 160, which is below 200 but not below 100, indicating moderate ARDS. Mild ARDS is a P/F ratio below 300, and severe ARDS is below 100.'),
  ('ards', 19, 'A nurse is reviewing the PaO₂/FiO₂ (P/F) ratios of four ventilated clients. Which ratio indicates severe ARDS?', '[{"id": "a", "text": "280"}, {"id": "b", "text": "220"}, {"id": "c", "text": "150"}, {"id": "d", "text": "85"}]'::jsonb, '["d"]', 'A P/F ratio below 100 indicates severe ARDS. A ratio of 150 falls in the moderate range (below 200), and 280 falls in the mild range (below 300).'),
  ('ards', 20, 'A provider suspects ARDS in a client with worsening dyspnea. Which combination of diagnostic tests best supports the diagnosis?', '[{"id": "a", "text": "Arterial blood gas and chest X-ray"}, {"id": "b", "text": "Sputum culture and chest X-ray"}, {"id": "c", "text": "Arterial blood gas and sputum culture"}, {"id": "d", "text": "Complete blood count and pulse oximetry"}]'::jsonb, '["a"]', 'The best diagnostics for ARDS are an ABG plus a chest X-ray showing bilateral white-out with no cardiomegaly. The other combinations omit one of these two key tests.'),
  ('ards', 21, 'A client with ARDS is intubated and placed on mechanical ventilation. Which tidal volume setting does the nurse anticipate?', '[{"id": "a", "text": "Low tidal volume of 6 mL/kg"}, {"id": "b", "text": "High tidal volume of 12 mL/kg"}, {"id": "c", "text": "High tidal volume of 15 mL/kg"}, {"id": "d", "text": "Moderate tidal volume of 10 mL/kg"}]'::jsonb, '["a"]', 'ARDS is managed with intubation and mechanical ventilation using a low tidal volume of 6 mL/kg plus PEEP. Higher tidal volumes raise ventilator pressures, which risks barotrauma.'),
  ('ards', 22, 'A client with ARDS on mechanical ventilation is prescribed a continuous sedative infusion. The nurse understands that the primary purpose of sedation for this client is to:', '[{"id": "a", "text": "Reduce fluid in the lungs"}, {"id": "b", "text": "Decrease inflammation in the alveoli"}, {"id": "c", "text": "Decrease oxygen demand"}, {"id": "d", "text": "Open collapsed dorsal alveoli"}]'::jsonb, '["c"]', 'Sedatives are used in ARDS to decrease oxygen demand. Diuretics reduce lung fluid, corticosteroids reduce inflammation, and prone positioning opens dorsal alveoli.'),
  ('ards', 23, 'A nurse is reviewing ARDS medications with a nursing student. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"Diuretics are given to decrease fluid in the lungs.\""}, {"id": "b", "text": "\"Corticosteroids are given to decrease inflammation.\""}, {"id": "c", "text": "\"Sedatives are given to decrease oxygen demand.\""}, {"id": "d", "text": "\"Paralytics are given to every client with mild ARDS.\""}]'::jsonb, '["d"]', 'Paralytics are reserved for severe cases of ARDS, so giving them to every mild case is incorrect. The statements about diuretics, corticosteroids, and sedatives are accurate.'),
  ('ards', 24, 'A client with ARDS has bilateral crackles and a positive fluid balance. Which IV fluid approach does the nurse anticipate?', '[{"id": "a", "text": "Liberal IV fluid boluses to raise oxygenation"}, {"id": "b", "text": "Conservative IV fluids to prevent more alveolar fluid"}, {"id": "c", "text": "Rapid IV fluid boluses to improve lung compliance"}, {"id": "d", "text": "Continuous high-rate IV fluids to thin secretions"}]'::jsonb, '["b"]', 'ARDS care includes avoiding fluid overload with a conservative IV fluid strategy, which prevents more fluid from entering the alveoli. Liberal or rapid fluids would add to alveolar fluid.'),
  ('ards', 25, 'A client was intubated for ARDS yesterday. When should the nurse anticipate that enteral nutrition will be started?', '[{"id": "a", "text": "After the client is extubated"}, {"id": "b", "text": "After the first full week of ventilation"}, {"id": "c", "text": "Once sedation has been fully discontinued"}, {"id": "d", "text": "Within 24–48 hours of admission"}]'::jsonb, '["d"]', 'Enteral nutrition should be started early, within 24–48 hours. Delaying feeding until extubation, after a week, or after sedation stops would allow muscle wasting.'),
  ('ards', 26, 'The spouse of a ventilated client with ARDS asks why tube feedings were started so soon. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Early feeding helps decrease the fluid in the lungs.\""}, {"id": "b", "text": "\"Early feeding helps open the collapsed air sacs.\""}, {"id": "c", "text": "\"Early feeding prevents muscle wasting and protects the gut.\""}, {"id": "d", "text": "\"Early feeding lowers the amount of oxygen the body uses.\""}]'::jsonb, '["c"]', 'Early enteral nutrition prevents muscle wasting and maintains gut integrity. Decreasing lung fluid is the role of diuretics and a conservative fluid strategy, and opening collapsed alveoli is the role of PEEP and prone positioning.'),
  ('ards', 27, 'A nursing assistant plans to get a client with ARDS out of bed and walk the client in the hallway to "build strength." Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"Activity should be restricted to minimize oxygen demand.\""}, {"id": "b", "text": "\"Walking will help open the collapsed alveoli in the lungs.\""}, {"id": "c", "text": "\"Walking is safe as long as the client keeps oxygen on.\""}, {"id": "d", "text": "\"Activity should be increased to prevent muscle wasting.\""}]'::jsonb, '["a"]', 'ARDS care includes restricting activity to minimize oxygen demand and prevent further injury. Muscle wasting is prevented with early enteral nutrition, not increased activity.'),
  ('ards', 28, 'The provider increases the positive end-expiratory pressure (PEEP) for a client with ARDS. The nurse understands that the primary purpose of PEEP is to:', '[{"id": "a", "text": "Increase the size of each delivered breath"}, {"id": "b", "text": "Keep alveoli open at the end of exhalation"}, {"id": "c", "text": "Increase the respiratory rate of the client"}, {"id": "d", "text": "Decrease the pressure in the airways"}]'::jsonb, '["b"]', 'PEEP keeps alveoli open at the end of exhalation, preventing alveolar collapse (atelectasis). It is not a tidal volume or rate setting.'),
  ('ards', 29, 'After PEEP is increased for a client with ARDS, the provider lowers the FiO₂. The nurse understands that this change is possible because PEEP:', '[{"id": "a", "text": "Maintains oxygenation at a lower FiO₂, reducing oxygen toxicity"}, {"id": "b", "text": "Raises tidal volume so less oxygen concentration is needed"}, {"id": "c", "text": "Lowers the client''s oxygen demand by acting as a sedative"}, {"id": "d", "text": "Decreases functional residual capacity to improve gas flow"}]'::jsonb, '["a"]', 'PEEP allows use of a lower FiO₂ while maintaining adequate oxygenation, which reduces oxygen toxicity. PEEP increases, rather than decreases, functional residual capacity.'),
  ('ards', 30, 'A nurse is explaining the effects of PEEP to a nursing student. Which effect of PEEP on lung volume should the nurse include?', '[{"id": "a", "text": "It decreases functional residual capacity"}, {"id": "b", "text": "It decreases lung compliance"}, {"id": "c", "text": "It increases alveolar collapse"}, {"id": "d", "text": "It increases functional residual capacity"}]'::jsonb, '["d"]', 'PEEP increases functional residual capacity (FRC) and prevents alveolar collapse. Decreasing FRC or increasing collapse is the reverse of its effect.'),
  ('ards', 31, 'A client with ARDS is receiving a high level of PEEP. The nurse monitors closely for which complication associated with excessive PEEP?', '[{"id": "a", "text": "Widespread atelectasis"}, {"id": "b", "text": "Pneumothorax"}, {"id": "c", "text": "Fluid overload"}, {"id": "d", "text": "Gastric aspiration"}]'::jsonb, '["b"]', 'Too high PEEP can cause barotrauma, such as pneumothorax or pneumomediastinum. PEEP prevents, rather than causes, atelectasis.'),
  ('ards', 32, 'A nurse is reviewing ventilator settings for a client with ARDS. Which PEEP setting falls within the typical range for ARDS?', '[{"id": "a", "text": "2 cmH₂O"}, {"id": "b", "text": "12 cmH₂O"}, {"id": "c", "text": "30 cmH₂O"}, {"id": "d", "text": "40 cmH₂O"}]'::jsonb, '["b"]', 'Typical PEEP in ARDS is 5–20 cmH₂O, so 12 cmH₂O falls within that range. Settings above that range increase the risk of barotrauma.'),
  ('ards', 33, 'A client with moderate-to-severe ARDS continues to have poor oxygenation despite mechanical ventilation with PEEP. Which position does the nurse anticipate for this client?', '[{"id": "a", "text": "High-Fowler''s position"}, {"id": "b", "text": "Left lateral Trendelenburg"}, {"id": "c", "text": "Supine with the head flat"}, {"id": "d", "text": "Prone position"}]'::jsonb, '["d"]', 'The best position for ARDS is prone (face down), the most evidence-based positioning strategy to improve oxygenation. The other positions are not the recommended strategy for ARDS.'),
  ('ards', 34, 'A client with severe ARDS is being placed in the prone position. For how long each day does the nurse anticipate the client will remain prone?', '[{"id": "a", "text": "16 or more hours"}, {"id": "b", "text": "4 to 6 hours"}, {"id": "c", "text": "8 to 10 hours"}, {"id": "d", "text": "1 to 2 hours"}]'::jsonb, '["a"]', 'The target for moderate-to-severe ARDS is 16 or more hours per day in the prone position. Shorter durations fall below that target.'),
  ('ards', 35, 'The daughter of a client with ARDS asks why the client is being turned face down. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It shifts blood flow to the parts of the lungs that are not breathing well.\""}, {"id": "b", "text": "\"It opens collapsed air sacs in the back and better matches airflow with blood flow.\""}, {"id": "c", "text": "\"It makes the lungs stiffer so the ventilator can deliver air more easily.\""}, {"id": "d", "text": "\"It drains fluid out of the lungs so that diuretics are no longer needed.\""}]'::jsonb, '["b"]', 'Prone positioning opens collapsed dorsal (back) alveoli and improves V/Q matching by redistributing perfusion to better-ventilated regions. It does not shift blood flow toward poorly ventilated areas or stiffen the lungs.'),
  ('ards', 36, 'A client with ARDS has been placed in the prone position. Which finding best indicates that the intervention is effective?', '[{"id": "a", "text": "PaCO₂ rises and the client appears more fatigued"}, {"id": "b", "text": "New crackles develop in the dependent lung fields"}, {"id": "c", "text": "SpO₂ rises from 85% to 93% on the same FiO₂"}, {"id": "d", "text": "Higher pressures are needed to deliver each breath"}]'::jsonb, '["c"]', 'Prone positioning improves V/Q matching and increases oxygenation, so a rising SpO₂ on the same FiO₂ shows effectiveness. A rising PaCO₂ with fatigue signals late respiratory acidosis, and rising pressures reflect stiff lungs.'),
  ('ards', 37, 'A nurse is teaching a group of new nurses about hypoxemia and hypoxia. Which statement by a new nurse indicates a need for further teaching?', '[{"id": "a", "text": "\"Hypoxemia can be measured with an ABG or pulse oximeter.\""}, {"id": "b", "text": "\"Hypoxia can occur even when blood oxygen is normal.\""}, {"id": "c", "text": "\"Hypoxia is a lab value showing low oxygen in the blood.\""}, {"id": "d", "text": "\"Hypoxemia may exist without symptoms early on.\""}]'::jsonb, '["c"]', 'Hypoxemia is the lab value of low oxygen in the blood, while hypoxia is the clinical state of inadequate oxygen at the tissue level. The other statements are accurate.'),
  ('ards', 38, 'A client with severe anemia has an SpO₂ of 98% but is restless, confused, and tachycardic. How should the nurse interpret these findings?', '[{"id": "a", "text": "Hypoxemia without any tissue hypoxia"}, {"id": "b", "text": "Tissue hypoxia despite normal blood oxygen"}, {"id": "c", "text": "Expected findings that require no action"}, {"id": "d", "text": "Early respiratory acidosis from fatigue"}]'::jsonb, '["b"]', 'Hypoxia is inadequate oxygen at the tissue level and can occur even with normal blood oxygen, such as in anemia; restlessness, confusion, and tachycardia are signs of hypoxia. Hypoxemia is excluded because the blood oxygen is normal.'),
  ('ards', 39, 'A nurse reviews oxygenation data for four clients. Which value indicates hypoxemia?', '[{"id": "a", "text": "PaO₂ of 92 mmHg"}, {"id": "b", "text": "SpO₂ of 96%"}, {"id": "c", "text": "SpO₂ of 93%"}, {"id": "d", "text": "PaO₂ of 72 mmHg"}]'::jsonb, '["d"]', 'Hypoxemia is a PaO₂ below 80 mmHg or an SpO₂ below 90%, so a PaO₂ of 72 mmHg meets the definition. The other values are above these thresholds.'),
  ('ards', 40, 'A client with ARDS has been hypoxic for several hours. Which pair of findings should alert the nurse to late signs of hypoxia?', '[{"id": "a", "text": "Bradycardia and hypotension"}, {"id": "b", "text": "Tachycardia and restlessness"}, {"id": "c", "text": "Tachypnea and confusion"}, {"id": "d", "text": "Restlessness and tachypnea"}]'::jsonb, '["a"]', 'Bradycardia and hypotension are late signs of hypoxia. Restlessness, confusion, tachypnea, and tachycardia are listed as signs of hypoxia, with restlessness and confusion identified as early signs.'),
  ('ards', 41, 'A nurse is caring for a ventilated client with ARDS. Which nursing action helps prevent the most common complication of ARDS?', '[{"id": "a", "text": "Keeping the head of the bed flat"}, {"id": "b", "text": "Keeping the head of the bed at 30–45°"}, {"id": "c", "text": "Increasing the tidal volume"}, {"id": "d", "text": "Increasing the IV fluid rate"}]'::jsonb, '["b"]', 'Ventilator-associated pneumonia (VAP) is the most common complication and is prevented with HOB elevation of 30–45°, oral care, and cuff pressure monitoring. A flat head of bed does not meet this prevention guideline.'),
  ('ards', 42, 'A charge nurse is reviewing ventilator-associated pneumonia (VAP) prevention with a new nurse. Which statement by the new nurse indicates a need for further teaching?', '[{"id": "a", "text": "\"I will provide oral care as part of the vent bundle.\""}, {"id": "b", "text": "\"I will monitor the endotracheal tube cuff pressure.\""}, {"id": "c", "text": "\"I will keep the head of the bed elevated 30–45°.\""}, {"id": "d", "text": "\"I will skip oral care while the client is intubated.\""}]'::jsonb, '["d"]', 'Oral care is a key VAP prevention measure along with HOB elevation of 30–45° and cuff pressure monitoring. Skipping oral care would increase VAP risk.'),
  ('ards', 43, 'A nurse is planning care for a client with ARDS on mechanical ventilation. Which complication is the most common?', '[{"id": "a", "text": "Barotrauma"}, {"id": "b", "text": "Multi-organ failure"}, {"id": "c", "text": "Ventilator-associated pneumonia"}, {"id": "d", "text": "Pneumomediastinum"}]'::jsonb, '["c"]', 'Ventilator-associated pneumonia is the most common complication of ARDS. Barotrauma (including pneumomediastinum) and multi-organ failure are also complications but are not the most common.'),
  ('ards', 44, 'A client with ARDS has had prolonged hypoxemia. Which assessment best helps the nurse detect developing multi-organ failure?', '[{"id": "a", "text": "Measuring urine output every hour"}, {"id": "b", "text": "Measuring urine output once each shift"}, {"id": "c", "text": "Checking oxygen saturation once daily"}, {"id": "d", "text": "Auscultating breath sounds once daily"}]'::jsonb, '["a"]', 'Prolonged hypoxemia can cause kidney, liver, and heart failure, so creatinine, LFTs, and urine output are monitored hourly. Once-a-shift or daily checks are less frequent than recommended.'),
  ('ards', 45, 'A client who was admitted with pancreatitis develops severe dyspnea, tachypnea, and an SpO₂ of 82%. Which action should the nurse take first?', '[{"id": "a", "text": "Notify the provider of the change"}, {"id": "b", "text": "Obtain a chest X-ray as ordered"}, {"id": "c", "text": "Administer oxygen therapy"}, {"id": "d", "text": "Draw an arterial blood gas"}]'::jsonb, '["c"]', 'The first priority is oxygen therapy, followed by notifying the provider. Notifying the provider and obtaining diagnostics come after oxygen is started.'),
  ('ards', 46, 'A ventilated client with ARDS is receiving an FiO₂ of 0.60 and has a PaO₂ of 95 mmHg and an SpO₂ of 97%. Which action does the nurse anticipate?', '[{"id": "a", "text": "Increasing the FiO₂ to 1.0 to build an oxygen reserve"}, {"id": "b", "text": "Keeping the FiO₂ unchanged for the rest of the week"}, {"id": "c", "text": "Reducing PEEP to zero while keeping the FiO₂ the same"}, {"id": "d", "text": "Lowering the FiO₂ while keeping PaO₂ above 60 mmHg"}]'::jsonb, '["d"]', 'The goal is the lowest FiO₂ that maintains a PaO₂ above 60 mmHg or SpO₂ above 90%, which reduces oxygen toxicity. Raising the FiO₂ when oxygenation already exceeds the target is unnecessary.'),
  ('ards', 47, 'A nurse is caring for a client with ARDS on mechanical ventilation. Which ventilator strategy helps prevent barotrauma?', '[{"id": "a", "text": "High tidal volume with zero PEEP"}, {"id": "b", "text": "Low tidal volume with optimal PEEP"}, {"id": "c", "text": "High tidal volume with high PEEP"}, {"id": "d", "text": "Low tidal volume with zero PEEP"}]'::jsonb, '["b"]', 'Barotrauma is prevented with a low tidal volume and optimal PEEP. High tidal volumes and excessively high PEEP raise ventilator pressures, and zero PEEP allows alveolar collapse.'),
  ('ards', 48, 'A nurse is reviewing the signs of ARDS using the ARDS mnemonic. The "A" in the mnemonic refers to which finding?', '[{"id": "a", "text": "Accessory muscle use only"}, {"id": "b", "text": "Alkalosis from hyperventilation"}, {"id": "c", "text": "Air hunger with cyanosis"}, {"id": "d", "text": "Atelectasis from widespread alveolar collapse"}]'::jsonb, '["d"]', 'The "A" stands for atelectasis, widespread alveolar collapse. Accessory muscle use, air hunger, and cyanosis fall under "S," severe dyspnea.'),
  ('ards', 49, 'A nurse is assessing a client with suspected ARDS. Which finding is consistent with the increased work of breathing seen in ARDS?', '[{"id": "a", "text": "Slow, deep respirations"}, {"id": "b", "text": "Intercostal retractions"}, {"id": "c", "text": "Bradycardia at rest"}, {"id": "d", "text": "Relaxed, easy breathing"}]'::jsonb, '["b"]', 'Increased work of breathing in ARDS includes intercostal retractions, along with tachypnea, accessory muscle use, and air hunger. Slow respirations and relaxed breathing do not fit the severe dyspnea of ARDS.'),
  ('ards', 50, 'A nurse is caring for a client with ARDS who has had prolonged hypoxemia. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "SpO₂ of 92% on the current FiO₂"}, {"id": "b", "text": "Crackles unchanged from the prior assessment"}, {"id": "c", "text": "Urine output steadily declining for 3 hours"}, {"id": "d", "text": "Client sedated and resting comfortably"}]'::jsonb, '["c"]', 'Prolonged hypoxemia can lead to kidney, liver, and heart failure, so a declining urine output should be reported. An SpO₂ of 92% meets the goal of keeping SpO₂ above 90%.'),
  ('asthma', 1, 'During medication reconciliation, a client with asthma reports taking several medications at home. Which medication should the nurse identify as a possible asthma trigger?', '[{"id": "a", "text": "Montelukast taken nightly"}, {"id": "b", "text": "Aspirin taken for headaches"}, {"id": "c", "text": "Cromolyn sodium nasal spray"}, {"id": "d", "text": "Budesonide inhaler twice daily"}]'::jsonb, '["b"]', 'Aspirin is listed with beta-blockers, NSAIDs, and sulfites as a drug trigger for asthma. Montelukast, cromolyn, and budesonide are long-term prevention or control medications for asthma, not triggers.'),
  ('asthma', 2, 'A client with asthma arrives in the emergency department slumped in a wheelchair, wheezing, with chest tightness and an SpO2 of 89%. Which action should the nurse take first?', '[{"id": "a", "text": "Administer the prescribed albuterol"}, {"id": "b", "text": "Auscultate the client''s lung sounds"}, {"id": "c", "text": "Place the client in high Fowler''s position"}, {"id": "d", "text": "Obtain a peak flow meter reading"}]'::jsonb, '["c"]', 'The priority sequence for an asthma attack begins with positioning in high Fowler''s to maximize lung expansion, followed by oxygen and then a short-acting bronchodilator. Peak flow assessment comes later in the sequence.'),
  ('asthma', 3, 'The nurse has just placed a client experiencing an acute asthma attack in high Fowler''s position. Which action should the nurse take next?', '[{"id": "a", "text": "Apply oxygen to keep SpO2 between 95% and 99%"}, {"id": "b", "text": "Administer the prescribed albuterol treatment"}, {"id": "c", "text": "Measure the client''s peak expiratory flow"}, {"id": "d", "text": "Observe the client for chest retractions"}]'::jsonb, '["a"]', 'After high Fowler''s positioning, the next priority is administering oxygen to maintain SpO2 95–99%, and then giving the short-acting bronchodilator. Peak flow and monitoring for retractions follow later.'),
  ('asthma', 4, 'A client is receiving supplemental oxygen during an asthma attack. Which pulse oximetry reading indicates the oxygen goal for this client has been met?', '[{"id": "a", "text": "88%"}, {"id": "b", "text": "91%"}, {"id": "c", "text": "93%"}, {"id": "d", "text": "97%"}]'::jsonb, '["d"]', 'Oxygen during an asthma attack is titrated to maintain SpO2 between 95% and 99%, so 97% meets the goal. Readings of 88%, 91%, and 93% are all below the target range.'),
  ('asthma', 5, 'A client in an acute asthma attack has prescriptions for several inhaled medications. Which medication should the nurse administer first?', '[{"id": "a", "text": "Salmeterol"}, {"id": "b", "text": "Albuterol"}, {"id": "c", "text": "Fluticasone"}, {"id": "d", "text": "Montelukast"}]'::jsonb, '["b"]', 'Bronchodilator therapy during an attack starts with a short-acting beta-agonist, and albuterol is the rescue inhaler for fast relief. Salmeterol is a maintenance LABA, fluticasone is a long-term ICS, and montelukast is for long-term prevention; none are for acute attacks.'),
  ('asthma', 6, 'The nurse is preparing to give an albuterol nebulizer treatment to a client who is wheezing during an asthma attack. When should the nurse auscultate the client''s lung sounds?', '[{"id": "a", "text": "Before and after the treatment"}, {"id": "b", "text": "Only after the treatment ends"}, {"id": "c", "text": "Only before the treatment starts"}, {"id": "d", "text": "Only if the SpO2 drops below 95%"}]'::jsonb, '["a"]', 'Lung sounds are auscultated both before and after treatment so the nurse can compare findings and judge the response. Assessing at only one point does not allow evaluation of the treatment.'),
  ('asthma', 7, 'A client experiencing an asthma attack is crying and panicking. The nurse uses a calm, reassuring approach. What is the rationale for this intervention?', '[{"id": "a", "text": "Anxiety reduces mucus production in the airways"}, {"id": "b", "text": "Anxiety relaxes the airway smooth muscle"}, {"id": "c", "text": "Anxiety worsens the client''s bronchospasm"}, {"id": "d", "text": "Calming the client replaces bronchodilators"}]'::jsonb, '["c"]', 'Keeping the client calm is a priority intervention because anxiety worsens bronchospasm. Anxiety does not relax smooth muscle, and calming is done alongside, not instead of, bronchodilator therapy.'),
  ('asthma', 8, 'The parent of a child with asthma calls the clinic. Which reported finding indicates an active asthma attack rather than an early warning sign?', '[{"id": "a", "text": "Sneezing and a scratchy throat"}, {"id": "b", "text": "Irritability and trouble sleeping"}, {"id": "c", "text": "Mild wheezing during active play"}, {"id": "d", "text": "Bluish color of the lips and skin"}]'::jsonb, '["d"]', 'Cyanosis (blue lips, skin) is a sign of an active asthma attack. Cold-like symptoms, irritability with trouble sleeping, and mild wheezing with activity are early warning signs that appear 1–2 days before an attack.'),
  ('asthma', 9, 'A client with asthma describes symptoms that have developed over the past 2 days. Which symptom should the nurse recognize as an early warning sign of an approaching attack?', '[{"id": "a", "text": "Frequent coughing at night"}, {"id": "b", "text": "Visible chest retractions"}, {"id": "c", "text": "Bluish lips and skin"}, {"id": "d", "text": "Uncontrollable coughing"}]'::jsonb, '["a"]', 'Frequent cough, especially at night, is an early warning sign occurring 1–2 days before an attack. Chest retractions, cyanosis, and uncontrollable coughing are signs of an active attack.'),
  ('asthma', 10, 'A client with asthma has a personal best peak flow of 500 L/min. This morning''s reading is 450 L/min, and the client has no symptoms. What should the nurse instruct the client to do?', '[{"id": "a", "text": "Add quick-relief medication and call the provider if no improvement"}, {"id": "b", "text": "Take quick-relief medication now and call 911 if no improvement"}, {"id": "c", "text": "Continue taking maintenance medications as prescribed"}, {"id": "d", "text": "Go to the emergency department for evaluation today"}]'::jsonb, '["c"]', '450 is 90% of the personal best, which is the green zone (80–100%): asthma is controlled and maintenance medications are continued as prescribed. Adding quick-relief medication is a yellow-zone action, and calling 911 or going to the ER is a red-zone action.'),
  ('asthma', 11, 'A client whose personal best peak flow is 400 L/min reports a reading of 240 L/min with mild chest tightness. Which instruction should the nurse give?', '[{"id": "a", "text": "Continue maintenance medications only; no change is needed"}, {"id": "b", "text": "Go directly to the emergency department for treatment"}, {"id": "c", "text": "Stop the controller inhaler until the reading improves"}, {"id": "d", "text": "Add quick-relief medication; call the provider if no improvement"}]'::jsonb, '["d"]', '240 is 60% of the personal best, placing the client in the yellow zone (50–79%), where asthma is getting worse and quick-relief medication is added, with a call to the provider if it doesn''t improve. Maintenance medications alone fit the green zone, and the ER is a red-zone consideration.'),
  ('asthma', 12, 'A client with a personal best peak flow of 500 L/min calls the nurse reporting a current reading of 200 L/min. Which response by the nurse is appropriate?', '[{"id": "a", "text": "Continue maintenance medications and recheck tomorrow"}, {"id": "b", "text": "Take quick-relief medication now; call 911 if no improvement"}, {"id": "c", "text": "Add your controller inhaler and recheck in a week"}, {"id": "d", "text": "Rest for an hour and repeat the reading before acting"}]'::jsonb, '["b"]', '200 is 40% of the personal best, which is the red zone (below 50%): a medical alert requiring quick-relief medication immediately and a call to 911 or the provider if there is no improvement. Delaying action or relying on maintenance medication is inappropriate in the red zone.'),
  ('asthma', 13, 'A client''s personal best peak flow is 450 L/min, and today''s reading is 360 L/min. How should the nurse interpret this reading?', '[{"id": "a", "text": "Green zone; continue maintenance medications"}, {"id": "b", "text": "Yellow zone; add quick-relief medication"}, {"id": "c", "text": "Red zone; take quick-relief medication now"}, {"id": "d", "text": "Yellow zone; call 911 immediately"}]'::jsonb, '["a"]', '360 is exactly 80% of 450, which falls within the green zone (80–100% of personal best) where maintenance medications are continued. The yellow zone begins below 80% (50–79%).'),
  ('asthma', 14, 'The nurse has taught a client how to use a peak flow meter. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will compare each reading to my personal best.\""}, {"id": "b", "text": "\"I will check my peak flow each morning at the same time.\""}, {"id": "c", "text": "\"I will check it at different times each day to compare.\""}, {"id": "d", "text": "\"A reading below 80% of my best means my asthma is worsening.\""}]'::jsonb, '["c"]', 'The peak flow meter should be used at the same time each day (morning or bedtime) and compared to the personal best, so varying the time indicates a need for more teaching. Readings below 80% do indicate worsening asthma.'),
  ('asthma', 15, 'At a follow-up visit, a client with asthma reports using an albuterol inhaler about 4 times each week for the past month. How should the nurse interpret this finding?', '[{"id": "a", "text": "The asthma is well controlled"}, {"id": "b", "text": "This is expected rescue inhaler use"}, {"id": "c", "text": "Maintenance medication can be stopped"}, {"id": "d", "text": "The asthma is poorly controlled"}]'::jsonb, '["d"]', 'Albuterol is not for daily use, and using it more than twice a week indicates poor asthma control. This frequency is not expected use and is not a reason to stop maintenance medications.'),
  ('asthma', 16, 'A client has just received an albuterol nebulizer treatment for wheezing. For which side effect should the nurse monitor?', '[{"id": "a", "text": "Tachycardia"}, {"id": "b", "text": "Bradycardia"}, {"id": "c", "text": "Oral thrush"}, {"id": "d", "text": "Burning in the nose"}]'::jsonb, '["a"]', 'Tachycardia is a listed side effect of albuterol, a SABA. Oral thrush is a risk of inhaled corticosteroids, and burning in the nose is a side effect of cromolyn sodium.'),
  ('asthma', 17, 'A client hospitalized for an asthma exacerbation is receiving frequent albuterol treatments. Which laboratory change should the nurse anticipate?', '[{"id": "a", "text": "Increased serum potassium"}, {"id": "b", "text": "Decreased blood glucose"}, {"id": "c", "text": "Decreased serum potassium"}, {"id": "d", "text": "Increased theophylline level"}]'::jsonb, '["c"]', 'Albuterol side effects include decreased potassium and hyperglycemia. An increased potassium or decreased glucose reverses the expected direction.'),
  ('asthma', 18, 'A client newly prescribed salmeterol asks, "Can I use this inhaler when I am having an asthma attack?" Which response by the nurse is correct?', '[{"id": "a", "text": "\"Yes, it works faster than your albuterol does.\""}, {"id": "b", "text": "\"No, salmeterol is for maintenance, not attacks.\""}, {"id": "c", "text": "\"Yes, as long as you use it with a spacer.\""}, {"id": "d", "text": "\"No, salmeterol is only used before exercise.\""}]'::jsonb, '["b"]', 'Salmeterol is a long-acting beta-agonist used for maintenance and is not for acute attacks; albuterol is the fast-acting rescue inhaler. A spacer does not change the drug''s role.'),
  ('asthma', 19, 'A provider prescribes formoterol as the only asthma medication for a client with persistent asthma. The nurse plans to clarify the prescription. Which reason supports this action?', '[{"id": "a", "text": "Formoterol must be used with an inhaled corticosteroid"}, {"id": "b", "text": "Formoterol is for clients who can''t tolerate beta-agonists"}, {"id": "c", "text": "Formoterol must be given as a subcutaneous injection"}, {"id": "d", "text": "Formoterol is reserved for treating acute attacks"}]'::jsonb, '["a"]', 'Formoterol is a LABA, and LABAs must be used with an ICS. It is itself a beta-agonist, is inhaled rather than injected, and is for maintenance, not acute attacks.'),
  ('asthma', 20, 'A client with asthma developed intolerable effects from beta-agonist inhalers. Which medication should the nurse anticipate the provider will prescribe?', '[{"id": "a", "text": "Formoterol"}, {"id": "b", "text": "Ipratropium"}, {"id": "c", "text": "Salmeterol"}, {"id": "d", "text": "Advair"}]'::jsonb, '["b"]', 'Ipratropium, a short-acting anticholinergic, is used for patients who can''t tolerate beta-agonists. Formoterol and salmeterol are beta-agonists, and Advair contains salmeterol.'),
  ('asthma', 21, 'A client using ipratropium reports a persistently dry mouth. Which recommendation should the nurse make?', '[{"id": "a", "text": "Stop using the inhaler until the mouth feels better"}, {"id": "b", "text": "Take an extra puff of the inhaler each day"}, {"id": "c", "text": "Suck on sugarless candy to relieve the dryness"}, {"id": "d", "text": "Switch to oral theophylline without telling the provider"}]'::jsonb, '["c"]', 'Dry mouth is the key side effect of ipratropium and is managed with sugarless candy. Stopping or changing medications on one''s own is not the recommended management.'),
  ('asthma', 22, 'A client is newly prescribed a fluticasone inhaler for long-term asthma control. Which instruction is most important for the nurse to include?', '[{"id": "a", "text": "Use it at the first sign of wheezing"}, {"id": "b", "text": "Avoid all sources of caffeine"}, {"id": "c", "text": "Use it only before exercising"}, {"id": "d", "text": "Rinse your mouth after each use"}]'::jsonb, '["d"]', 'Fluticasone is an inhaled corticosteroid, and the mouth should be rinsed after use because of the risk of oral thrush. ICS is for long-term control, not acute symptoms, and avoiding caffeine applies to theophylline.'),
  ('asthma', 23, 'A client has used inhaled budesonide daily for several years. Which long-term adverse effects should the nurse include in the client''s teaching?', '[{"id": "a", "text": "Hypoglycemia and bradycardia"}, {"id": "b", "text": "Osteoporosis and cataracts"}, {"id": "c", "text": "Burning in the nose and sneezing"}, {"id": "d", "text": "Hyperkalemia and jitteriness"}]'::jsonb, '["b"]', 'Inhaled corticosteroids such as budesonide carry risks of oral thrush, osteoporosis, and cataracts. Burning in the nose and sneezing are side effects of cromolyn sodium.'),
  ('asthma', 24, 'The nurse recommends that a client using a beclomethasone metered-dose inhaler attach a spacer. Which explanation supports this recommendation?', '[{"id": "a", "text": "It allows the inhaler to act as a rescue drug"}, {"id": "b", "text": "It removes the need to rinse the mouth after use"}, {"id": "c", "text": "It increases lung delivery and reduces oral deposition"}, {"id": "d", "text": "It removes the need to shake the inhaler first"}]'::jsonb, '["c"]', 'A spacer increases drug delivery to the lungs and reduces oral deposition, which decreases thrush risk with inhaled corticosteroids. It does not change the drug into a rescue medication or replace other technique steps.'),
  ('asthma', 25, 'The nurse is teaching a client who has been prescribed budesonide. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will use budesonide to stop an asthma attack.\""}, {"id": "b", "text": "\"I will rinse my mouth after each use.\""}, {"id": "c", "text": "\"I will keep using it even when I feel well.\""}, {"id": "d", "text": "\"I will use a spacer with this inhaler.\""}]'::jsonb, '["a"]', 'Inhaled corticosteroids such as budesonide are for long-term control and are not for acute attacks. Rinsing the mouth, continuing maintenance medications when well, and using a spacer are all correct.'),
  ('asthma', 26, 'A client is prescribed both albuterol and fluticasone inhalers for the same morning dose time. Which sequence should the nurse teach?', '[{"id": "a", "text": "Fluticasone, wait 5 minutes, then albuterol"}, {"id": "b", "text": "Albuterol and fluticasone back to back with no wait"}, {"id": "c", "text": "Fluticasone, then albuterol only if wheezing continues"}, {"id": "d", "text": "Albuterol, wait 5 minutes, then fluticasone"}]'::jsonb, '["d"]', 'The SABA (albuterol) is used first to open the airways, followed by a 5-minute wait, and then the ICS (fluticasone). Reversing the order or skipping the wait is incorrect.'),
  ('asthma', 27, 'A client prescribed Advair asks the nurse what medications the inhaler contains. Which response is accurate?', '[{"id": "a", "text": "Albuterol and fluticasone"}, {"id": "b", "text": "Ipratropium and albuterol"}, {"id": "c", "text": "Fluticasone and salmeterol"}, {"id": "d", "text": "Budesonide and montelukast"}]'::jsonb, '["c"]', 'Advair is a combination maintenance inhaler containing fluticasone (an ICS) and salmeterol (a LABA). It does not contain albuterol, the rescue SABA.'),
  ('asthma', 28, 'A client taking oral theophylline for asthma has a serum theophylline level of 25 mcg/mL. How should the nurse interpret this result?', '[{"id": "a", "text": "Above the therapeutic range; report it"}, {"id": "b", "text": "Within the therapeutic range; continue"}, {"id": "c", "text": "Below the therapeutic range; expect an increase"}, {"id": "d", "text": "At the low end of the range; recheck in a month"}]'::jsonb, '["a"]', 'The therapeutic theophylline level is 10–20 mcg/mL, so 25 mcg/mL is above range and requires close monitoring and reporting. It is not within or below the therapeutic range.'),
  ('asthma', 29, 'The nurse is teaching a client who takes theophylline. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"I will drink extra coffee to boost its effect.\""}, {"id": "b", "text": "\"I will use theophylline as my first-line rescue drug.\""}, {"id": "c", "text": "\"I can skip blood level checks if I feel well.\""}, {"id": "d", "text": "\"I will avoid coffee and other sources of caffeine.\""}]'::jsonb, '["d"]', 'Caffeine increases theophylline toxicity and should be avoided. Theophylline is not first line, and it requires close monitoring of levels.'),
  ('asthma', 30, 'A client asks how montelukast helps control asthma. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It quickly opens the airways during an attack"}, {"id": "b", "text": "It blocks airway inflammation and mucus"}, {"id": "c", "text": "It reduces the allergic response as an anti-IgE drug"}, {"id": "d", "text": "It stabilizes mast cells to prevent symptoms"}]'::jsonb, '["b"]', 'Montelukast is a leukotriene modifier for long-term prevention that blocks airway inflammation and mucus; it is not for acute attacks. Anti-IgE action describes omalizumab, and mast cell stabilization describes cromolyn sodium.'),
  ('asthma', 31, 'A client with severe allergic asthma is starting omalizumab. Which information about administration should the nurse include?', '[{"id": "a", "text": "It is taken as an oral tablet each night"}, {"id": "b", "text": "It is inhaled as a puff during attacks"}, {"id": "c", "text": "It is a SQ injection every 2 to 4 weeks"}, {"id": "d", "text": "It is nebulized as a treatment twice daily"}]'::jsonb, '["c"]', 'Omalizumab is an anti-IgE biologic for severe allergic asthma given as a subcutaneous injection every 2–4 weeks. It is not an oral, inhaled, or nebulized medication.'),
  ('asthma', 32, 'A client who recently started cromolyn sodium reports a burning sensation in the nose. How should the nurse interpret this report?', '[{"id": "a", "text": "A sign of oral thrush from the drug"}, {"id": "b", "text": "A sign of theophylline toxicity"}, {"id": "c", "text": "An indication of low potassium"}, {"id": "d", "text": "A known side effect of cromolyn"}]'::jsonb, '["d"]', 'Burning in the nose, bad taste, and sneezing are listed side effects of cromolyn sodium. Oral thrush is linked to inhaled corticosteroids, and low potassium is linked to albuterol.'),
  ('asthma', 33, 'The nurse observes a client using a metered-dose inhaler. Which action by the client demonstrates correct technique?', '[{"id": "a", "text": "Holds the breath for 10 seconds after inhaling"}, {"id": "b", "text": "Inhales quickly and shallowly with the puff"}, {"id": "c", "text": "Presses the canister twice during one breath"}, {"id": "d", "text": "Inhales deeply just before placing the mouthpiece"}]'::jsonb, '["a"]', 'After inhaling, the breath is held for 10–15 seconds to maximize drug deposition. Inhalation should be slow and deep, one puff is released per press, and the client should exhale fully before placing the mouthpiece.'),
  ('asthma', 34, 'A client is prescribed two puffs of a metered-dose inhaler. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I shake the inhaler well before each use.\""}, {"id": "b", "text": "\"I take my second puff right after the first one.\""}, {"id": "c", "text": "\"I breathe out fully before using the inhaler.\""}, {"id": "d", "text": "\"I hold my breath after I inhale the puff.\""}]'::jsonb, '["b"]', 'When more than one puff is ordered, the client should wait 1 minute between puffs. Shaking the inhaler, exhaling fully first, and holding the breath after inhaling are all correct steps.'),
  ('asthma', 35, 'The nurse is teaching a client the steps for using a metered-dose inhaler. Which step should the client perform first?', '[{"id": "a", "text": "Exhale fully"}, {"id": "b", "text": "Press the canister once"}, {"id": "c", "text": "Shake the inhaler well"}, {"id": "d", "text": "Hold the breath for 10 seconds"}]'::jsonb, '["c"]', 'Correct MDI technique begins with shaking the inhaler well before each use, then exhaling fully, pressing once while inhaling slowly and deeply, and holding the breath.'),
  ('asthma', 36, 'The nurse observes a client take a deep breath in and then place the metered-dose inhaler mouthpiece in the mouth. What should the nurse instruct the client to do immediately before placing the mouthpiece?', '[{"id": "a", "text": "Inhale as deeply as possible"}, {"id": "b", "text": "Hold the breath for 10 seconds"}, {"id": "c", "text": "Press the canister two times"}, {"id": "d", "text": "Exhale fully"}]'::jsonb, '["d"]', 'The client should exhale fully before placing the mouthpiece in the mouth, then inhale slowly and deeply with one puff. Breath-holding comes after inhaling the medication.'),
  ('asthma', 37, 'An older adult with asthma has difficulty coordinating pressing the metered-dose inhaler with inhaling. Which intervention should the nurse recommend?', '[{"id": "a", "text": "Attach a spacer to the inhaler"}, {"id": "b", "text": "Switch to oral theophylline"}, {"id": "c", "text": "Take two puffs at the same time"}, {"id": "d", "text": "Skip shaking the inhaler first"}]'::jsonb, '["a"]', 'A spacer (valved holding chamber) is used when coordination is difficult, especially in children and the elderly. Theophylline is not first line, and the other options are incorrect technique.'),
  ('asthma', 38, 'A young child in respiratory distress cannot coordinate a metered-dose inhaler, so a nebulizer treatment is prescribed. Which instruction should the nurse give the child''s parent?', '[{"id": "a", "text": "Have the child lie flat and take rapid deep breaths"}, {"id": "b", "text": "Have the child sit upright and breathe normally"}, {"id": "c", "text": "Have the child hold each breath for 10 to 15 seconds"}, {"id": "d", "text": "Have the child recline and breathe only through the nose"}]'::jsonb, '["b"]', 'During a nebulizer treatment the client sits upright and breathes normally through the mouthpiece or mask. The 10–15 second breath-hold applies to MDI technique, not nebulizer use.'),
  ('asthma', 39, 'The nurse teaches a client about home nebulizer use. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"The machine turns my liquid medicine into a fine mist.\""}, {"id": "b", "text": "\"I will sit upright while I do my treatments.\""}, {"id": "c", "text": "\"I will clean the cup and mouthpiece once a week.\""}, {"id": "d", "text": "\"Each treatment usually takes about 10 to 15 minutes.\""}]'::jsonb, '["c"]', 'The nebulizer cup and mouthpiece should be cleaned after each use to prevent infection, so weekly cleaning needs correction. The other statements about the mist, upright position, and 10–15 minute duration are correct.'),
  ('asthma', 40, 'A teenager with asthma who plays soccer asks the nurse how to prevent symptoms during games. Which instruction should the nurse give?', '[{"id": "a", "text": "Use the short-acting bronchodilator before exercising"}, {"id": "b", "text": "Stop playing sports because exercise is contraindicated"}, {"id": "c", "text": "Use the salmeterol inhaler to treat symptoms during play"}, {"id": "d", "text": "Skip the warm-up to avoid tiring the airways"}]'::jsonb, '["a"]', 'Exercise is not contraindicated in asthma; the client should warm up for 10–15 minutes and use a short-acting bronchodilator before exercise. Salmeterol is a maintenance drug, not for treating acute symptoms.'),
  ('asthma', 41, 'A client with exercise-induced bronchoconstriction plans to jog outdoors during the winter. Which instruction should the nurse provide?', '[{"id": "a", "text": "Breathe through the mouth to increase airflow"}, {"id": "b", "text": "Wear a scarf to warm the air that is inhaled"}, {"id": "c", "text": "Skip the warm-up when the weather is cold"}, {"id": "d", "text": "Stop controller medications during the winter"}]'::jsonb, '["b"]', 'Cold, dry air is a trigger for exercise-induced bronchoconstriction, so a scarf is worn in cold weather to warm inhaled air. Clients should breathe through the nose, warm up, and continue maintenance medications.'),
  ('asthma', 42, 'The nurse provides teaching about exercise to a client with asthma. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will warm up for 10 to 15 minutes before I run.\""}, {"id": "b", "text": "\"I will try to breathe through my nose when I run.\""}, {"id": "c", "text": "\"I will keep running even when I have a chest cold.\""}, {"id": "d", "text": "\"I will use my albuterol inhaler before I start running.\""}]'::jsonb, '["c"]', 'Clients should avoid exercise when sick because respiratory infections worsen asthma. Warming up for 10–15 minutes, nose breathing, and using a short-acting bronchodilator before exercise are correct.'),
  ('asthma', 43, 'The nurse reviews an asthma action plan with a client. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will try to avoid my known triggers.\""}, {"id": "b", "text": "\"I will check my peak flow at the same time daily.\""}, {"id": "c", "text": "\"I will rinse my mouth after my steroid inhaler.\""}, {"id": "d", "text": "\"I will stop my controller inhaler when I feel well.\""}]'::jsonb, '["d"]', 'Maintenance medications should be taken even when feeling well. Avoiding triggers, checking peak flow at the same time daily, and rinsing after a corticosteroid inhaler are all part of correct teaching.'),
  ('asthma', 44, 'A client with asthma reports frequent nighttime symptoms and has recently been diagnosed with GERD. How should the nurse interpret the GERD diagnosis in relation to the asthma?', '[{"id": "a", "text": "GERD is unrelated to the client''s asthma symptoms"}, {"id": "b", "text": "GERD only triggers exercise-induced bronchoconstriction"}, {"id": "c", "text": "GERD is a body factor that can trigger asthma"}, {"id": "d", "text": "GERD is a sign the client is overusing albuterol"}]'::jsonb, '["c"]', 'GERD is listed among body-factor triggers of asthma, along with respiratory infections and hormonal changes. It is not limited to exercise-induced symptoms and is not a sign of albuterol overuse.'),
  ('asthma', 45, 'A client in an acute asthma attack is coughing up mucus. The nurse understands that the excess mucus during an attack results from which process?', '[{"id": "a", "text": "Inflamed mucosa causing goblet cells to overproduce mucus"}, {"id": "b", "text": "Relaxation of the smooth muscle around the bronchioles"}, {"id": "c", "text": "Dilation of the bronchi that allows mucus to pool"}, {"id": "d", "text": "Reduced inflammation of the airway mucosal lining"}]'::jsonb, '["a"]', 'During an attack the mucosal lining becomes inflamed and goblet cells produce excess mucus, while smooth muscle around the bronchi and bronchioles constricts. Relaxation, dilation, and reduced inflammation reverse what happens.'),
  ('asthma', 46, 'The nurse auscultates wheezing in a client having an asthma attack. Which mechanism explains this finding?', '[{"id": "a", "text": "Widening of the bronchioles"}, {"id": "b", "text": "Reduced mucus in the airways"}, {"id": "c", "text": "Relaxation of airway smooth muscle"}, {"id": "d", "text": "Air moving through narrowed airways"}]'::jsonb, '["d"]', 'Wheezing is produced by air moving through narrowed airways caused by smooth muscle constriction and mucus. Widened airways, reduced mucus, and muscle relaxation are the opposite of an attack.'),
  ('asthma', 47, 'A client newly diagnosed with asthma asks the nurse, "Will this ever go away?" Which response is accurate?', '[{"id": "a", "text": "\"Asthma is cured once your triggers are removed.\""}, {"id": "b", "text": "\"There is no cure, but asthma can be managed.\""}, {"id": "c", "text": "\"The airway narrowing is permanent and worsens.\""}, {"id": "d", "text": "\"Asthma goes away after a full course of steroids.\""}]'::jsonb, '["b"]', 'Asthma is a chronic disease with reversible airway narrowing and inflammation; it has no cure but is manageable. The narrowing is reversible, not permanent, and no treatment cures it.'),
  ('asthma', 48, 'The nurse is assessing a client during an active asthma attack. Which breathing pattern should the nurse expect?', '[{"id": "a", "text": "Slow rate with easy exhalation"}, {"id": "b", "text": "Slow rate with difficult inhalation"}, {"id": "c", "text": "Normal rate with no wheezing"}, {"id": "d", "text": "Rapid rate with difficult exhalation"}]'::jsonb, '["d"]', 'An active attack produces severe difficulty exhaling and an increased respiratory rate, along with wheezing. A slow or normal rate without wheezing does not fit an active attack.'),
  ('asthma', 49, 'During a home visit for a child with frequent asthma attacks, which finding should the nurse address as a potential trigger?', '[{"id": "a", "text": "Evidence of cockroaches in the kitchen"}, {"id": "b", "text": "A peak flow log posted on the refrigerator"}, {"id": "c", "text": "A spacer stored next to the inhaler"}, {"id": "d", "text": "A scarf hanging by the door for winter"}]'::jsonb, '["a"]', 'Cockroach allergen is a listed asthma trigger, and clients are taught to identify and avoid personal triggers. A peak flow log, spacer, and scarf for cold weather are management tools, not triggers.'),
  ('asthma', 50, 'The nurse teaches a client with asthma about medications that can trigger attacks. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"Aspirin is a safe choice for my headaches.\""}, {"id": "b", "text": "\"I should ask before taking NSAIDs or beta-blockers.\""}, {"id": "c", "text": "\"Medications cannot trigger my asthma.\""}, {"id": "d", "text": "\"Beta-blockers will help open my airways.\""}]'::jsonb, '["b"]', 'Beta-blockers, NSAIDs, and aspirin are classic drug triggers for asthma, so medication history should always be checked. Aspirin is not a safe choice, and medications can trigger asthma.'),
  ('copd', 1, 'A client with stable COPD receiving oxygen at 2 L/min by nasal cannula has an SpO₂ of 90% and asks the nurse to turn the oxygen up so the reading will reach 100%. Which response by the nurse is best?', '[{"id": "a", "text": "Your level is low, so we need to reach at least 98%."}, {"id": "b", "text": "I will increase your oxygen to 6 L/min right away."}, {"id": "c", "text": "Your oxygen level is already in your target range."}, {"id": "d", "text": "I will switch you to a high-flow mask to reach 100%."}]'::jsonb, '["c"]', 'In stable COPD the target SpO₂ is 88–92%, so 90% on low-flow oxygen is on target. Increasing to high-flow oxygen is dangerous because it removes the hypoxic drive.'),
  ('copd', 2, 'A client with long-standing COPD and chronic CO₂ retention has arterial blood gases drawn. Which set of results should the nurse expect?', '[{"id": "a", "text": "pH 7.32, PaCO₂ 52 mmHg, HCO₃⁻ 30 mEq/L"}, {"id": "b", "text": "pH 7.48, PaCO₂ 30 mmHg, HCO₃⁻ 22 mEq/L"}, {"id": "c", "text": "pH 7.40, PaCO₂ 40 mmHg, HCO₃⁻ 24 mEq/L"}, {"id": "d", "text": "pH 7.30, PaCO₂ 38 mmHg, HCO₃⁻ 18 mEq/L"}]'::jsonb, '["a"]', 'In COPD the PaCO₂ rises above 35–45 mmHg, the pH falls below 7.35 (respiratory acidosis), and HCO₃⁻ rises above 22–26 mEq/L from renal compensation. Normal values do not reflect CO₂ retention.'),
  ('copd', 3, 'A client is admitted with a COPD exacerbation. The SpO₂ is 85% and the client is breathing rapidly. Which oxygen plan should the nurse anticipate?', '[{"id": "a", "text": "No oxygen until the blood gas results return"}, {"id": "b", "text": "High-flow oxygen until the SpO₂ reaches 100%"}, {"id": "c", "text": "Oxygen at 10 L/min by a simple face mask"}, {"id": "d", "text": "Controlled low-flow oxygen with SpO₂ monitoring"}]'::jsonb, '["d"]', 'During an exacerbation SpO₂ may drop to 84–86%, but controlled, low-flow oxygen is still used. High-flow oxygen removes the hypoxic drive and can cause apnea.'),
  ('copd', 4, 'A nursing student asks why high-flow oxygen is dangerous for a client with COPD. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It causes polycythemia that quickly thickens the blood."}, {"id": "b", "text": "It triggers cor pulmonale and right-sided heart failure."}, {"id": "c", "text": "It removes the hypoxic drive, so breathing may stop."}, {"id": "d", "text": "It lowers bicarbonate and blocks renal compensation."}]'::jsonb, '["c"]', 'In COPD, O₂ becomes the breathing trigger, so high-flow O₂ removes the hypoxic drive and the client may stop breathing. Polycythemia results from chronic hypoxia, not from oxygen therapy.'),
  ('copd', 5, 'The provider wants a client with COPD to receive a precise, controlled FiO₂. Which delivery device should the nurse anticipate?', '[{"id": "a", "text": "Partial rebreather mask"}, {"id": "b", "text": "Nasal cannula at 6 L/min"}, {"id": "c", "text": "Simple face mask"}, {"id": "d", "text": "Venturi mask"}]'::jsonb, '["d"]', 'The Venturi mask provides the most precise O₂ delivery and is preferred in COPD for controlled FiO₂. A nasal cannula in COPD is used only at low flow (1–2 L/min), not 6 L/min.'),
  ('copd', 6, 'While applying a Venturi mask to a client with COPD, the nurse checks which component that determines the delivered oxygen concentration?', '[{"id": "a", "text": "The reservoir bag inflated before each breath"}, {"id": "b", "text": "The nasal prongs placed in each nostril"}, {"id": "c", "text": "The color-coded adaptor set to the ordered FiO₂"}, {"id": "d", "text": "The humidifier bottle filled to the line"}]'::jsonb, '["c"]', 'A Venturi mask uses a color-coded adaptor that delivers 24%–60% FiO₂, which is why it is the most precise delivery method. Nasal prongs belong to a nasal cannula, not a Venturi mask.'),
  ('copd', 7, 'A 64-year-old client newly diagnosed with COPD has a 40-pack-year history, mild GERD, and works in a quiet office. Which factor is the most likely primary cause of the disease?', '[{"id": "a", "text": "Work-related stress"}, {"id": "b", "text": "Gastroesophageal reflux disease"}, {"id": "c", "text": "Exposure to cold weather"}, {"id": "d", "text": "Long-term cigarette smoking"}]'::jsonb, '["d"]', 'Smoking is the #1 cause of COPD. GERD, cold weather, and stress are triggers to avoid, not the main cause of the disease.'),
  ('copd', 8, 'Which nursing intervention is most important to slow the progression of a client''s COPD?', '[{"id": "a", "text": "Encouraging 2–3 L of fluid daily"}, {"id": "b", "text": "Supporting smoking cessation"}, {"id": "c", "text": "Teaching diaphragmatic breathing"}, {"id": "d", "text": "Positioning in high Fowler''s"}]'::jsonb, '["b"]', 'Smoking cessation is the #1 intervention to slow COPD progression. Fluids loosen mucus and high Fowler''s maximizes lung expansion, but neither slows progression.'),
  ('copd', 9, 'A 34-year-old client who has never smoked is diagnosed with COPD. The nurse anticipates evaluation for which underlying risk factor?', '[{"id": "a", "text": "Theophylline toxicity"}, {"id": "b", "text": "Alpha-1 antitrypsin deficiency"}, {"id": "c", "text": "Right-sided heart failure"}, {"id": "d", "text": "Chronic polycythemia"}]'::jsonb, '["b"]', 'Genetics, specifically alpha-1 antitrypsin deficiency, is a listed cause of COPD and is relevant when smoking is absent. Polycythemia and cor pulmonale are consequences of COPD, not causes.'),
  ('copd', 10, 'When obtaining a history from a client with COPD, which occupational background should the nurse recognize as a risk factor?', '[{"id": "a", "text": "Teaching in an elementary school classroom"}, {"id": "b", "text": "Desk work in a quiet accounting office"}, {"id": "c", "text": "Answering phones at a busy call center"}, {"id": "d", "text": "Asbestos and dust exposure in construction"}]'::jsonb, '["d"]', 'Occupational hazards such as asbestos, dust, and chemicals are causes of COPD. The other jobs involve none of these listed exposures.'),
  ('copd', 11, 'A client has the chronic bronchitis form of COPD, often called the ''blue bloater.'' Which assessment finding should the nurse expect?', '[{"id": "a", "text": "Pursed-lip breathing with cachexia"}, {"id": "b", "text": "Pink complexion with barrel chest"}, {"id": "c", "text": "Cyanosis with peripheral edema"}, {"id": "d", "text": "Weight loss with muscle wasting"}]'::jsonb, '["c"]', 'Chronic bronchitis presents with cyanosis (blue skin) and peripheral edema from cor pulmonale. Pink complexion, barrel chest, and cachexia describe emphysema, the ''pink puffer.'''),
  ('copd', 12, 'A thin client with emphysema, often called the ''pink puffer,'' is being assessed. Which finding should the nurse expect?', '[{"id": "a", "text": "Peripheral edema"}, {"id": "b", "text": "Overweight build"}, {"id": "c", "text": "Cyanotic skin"}, {"id": "d", "text": "Barrel chest"}]'::jsonb, '["d"]', 'Emphysema causes a barrel chest from hyperinflated lungs. Peripheral edema, cyanosis, and an overweight build are features of chronic bronchitis, the ''blue bloater.'''),
  ('copd', 13, 'The nurse notes that a client with emphysema has a pink complexion. The nurse understands this coloring is due to which mechanism?', '[{"id": "a", "text": "Compensatory hyperventilation"}, {"id": "b", "text": "Right-sided heart failure"}, {"id": "c", "text": "Peripheral edema from fluid overload"}, {"id": "d", "text": "Normal oxygen and carbon dioxide levels"}]'::jsonb, '["a"]', 'In emphysema the pink complexion results from compensatory hyperventilation. Both types of COPD still cause hypoxia and hypercapnia, so gas levels are not normal.'),
  ('copd', 14, 'A client with emphysema asks why the chest has become rounded and barrel-shaped. The nurse''s explanation should be based on which process?', '[{"id": "a", "text": "Fluid collecting in the abdomen"}, {"id": "b", "text": "Thick mucus filling the large bronchi"}, {"id": "c", "text": "Enlargement of the right ventricle"}, {"id": "d", "text": "Air trapping with hyperinflated lungs"}]'::jsonb, '["d"]', 'In emphysema, destroyed alveolar walls cause air trapping, producing hyperinflated lungs and a barrel chest. Mucus-filled bronchi describe chronic bronchitis.'),
  ('copd', 15, 'Which history finding best supports a diagnosis of the chronic bronchitis type of COPD?', '[{"id": "a", "text": "Productive cough for 1 month in a single year"}, {"id": "b", "text": "Productive cough ≥3 months in 2 consecutive years"}, {"id": "c", "text": "Shortness of breath only when lying on one side"}, {"id": "d", "text": "Dry cough for 3 weeks following a chest cold"}]'::jsonb, '["b"]', 'Chronic bronchitis is defined by a productive cough lasting at least 3 months in 2 consecutive years. A cough lasting 1 month in a single year does not meet this definition.'),
  ('copd', 16, 'A client with chronic bronchitis develops new bilateral ankle edema. The nurse recognizes this as a sign of which complication?', '[{"id": "a", "text": "Cor pulmonale"}, {"id": "b", "text": "Polycythemia"}, {"id": "c", "text": "Loss of hypoxic drive"}, {"id": "d", "text": "Respiratory alkalosis"}]'::jsonb, '["a"]', 'Peripheral edema in chronic bronchitis reflects cor pulmonale, which is right-sided heart failure from pulmonary hypertension. Polycythemia causes thick blood and clot risk, not edema.'),
  ('copd', 17, 'Which sequence correctly describes the development of cor pulmonale in a client with COPD?', '[{"id": "a", "text": "Pulmonary hypertension leading to right-sided heart failure"}, {"id": "b", "text": "Right-sided heart failure leading to pulmonary hypertension"}, {"id": "c", "text": "Systemic hypertension leading to left-sided heart failure"}, {"id": "d", "text": "Pulmonary hypertension leading to left-sided heart failure"}]'::jsonb, '["a"]', 'Cor pulmonale is pulmonary hypertension that leads to right-sided heart failure. The reversed sequence and left-sided failure are incorrect.'),
  ('copd', 18, 'Laboratory results show an elevated red blood cell count in a client with long-standing COPD. Which intervention should the nurse plan?', '[{"id": "a", "text": "Hold all prescribed bronchodilators"}, {"id": "b", "text": "Implement DVT precautions"}, {"id": "c", "text": "Increase oxygen to a high flow rate"}, {"id": "d", "text": "Restrict fluids to less than 1 L/day"}]'::jsonb, '["b"]', 'Polycythemia causes thick blood, so the nurse monitors it and uses DVT precautions. High-flow oxygen is never used in COPD because it removes the hypoxic drive.'),
  ('copd', 19, 'A client with COPD asks why the red blood cell count is high. Which response by the nurse is accurate?', '[{"id": "a", "text": "High carbon dioxide levels are destroying your red cells."}, {"id": "b", "text": "Your inhaled steroid is making your body produce red cells."}, {"id": "c", "text": "Your body makes more red cells to make up for low oxygen."}, {"id": "d", "text": "Drinking extra fluids has concentrated your red cells."}]'::jsonb, '["c"]', 'Polycythemia is increased RBC production to compensate for chronic hypoxia. It is not caused by inhaled steroids or fluid intake.'),
  ('copd', 20, 'Which statement best describes the stimulus to breathe in a client with COPD who chronically retains CO₂?', '[{"id": "a", "text": "A high carbon dioxide level remains the main trigger."}, {"id": "b", "text": "A rising blood pH becomes the main trigger to breathe."}, {"id": "c", "text": "A low oxygen level becomes the main trigger to breathe."}, {"id": "d", "text": "An oxygen saturation of 100% becomes the main trigger."}]'::jsonb, '["c"]', 'In COPD the body adapts to high CO₂, so O₂ becomes the breathing trigger (hypoxic drive). High CO₂ therefore no longer serves as the main stimulus.'),
  ('copd', 21, 'A client with COPD becomes short of breath while lying in bed. Which position should the nurse assist the client into?', '[{"id": "a", "text": "Prone with the head flat"}, {"id": "b", "text": "High Fowler''s position"}, {"id": "c", "text": "Supine with the head flat"}, {"id": "d", "text": "Trendelenburg position"}]'::jsonb, '["b"]', 'High Fowler''s (or tripod) positioning maximizes lung expansion in COPD. Flat or head-down positions do not support lung expansion.'),
  ('copd', 22, 'The nurse enters the room and finds a client with COPD sitting on the edge of the bed, leaning forward with hands on the knees. How should the nurse interpret this finding?', '[{"id": "a", "text": "The client is in respiratory distress."}, {"id": "b", "text": "The client is resting comfortably."}, {"id": "c", "text": "The client is easing heartburn from GERD."}, {"id": "d", "text": "The client''s lung function is improving."}]'::jsonb, '["a"]', 'Tripoding, leaning forward with hands on the knees, is always a sign of respiratory distress. It does not indicate comfort or improvement.'),
  ('copd', 23, 'A nurse teaches pursed-lip breathing to a client with emphysema. What is the primary purpose of this technique?', '[{"id": "a", "text": "Strengthening the cough to clear thick mucus"}, {"id": "b", "text": "Speeding inhalation to raise oxygen levels"}, {"id": "c", "text": "Prolonging exhalation to prevent air trapping"}, {"id": "d", "text": "Shortening exhalation to conserve energy"}]'::jsonb, '["c"]', 'Pursed-lip breathing prolongs exhalation and prevents air trapping. Shortening exhalation is the opposite of its purpose.'),
  ('copd', 24, 'After teaching about pursed-lip breathing, which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will make my breath out longer than usual."}, {"id": "b", "text": "I will practice this during my pulmonary rehab sessions."}, {"id": "c", "text": "Breathing out through pursed lips keeps air from getting trapped."}, {"id": "d", "text": "I will blow my air out quickly and forcefully."}]'::jsonb, '["d"]', 'Pursed-lip breathing extends exhalation, so exhaling quickly and forcefully is incorrect. Preventing air trapping and practicing in pulmonary rehab are accurate.'),
  ('copd', 25, 'A client with COPD has thick secretions and no fluid restrictions. Which daily fluid intake should the nurse encourage?', '[{"id": "a", "text": "Less than 1 L/day"}, {"id": "b", "text": "1–1.5 L/day"}, {"id": "c", "text": "2–3 L/day"}, {"id": "d", "text": "4–5 L/day"}]'::jsonb, '["c"]', 'Encouraging 2–3 L of fluid per day loosens mucus in COPD. Lower intakes fall short of this recommendation.'),
  ('copd', 26, 'A client with COPD asks which vaccines will help prevent flare-ups. Which vaccines should the nurse recommend?', '[{"id": "a", "text": "Measles and mumps vaccines"}, {"id": "b", "text": "Influenza and pneumonia vaccines"}, {"id": "c", "text": "Tetanus and diphtheria vaccines"}, {"id": "d", "text": "Hepatitis A and B vaccines"}]'::jsonb, '["b"]', 'Flu and pneumonia vaccines are recommended in COPD to prevent exacerbations. The other vaccines are not the ones identified for preventing COPD exacerbations.'),
  ('copd', 27, 'A client with COPD is prescribed inhaled fluticasone. Which instruction should the nurse include?', '[{"id": "a", "text": "Take each dose with a cup of coffee."}, {"id": "b", "text": "Lie flat for 30 minutes after each use."}, {"id": "c", "text": "Rinse your mouth after each use."}, {"id": "d", "text": "Use it first during an acute attack."}]'::jsonb, '["c"]', 'Clients should rinse the mouth after using an inhaled corticosteroid because of the risk of thrush. Fluticasone is not the fast-acting medication for acute narrowing; bronchodilators such as albuterol are.'),
  ('copd', 28, 'A client has used an inhaled corticosteroid for COPD for several years. Which long-term adverse effect should the nurse monitor for?', '[{"id": "a", "text": "Polycythemia"}, {"id": "b", "text": "Respiratory alkalosis"}, {"id": "c", "text": "Osteoporosis"}, {"id": "d", "text": "Cor pulmonale"}]'::jsonb, '["c"]', 'Inhaled corticosteroids carry a risk of thrush and osteoporosis. Polycythemia and cor pulmonale are complications of COPD itself, not of the medication.'),
  ('copd', 29, 'A client with COPD taking theophylline has a serum theophylline level of 24 mcg/mL. Which action should the nurse take?', '[{"id": "a", "text": "Report the level as above the monitoring range."}, {"id": "b", "text": "Administer the next scheduled dose early."}, {"id": "c", "text": "Encourage a caffeinated drink with the next dose."}, {"id": "d", "text": "Document the level as within the therapeutic range."}]'::jsonb, '["a"]', 'Theophylline levels are monitored for a range of 10–20 mcg/mL, so 24 mcg/mL is above range and should be reported. Caffeine should be avoided with theophylline.'),
  ('copd', 30, 'Which statement by a client taking theophylline for COPD indicates a need for further teaching?', '[{"id": "a", "text": "I will drink extra coffee each morning with my pill."}, {"id": "b", "text": "This medicine relaxes the muscles of my airways."}, {"id": "c", "text": "I take theophylline by mouth as a pill."}, {"id": "d", "text": "I will keep my appointments for blood level checks."}]'::jsonb, '["a"]', 'Clients taking theophylline should avoid caffeine, so extra coffee shows a need for more teaching. Theophylline is an oral pill that relaxes airway muscles and requires level monitoring.'),
  ('copd', 31, 'A client is admitted with a severe COPD exacerbation. Which intravenous medication should the nurse anticipate?', '[{"id": "a", "text": "Theophylline"}, {"id": "b", "text": "Methylprednisolone"}, {"id": "c", "text": "Fluticasone"}, {"id": "d", "text": "Beclomethasone"}]'::jsonb, '["b"]', 'IV methylprednisolone is the corticosteroid used for severe exacerbations. Fluticasone and beclomethasone are inhaled, and theophylline is an oral pill.'),
  ('copd', 32, 'A client with COPD suddenly becomes short of breath with wheezing. Which prescribed inhaler should the nurse expect to relieve the airway narrowing?', '[{"id": "a", "text": "Fluticasone"}, {"id": "b", "text": "Beclomethasone"}, {"id": "c", "text": "Budesonide"}, {"id": "d", "text": "Albuterol"}]'::jsonb, '["d"]', 'Albuterol is a short-acting bronchodilator (SABA) that relieves airway narrowing. Fluticasone, budesonide, and beclomethasone are inhaled corticosteroids.'),
  ('copd', 33, 'A client with COPD has an arterial PaO₂ of 62 mmHg. How should the nurse interpret this value?', '[{"id": "a", "text": "Decreased, consistent with hypoxia"}, {"id": "b", "text": "Normal for an adult client"}, {"id": "c", "text": "Increased, consistent with hypercapnia"}, {"id": "d", "text": "Increased, indicating excess oxygen"}]'::jsonb, '["a"]', 'Normal PaO₂ is 80–100 mmHg, so 62 mmHg is decreased and consistent with hypoxia in COPD. Hypercapnia refers to high CO₂, not oxygen.'),
  ('copd', 34, 'A client with chronic COPD has an HCO₃⁻ of 31 mEq/L. How should the nurse interpret this finding?', '[{"id": "a", "text": "An expected effect of high-flow oxygen"}, {"id": "b", "text": "A sign of compensatory hyperventilation"}, {"id": "c", "text": "Evidence that the acidosis has fully resolved"}, {"id": "d", "text": "Renal compensation for CO₂ retention"}]'::jsonb, '["d"]', 'Normal HCO₃⁻ is 22–26 mEq/L; in COPD it rises as renal compensation for CO₂ retention. An elevated bicarbonate does not mean the acidosis has resolved.'),
  ('copd', 35, 'A client with COPD has a PaCO₂ of 55 mmHg. The nurse recognizes the client is at risk for which acid-base imbalance?', '[{"id": "a", "text": "Metabolic alkalosis"}, {"id": "b", "text": "Respiratory acidosis"}, {"id": "c", "text": "Respiratory alkalosis"}, {"id": "d", "text": "Metabolic acidosis"}]'::jsonb, '["b"]', 'Normal PaCO₂ is 35–45 mmHg; high CO₂ (hypercapnia) leads to respiratory acidosis. Respiratory alkalosis is the reverse direction.'),
  ('copd', 36, 'A client with COPD is referred to pulmonary rehabilitation and asks what the program involves. Which response by the nurse is accurate?', '[{"id": "a", "text": "Exercise combined with breathing training"}, {"id": "b", "text": "Complete rest from all physical activity"}, {"id": "c", "text": "Fluid restriction combined with diuretics"}, {"id": "d", "text": "Bed rest combined with oxygen therapy"}]'::jsonb, '["a"]', 'Pulmonary rehab consists of exercise plus breathing training. Bed rest and avoiding activity are not part of the program.'),
  ('copd', 37, 'Which breathing techniques should the nurse expect a client with COPD to learn in pulmonary rehabilitation?', '[{"id": "a", "text": "Rapid, shallow upper-chest breathing"}, {"id": "b", "text": "Prolonged breath-holding exercises"}, {"id": "c", "text": "Pursed-lip and diaphragmatic breathing"}, {"id": "d", "text": "Deliberate hyperventilation drills"}]'::jsonb, '["c"]', 'Pulmonary rehab teaches pursed-lip and diaphragmatic breathing. Rapid, shallow breathing is not a taught technique.'),
  ('copd', 38, 'Which statement by a client with COPD shows understanding of trigger avoidance?', '[{"id": "a", "text": "I will limit my time outside on very cold days."}, {"id": "b", "text": "Stress has no effect on my breathing problems."}, {"id": "c", "text": "My heartburn has nothing to do with my lungs."}, {"id": "d", "text": "Breathing cold air will help open my airways."}]'::jsonb, '["a"]', 'Cold weather, stress, and GERD are COPD triggers to avoid. Statements dismissing cold air, stress, or heartburn show misunderstanding.'),
  ('copd', 39, 'During an admission interview, which finding in the history of a client with COPD should the nurse identify as a trigger for exacerbations?', '[{"id": "a", "text": "Receiving the yearly flu vaccine"}, {"id": "b", "text": "Frequent heartburn from GERD"}, {"id": "c", "text": "Drinking 2–3 L of fluid daily"}, {"id": "d", "text": "A daily 20-minute walking routine"}]'::jsonb, '["b"]', 'GERD is listed as a COPD trigger to avoid. Fluids of 2–3 L/day and flu vaccination are recommended interventions, not triggers.'),
  ('copd', 40, 'The nurse is applying oxygen by nasal cannula to a client with stable COPD. Which flow rate is appropriate?', '[{"id": "a", "text": "1–2 L/min"}, {"id": "b", "text": "4–6 L/min"}, {"id": "c", "text": "8–10 L/min"}, {"id": "d", "text": "12–15 L/min"}]'::jsonb, '["a"]', 'Stable COPD is managed with low-flow O₂ by nasal cannula at 1–2 L/min to avoid suppressing the hypoxic drive. Higher rates risk removing that drive.'),
  ('copd', 41, 'A client with stable COPD is receiving low-flow oxygen. Which SpO₂ reading indicates the therapy is meeting the target?', '[{"id": "a", "text": "84%"}, {"id": "b", "text": "90%"}, {"id": "c", "text": "96%"}, {"id": "d", "text": "100%"}]'::jsonb, '["b"]', 'The SpO₂ target in stable COPD is 88–92%, so 90% meets it. A reading of 84% is a level seen in exacerbation and is below target.'),
  ('copd', 42, 'A visitor turned up the oxygen of a client with COPD to a high flow rate. The nurse finds the client''s respirations becoming slow and shallow. Which action should the nurse take first?', '[{"id": "a", "text": "Return the oxygen to the prescribed low flow."}, {"id": "b", "text": "Lower the head of the bed to a flat position."}, {"id": "c", "text": "Increase the oxygen flow rate even further."}, {"id": "d", "text": "Reassess the client again in one hour."}]'::jsonb, '["a"]', 'High-flow O₂ removes the hypoxic drive and can cause apnea, so the flow must be returned to low flow. Increasing the flow further worsens the danger.'),
  ('copd', 43, 'A client in a COPD exacerbation has an SpO₂ of 85%. A new nurse asks how to manage this. Which response by the charge nurse is accurate?', '[{"id": "a", "text": "This is the expected target for clients with stable COPD."}, {"id": "b", "text": "It can drop this low; still use controlled low-flow oxygen."}, {"id": "c", "text": "Oxygen should be avoided entirely during an exacerbation."}, {"id": "d", "text": "This level means high-flow oxygen is needed to reach 100%."}]'::jsonb, '["b"]', 'In an exacerbation SpO₂ may drop to 84–86%, and controlled low-flow O₂ is still used. The stable COPD target is 88–92%, not 85%.'),
  ('copd', 44, 'A client with COPD is breathing rapidly. The nurse understands that the rapid breathing is most likely which of the following?', '[{"id": "a", "text": "An expected effect of inhaled corticosteroids"}, {"id": "b", "text": "A sign that the oxygen flow is set too high"}, {"id": "c", "text": "A result of drinking 2–3 L of fluid daily"}, {"id": "d", "text": "A compensation for impaired gas exchange"}]'::jsonb, '["d"]', 'Tachypnea in COPD is rapid breathing to compensate for low O₂ and high CO₂. Excess oxygen removes the hypoxic drive rather than causing rapid breathing.'),
  ('copd', 45, 'Which statement by a client is most consistent with the typical shortness of breath pattern in COPD?', '[{"id": "a", "text": "My breathing is worst when I sit still."}, {"id": "b", "text": "My breathing improves the more active I am."}, {"id": "c", "text": "My breathing trouble started suddenly yesterday."}, {"id": "d", "text": "My breathing gets worse when I climb stairs."}]'::jsonb, '["d"]', 'Shortness of breath in COPD is progressive and worsens with exertion. COPD is a progressive disease, so a sudden onset does not fit.'),
  ('copd', 46, 'A nurse is assessing a client with advanced emphysema. Which finding related to body build is expected?', '[{"id": "a", "text": "Weight gain with a bloated look"}, {"id": "b", "text": "Swelling in both lower legs"}, {"id": "c", "text": "Weight loss with muscle wasting"}, {"id": "d", "text": "Overweight build with cyanosis"}]'::jsonb, '["c"]', 'Emphysema causes cachexia, meaning weight loss and muscle wasting. An overweight, bloated, edematous appearance describes chronic bronchitis.'),
  ('copd', 47, 'Which pathophysiologic change should the nurse identify as characteristic of emphysema rather than chronic bronchitis?', '[{"id": "a", "text": "Destroyed alveolar walls with air trapping"}, {"id": "b", "text": "Inflamed bronchi filled with mucus"}, {"id": "c", "text": "Productive cough for two straight years"}, {"id": "d", "text": "Peripheral edema from cor pulmonale"}]'::jsonb, '["a"]', 'Emphysema involves destroyed alveolar walls leading to air trapping. Inflamed, mucus-filled bronchi and peripheral edema characterize chronic bronchitis.'),
  ('copd', 48, 'When auscultating the lungs of a client with the chronic bronchitis type of COPD, which breath sounds should the nurse expect?', '[{"id": "a", "text": "Absent sounds on one side"}, {"id": "b", "text": "Crackles and wheezes"}, {"id": "c", "text": "No abnormal sounds present"}, {"id": "d", "text": "Clear sounds in all lobes"}]'::jsonb, '["b"]', 'Chronic bronchitis produces crackles and wheezes, which are abnormal lung sounds in COPD. Clear lung fields would not be expected.'),
  ('copd', 49, 'A client with COPD keeps leaning forward with hands on the knees. The client''s partner asks why. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It helps slow the heart rate during times of stress."}, {"id": "b", "text": "It helps the client fall asleep more easily."}, {"id": "c", "text": "It helps relieve abdominal pain from acid reflux."}, {"id": "d", "text": "It helps use accessory muscles and gravity to breathe."}]'::jsonb, '["d"]', 'In tripoding, the client uses accessory muscles and gravity to assist breathing, which signals respiratory distress. It is not a comfort or sleep position.'),
  ('copd', 50, 'A client with COPD reports increased shortness of breath, is tripoding, and has an SpO₂ of 86% on room air. Which action should the nurse take first?', '[{"id": "a", "text": "Encourage 2–3 L of oral fluids over the day"}, {"id": "b", "text": "Apply oxygen by nasal cannula at 1–2 L/min"}, {"id": "c", "text": "Apply oxygen at 15 L/min for rapid correction"}, {"id": "d", "text": "Provide smoking cessation brochures"}]'::jsonb, '["b"]', 'Low-flow O₂ at 1–2 L/min is the priority action for this client in distress, and high-flow oxygen is never used in COPD. Fluids and smoking cessation are important but do not address the immediate hypoxia.'),
  ('bronchitis', 1, 'A client reports a long-standing cough that brings up mucus. Which history best meets the clinical definition of chronic bronchitis?', '[{"id": "a", "text": "Productive cough for 3 weeks after an upper respiratory illness"}, {"id": "b", "text": "Productive cough for at least 3 months in 2 consecutive years"}, {"id": "c", "text": "Dry cough lasting at least 3 months in a single year"}, {"id": "d", "text": "Productive cough for 2 months in 3 nonconsecutive years"}]'::jsonb, '["b"]', 'Chronic bronchitis is defined clinically as a productive cough for at least 3 months in 2 consecutive years. A cough lasting only 2 months, or not in consecutive years, does not meet the definition.'),
  ('bronchitis', 2, 'A nurse is reviewing risk factors with a client newly diagnosed with chronic bronchitis. Which factor is most often the cause?', '[{"id": "a", "text": "Cigarette smoking"}, {"id": "b", "text": "Recent weight gain"}, {"id": "c", "text": "Use of a bedside humidifier"}, {"id": "d", "text": "Annual flu vaccination"}]'::jsonb, '["a"]', 'Chronic bronchitis is often caused by smoking. A humidifier and flu vaccination are recommended interventions, not causes.'),
  ('bronchitis', 3, 'Which description best explains the underlying problem in chronic bronchitis?', '[{"id": "a", "text": "Inflamed bronchi blocked by excess mucus"}, {"id": "b", "text": "A blood clot blocking a pulmonary artery"}, {"id": "c", "text": "Air trapped within the pleural space"}, {"id": "d", "text": "Fluid collecting around the heart"}]'::jsonb, '["a"]', 'Chronic bronchitis is inflammation and obstruction of the bronchi by excessive mucus. The other options do not describe this bronchial process.'),
  ('bronchitis', 4, 'A client asks how chronic bronchitis is classified. The nurse explains it is a subtype of which condition?', '[{"id": "a", "text": "Right-sided heart failure"}, {"id": "b", "text": "Pulmonary hypertension"}, {"id": "c", "text": "Acute bacterial pneumonia"}, {"id": "d", "text": "Chronic obstructive pulmonary disease"}]'::jsonb, '["d"]', 'Chronic bronchitis is part of COPD. Pulmonary hypertension and right heart failure (cor pulmonale) are complications that can develop from it, not its classification.'),
  ('bronchitis', 5, 'A client with chronic bronchitis is described as a ''blue bloater.'' Which pair of findings does this nickname refer to?', '[{"id": "a", "text": "Clubbing and fever"}, {"id": "b", "text": "Cyanosis and edema"}, {"id": "c", "text": "Pallor and weight loss"}, {"id": "d", "text": "Wheezing and tachypnea"}]'::jsonb, '["b"]', 'The ''Blue Bloater'' nickname refers to cyanosis plus edema. Wheezing and tachypnea occur but are not what the nickname describes.'),
  ('bronchitis', 6, 'The nurse notes bluish lips and nail beds in a client with chronic bronchitis. Which explanation is most accurate?', '[{"id": "a", "text": "Reaction to bedside humidifier mist"}, {"id": "b", "text": "Adverse effect of inhaled fluticasone"}, {"id": "c", "text": "Low oxygen with poor compensation"}, {"id": "d", "text": "Overhydration from 2–3 L of fluids"}]'::jsonb, '["c"]', 'The ''blue'' in blue bloater is cyanosis from low O₂ and poor compensation. Fluids of 2–3 L/day are a recommended intervention, not a cause of cyanosis.'),
  ('bronchitis', 7, 'A client with chronic bronchitis develops swelling in both ankles. The nurse recognizes this edema is most likely caused by which condition?', '[{"id": "a", "text": "Drinking 2–3 L of fluid daily"}, {"id": "b", "text": "Left-sided heart failure"}, {"id": "c", "text": "Cor pulmonale from lung disease"}, {"id": "d", "text": "Allergic reaction to albuterol"}]'::jsonb, '["c"]', 'The ''bloated'' appearance is peripheral edema from cor pulmonale, which is right heart failure. It is not left-sided failure or a result of recommended fluid intake.'),
  ('bronchitis', 8, 'While assessing a client with long-standing chronic bronchitis, the nurse notes clubbing of the fingers. This finding indicates which condition?', '[{"id": "a", "text": "Overuse of mucolytics"}, {"id": "b", "text": "Recent dehydration"}, {"id": "c", "text": "Chronic hypoxia"}, {"id": "d", "text": "Acute bacterial infection"}]'::jsonb, '["c"]', 'Clubbing of the fingers results from chronic hypoxia. It does not indicate an acute infection.'),
  ('bronchitis', 9, 'When auscultating the lungs of a client with chronic bronchitis, which breath sounds should the nurse expect?', '[{"id": "a", "text": "No adventitious sounds at all"}, {"id": "b", "text": "Crackles and wheezing"}, {"id": "c", "text": "Clear breath sounds bilaterally"}, {"id": "d", "text": "Absent sounds over one lung"}]'::jsonb, '["b"]', 'Crackles and wheezing on auscultation are part of the classic blue bloater profile. Clear lungs would not be expected with mucus-obstructed bronchi.'),
  ('bronchitis', 10, 'Which description of cough should the nurse expect when assessing a client with chronic bronchitis?', '[{"id": "a", "text": "Persistent cough producing thick sputum"}, {"id": "b", "text": "Dry cough without any sputum"}, {"id": "c", "text": "Barking cough only during the night"}, {"id": "d", "text": "Brief cough that resolves within days"}]'::jsonb, '["a"]', 'Chronic bronchitis causes a persistent, productive cough with thick sputum. A dry or short-lived cough does not fit the condition.'),
  ('bronchitis', 11, 'Which general appearance is the nurse most likely to observe in a client with chronic bronchitis?', '[{"id": "a", "text": "Thin build with muscle wasting"}, {"id": "b", "text": "Overweight, bloated appearance"}, {"id": "c", "text": "Pink, flushed complexion"}, {"id": "d", "text": "Normal weight without swelling"}]'::jsonb, '["b"]', 'The blue bloater profile includes an overweight appearance with peripheral edema and cyanosis. A pink complexion contradicts the cyanosis expected in this condition.'),
  ('bronchitis', 12, 'A client with chronic bronchitis describes several symptoms. Which complaint should the nurse recognize as the classic keyword symptom?', '[{"id": "a", "text": "Joint stiffness"}, {"id": "b", "text": "Chest tightness"}, {"id": "c", "text": "Abdominal cramping"}, {"id": "d", "text": "Throbbing headache"}]'::jsonb, '["b"]', 'Chest tightness is the classic keyword symptom for chronic bronchitis and COPD. The other complaints are not listed symptoms.'),
  ('bronchitis', 13, 'Which respiratory finding should the nurse expect when assessing a client with chronic bronchitis?', '[{"id": "a", "text": "Absence of shortness of breath"}, {"id": "b", "text": "Pink, well-oxygenated skin"}, {"id": "c", "text": "Rapid respiratory rate"}, {"id": "d", "text": "Slow, deep respirations"}]'::jsonb, '["c"]', 'Tachypnea, along with hypoxia and shortness of breath, is a general COPD symptom seen in chronic bronchitis. Slow breathing and absence of dyspnea are not expected.'),
  ('bronchitis', 14, 'A client with chronic bronchitis is found sitting and leaning forward with hands on the knees. How should the nurse interpret this?', '[{"id": "a", "text": "The client is in respiratory distress."}, {"id": "b", "text": "The client is resting comfortably."}, {"id": "c", "text": "The client is relieving back pain."}, {"id": "d", "text": "The client''s breathing is improving."}]'::jsonb, '["a"]', 'Tripoding means the client is in respiratory distress. It is not a sign of comfort or improvement.'),
  ('bronchitis', 15, 'The nurse documents that a client with chronic bronchitis is in the tripod position. Which description matches this documentation?', '[{"id": "a", "text": "Standing upright with arms raised overhead"}, {"id": "b", "text": "Sitting and leaning forward on hands or knees"}, {"id": "c", "text": "Lying flat with both legs elevated"}, {"id": "d", "text": "Side-lying with knees drawn to the chest"}]'::jsonb, '["b"]', 'The tripod position is leaning forward on the hands or knees. Lying flat or side-lying does not match tripoding.'),
  ('bronchitis', 16, 'Which position should the nurse use to maximize lung expansion for a client with chronic bronchitis who is short of breath?', '[{"id": "a", "text": "Prone"}, {"id": "b", "text": "Supine"}, {"id": "c", "text": "High Fowler''s"}, {"id": "d", "text": "Trendelenburg"}]'::jsonb, '["c"]', 'High Fowler''s or tripod positioning maximizes lung expansion. Flat or head-down positions do not.'),
  ('bronchitis', 17, 'A client with chronic bronchitis has thick, hard-to-clear sputum and no fluid restrictions. Which daily fluid intake should the nurse recommend?', '[{"id": "a", "text": "Less than 1 liter/day"}, {"id": "b", "text": "1–1.5 liters/day"}, {"id": "c", "text": "2–3 liters/day"}, {"id": "d", "text": "4–5 liters/day"}]'::jsonb, '["c"]', 'Increasing fluid intake to 2–3 liters/day loosens and thins mucus. Lower amounts fall short of the recommendation.'),
  ('bronchitis', 18, 'A client with chronic bronchitis asks why the nurse keeps encouraging extra fluids. Which response is accurate?', '[{"id": "a", "text": "Fluids replace the need for your inhaler."}, {"id": "b", "text": "Fluids help reverse clubbing of your fingers."}, {"id": "c", "text": "Fluids help loosen and thin your mucus."}, {"id": "d", "text": "Fluids help treat the swelling in your legs."}]'::jsonb, '["c"]', 'Increased fluid intake loosens and thins mucus. Leg swelling from cor pulmonale is treated with diuretics, not extra fluids.'),
  ('bronchitis', 19, 'Which item should the nurse place at the bedside to help a client with chronic bronchitis clear mucus?', '[{"id": "a", "text": "A dehumidifier to dry the air"}, {"id": "b", "text": "A fan blowing cool, dry air"}, {"id": "c", "text": "A scented candle for relaxation"}, {"id": "d", "text": "A humidifier to moisten the air"}]'::jsonb, '["d"]', 'A bedside humidifier moistens the air to aid mucus clearance. Drying the air works against this, and open flames are avoided near oxygen equipment.'),
  ('bronchitis', 20, 'The nurse prepares to perform chest physiotherapy for a client with chronic bronchitis. Which techniques does this therapy include?', '[{"id": "a", "text": "Percussion and postural drainage"}, {"id": "b", "text": "Cold compresses and fluid restriction"}, {"id": "c", "text": "Pursed-lip and diaphragmatic breathing"}, {"id": "d", "text": "Incentive spirometry and ambulation"}]'::jsonb, '["a"]', 'Chest physiotherapy (CPT) consists of percussion and postural drainage to clear secretions. The other pairs are not components of CPT.'),
  ('bronchitis', 21, 'A weak client with chronic bronchitis cannot clear secretions independently despite coughing efforts. Which equipment should be readily available at the bedside?', '[{"id": "a", "text": "A suction device"}, {"id": "b", "text": "A heating pad"}, {"id": "c", "text": "A cooling blanket"}, {"id": "d", "text": "A dehumidifier"}]'::jsonb, '["a"]', 'A suction device at the bedside is used for mucus removal when the client cannot clear secretions independently. A dehumidifier would dry the air rather than aid clearance.'),
  ('bronchitis', 22, 'The nurse teaches the huff (half) cough technique to a client with chronic bronchitis. Which sequence should the nurse teach?', '[{"id": "a", "text": "Exhale completely, hold, then cough as hard as possible"}, {"id": "b", "text": "Cough forcefully several times, then inhale deeply"}, {"id": "c", "text": "Take several short breaths, then cough repeatedly"}, {"id": "d", "text": "Take a deep breath, hold it, then cough halfway"}]'::jsonb, '["d"]', 'The huff cough is a deep breath, then a hold, then a cough halfway to mobilize mucus. Coughing as hard as possible defeats the goal of avoiding excessive strain.'),
  ('bronchitis', 23, 'A client asks why the huff cough is used instead of forceful coughing. Which response by the nurse is accurate?', '[{"id": "a", "text": "It raises the oxygen level to 100%."}, {"id": "b", "text": "It moves mucus up without excessive strain."}, {"id": "c", "text": "It stops the lungs from producing mucus."}, {"id": "d", "text": "It keeps mucus in place until suctioning."}]'::jsonb, '["b"]', 'The huff cough moves mucus up without excessive strain or bronchospasm. It does not stop mucus production.'),
  ('bronchitis', 24, 'Which statement by a client indicates a need for further teaching about the huff cough technique?', '[{"id": "a", "text": "This cough helps move mucus up with less strain."}, {"id": "b", "text": "I will cough as hard as I can several times in a row."}, {"id": "c", "text": "I will take a deep breath and hold it before I cough."}, {"id": "d", "text": "I will cough only halfway instead of with full force."}]'::jsonb, '["b"]', 'The huff cough involves a deep breath, a hold, and a halfway cough to avoid excessive strain, so coughing as hard as possible repeatedly shows misunderstanding. The other statements are accurate.'),
  ('bronchitis', 25, 'A client with stable chronic bronchitis is prescribed oxygen by nasal cannula. Which flow rate should the nurse expect?', '[{"id": "a", "text": "1–2 L/min"}, {"id": "b", "text": "4–6 L/min"}, {"id": "c", "text": "8–10 L/min"}, {"id": "d", "text": "12–15 L/min"}]'::jsonb, '["a"]', 'Clients with chronic bronchitis receive low-flow O₂ at 1–2 L/min with an SpO₂ target of 88–92%. Higher flow rates are not used.'),
  ('bronchitis', 26, 'A client with chronic bronchitis receiving oxygen at 2 L/min has an SpO₂ of 90%. Which action should the nurse take?', '[{"id": "a", "text": "Notify the provider of severe hypoxia."}, {"id": "b", "text": "Switch to a high-flow oxygen system."}, {"id": "c", "text": "Continue the current oxygen flow rate."}, {"id": "d", "text": "Increase the flow to raise SpO₂ to 100%."}]'::jsonb, '["c"]', 'The SpO₂ target is 88–92%, so 90% on 1–2 L/min is appropriate and the current flow should continue. Increasing to high flow is never done in COPD.'),
  ('bronchitis', 27, 'A nursing student asks why oxygen is kept at a low flow for a client with chronic bronchitis. Which explanation is accurate?', '[{"id": "a", "text": "To lower the risk of finger clubbing"}, {"id": "b", "text": "To avoid suppressing the hypoxic drive"}, {"id": "c", "text": "To prevent drying of the nasal passages"}, {"id": "d", "text": "To reduce the cost of home oxygen"}]'::jsonb, '["b"]', 'Low-flow oxygen is used in COPD to avoid suppressing the hypoxic drive. Clubbing results from chronic hypoxia, so it is not prevented by limiting oxygen.'),
  ('bronchitis', 28, 'A client with chronic bronchitis has thick, tenacious secretions. Which prescribed medication is intended to thin the secretions?', '[{"id": "a", "text": "Azithromycin"}, {"id": "b", "text": "Acetylcysteine"}, {"id": "c", "text": "Fluticasone"}, {"id": "d", "text": "Albuterol"}]'::jsonb, '["b"]', 'Acetylcysteine is a mucolytic that breaks down mucus and thins secretions. Albuterol opens airways, azithromycin treats bacterial exacerbations, and fluticasone reduces inflammation.'),
  ('bronchitis', 29, 'The nurse is teaching a client with chronic bronchitis about guaifenesin. Which description of its action is accurate?', '[{"id": "a", "text": "It treats bacterial infection."}, {"id": "b", "text": "It opens narrowed airways."}, {"id": "c", "text": "It reduces airway inflammation."}, {"id": "d", "text": "It breaks down and thins mucus."}]'::jsonb, '["d"]', 'Guaifenesin is a mucolytic that breaks down mucus and thins secretions. Opening airways is the action of bronchodilators.'),
  ('bronchitis', 30, 'A client with chronic bronchitis asks which inhaler to use for sudden shortness of breath. Which medication is the rescue inhaler?', '[{"id": "a", "text": "Prednisone"}, {"id": "b", "text": "Albuterol"}, {"id": "c", "text": "Doxycycline"}, {"id": "d", "text": "Fluticasone"}]'::jsonb, '["b"]', 'Albuterol is a SABA, and the SABA is the rescue inhaler. Fluticasone is an inhaled corticosteroid that reduces inflammation.'),
  ('bronchitis', 31, 'A client with chronic bronchitis is prescribed ipratropium. Which explanation of its action should the nurse provide?', '[{"id": "a", "text": "It breaks down mucus."}, {"id": "b", "text": "It treats bacterial infection."}, {"id": "c", "text": "It removes excess fluid."}, {"id": "d", "text": "It opens the airways."}]'::jsonb, '["d"]', 'Ipratropium is a bronchodilator that opens the airways. Breaking down mucus is the action of mucolytics.'),
  ('bronchitis', 32, 'A client with chronic bronchitis is prescribed inhaled fluticasone. Which instruction should the nurse give?', '[{"id": "a", "text": "Rinse your mouth after each use."}, {"id": "b", "text": "Take it only during infections."}, {"id": "c", "text": "Use it as your rescue inhaler."}, {"id": "d", "text": "Stop it once your sputum thins."}]'::jsonb, '["a"]', 'The mouth should be rinsed after using an inhaled corticosteroid (ICS). The rescue inhaler is the SABA, albuterol, not fluticasone.'),
  ('bronchitis', 33, 'Oral prednisone is prescribed for a client with chronic bronchitis. Which therapeutic effect should the nurse expect?', '[{"id": "a", "text": "Removal of excess body fluid"}, {"id": "b", "text": "Thinner, looser secretions"}, {"id": "c", "text": "Clearing of bacterial infection"}, {"id": "d", "text": "Reduced airway inflammation"}]'::jsonb, '["d"]', 'Corticosteroids such as oral prednisone reduce inflammation. Thinning secretions is the role of mucolytics.'),
  ('bronchitis', 34, 'Azithromycin is prescribed for a client with chronic bronchitis. The nurse understands this medication is indicated for which situation?', '[{"id": "a", "text": "Daily thinning of thick, sticky secretions"}, {"id": "b", "text": "Fluid overload from cor pulmonale"}, {"id": "c", "text": "Quick relief of sudden wheezing"}, {"id": "d", "text": "An exacerbation from bacterial infection"}]'::jsonb, '["d"]', 'Antibiotics such as azithromycin are used for exacerbations caused by bacterial infection. Quick relief of wheezing comes from the SABA rescue inhaler.'),
  ('bronchitis', 35, 'A client with chronic bronchitis has an exacerbation, and a sputum culture confirms a bacterial infection. Which medication should the nurse anticipate?', '[{"id": "a", "text": "Doxycycline"}, {"id": "b", "text": "Albuterol"}, {"id": "c", "text": "Fluticasone"}, {"id": "d", "text": "Guaifenesin"}]'::jsonb, '["a"]', 'Doxycycline is an antibiotic used for exacerbations caused by bacterial infection. Guaifenesin is a mucolytic and does not treat infection.'),
  ('bronchitis', 36, 'A client with chronic bronchitis will use oxygen at home. Which safety measure should the nurse include in discharge teaching?', '[{"id": "a", "text": "Keep a lit candle nearby for light."}, {"id": "b", "text": "Allow visitors to smoke in another room."}, {"id": "c", "text": "Store the tank right beside the gas stove."}, {"id": "d", "text": "Post an ''Oxygen In Use'' sign on the door."}]'::jsonb, '["d"]', 'An ''Oxygen In Use'' sign should be posted on the door. Smoking is not allowed anywhere in the home, and open flames are avoided near oxygen.'),
  ('bronchitis', 37, 'A client using home oxygen has a gas stove in the kitchen. Which instruction should the nurse give about tank placement?', '[{"id": "a", "text": "Keep the tank 2–3 meters from the stove."}, {"id": "b", "text": "Store the tank in a cabinet above the stove."}, {"id": "c", "text": "Keep the tank 0.5 meter from the stove."}, {"id": "d", "text": "Keep the tank beside the stove when it is off."}]'::jsonb, '["a"]', 'Oxygen tanks should be kept 2–3 meters away from gas sources. Half a meter or storage beside or above the stove is too close.'),
  ('bronchitis', 38, 'Which statement by the spouse of a client using home oxygen indicates a need for further teaching?', '[{"id": "a", "text": "We will put an oxygen sign on our front door."}, {"id": "b", "text": "We will not light candles near her oxygen."}, {"id": "c", "text": "I can smoke in the living room while she rests."}, {"id": "d", "text": "I will keep her tank away from the gas stove."}]'::jsonb, '["c"]', 'There should be no smoking in the home of a client using oxygen, so smoking in another room is unsafe. Posting a sign, keeping the tank from gas sources, and avoiding flames are correct.'),
  ('bronchitis', 39, 'Which item should the nurse instruct the family to remove from the room of a client with chronic bronchitis who uses home oxygen?', '[{"id": "a", "text": "A suction device"}, {"id": "b", "text": "Extra pillows"}, {"id": "c", "text": "A bedside humidifier"}, {"id": "d", "text": "Lit candles"}]'::jsonb, '["d"]', 'Open flames must be avoided near O₂ equipment. A humidifier and suction device are recommended bedside items for mucus clearance.'),
  ('bronchitis', 40, 'How often should the nurse advise a client with chronic bronchitis to receive the influenza vaccine?', '[{"id": "a", "text": "Every year"}, {"id": "b", "text": "Once in a lifetime"}, {"id": "c", "text": "Every 5 years"}, {"id": "d", "text": "Only when symptomatic"}]'::jsonb, '["a"]', 'An annual flu vaccine is recommended to prevent exacerbations. A single or 5-year schedule does not meet this recommendation.'),
  ('bronchitis', 41, 'A client with chronic bronchitis asks why the pneumococcal vaccine is recommended. Which response by the nurse is accurate?', '[{"id": "a", "text": "It replaces your yearly flu vaccine."}, {"id": "b", "text": "It thins the mucus in your lungs."}, {"id": "c", "text": "It treats your current bronchitis."}, {"id": "d", "text": "It helps prevent bacterial pneumonia."}]'::jsonb, '["d"]', 'The pneumococcal vaccine prevents bacterial pneumonia. It does not replace the annual flu vaccine; both are recommended.'),
  ('bronchitis', 42, 'Which statement by a client with chronic bronchitis indicates a need for further teaching about vaccinations?', '[{"id": "a", "text": "The pneumonia vaccine helps protect my lungs."}, {"id": "b", "text": "I will get my flu shot every year."}, {"id": "c", "text": "Vaccines will not affect my flare-ups."}, {"id": "d", "text": "I will get my COVID-19 booster as recommended."}]'::jsonb, '["c"]', 'Flu and pneumonia vaccines prevent exacerbations, so believing vaccines do not affect flare-ups is incorrect. The other statements match recommended vaccinations.'),
  ('bronchitis', 43, 'Which sequence correctly describes how cor pulmonale develops in a client with chronic bronchitis?', '[{"id": "a", "text": "Chronic hypoxia, vasoconstriction, pulmonary hypertension, right ventricular failure"}, {"id": "b", "text": "Vasoconstriction, right ventricular failure, chronic hypoxia, pulmonary hypertension"}, {"id": "c", "text": "Right ventricular failure, pulmonary hypertension, chronic hypoxia, vasoconstriction"}, {"id": "d", "text": "Pulmonary hypertension, chronic hypoxia, right ventricular failure, vasoconstriction"}]'::jsonb, '["a"]', 'Chronic hypoxia causes pulmonary vasoconstriction and pulmonary hypertension; the right ventricle works harder and eventually fails. Sequences beginning with ventricular failure reverse cause and effect.'),
  ('bronchitis', 44, 'Which new finding in a client with chronic bronchitis should the nurse report as a possible sign of cor pulmonale?', '[{"id": "a", "text": "Thick, tenacious sputum"}, {"id": "b", "text": "Persistent productive cough"}, {"id": "c", "text": "Expiratory wheezing"}, {"id": "d", "text": "Jugular vein distention"}]'::jsonb, '["d"]', 'JVD is a sign of cor pulmonale, along with peripheral edema, hepatomegaly, and ascites. Productive cough, wheezes, and thick sputum are expected findings of chronic bronchitis itself.'),
  ('bronchitis', 45, 'A client with long-standing chronic bronchitis has new abdominal distention from ascites and an enlarged liver. The nurse suspects which complication?', '[{"id": "a", "text": "Inhaled steroid adverse effect"}, {"id": "b", "text": "Cor pulmonale"}, {"id": "c", "text": "Mucolytic adverse effect"}, {"id": "d", "text": "Bacterial pneumonia"}]'::jsonb, '["b"]', 'Hepatomegaly and ascites are signs of cor pulmonale, the right-sided heart failure that complicates COPD. They are not described as medication effects.'),
  ('bronchitis', 46, 'A client with chronic bronchitis is diagnosed with cor pulmonale. Which treatment plan should the nurse anticipate?', '[{"id": "a", "text": "Treating the COPD and giving diuretics"}, {"id": "b", "text": "Giving high-flow oxygen continuously"}, {"id": "c", "text": "Giving antibiotics as the only therapy"}, {"id": "d", "text": "Increasing fluids to 4–5 L daily"}]'::jsonb, '["a"]', 'Cor pulmonale is treated by treating the underlying COPD plus diuretics for fluid overload. High-flow oxygen is never used in COPD.'),
  ('bronchitis', 47, 'Which statement best defines cor pulmonale?', '[{"id": "a", "text": "Right-sided heart failure from valve disease"}, {"id": "b", "text": "Right-sided heart failure caused by lung disease"}, {"id": "c", "text": "Lung infection caused by heart failure"}, {"id": "d", "text": "Left-sided heart failure causing lung fluid"}]'::jsonb, '["b"]', 'Cor pulmonale is right heart failure caused by lung disease. Left-sided failure and valve disease are not the cause.'),
  ('bronchitis', 48, 'Besides influenza and pneumococcal vaccines, which vaccination guidance should the nurse include for a client with chronic bronchitis?', '[{"id": "a", "text": "Delay vaccines until symptoms fully resolve"}, {"id": "b", "text": "Receive vaccines only during exacerbations"}, {"id": "c", "text": "Receive COVID-19 boosters as recommended"}, {"id": "d", "text": "Avoid all other vaccines during treatment"}]'::jsonb, '["c"]', 'A COVID-19 booster as recommended is part of the vaccination teaching. Avoiding or delaying vaccines conflicts with the emphasis on vaccinating to prevent exacerbations.'),
  ('bronchitis', 49, 'A client with chronic bronchitis is tripoding, has thick secretions, and has an SpO₂ of 85% on room air. Which action should the nurse take first?', '[{"id": "a", "text": "Apply oxygen at 10 L/min by simple face mask"}, {"id": "b", "text": "Teach the huff cough technique now"}, {"id": "c", "text": "Apply oxygen by nasal cannula at 1–2 L/min"}, {"id": "d", "text": "Schedule the annual influenza vaccine"}]'::jsonb, '["c"]', 'Tripoding indicates respiratory distress, so low-flow O₂ at 1–2 L/min is the priority; high-flow oxygen is never used in COPD. Teaching and vaccination are important but not first.'),
  ('bronchitis', 50, 'After several days of increased fluids and acetylcysteine, which finding indicates that treatment for a client with chronic bronchitis is effective?', '[{"id": "a", "text": "Sputum is thicker and harder to clear"}, {"id": "b", "text": "Wheezing is louder on lung auscultation"}, {"id": "c", "text": "New swelling appears in both of the ankles"}, {"id": "d", "text": "Secretions are thinner and easier to clear"}]'::jsonb, '["d"]', 'Mucolytics and fluids are given to break down and thin secretions, so thinner sputum shows effectiveness. New ankle swelling suggests cor pulmonale, not improvement.'),
  ('emphysema', 1, 'A client with emphysema is short of breath but has a pink complexion. The nurse understands that the client''s skin color is maintained primarily by which mechanism?', '[{"id": "a", "text": "Compensatory hyperventilation that keeps oxygen near normal"}, {"id": "b", "text": "Polycythemia that increases circulating red blood cells"}, {"id": "c", "text": "Carbon dioxide retention that dilates the skin vessels"}, {"id": "d", "text": "Productive coughing that keeps the airways clear of mucus"}]'::jsonb, '["a"]', 'The pink complexion of emphysema reflects compensatory hyperventilation, which maintains near-normal oxygen, unlike the cyanotic Blue Bloater. Polycythemia is listed as a complication that raises DVT risk, not as the reason for the pink color.'),
  ('emphysema', 2, 'The nurse is assessing a client with emphysema. Which finding best helps distinguish emphysema from chronic bronchitis?', '[{"id": "a", "text": "Productive cough with thick mucus"}, {"id": "b", "text": "Diminished breath sounds"}, {"id": "c", "text": "Bilateral peripheral edema"}, {"id": "d", "text": "Cyanosis of the skin"}]'::jsonb, '["b"]', 'In emphysema, destroyed alveoli mean less lung tissue, so breath sounds are diminished. Productive cough with thick mucus, peripheral edema, and cyanosis are features of the chronic bronchitis Blue Bloater.'),
  ('emphysema', 3, 'A client with emphysema breathes out through pursed lips. A nursing student asks why this helps. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It shortens exhalation so the next breath comes sooner"}, {"id": "b", "text": "It strengthens the diaphragm and reduces accessory muscle use"}, {"id": "c", "text": "It creates back-pressure that keeps airways open during exhalation"}, {"id": "d", "text": "It forces thick mucus up and out of the lower airways"}]'::jsonb, '["c"]', 'Pursed-lip breathing creates back-pressure that keeps airways open during exhalation and prevents air trapping. Strengthening the diaphragm and reducing accessory muscle use describes diaphragmatic breathing, a different technique.'),
  ('emphysema', 4, 'The nurse teaches pursed-lip breathing to a client with emphysema. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Breathing out through pursed lips helps keep my airways open.\""}, {"id": "b", "text": "\"This technique helps prevent air from getting trapped in my lungs.\""}, {"id": "c", "text": "\"I should make my breath out longer than my breath in.\""}, {"id": "d", "text": "\"I should push my breath out as quickly as I can.\""}]'::jsonb, '["d"]', 'Pursed-lip breathing prolongs exhalation to prevent air trapping, so exhaling as quickly as possible shows misunderstanding. The other statements correctly describe keeping airways open, preventing air trapping, and a prolonged exhalation.'),
  ('emphysema', 5, 'While inspecting the chest of a client with long-standing emphysema, the nurse expects to find which chest shape?', '[{"id": "a", "text": "Anteroposterior diameter equal to the lateral diameter"}, {"id": "b", "text": "Anteroposterior diameter about half the lateral diameter"}, {"id": "c", "text": "Ribs pulled inward with a narrowed chest wall"}, {"id": "d", "text": "Flattened anterior chest with a sunken sternum"}]'::jsonb, '["a"]', 'Chronic hyperinflation pushes the ribs outward so the AP diameter equals the lateral diameter, producing a barrel chest. An AP diameter half the lateral diameter would not reflect this hyperinflation.'),
  ('emphysema', 6, 'A client newly diagnosed with emphysema asks why the chest has become rounded like a barrel. The nurse explains that this change results from which process?', '[{"id": "a", "text": "Fluid retention from right-sided heart failure"}, {"id": "b", "text": "Hyperinflation of the lungs from trapped air"}, {"id": "c", "text": "Excess mucus production in the large airways"}, {"id": "d", "text": "Muscle wasting from a high work of breathing"}]'::jsonb, '["b"]', 'Air trapping leads to hyperinflation, which produces the barrel chest and flattened diaphragm. Muscle wasting from the high work of breathing explains cachexia, not the barrel shape.'),
  ('emphysema', 7, 'A client with emphysema asks, "Why does it take me so long to breathe out?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Mucus plugs block your airways each time you breathe in.\""}, {"id": "b", "text": "\"Fluid in your lungs slows the air leaving your air sacs.\""}, {"id": "c", "text": "\"Your airways collapse as you exhale, which slows breathing out.\""}, {"id": "d", "text": "\"Your lungs have become more elastic and hold the air in.\""}]'::jsonb, '["c"]', 'Airway collapse during exhalation prolongs the expiratory phase in emphysema. Emphysema involves a loss of lung elasticity, not an increase, so the statement about more elastic lungs is incorrect.'),
  ('emphysema', 8, 'A nurse is explaining the pathophysiology of emphysema to a client''s family. Which sequence correctly describes how air trapping develops?', '[{"id": "a", "text": "Airway collapse during inhalation → loss of elasticity → air trapping"}, {"id": "b", "text": "Air trapping → loss of elasticity → airway collapse during exhalation"}, {"id": "c", "text": "Increased elasticity → airway narrowing during inhalation → air trapping"}, {"id": "d", "text": "Loss of lung elasticity → airway collapse during exhalation → air trapping"}]'::jsonb, '["d"]', 'Loss of lung elasticity causes airways to collapse during exhalation, which traps air. The collapse occurs during exhalation, not inhalation, and elasticity is lost rather than increased.'),
  ('emphysema', 9, 'A client with a long smoking history has a CT scan showing large air spaces called bullae. The nurse understands that these spaces form because of which process?', '[{"id": "a", "text": "Destruction of alveolar walls by smoke and irritants"}, {"id": "b", "text": "Collection of fluid within the pleural space"}, {"id": "c", "text": "Plugging of the small airways with thick mucus"}, {"id": "d", "text": "Swelling of the bronchial lining from infection"}]'::jsonb, '["a"]', 'Smoke and irritants destroy alveolar walls, creating large air spaces called bullae. Thick mucus plugging is associated with the productive cough of chronic bronchitis, not bullae formation.'),
  ('emphysema', 10, 'A client with emphysema has multiple large bullae seen on imaging. The nurse recognizes that this client is at increased risk for which complication?', '[{"id": "a", "text": "Polycythemia"}, {"id": "b", "text": "Pneumothorax"}, {"id": "c", "text": "Pulmonary hypertension"}, {"id": "d", "text": "Cor pulmonale"}]'::jsonb, '["b"]', 'Pneumothorax is a respiratory complication of emphysema caused by ruptured bullae. Pulmonary hypertension and cor pulmonale are cardiovascular complications not attributed to bullae rupture.'),
  ('emphysema', 11, 'A client with emphysema has had three respiratory infections this year. The nurse understands that frequent infections in emphysema are related to which factor?', '[{"id": "a", "text": "Excessive fluid intake that thins secretions"}, {"id": "b", "text": "Compensatory hyperventilation"}, {"id": "c", "text": "Impaired clearance of mucus"}, {"id": "d", "text": "Increased total lung capacity"}]'::jsonb, '["c"]', 'Frequent infections in emphysema result from impaired mucus clearance. Increased fluid intake is actually recommended to loosen mucus, and increased TLC reflects air trapping.'),
  ('emphysema', 12, 'A client with long-standing emphysema develops new bilateral peripheral edema. The nurse recognizes this finding as a sign of which complication?', '[{"id": "a", "text": "Pneumothorax"}, {"id": "b", "text": "Respiratory acidosis"}, {"id": "c", "text": "Polycythemia"}, {"id": "d", "text": "Cor pulmonale"}]'::jsonb, '["d"]', 'Peripheral edema is linked to cor pulmonale, which is right-sided heart failure. Pneumothorax results from ruptured bullae and respiratory acidosis from CO2 retention; neither is signaled by peripheral edema.'),
  ('emphysema', 13, 'The nurse is reviewing cardiovascular complications of emphysema with a group of nursing students. Which description of cor pulmonale is accurate?', '[{"id": "a", "text": "Right-sided heart failure"}, {"id": "b", "text": "Left-sided heart failure"}, {"id": "c", "text": "Rupture of lung bullae"}, {"id": "d", "text": "A clot in a deep vein"}]'::jsonb, '["a"]', 'Cor pulmonale is right-sided heart failure, a cardiovascular complication of emphysema. Rupture of bullae causes pneumothorax, and a deep vein clot is the DVT risk associated with polycythemia.'),
  ('emphysema', 14, 'Laboratory results for a client with emphysema indicate polycythemia. The nurse should monitor this client closely for which complication?', '[{"id": "a", "text": "Pneumothorax"}, {"id": "b", "text": "Deep vein thrombosis"}, {"id": "c", "text": "Respiratory alkalosis"}, {"id": "d", "text": "Frequent infections"}]'::jsonb, '["b"]', 'Polycythemia in emphysema increases the risk of deep vein thrombosis. Pneumothorax is caused by ruptured bullae, and frequent infections result from impaired mucus clearance.'),
  ('emphysema', 15, 'A client with late-stage emphysema has arterial blood gases drawn. Which pattern does the nurse expect?', '[{"id": "a", "text": "Decreased CO2, decreased O2, increased pH"}, {"id": "b", "text": "Increased CO2, increased O2, increased pH"}, {"id": "c", "text": "Increased CO2, decreased O2, decreased pH"}, {"id": "d", "text": "Decreased CO2, increased O2, decreased pH"}]'::jsonb, '["c"]', 'Late-stage emphysema ABGs show increased CO2, decreased O2, and decreased pH, consistent with respiratory acidosis. A decreased CO2 with increased pH does not reflect the CO2 retention of late disease.'),
  ('emphysema', 16, 'A client with emphysema is retaining carbon dioxide. The nurse recognizes that this places the client at risk for which acid-base imbalance?', '[{"id": "a", "text": "Respiratory alkalosis"}, {"id": "b", "text": "Metabolic alkalosis"}, {"id": "c", "text": "Metabolic acidosis"}, {"id": "d", "text": "Respiratory acidosis"}]'::jsonb, '["d"]', 'CO2 retention in emphysema creates a risk of respiratory acidosis. Respiratory alkalosis would not result from retaining CO2.'),
  ('emphysema', 17, 'Pulmonary function tests are performed on a client suspected of having emphysema. Which results support this diagnosis?', '[{"id": "a", "text": "Decreased FEV1/FVC ratio and increased TLC"}, {"id": "b", "text": "Increased FEV1/FVC ratio and decreased TLC"}, {"id": "c", "text": "Decreased FEV1/FVC ratio and decreased TLC"}, {"id": "d", "text": "Increased FEV1/FVC ratio and increased TLC"}]'::jsonb, '["a"]', 'Emphysema produces an obstructive pattern with a decreased FEV1/FVC ratio and an increased TLC from air trapping. A decreased TLC would not reflect air trapping.'),
  ('emphysema', 18, 'A client''s pulmonary function tests show an increased total lung capacity (TLC). The nurse interprets this finding as evidence of which process in emphysema?', '[{"id": "a", "text": "Improved gas exchange"}, {"id": "b", "text": "Air trapping"}, {"id": "c", "text": "Increased lung elasticity"}, {"id": "d", "text": "Fluid overload"}]'::jsonb, '["b"]', 'An increased TLC in emphysema reflects air trapping. Emphysema involves loss of lung elasticity and decreased surface area for gas exchange, so the other interpretations are incorrect.'),
  ('emphysema', 19, 'The nurse reviews the chest X-ray report of a client with emphysema. Which findings does the nurse expect?', '[{"id": "a", "text": "Small lung volumes with an elevated diaphragm"}, {"id": "b", "text": "Normal lung volumes with a decreased AP diameter"}, {"id": "c", "text": "Hyperinflated lungs with a flattened diaphragm"}, {"id": "d", "text": "Collapsed lung bases with an elevated diaphragm"}]'::jsonb, '["c"]', 'The chest X-ray in emphysema shows hyperinflated lungs, a flattened diaphragm, and an increased AP diameter. An elevated diaphragm or small lung volumes contradict the hyperinflation of emphysema.'),
  ('emphysema', 20, 'The provider wants to visualize bullae in a client with suspected emphysema. The nurse anticipates preparing the client for which test?', '[{"id": "a", "text": "Arterial blood gas"}, {"id": "b", "text": "Pulmonary function tests"}, {"id": "c", "text": "Pulse oximetry"}, {"id": "d", "text": "CT scan"}]'::jsonb, '["d"]', 'A CT scan shows bullae, the destroyed alveolar spaces of emphysema. PFTs show an obstructive pattern and air trapping, and ABGs show gas exchange values, but neither visualizes bullae.'),
  ('emphysema', 21, 'A 34-year-old client who has never smoked is diagnosed with emphysema. The nurse anticipates testing for which underlying cause?', '[{"id": "a", "text": "Alpha-1 antitrypsin deficiency"}, {"id": "b", "text": "Pulmonary hypertension"}, {"id": "c", "text": "Cor pulmonale"}, {"id": "d", "text": "Polycythemia"}]'::jsonb, '["a"]', 'Alpha-1 antitrypsin deficiency is a genetic risk factor that causes emphysema even in non-smokers. Pulmonary hypertension, cor pulmonale, and polycythemia are complications of emphysema, not causes.'),
  ('emphysema', 22, 'During a community health presentation, a participant asks about the leading cause of emphysema. The nurse identifies which risk factor as the number one cause?', '[{"id": "a", "text": "Air pollution"}, {"id": "b", "text": "Smoking"}, {"id": "c", "text": "Alpha-1 antitrypsin deficiency"}, {"id": "d", "text": "Chronic respiratory infections"}]'::jsonb, '["b"]', 'Smoking is the number one cause of emphysema because it destroys alveolar walls. Alpha-1 antitrypsin deficiency, air pollution, and chronic infections are risk factors but not the leading cause.'),
  ('emphysema', 23, 'The nurse is screening clients at a community clinic. Which client has a recognized risk factor for emphysema?', '[{"id": "a", "text": "A client who follows a high-protein diet"}, {"id": "b", "text": "A client who drinks 2 to 3 L of fluid daily"}, {"id": "c", "text": "A client with occupational dust exposure"}, {"id": "d", "text": "A client who practices diaphragmatic breathing"}]'::jsonb, '["c"]', 'Air pollution and occupational dust exposure are risk factors for emphysema. A high-protein diet, 2 to 3 L of fluid daily, and diaphragmatic breathing are recommended home-management measures, not risk factors.'),
  ('emphysema', 24, 'A client with emphysema becomes short of breath while walking in the hallway. Which action should the nurse take first?', '[{"id": "a", "text": "Apply oxygen by non-rebreather mask at a high flow"}, {"id": "b", "text": "Assist the client to lie flat in the nearest bed"}, {"id": "c", "text": "Instruct the client to exhale as quickly as possible"}, {"id": "d", "text": "Coach the client to use pursed-lip breathing"}]'::jsonb, '["d"]', 'Pursed-lip breathing is the number one priority action because it prolongs exhalation and prevents air trapping. Oxygen in emphysema should be low-flow, 1 to 2 L/min by nasal cannula, not high-flow.'),
  ('emphysema', 25, 'The nurse is positioning a client with emphysema who reports dyspnea. Which position is most appropriate?', '[{"id": "a", "text": "High Fowler''s"}, {"id": "b", "text": "Supine"}, {"id": "c", "text": "Prone"}, {"id": "d", "text": "Trendelenburg"}]'::jsonb, '["a"]', 'High Fowler''s position optimizes breathing mechanics for the client with emphysema. Lying supine or head-down positions do not provide this benefit.'),
  ('emphysema', 26, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a client with emphysema. Which action by the UAP requires correction?', '[{"id": "a", "text": "Raising the head of the bed to high Fowler''s"}, {"id": "b", "text": "Lowering the bed flat so the client can rest"}, {"id": "c", "text": "Offering the client small, frequent snacks"}, {"id": "d", "text": "Asking a visitor not to wear strong perfume"}]'::jsonb, '["b"]', 'High Fowler''s position optimizes breathing mechanics, so lowering the bed flat needs correction. Small frequent meals and avoiding perfumes are appropriate parts of emphysema care.'),
  ('emphysema', 27, 'Oxygen is prescribed for a client admitted with emphysema. Which oxygen order does the nurse anticipate?', '[{"id": "a", "text": "10 L/min by non-rebreather mask"}, {"id": "b", "text": "6 L/min by nasal cannula"}, {"id": "c", "text": "1 to 2 L/min by nasal cannula"}, {"id": "d", "text": "15 L/min by non-rebreather mask"}]'::jsonb, '["c"]', 'Clients with emphysema receive low-flow oxygen at 1 to 2 L/min via nasal cannula. Higher flows such as 6 L/min or non-rebreather settings are not low-flow oxygen.'),
  ('emphysema', 28, 'The nurse is titrating supplemental oxygen for a client with emphysema. Which oxygen saturation (SpO2) range is the target?', '[{"id": "a", "text": "80% to 84%"}, {"id": "b", "text": "95% to 98%"}, {"id": "c", "text": "99% to 100%"}, {"id": "d", "text": "88% to 92%"}]'::jsonb, '["d"]', 'Oxygen for emphysema is low-flow and targets an SpO2 of 88% to 92%. Aiming for 95% or higher would require more oxygen than this target calls for.'),
  ('emphysema', 29, 'A client with emphysema receiving oxygen at 2 L/min by nasal cannula has an SpO2 of 90%. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Continue the current low-flow oxygen"}, {"id": "b", "text": "Increase the flow to reach an SpO2 of 98%"}, {"id": "c", "text": "Change to a high-flow non-rebreather mask"}, {"id": "d", "text": "Increase the nasal cannula to 6 L/min"}]'::jsonb, '["a"]', 'An SpO2 of 90% is within the 88% to 92% target for low-flow oxygen, so the current therapy should continue. Increasing oxygen to reach 98% exceeds the target range.'),
  ('emphysema', 30, 'A client is admitted with an emphysema exacerbation. Which medications does the nurse anticipate will be prescribed as bronchodilators?', '[{"id": "a", "text": "Corticosteroids and albuterol"}, {"id": "b", "text": "Albuterol and ipratropium"}, {"id": "c", "text": "Ipratropium and corticosteroids"}, {"id": "d", "text": "Corticosteroids alone"}]'::jsonb, '["b"]', 'The bronchodilators used in emphysema are albuterol (a SABA) and ipratropium. Corticosteroids are given for inflammation during exacerbations, not as bronchodilators.'),
  ('emphysema', 31, 'A client with an emphysema exacerbation is started on a corticosteroid and asks what the medication is for. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It acts as a short-acting bronchodilator.\""}, {"id": "b", "text": "\"It thins your mucus so you can cough it up.\""}, {"id": "c", "text": "\"It reduces inflammation during this flare-up.\""}, {"id": "d", "text": "\"It replaces your need for oxygen therapy.\""}]'::jsonb, '["c"]', 'Corticosteroids are used for inflammation during exacerbations of emphysema. The short-acting bronchodilator is albuterol, not a corticosteroid.'),
  ('emphysema', 32, 'A client with emphysema who smokes one pack of cigarettes a day asks which change would do the most to help. Which response by the nurse is best?', '[{"id": "a", "text": "\"Increase your home oxygen flow rate.\""}, {"id": "b", "text": "\"Eat three large meals each day.\""}, {"id": "c", "text": "\"Add more carbohydrates to your diet.\""}, {"id": "d", "text": "\"Stop smoking completely.\""}]'::jsonb, '["d"]', 'Smoking cessation is the most important intervention for emphysema. Large meals push the diaphragm up and high-carbohydrate foods increase CO2 production, so those suggestions are harmful.'),
  ('emphysema', 33, 'The nurse is developing a plan of care for a client with stable emphysema. Which intervention is appropriate to include?', '[{"id": "a", "text": "Referral to pulmonary rehab with breathing exercises"}, {"id": "b", "text": "High-carbohydrate nutritional supplements"}, {"id": "c", "text": "Fluid restriction to 1 L per day"}, {"id": "d", "text": "Three large meals daily to maintain weight"}]'::jsonb, '["a"]', 'Pulmonary rehab and breathing exercises are priority interventions for emphysema. Fluids should be increased to 2 to 3 L/day to loosen mucus, not restricted, and high-carbohydrate foods should be avoided.'),
  ('emphysema', 34, 'A client with emphysema asks which type of diet is recommended. The nurse should recommend a diet that is:', '[{"id": "a", "text": "High in carbohydrates and low in fat"}, {"id": "b", "text": "High in protein and high in fat"}, {"id": "c", "text": "Low in protein and high in carbohydrates"}, {"id": "d", "text": "Low in fat and low in protein"}]'::jsonb, '["b"]', 'Clients with emphysema should avoid high-carbohydrate diets and eat high-protein, high-fat foods instead. Carbohydrate-heavy diets produce more CO2 during metabolism.'),
  ('emphysema', 35, 'A client with emphysema and hypercapnia asks why carbohydrates should be limited. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Carbohydrates cause your body to retain fluid.\""}, {"id": "b", "text": "\"Carbohydrates make your mucus thicker.\""}, {"id": "c", "text": "\"Carbohydrate metabolism produces more carbon dioxide.\""}, {"id": "d", "text": "\"Carbohydrates increase your appetite too much.\""}]'::jsonb, '["c"]', 'Carbohydrate metabolism produces more CO2 than fat or protein metabolism, which worsens hypercapnia. Fluid retention and thicker mucus are not the reasons given for limiting carbohydrates.'),
  ('emphysema', 36, 'The nurse reviews meal selections made by a client with emphysema. Which selection best reflects the dietary teaching?', '[{"id": "a", "text": "A large bowl of pasta with garlic bread"}, {"id": "b", "text": "Pancakes with syrup and orange juice"}, {"id": "c", "text": "White rice with a baked potato"}, {"id": "d", "text": "Grilled chicken with avocado and cheese"}]'::jsonb, '["d"]', 'Clients with emphysema should avoid high-carbohydrate foods and choose high-protein, high-fat options. Pasta, pancakes, rice, and potatoes are carbohydrate-heavy and increase CO2 production.'),
  ('emphysema', 37, 'A client with emphysema has thick secretions that are difficult to expectorate. Which daily fluid intake should the nurse encourage?', '[{"id": "a", "text": "2 to 3 L per day"}, {"id": "b", "text": "500 mL per day"}, {"id": "c", "text": "1 L per day"}, {"id": "d", "text": "5 to 6 L per day"}]'::jsonb, '["a"]', 'Clients with emphysema should increase fluids to 2 to 3 L/day to loosen mucus. Lower intakes such as 500 mL or 1 L would not meet this goal.'),
  ('emphysema', 38, 'The nurse is monitoring a client with emphysema for cardiovascular complications of the disease. Which complication is the nurse monitoring for?', '[{"id": "a", "text": "Pneumothorax"}, {"id": "b", "text": "Pulmonary hypertension"}, {"id": "c", "text": "Respiratory acidosis"}, {"id": "d", "text": "Frequent infections"}]'::jsonb, '["b"]', 'Pulmonary hypertension is a cardiovascular complication of emphysema, along with cor pulmonale and polycythemia. Pneumothorax, respiratory acidosis, and frequent infections are respiratory complications.'),
  ('emphysema', 39, 'A client with emphysema reports becoming breathless during meals. Which recommendation by the nurse is most appropriate?', '[{"id": "a", "text": "\"Eat three large meals at set times.\""}, {"id": "b", "text": "\"Lie flat for 30 minutes after eating.\""}, {"id": "c", "text": "\"Eat small, frequent meals during the day.\""}, {"id": "d", "text": "\"Skip meals when you feel short of breath.\""}]'::jsonb, '["c"]', 'Frequent small meals prevent breathlessness while eating because big meals push the diaphragm up. Three large meals would worsen breathlessness for the same reason.'),
  ('emphysema', 40, 'The nurse is evaluating discharge teaching for a client with emphysema. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will drink 2 to 3 liters of fluid each day.\""}, {"id": "b", "text": "\"I will choose foods high in protein and fat.\""}, {"id": "c", "text": "\"I will stay away from smoke and strong perfumes.\""}, {"id": "d", "text": "\"I will eat one big meal a day so I don''t tire out.\""}]'::jsonb, '["d"]', 'Big meals push the diaphragm up and cause breathlessness, so frequent small meals are recommended. Drinking 2 to 3 L of fluid, eating high-protein, high-fat foods, and avoiding smoke and perfumes are correct.'),
  ('emphysema', 41, 'A client with emphysema is planning activities for the winter months. Which activity should the nurse advise the client to avoid?', '[{"id": "a", "text": "Walking outdoors in cold air"}, {"id": "b", "text": "Practicing diaphragmatic breathing"}, {"id": "c", "text": "Drinking extra fluids during the day"}, {"id": "d", "text": "Eating small, frequent meals"}]'::jsonb, '["a"]', 'Cold air is a respiratory irritant that clients with emphysema should avoid. Diaphragmatic breathing, increased fluids, and small frequent meals are recommended home-management measures.'),
  ('emphysema', 42, 'The nurse teaches a client with emphysema about avoiding respiratory irritants. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll stay indoors on days when air pollution is high.\""}, {"id": "b", "text": "\"I can keep wearing my favorite strong perfume.\""}, {"id": "c", "text": "\"I''ll ask my family not to smoke around me.\""}, {"id": "d", "text": "\"I''ll limit my time outside in very cold air.\""}]'::jsonb, '["b"]', 'Perfumes are respiratory irritants that should be avoided along with smoke, cold air, and pollution. The other statements correctly describe avoiding these irritants.'),
  ('emphysema', 43, 'A client with emphysema is learning diaphragmatic breathing and asks how it differs from pursed-lip breathing. Which statement about diaphragmatic breathing is accurate?', '[{"id": "a", "text": "It creates back-pressure to keep the airways open as you exhale."}, {"id": "b", "text": "It increases the amount of air trapped within the lungs."}, {"id": "c", "text": "It strengthens the diaphragm and reduces accessory muscle use."}, {"id": "d", "text": "It shortens exhalation so that breathing takes less energy."}]'::jsonb, '["c"]', 'Diaphragmatic breathing strengthens the diaphragm and reduces accessory muscle use. Creating back-pressure to keep airways open during exhalation describes pursed-lip breathing.'),
  ('emphysema', 44, 'The nurse is caring for one client with emphysema and another with chronic bronchitis. Which finding is more expected in the client with chronic bronchitis?', '[{"id": "a", "text": "Pursed-lip breathing"}, {"id": "b", "text": "Barrel chest"}, {"id": "c", "text": "Thin, cachexic appearance"}, {"id": "d", "text": "Cyanosis"}]'::jsonb, '["d"]', 'Cyanosis from poor oxygenation is the ''blue'' of the chronic bronchitis Blue Bloater. Pursed-lip breathing, barrel chest, and a thin, cachexic appearance are features of the emphysema Pink Puffer.'),
  ('emphysema', 45, 'A client with emphysema has lost weight and shows muscle wasting. The nurse understands that this is mainly caused by which factors?', '[{"id": "a", "text": "High work of breathing and decreased appetite"}, {"id": "b", "text": "Fluid shifts from worsening peripheral edema"}, {"id": "c", "text": "A diet that is high in protein and high in fat"}, {"id": "d", "text": "Drinking 2 to 3 L of fluid every day"}]'::jsonb, '["a"]', 'Cachexia in emphysema is weight loss and muscle wasting from the high work of breathing and decreased appetite. A high-protein, high-fat diet is the recommended diet, not a cause of wasting.'),
  ('emphysema', 46, 'The nurse auscultates the lungs of a client with emphysema. Which findings does the nurse expect?', '[{"id": "a", "text": "Coarse crackles with a productive cough"}, {"id": "b", "text": "Diminished sounds with prolonged expiration"}, {"id": "c", "text": "Loud breath sounds with a short expiration"}, {"id": "d", "text": "Clear sounds with a shortened expiratory phase"}]'::jsonb, '["b"]', 'Emphysema produces diminished breath sounds and prolonged expiration with wheezing. Crackles with a productive cough are features of chronic bronchitis.'),
  ('emphysema', 47, 'Which statement by a client with emphysema is most consistent with the typical course of the disease?', '[{"id": "a", "text": "\"My breathing problems come and go and clear up completely in between.\""}, {"id": "b", "text": "\"I cough up large amounts of thick mucus every single day.\""}, {"id": "c", "text": "\"My shortness of breath with activity has slowly gotten worse over the years.\""}, {"id": "d", "text": "\"My ankles swell, and I have gained a lot of weight.\""}]'::jsonb, '["c"]', 'Dyspnea on exertion in emphysema is progressive and worsens over time with activity. Daily thick mucus, ankle swelling, and weight gain describe the chronic bronchitis Blue Bloater.'),
  ('emphysema', 48, 'A nursing student asks why clients with emphysema become hypoxic. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Lung elasticity increases and limits each inhalation."}, {"id": "b", "text": "Fluid collects in the alveoli and blocks diffusion."}, {"id": "c", "text": "Excess mucus production fills the alveolar spaces."}, {"id": "d", "text": "Destroyed alveoli leave less surface area for gas exchange."}]'::jsonb, '["d"]', 'Destruction of alveoli decreases the surface area for gas exchange, leading to hypoxia. Emphysema involves a loss of lung elasticity, not an increase.'),
  ('emphysema', 49, 'A nursing student asks why emphysema is nicknamed the "Pink Puffer." The nurse explains that the nickname refers to which two features?', '[{"id": "a", "text": "Pink complexion and pursed-lip breathing"}, {"id": "b", "text": "Cyanosis and peripheral edema"}, {"id": "c", "text": "Pink sputum and coarse crackles"}, {"id": "d", "text": "Flushed skin and a productive cough"}]'::jsonb, '["a"]', 'The Pink Puffer nickname reflects a pink complexion plus pursed-lip breathing. Cyanosis and peripheral edema describe the chronic bronchitis Blue Bloater.'),
  ('emphysema', 50, 'The chest X-ray of a client with emphysema shows a flattened diaphragm. The nurse recognizes this finding as the result of which process?', '[{"id": "a", "text": "Fluid accumulation from cor pulmonale"}, {"id": "b", "text": "Chronic hyperinflation of the lungs"}, {"id": "c", "text": "Collapse of alveoli at the lung bases"}, {"id": "d", "text": "Weakening of the diaphragm from cachexia"}]'::jsonb, '["b"]', 'Hyperinflation in emphysema produces a barrel chest and a flattened diaphragm. Cor pulmonale is associated with peripheral edema, not a flattened diaphragm.'),
  ('hemo_pneumo', 1, 'A client arrives in the emergency department with a stab wound to the chest. The nurse hears air moving in and out of the wound with each breath. Which action should the nurse take first?', '[{"id": "a", "text": "Prepare for needle decompression at the 2nd ICS"}, {"id": "b", "text": "Apply a sterile dressing taped on all four sides"}, {"id": "c", "text": "Apply a sterile dressing taped on three sides"}, {"id": "d", "text": "Obtain a chest X-ray before any treatment"}]'::jsonb, '["c"]', 'Audible air movement through a penetrating wound indicates an open (sucking) chest wound, which is treated with a 3-sided vented dressing. A fully occlusive four-sided dressing is specifically not used; needle decompression is the treatment for tension pneumothorax.'),
  ('hemo_pneumo', 2, 'The nurse applies a vented dressing to a client''s sucking chest wound and leaves one side untaped. The nurse explains that the untaped side is intended to:', '[{"id": "a", "text": "let air vent out during exhalation"}, {"id": "b", "text": "allow blood to drain from the pleural space"}, {"id": "c", "text": "draw air into the chest during inhalation"}, {"id": "d", "text": "provide an opening for chest tube insertion"}]'::jsonb, '["a"]', 'The 3-sided dressing is taped on three sides with one side left open so air can vent out during exhalation. The open side is not meant to let air enter on inhalation.'),
  ('hemo_pneumo', 3, 'A client receiving mechanical ventilation after a motor vehicle crash suddenly develops absent breath sounds on the right, BP 80/50 mm Hg, HR 132/min, distended neck veins, and a trachea shifted to the left. These findings are most consistent with which condition?', '[{"id": "a", "text": "Open pneumothorax"}, {"id": "b", "text": "Tension pneumothorax"}, {"id": "c", "text": "Hemothorax"}, {"id": "d", "text": "Spontaneous pneumothorax"}]'::jsonb, '["b"]', 'Tracheal deviation away from the affected side with hypotension, tachycardia, JVD, and absent breath sounds are the classic signs of tension pneumothorax. An open pneumothorax is identified by air movement heard through a chest wound.'),
  ('hemo_pneumo', 4, 'A client has a tension pneumothorax on the left side. When assessing tracheal position, which finding does the nurse expect?', '[{"id": "a", "text": "Trachea shifted toward the left"}, {"id": "b", "text": "Trachea shifting side to side with breaths"}, {"id": "c", "text": "Trachea midline and stable"}, {"id": "d", "text": "Trachea shifted toward the right"}]'::jsonb, '["d"]', 'In tension pneumothorax the trachea deviates away from the affected side, so a left-sided tension pneumothorax shifts the trachea to the right. Deviation toward the left reverses the direction.'),
  ('hemo_pneumo', 5, 'A trauma client shows signs of tension pneumothorax. A portable chest X-ray has been ordered but not yet performed. Which action is the priority?', '[{"id": "a", "text": "Apply a 3-sided vented dressing to the chest"}, {"id": "b", "text": "Wait for the chest X-ray to confirm the diagnosis"}, {"id": "c", "text": "Prepare for immediate needle decompression"}, {"id": "d", "text": "Instruct the client to take a deep breath and bear down"}]'::jsonb, '["c"]', 'Needle decompression is the first priority in tension pneumothorax, and the nurse should not wait for an X-ray. A 3-sided dressing is the emergency treatment for an open sucking chest wound.'),
  ('hemo_pneumo', 6, 'The nurse is assisting with emergency needle decompression for a tension pneumothorax. At which location does the nurse anticipate the needle will be inserted?', '[{"id": "a", "text": "5th intercostal space, midclavicular line"}, {"id": "b", "text": "2nd intercostal space, midaxillary line"}, {"id": "c", "text": "4th intercostal space, midaxillary line"}, {"id": "d", "text": "2nd intercostal space, midclavicular line"}]'::jsonb, '["d"]', 'Needle decompression is performed at the 2nd intercostal space in the midclavicular line, followed by a chest tube. The other sites do not match this landmark.'),
  ('hemo_pneumo', 7, 'Needle decompression has just been performed for a client''s tension pneumothorax. Which intervention should the nurse prepare for next?', '[{"id": "a", "text": "Application of a 3-sided vented dressing"}, {"id": "b", "text": "Oxygen and observation only"}, {"id": "c", "text": "A fully occlusive dressing over the site"}, {"id": "d", "text": "Insertion of a chest tube"}]'::jsonb, '["d"]', 'Treatment of tension pneumothorax is needle decompression at the 2nd ICS midclavicular line followed by a chest tube. Oxygen and observation is an option for spontaneous pneumothorax, not tension.'),
  ('hemo_pneumo', 8, 'A nursing student is discussing tension pneumothorax. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "Air enters the pleural space but cannot escape."}, {"id": "b", "text": "Needle decompression is done without waiting for an X-ray."}, {"id": "c", "text": "Tracheal deviation is an early warning sign."}, {"id": "d", "text": "Pressure buildup can shift the mediastinum."}]'::jsonb, '["c"]', 'Tracheal deviation in tension pneumothorax is a late, ominous sign, not an early one. The other statements correctly describe the one-way valve effect, mediastinal shift, and decompression without waiting for an X-ray.'),
  ('hemo_pneumo', 9, 'Which pathophysiologic process explains the development of a tension pneumothorax?', '[{"id": "a", "text": "Air enters the pleural space but cannot escape"}, {"id": "b", "text": "Air moves freely in and out through a chest wall wound"}, {"id": "c", "text": "Blood collects and sinks to the base of the pleural space"}, {"id": "d", "text": "Air becomes trapped under the skin of the chest wall"}]'::jsonb, '["a"]', 'Tension pneumothorax results from a one-way valve effect: air enters the pleural space but cannot escape, so pressure builds and the mediastinum shifts. Air moving in and out through a wound describes an open pneumothorax.'),
  ('hemo_pneumo', 10, 'The nurse is reviewing the histories of four clients. Which client is at greatest risk for a spontaneous pneumothorax?', '[{"id": "a", "text": "A 60-year-old with chest bleeding after surgery"}, {"id": "b", "text": "A 50-year-old with rib fractures from a fall"}, {"id": "c", "text": "A 30-year-old with a penetrating stab wound"}, {"id": "d", "text": "A tall, thin 19-year-old male who smokes"}]'::jsonb, '["d"]', 'Spontaneous pneumothorax occurs without trauma, and the risk profile includes tall, thin young males and smokers. Rib fractures and penetrating wounds are traumatic causes of closed and open pneumothorax.'),
  ('hemo_pneumo', 11, 'A client with no history of injury asks what caused the lung to collapse suddenly. The nurse explains that a spontaneous pneumothorax is caused by:', '[{"id": "a", "text": "pressure injury from a mechanical ventilator"}, {"id": "b", "text": "blood collecting in the pleural space"}, {"id": "c", "text": "rupture of a small air-filled blister on the lung"}, {"id": "d", "text": "air entering through an opening in the chest wall"}]'::jsonb, '["c"]', 'A spontaneous pneumothorax involves no trauma and results from a ruptured bleb, a small air-filled blister on the lung surface. Ventilator barotrauma is listed as a cause of closed pneumothorax.'),
  ('hemo_pneumo', 12, 'A 22-year-old client who smokes is resting in a chair when a spontaneous pneumothorax occurs. Which presentation does the nurse expect?', '[{"id": "a", "text": "Gradual dyspnea that develops over several weeks"}, {"id": "b", "text": "Sudden sharp chest pain with shortness of breath"}, {"id": "c", "text": "Audible air movement through a chest wall wound"}, {"id": "d", "text": "Bright red drainage from the chest wall"}]'::jsonb, '["b"]', 'Spontaneous pneumothorax has a sudden onset of sharp chest pain and dyspnea, often at rest. Air heard moving through a wound indicates an open pneumothorax from penetrating trauma.'),
  ('hemo_pneumo', 13, 'Which treatment plan does the nurse recognize as appropriate for a client with a spontaneous pneumothorax?', '[{"id": "a", "text": "Oxygen with observation, or a chest tube"}, {"id": "b", "text": "Valsalva maneuver followed by an occlusive dressing"}, {"id": "c", "text": "Chest tube that is milked to speed re-expansion"}, {"id": "d", "text": "3-sided vented dressing followed by observation"}]'::jsonb, '["a"]', 'Spontaneous pneumothorax is treated with oxygen and observation or a chest tube. A 3-sided dressing is for an open wound, and a chest tube must never be milked.'),
  ('hemo_pneumo', 14, 'Which client situation is an example of a closed pneumothorax?', '[{"id": "a", "text": "A client has a chest wound through which air can be heard moving"}, {"id": "b", "text": "A ventilated client develops barotrauma with no external wound"}, {"id": "c", "text": "A client has blood collecting in the pleural space after surgery"}, {"id": "d", "text": "A client has both blood and air in the pleural space after a stabbing"}]'::jsonb, '["b"]', 'A closed pneumothorax has no external wound; air enters the pleural space internally, and mechanical ventilation barotrauma is a listed cause. Air heard moving through a wound describes an open pneumothorax.'),
  ('hemo_pneumo', 15, 'A client with rib fractures from blunt trauma develops a closed pneumothorax. Which assessment finding does the nurse expect?', '[{"id": "a", "text": "Increased breath sounds on the affected side"}, {"id": "b", "text": "Air movement heard through a chest wound"}, {"id": "c", "text": "Tracheal deviation toward the affected side"}, {"id": "d", "text": "Decreased or absent breath sounds"}]'::jsonb, '["d"]', 'Signs of a closed pneumothorax include decreased or absent breath sounds, chest pain, and dyspnea. Air heard moving through a wound is characteristic of an open pneumothorax.'),
  ('hemo_pneumo', 16, 'A provider prepares to insert a chest tube for a client with a hemothorax. The nurse anticipates the tube will be placed:', '[{"id": "a", "text": "higher on the chest, because blood rises"}, {"id": "b", "text": "higher on the chest, because air rises"}, {"id": "c", "text": "lower on the chest, because blood sinks"}, {"id": "d", "text": "at the 2nd intercostal space, midclavicular line"}]'::jsonb, '["c"]', 'Blood sinks, so a chest tube for hemothorax is placed lower. Higher placement is used for pneumothorax because air rises.'),
  ('hemo_pneumo', 17, 'The nurse is teaching a new graduate nurse about chest tube placement. Which statement by the new graduate indicates a need for further teaching?', '[{"id": "a", "text": "A hemopneumothorax may need one tube placed high and one low."}, {"id": "b", "text": "For a hemothorax, the tube goes lower because blood sinks."}, {"id": "c", "text": "For a pneumothorax, the tube goes higher because air rises."}, {"id": "d", "text": "For a pneumothorax, the tube goes lower because air settles at the base."}]'::jsonb, '["d"]', 'Air rises, so a chest tube for pneumothorax is placed higher, not lower. Lower placement is correct for hemothorax because blood sinks.'),
  ('hemo_pneumo', 18, 'A client with chest trauma is found to have both air and blood in the pleural space. Which chest tube plan does the nurse anticipate?', '[{"id": "a", "text": "Two tubes, one placed high and one placed low"}, {"id": "b", "text": "One tube placed high to drain both air and blood"}, {"id": "c", "text": "Needle decompression without any chest tube"}, {"id": "d", "text": "One tube placed low to drain both air and blood"}]'::jsonb, '["a"]', 'A hemopneumothorax (air and blood) may require two chest tubes, one high for air and one low for blood. A single tube at one level does not match where both air and blood collect.'),
  ('hemo_pneumo', 19, 'After a motor vehicle crash, imaging shows blood but no air in a client''s pleural space. The nurse documents this condition as:', '[{"id": "a", "text": "a closed pneumothorax"}, {"id": "b", "text": "a hemopneumothorax"}, {"id": "c", "text": "a tension pneumothorax"}, {"id": "d", "text": "a hemothorax"}]'::jsonb, '["d"]', 'Hemothorax is blood in the pleural space, usually from trauma or surgery. Hemopneumothorax would require both air and blood, and pneumothorax types involve air.'),
  ('hemo_pneumo', 20, 'While assessing a client who has a chest tube for a pneumothorax, the nurse palpates a crackling, bubbly sensation under the skin of the neck. The nurse interprets this finding as:', '[{"id": "a", "text": "normal tidaling in the water seal"}, {"id": "b", "text": "subcutaneous emphysema"}, {"id": "c", "text": "a sign of a re-expanded lung"}, {"id": "d", "text": "active bleeding into the tissues"}]'::jsonb, '["b"]', 'Air trapped under the skin produces crepitus, a crackly or bubbling feeling on palpation, which is subcutaneous emphysema. Tidaling is water movement in the water-seal chamber, not a skin finding.'),
  ('hemo_pneumo', 21, 'A client with a pneumothorax has new crepitus over the chest wall and face. Which action should the nurse take?', '[{"id": "a", "text": "Document it as an expected finding"}, {"id": "b", "text": "Notify the physician immediately"}, {"id": "c", "text": "Clamp the chest tube until it resolves"}, {"id": "d", "text": "Milk the chest tube to improve drainage"}]'::jsonb, '["b"]', 'Crepitus indicates subcutaneous emphysema, a sign of an air leak, and the physician should be notified immediately. Milking and clamping the tube are actions to never take.'),
  ('hemo_pneumo', 22, 'When preparing the room of a client with a new chest tube, which bedside item does the nurse keep available specifically to seal the wound site if the tube dislodges?', '[{"id": "a", "text": "Petroleum gauze"}, {"id": "b", "text": "Transparent dressing"}, {"id": "c", "text": "4×4 gauze pads"}, {"id": "d", "text": "Chest tube clamp"}]'::jsonb, '["a"]', 'Petroleum gauze is kept at the bedside to seal the wound site if the tube dislodges. A transparent dressing secures the insertion site, and the clamp is for brief clamping when changing the collection unit.'),
  ('hemo_pneumo', 23, 'In which situation is it appropriate for the nurse to clamp a client''s chest tube?', '[{"id": "a", "text": "Briefly, while changing the collection unit"}, {"id": "b", "text": "While transporting the client to radiology"}, {"id": "c", "text": "Whenever continuous bubbling is noted"}, {"id": "d", "text": "As soon as tidaling in the water seal stops"}]'::jsonb, '["a"]', 'The chest tube is never clamped except briefly when changing the collection unit. Absent tidaling should be assessed for a kink rather than clamped, and transport does not require clamping.'),
  ('hemo_pneumo', 24, 'The nurse observes gentle, continuous bubbling in the suction control chamber of a client''s wet chest drainage system. Which action is appropriate?', '[{"id": "a", "text": "Increase the suction until the bubbling stops"}, {"id": "b", "text": "Notify the physician of an air leak"}, {"id": "c", "text": "Continue to monitor, as this is expected"}, {"id": "d", "text": "Clamp the tube and recheck in 1 hour"}]'::jsonb, '["c"]', 'Gentle continuous bubbling in the suction chamber is normal. Continuous bubbling signals an air leak only when it occurs in the air leak indicator, not the suction chamber.'),
  ('hemo_pneumo', 25, 'The nurse notes vigorous bubbling in the suction control chamber of a client''s wet chest drainage system. The nurse interprets this as:', '[{"id": "a", "text": "suction set too low"}, {"id": "b", "text": "suction set too high"}, {"id": "c", "text": "an air leak in the system"}, {"id": "d", "text": "an expected normal finding"}]'::jsonb, '["b"]', 'Vigorous bubbling in the suction chamber means suction is too high; gentle bubbling is normal. Suction that is too low produces no bubbling.'),
  ('hemo_pneumo', 26, 'There is no bubbling in the suction control chamber of a client''s wet chest drainage system, which is ordered to suction. Which action should the nurse take?', '[{"id": "a", "text": "Check that suction is connected and set correctly"}, {"id": "b", "text": "Report a continuous air leak to the physician"}, {"id": "c", "text": "Milk the tubing to restore the bubbling"}, {"id": "d", "text": "Document that the lung has re-expanded"}]'::jsonb, '["a"]', 'No bubbling in the suction chamber means suction is too low or not connected. Lung re-expansion is suggested by absent tidaling in the water seal, not by an absence of suction bubbling.'),
  ('hemo_pneumo', 27, 'A client''s wet chest drainage system is ordered to suction. The nurse anticipates the suction will typically be set at:', '[{"id": "a", "text": "−10 cmH2O"}, {"id": "b", "text": "−20 cmH2O"}, {"id": "c", "text": "−60 cmH2O"}, {"id": "d", "text": "−80 cmH2O"}]'::jsonb, '["b"]', 'Suction for a wet system is typically adjusted to −20 cmH2O. The other values do not match the typical setting.'),
  ('hemo_pneumo', 28, 'The nurse assesses the water-seal chamber of a client with a chest tube who is breathing spontaneously. Which finding is expected?', '[{"id": "a", "text": "Water falls on inhalation and rises on exhalation"}, {"id": "b", "text": "Continuous bubbling occurs with every breath"}, {"id": "c", "text": "Vigorous bubbling occurs throughout the cycle"}, {"id": "d", "text": "Water rises on inhalation and falls on exhalation"}]'::jsonb, '["d"]', 'With spontaneous breathing, tidaling rises on inhalation and falls on exhalation. The reverse pattern is expected only for a client on a ventilator.'),
  ('hemo_pneumo', 29, 'A client receiving mechanical ventilation has a chest tube. The nurse observes that the water-seal level falls on inhalation and rises on exhalation. The nurse should:', '[{"id": "a", "text": "recognize this as the expected tidaling pattern"}, {"id": "b", "text": "check the tubing for a kink or clot"}, {"id": "c", "text": "notify the physician of an air leak"}, {"id": "d", "text": "increase the suction to correct the pattern"}]'::jsonb, '["a"]', 'Tidaling normally rises on inhalation and falls on exhalation with spontaneous breathing, and the pattern is opposite on a ventilator, so this is expected. Kinks are suspected when tidaling stops, not when it reverses on a ventilator.'),
  ('hemo_pneumo', 30, 'The water-seal chamber of a client''s chest drainage system has stopped tidaling. Which action should the nurse take first?', '[{"id": "a", "text": "Document that the lung has fully re-expanded"}, {"id": "b", "text": "Milk the tubing to dislodge any clots"}, {"id": "c", "text": "Assess the tubing for kinks or clogging"}, {"id": "d", "text": "Increase the suction to restart tidaling"}]'::jsonb, '["c"]', 'Absent tidaling may mean the lung has re-expanded or the tube is kinked, so the nurse assesses first. Assuming re-expansion could miss a kinked tube, and milking is never done.'),
  ('hemo_pneumo', 31, 'The nurse is explaining absent tidaling in a water-seal chamber to a nursing student. Which two causes should the nurse identify?', '[{"id": "a", "text": "Full lung re-expansion or a kinked tube"}, {"id": "b", "text": "An air leak or suction set too high"}, {"id": "c", "text": "Active bleeding or old blood in the tubing"}, {"id": "d", "text": "Suction set too low or a disconnected source"}]'::jsonb, '["a"]', 'No tidaling means either the lung has fully re-expanded or the tube is kinked or clogged. Suction that is too low or disconnected explains absent bubbling in the suction chamber, not absent tidaling.'),
  ('hemo_pneumo', 32, 'The nurse observes continuous bubbling in the air leak indicator of a client''s chest drainage system. The nurse interprets this as:', '[{"id": "a", "text": "an expected normal finding"}, {"id": "b", "text": "an air leak"}, {"id": "c", "text": "suction set too high"}, {"id": "d", "text": "a fully re-expanded lung"}]'::jsonb, '["b"]', 'Continuous bubbling in the air leak chamber indicates an air leak, whereas intermittent bubbling is normal. Suction that is too high shows vigorous bubbling in the suction chamber instead.'),
  ('hemo_pneumo', 33, 'The nurse is assessing several clients'' chest drainage systems. Which finding requires further nursing action?', '[{"id": "a", "text": "Gentle continuous bubbling in the suction chamber"}, {"id": "b", "text": "Intermittent bubbling in the air leak chamber"}, {"id": "c", "text": "Continuous bubbling in the air leak chamber"}, {"id": "d", "text": "Dark blood in the drainage collection chamber"}]'::jsonb, '["c"]', 'Continuous bubbling in the air leak chamber signals an air leak, which must never be left unaddressed. Intermittent air-leak bubbling, gentle suction bubbling, and dark old blood are all normal.'),
  ('hemo_pneumo', 34, 'The nurse suspects an air leak in a client''s chest drainage system. How should the nurse locate the leak?', '[{"id": "a", "text": "Pinch the tubing every 12 inches, starting at the collection unit"}, {"id": "b", "text": "Pinch the tubing every 12 inches, starting near the client"}, {"id": "c", "text": "Milk the tubing from the client toward the collection unit"}, {"id": "d", "text": "Clamp the tube near the client for 1 hour and observe"}]'::jsonb, '["b"]', 'The leak is located by pinching the tube every 12 inches, moving from the patient toward the collection unit. Starting at the collection unit reverses the order, and milking the tube is never done.'),
  ('hemo_pneumo', 35, 'A postoperative client''s chest tube drainage changes from dark red to bright red. Which action should the nurse take?', '[{"id": "a", "text": "Document it as old blood, an expected finding"}, {"id": "b", "text": "Notify the physician immediately"}, {"id": "c", "text": "Milk the tube to keep it from clotting"}, {"id": "d", "text": "Lift the unit above the chest to inspect it"}]'::jsonb, '["b"]', 'Bright red drainage indicates active bleeding and requires notifying the physician STAT. Dark blood is old blood, so bright red drainage cannot be documented as expected.'),
  ('hemo_pneumo', 36, 'Which chest tube drainage finding indicates that the drainage is clearing?', '[{"id": "a", "text": "Bright red drainage"}, {"id": "b", "text": "Bright red drainage with clots"}, {"id": "c", "text": "Dark red drainage"}, {"id": "d", "text": "Pink, serosanguineous drainage"}]'::jsonb, '["d"]', 'Pink or serosanguineous drainage indicates the drainage is clearing. Dark blood represents old blood, and bright red drainage signals active bleeding.'),
  ('hemo_pneumo', 37, 'Several hours after chest surgery, the nurse notes dark red drainage in the client''s collection chamber. The nurse interprets this as:', '[{"id": "a", "text": "a sign that the drainage is clearing"}, {"id": "b", "text": "active bleeding requiring a STAT call"}, {"id": "c", "text": "old blood, an expected finding"}, {"id": "d", "text": "a sign of an air leak in the system"}]'::jsonb, '["c"]', 'Dark blood in the collection chamber is old blood, which is expected. Bright red drainage, not dark, signals active bleeding.'),
  ('hemo_pneumo', 38, 'A client''s chest drainage is being changed to a dry (mechanical) system. Which feature of this system should the nurse explain?', '[{"id": "a", "text": "Suction is confirmed by gentle water bubbling"}, {"id": "b", "text": "The water seal must be refilled every shift"}, {"id": "c", "text": "It is easier to transport and needs less upkeep"}, {"id": "d", "text": "Suction is adjusted by adding water to a chamber"}]'::jsonb, '["c"]', 'A dry system has no water bubbling, uses a mechanical pressure-control valve, and is easier to transport with less maintenance. Gentle water bubbling describes the suction chamber of a wet system.'),
  ('hemo_pneumo', 39, 'The nurse observes an assistive staff member squeezing and stripping a client''s chest tube to keep it draining. Which explanation should the nurse give?', '[{"id": "a", "text": "Stripping is needed every hour to keep clots from forming."}, {"id": "b", "text": "Stripping is safe as long as it is done toward the client."}, {"id": "c", "text": "Stripping creates extreme negative pressure that can injure the lung."}, {"id": "d", "text": "Stripping is safe only when the unit is held above the chest."}]'::jsonb, '["c"]', 'A chest tube is never milked or stripped because it creates extreme negative pressure that can cause lung injury. The collection unit is also never lifted above chest level.'),
  ('hemo_pneumo', 40, 'The charge nurse observes a new nurse caring for a client with a chest tube. Which action by the new nurse requires intervention?', '[{"id": "a", "text": "Keeping the collection unit below chest level"}, {"id": "b", "text": "Marking the drainage level with date and time"}, {"id": "c", "text": "Taping all tubing connections securely"}, {"id": "d", "text": "Milking the chest tube to keep it patent"}]'::jsonb, '["d"]', 'The chest tube must never be milked. Keeping the unit below the chest, taping connections, and marking drainage with date and time are all required chest tube actions.'),
  ('hemo_pneumo', 41, 'A client with a chest tube is being transported by wheelchair to radiology. Where should the nurse place the drainage collection unit?', '[{"id": "a", "text": "Level with the client''s shoulders"}, {"id": "b", "text": "On the client''s lap, above chest level"}, {"id": "c", "text": "Below the level of the client''s chest"}, {"id": "d", "text": "Hung on the IV pole above the client"}]'::jsonb, '["c"]', 'The collection unit must be kept below chest level at all times, including during transport. Lifting the unit above chest level is something the nurse must never do.'),
  ('hemo_pneumo', 42, 'Which action is part of routine nursing care for a client with a chest tube?', '[{"id": "a", "text": "Stripping the tubing every hour"}, {"id": "b", "text": "Marking the drainage level with date and time"}, {"id": "c", "text": "Loosening connections to prevent kinks"}, {"id": "d", "text": "Clamping the tube during ambulation"}]'::jsonb, '["b"]', 'The nurse should always mark the drainage level with the date and time. Stripping and clamping the tube are never done, and connections should be taped and secured rather than loosened.'),
  ('hemo_pneumo', 43, 'During rounds, the nurse finds a loose connection between a client''s chest tube and the drainage tubing. Which action is appropriate?', '[{"id": "a", "text": "Clamp the chest tube for the rest of the shift"}, {"id": "b", "text": "Raise the unit above the chest to check flow"}, {"id": "c", "text": "Milk the tubing to restore the flow"}, {"id": "d", "text": "Secure the connection and tape it"}]'::jsonb, '["d"]', 'All chest tube connections should always be taped and secured. Clamping the tube, lifting the unit above chest level, and milking the tubing are all actions to never take.'),
  ('hemo_pneumo', 44, 'A client''s chest tube is accidentally pulled completely out of the chest. Which action should the nurse take first?', '[{"id": "a", "text": "Cover the site with a sterile gloved hand"}, {"id": "b", "text": "Notify the physician of the dislodgement"}, {"id": "c", "text": "Submerge the tube end in sterile water"}, {"id": "d", "text": "Attempt to reinsert the tube into the site"}]'::jsonb, '["a"]', 'With complete dislodgement, the nurse immediately covers the insertion site with a sterile gloved hand, then applies a dressing and notifies the physician. Notifying the physician comes after the site is covered.'),
  ('hemo_pneumo', 45, 'The physician is about to remove a client''s chest tube. Which instruction should the nurse give the client?', '[{"id": "a", "text": "Exhale completely and breathe shallowly."}, {"id": "b", "text": "Take a deep breath and bear down."}, {"id": "c", "text": "Cough forcefully as the tube comes out."}, {"id": "d", "text": "Breathe in and out as rapidly as possible."}]'::jsonb, '["b"]', 'During chest tube removal, the client takes a deep breath and bears down (Valsalva maneuver). This increases intrathoracic pressure and prevents air from re-entering.'),
  ('hemo_pneumo', 46, 'A client asks why bearing down is necessary while the chest tube is being removed. The nurse explains that bearing down:', '[{"id": "a", "text": "raises chest pressure to keep air from re-entering"}, {"id": "b", "text": "relaxes the chest muscles to reduce pain"}, {"id": "c", "text": "pushes remaining blood out through the tube"}, {"id": "d", "text": "lowers chest pressure so leftover air is pulled out"}]'::jsonb, '["a"]', 'The Valsalva maneuver increases intrathoracic pressure, which prevents air re-entry during removal. It raises, rather than lowers, intrathoracic pressure.'),
  ('hemo_pneumo', 47, 'A client''s chest tube is scheduled to be removed by the physician. Which nursing action is appropriate before the removal?', '[{"id": "a", "text": "Remove the tube independently at the bedside"}, {"id": "b", "text": "Administer the prescribed analgesic beforehand"}, {"id": "c", "text": "Clamp the tube for several hours beforehand"}, {"id": "d", "text": "Milk the tubing to empty remaining drainage"}]'::jsonb, '["b"]', 'The nurse administers analgesics beforehand, monitors vital signs, and prepares suture materials, while the physician performs the removal. Clamping and milking the tube are never done.'),
  ('hemo_pneumo', 48, 'A client''s chest tube has just been removed. Which action should the nurse take immediately?', '[{"id": "a", "text": "Leave the site open to air so it can dry"}, {"id": "b", "text": "Apply an occlusive dressing to the site"}, {"id": "c", "text": "Apply petroleum gauze on the next day"}, {"id": "d", "text": "Apply a dressing once the sutures heal"}]'::jsonb, '["b"]', 'An occlusive dressing is applied immediately after chest tube removal. Delaying the dressing or leaving the site open does not follow this protocol.'),
  ('hemo_pneumo', 49, 'A client with a gunshot wound to the chest has an audible sucking sound at the wound with each breath. The nurse identifies this as which type of pneumothorax?', '[{"id": "a", "text": "Closed"}, {"id": "b", "text": "Spontaneous"}, {"id": "c", "text": "Tension"}, {"id": "d", "text": "Open"}]'::jsonb, '["d"]', 'An open pneumothorax results from a penetrating wound, and its key finding is a sucking sound at the wound. A closed pneumothorax has no external wound.'),
  ('hemo_pneumo', 50, 'Which sequence of treatment does the nurse anticipate for a client with an open pneumothorax?', '[{"id": "a", "text": "3-sided dressing, then chest tube"}, {"id": "b", "text": "Needle decompression, then chest tube"}, {"id": "c", "text": "Chest tube, then 3-sided dressing"}, {"id": "d", "text": "Fully occlusive dressing, then observation"}]'::jsonb, '["a"]', 'An open pneumothorax is treated with a 3-sided dressing followed by a chest tube. Needle decompression followed by a chest tube is the sequence for tension pneumothorax.'),
  ('spirometry', 1, 'A client 1 day after abdominal surgery has decreased breath sounds in both lung bases. Which action should the nurse take first?', '[{"id": "a", "text": "Have the client use the incentive spirometer"}, {"id": "b", "text": "Perform chest percussion over the incision"}, {"id": "c", "text": "Place the client in Trendelenburg position"}, {"id": "d", "text": "Keep the client flat to reduce incision pain"}]'::jsonb, '["a"]', 'For post-op decreased breath sounds, the first action is incentive spirometry. Chest percussion must be avoided over recent surgical wounds.'),
  ('spirometry', 2, 'A client scheduled for hip surgery asks why an incentive spirometer will be used after surgery. The nurse explains that the primary goal of the device is to:', '[{"id": "a", "text": "Strengthen the muscles used for exhalation"}, {"id": "b", "text": "Prevent collapse of the alveoli"}, {"id": "c", "text": "Deliver aerosolized medication to the lungs"}, {"id": "d", "text": "Mechanically remove secretions from the airway"}]'::jsonb, '["b"]', 'The primary goal of incentive spirometry is to prevent atelectasis, the collapse of alveoli. Aerosolized medication describes nebulizer therapy, and mechanical removal of secretions describes suctioning.'),
  ('spirometry', 3, 'The nurse is identifying clients who would benefit most from incentive spirometry to prevent atelectasis. Which client should the nurse prioritize?', '[{"id": "a", "text": "A client walking independently after a clinic visit"}, {"id": "b", "text": "A client with a sprained ankle who is ambulating"}, {"id": "c", "text": "A client on prolonged bed rest after a pelvic fracture"}, {"id": "d", "text": "A client admitted for observation who walks the halls"}]'::jsonb, '["c"]', 'Atelectasis is common after surgery or during prolonged immobility, so the client on prolonged bed rest benefits most. The other clients are ambulatory and not immobilized.'),
  ('spirometry', 4, 'The nurse observes a postoperative client blowing forcefully into the mouthpiece of an incentive spirometer. Which action should the nurse take?', '[{"id": "a", "text": "Praise the client for the strong effort"}, {"id": "b", "text": "Document the effort and recheck in 4 hours"}, {"id": "c", "text": "Raise the goal marker on the device"}, {"id": "d", "text": "Correct the technique to inhaling through it"}]'::jsonb, '["d"]', 'The client must inhale through the incentive spirometer; exhaling into it should be corrected immediately. Documenting and rechecking later delays the needed correction.'),
  ('spirometry', 5, 'The nurse teaches a client how to use an incentive spirometer. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll blow into the mouthpiece to push the ball up.\""}, {"id": "b", "text": "\"I''ll sit up as straight as I can before I start.\""}, {"id": "c", "text": "\"I''ll hold my breath for 3 to 5 seconds at the top.\""}, {"id": "d", "text": "\"I''ll cough after I finish my deep breaths.\""}]'::jsonb, '["a"]', 'The patient inhales through the device, not exhales, so blowing into it shows a need for teaching. Sitting upright, holding the breath 3 to 5 seconds, and coughing afterward are correct steps.'),
  ('spirometry', 6, 'The nurse observes an unlicensed assistive personnel (UAP) helping a postoperative client with incentive spirometry. Which action by the UAP requires correction?', '[{"id": "a", "text": "Helping the client sit on the edge of the bed"}, {"id": "b", "text": "Telling the client to blow into the device"}, {"id": "c", "text": "Reminding the client to use it every hour while awake"}, {"id": "d", "text": "Encouraging the client to cough after the session"}]'::jsonb, '["b"]', 'Incentive spirometry requires inhaling; telling the client to exhale into the device is the most common error and must be corrected. Sitting on the edge of the bed, hourly use while awake, and coughing afterward are correct.'),
  ('spirometry', 7, 'The nurse is teaching a client to use an incentive spirometer. After the client is positioned upright, which instruction should the nurse give next?', '[{"id": "a", "text": "\"Seal your lips tightly around the mouthpiece.\""}, {"id": "b", "text": "\"Inhale slowly to raise the ball to the marker.\""}, {"id": "c", "text": "\"Breathe out normally to empty your lungs.\""}, {"id": "d", "text": "\"Cough to clear any loosened secretions.\""}]'::jsonb, '["c"]', 'After positioning, the client exhales normally to empty the lungs before placing the mouthpiece. Sealing the lips and inhaling come after this step, and coughing comes at the end.'),
  ('spirometry', 8, 'A nurse reviews incentive spirometry technique with a client after the client has exhaled normally. Which sequence of remaining steps is correct?', '[{"id": "a", "text": "Inhale slowly, seal lips, exhale slowly, hold breath, cough"}, {"id": "b", "text": "Seal lips, exhale forcefully, hold breath, inhale, cough"}, {"id": "c", "text": "Cough, seal lips, inhale quickly, exhale slowly, hold breath"}, {"id": "d", "text": "Seal lips, inhale slowly, hold breath, exhale slowly, cough"}]'::jsonb, '["d"]', 'After exhaling normally, the client seals the lips, inhales slowly and deeply, holds the breath 3 to 5 seconds, exhales slowly, and then coughs. Inhaling before sealing the lips or coughing first places the steps out of order.'),
  ('spirometry', 9, 'A postoperative client using an incentive spirometer asks how long to hold the breath after reaching the goal marker. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Hold it for 3 to 5 seconds.\""}, {"id": "b", "text": "\"Hold it for 1 second only.\""}, {"id": "c", "text": "\"Hold it for 15 to 20 seconds.\""}, {"id": "d", "text": "\"Hold it for a full 30 seconds.\""}]'::jsonb, '["a"]', 'The breath is held for 3 to 5 seconds at peak inhalation. One second is too brief to allow the alveoli to fully expand.'),
  ('spirometry', 10, 'A client asks why the breath must be held at the top of each incentive spirometer breath. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It builds up carbon dioxide to trigger a cough.\""}, {"id": "b", "text": "\"It allows the air sacs to fully expand.\""}, {"id": "c", "text": "\"It resets the piston for the next breath.\""}, {"id": "d", "text": "\"It strengthens the muscles used to exhale.\""}]'::jsonb, '["b"]', 'Holding the breath for 3 to 5 seconds at the top allows the alveoli to fully expand. Coughing is a separate step that mobilizes secretions loosened during deep inhalation.'),
  ('spirometry', 11, 'A client using an incentive spirometer inhales very rapidly, causing the ball to shoot up and drop quickly. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Inhale even faster to keep the ball up longer.\""}, {"id": "b", "text": "\"Take short, shallow breaths more often instead.\""}, {"id": "c", "text": "\"Inhale slowly and deeply to raise the ball.\""}, {"id": "d", "text": "\"Exhale into the device to steady the ball.\""}]'::jsonb, '["c"]', 'The correct technique is to inhale slowly and deeply to raise the piston or ball to the goal marker. Exhaling into the device is incorrect because incentive spirometry is an inhalation technique.'),
  ('spirometry', 12, 'A nurse is writing discharge instructions for a client who will continue incentive spirometry at home. How often should the nurse instruct the client to use the device?', '[{"id": "a", "text": "10 times per day"}, {"id": "b", "text": "3 times per hour while awake"}, {"id": "c", "text": "Once every 4 hours around the clock"}, {"id": "d", "text": "10 times per hour while awake"}]'::jsonb, '["d"]', 'Incentive spirometry is repeated 10 times per hour while awake. Ten times per day or once every 4 hours is far less frequent than recommended.'),
  ('spirometry', 13, 'Which statement by a postoperative client indicates correct understanding of how often to use the incentive spirometer?', '[{"id": "a", "text": "\"I''ll do 10 breaths every hour while I''m awake.\""}, {"id": "b", "text": "\"I''ll do 10 breaths in the morning and at night.\""}, {"id": "c", "text": "\"I''ll use it only when I feel short of breath.\""}, {"id": "d", "text": "\"I''ll wake up every hour overnight to use it.\""}]'::jsonb, '["a"]', 'The device is used every hour while awake, 10 breaths per hour. Waking every hour overnight is not required because use is while awake, and twice daily use is too infrequent.'),
  ('spirometry', 14, 'A client asks why the nurse wants a cough after each set of incentive spirometer breaths. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Coughing helps the air sacs stay fully inflated.\""}, {"id": "b", "text": "\"Coughing moves secretions loosened by deep breaths.\""}, {"id": "c", "text": "\"Coughing resets the device for the next session.\""}, {"id": "d", "text": "\"Coughing lowers the pain around your incision.\""}]'::jsonb, '["b"]', 'Coughing after incentive spirometry mobilizes secretions loosened during deep inhalation. Full alveolar expansion is the purpose of the 3- to 5-second breath hold, not the cough.'),
  ('spirometry', 15, 'A client who had abdominal surgery yesterday is reluctant to deep breathe and cough because of incisional pain. Which nursing action is most appropriate?', '[{"id": "a", "text": "Allow the client to skip coughing until the pain resolves"}, {"id": "b", "text": "Have the client lie flat before coughing"}, {"id": "c", "text": "Teach the client to splint the incision with a pillow"}, {"id": "d", "text": "Have the client cough without taking deep breaths first"}]'::jsonb, '["c"]', 'Splinting the incision with a pillow before deep breathing and coughing reduces pain and encourages compliance. Skipping coughing delays secretion clearance that the post-op client needs.'),
  ('spirometry', 16, 'A client is scheduled for elective abdominal surgery next week. When is the best time for the nurse to teach incentive spirometer technique?', '[{"id": "a", "text": "Upon arrival in the postanesthesia care unit"}, {"id": "b", "text": "When the client develops decreased breath sounds"}, {"id": "c", "text": "On the day the client is discharged home"}, {"id": "d", "text": "During the preoperative visit before surgery"}]'::jsonb, '["d"]', 'Incentive spirometry should be taught before surgery because it is easier to learn when the client is not in pain. Teaching after surgery means the client is learning while in pain.'),
  ('spirometry', 17, 'A nurse is planning care for a client scheduled for thoracic surgery tomorrow. Which plan regarding incentive spirometry reflects best practice?', '[{"id": "a", "text": "Teach and practice the technique today"}, {"id": "b", "text": "Wait until the second postoperative day"}, {"id": "c", "text": "Teach it only if atelectasis develops"}, {"id": "d", "text": "Provide a written handout at discharge"}]'::jsonb, '["a"]', 'Incentive spirometry is taught preoperatively because compliance is better when the client is pain-free. Waiting until after surgery means teaching while the client is in pain.'),
  ('spirometry', 18, 'After assisting a postoperative client with incentive spirometry, which information should the nurse document?', '[{"id": "a", "text": "Only the time the session ended"}, {"id": "b", "text": "Effort, volume achieved, and client response"}, {"id": "c", "text": "The brand and color of the device"}, {"id": "d", "text": "Only the number of coughs produced"}]'::jsonb, '["b"]', 'The nurse documents effort, volume achieved, and patient response after incentive spirometry. Recording only the time or the number of coughs omits the required information.'),
  ('spirometry', 19, 'The nurse wants to evaluate whether incentive spirometry is improving a postoperative client''s lung status. Which action is most appropriate?', '[{"id": "a", "text": "Ask the client whether the device is easy to use"}, {"id": "b", "text": "Check bowel sounds before each spirometry session"}, {"id": "c", "text": "Auscultate lung sounds before and after the session"}, {"id": "d", "text": "Count how many times the client used it this shift"}]'::jsonb, '["c"]', 'Auscultating lung sounds before and after incentive spirometry assesses improvement. Counting uses or asking about ease of use does not evaluate lung status.'),
  ('spirometry', 20, 'The nurse is reviewing prescriptions for incentive spirometry on a surgical unit. For which client should the nurse question the prescription?', '[{"id": "a", "text": "A client 1 day after abdominal surgery"}, {"id": "b", "text": "A client on prolonged bed rest"}, {"id": "c", "text": "A client with pneumonia and secretions"}, {"id": "d", "text": "A client with active hemoptysis"}]'::jsonb, '["d"]', 'Active hemoptysis is a contraindication to incentive spirometry. Post-surgical and immobilized clients are the clients incentive spirometry is meant to help.'),
  ('spirometry', 21, 'Which client finding would lead the nurse to withhold incentive spirometry and consult the provider?', '[{"id": "a", "text": "An untreated pneumothorax"}, {"id": "b", "text": "Decreased breath sounds after surgery"}, {"id": "c", "text": "Incisional pain with coughing"}, {"id": "d", "text": "Several days of bed rest"}]'::jsonb, '["a"]', 'Untreated pneumothorax is a contraindication to incentive spirometry. Decreased post-op breath sounds are an indication, for which incentive spirometry is the first action.'),
  ('spirometry', 22, 'The nurse is preparing a postoperative client to use an incentive spirometer. Which position should the nurse assist the client into?', '[{"id": "a", "text": "Supine with one pillow"}, {"id": "b", "text": "High Fowler''s"}, {"id": "c", "text": "Trendelenburg"}, {"id": "d", "text": "Side-lying flat"}]'::jsonb, '["b"]', 'Sitting upright in high Fowler''s or on the edge of the bed is the best position for maximum lung expansion. Trendelenburg is used for postural drainage of the lower lobes, not for incentive spirometry.'),
  ('spirometry', 23, 'The nurse finds a client slouched low in bed with the head of the bed at 15 degrees, attempting to use the incentive spirometer. Which action should the nurse take first?', '[{"id": "a", "text": "Raise the goal marker to increase the challenge"}, {"id": "b", "text": "Lower the head of the bed so the client can relax"}, {"id": "c", "text": "Assist the client to sit upright in high Fowler''s"}, {"id": "d", "text": "Have the client exhale into the device instead"}]'::jsonb, '["c"]', 'High Fowler''s or sitting upright allows maximum diaphragmatic excursion during incentive spirometry. Lowering the head of the bed further reduces lung expansion.'),
  ('spirometry', 24, 'A postoperative client has been using an incentive spirometer for 2 days. Which finding indicates that the therapy is effective?', '[{"id": "a", "text": "Volume achieved on the device is decreasing"}, {"id": "b", "text": "The client is avoiding coughing after sessions"}, {"id": "c", "text": "Breath sounds are diminished in the lung bases"}, {"id": "d", "text": "Oxygen saturation has improved since surgery"}]'::jsonb, '["d"]', 'Incentive spirometry improves oxygenation and SpO2, so improved oxygen saturation shows effectiveness. Diminished breath sounds at the bases would suggest the therapy is not yet effective.'),
  ('spirometry', 25, 'A nursing student asks the nurse what pulmonary hygiene means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Techniques that clear secretions and optimize lung function.\""}, {"id": "b", "text": "\"Cleaning the oxygen equipment between client uses.\""}, {"id": "c", "text": "\"Oral care that is given to clients on ventilators.\""}, {"id": "d", "text": "\"Medications given to prevent lung infections.\""}]'::jsonb, '["a"]', 'Pulmonary hygiene is a broad set of techniques used to clear airway secretions and optimize lung function. It is not limited to equipment cleaning, oral care, or medications.'),
  ('spirometry', 26, 'The nurse is caring for several clients. Which client has the greatest need for pulmonary hygiene measures?', '[{"id": "a", "text": "A client with a sprained wrist who is ambulating"}, {"id": "b", "text": "A client after a stroke who cannot cough effectively"}, {"id": "c", "text": "A client with a skin rash awaiting discharge"}, {"id": "d", "text": "A client with a broken toe who walks with a boot"}]'::jsonb, '["b"]', 'Pulmonary hygiene is essential for neurologically impaired clients who cannot initiate or complete an effective cough. The other clients are mobile with no listed impairment in secretion clearance.'),
  ('spirometry', 27, 'A nurse explains to a student why clients after abdominal or thoracic surgery especially need pulmonary hygiene. Which explanation is accurate?', '[{"id": "a", "text": "These surgeries cause excess secretion production."}, {"id": "b", "text": "These clients are usually intubated for several days."}, {"id": "c", "text": "Pain after these surgeries inhibits deep breathing."}, {"id": "d", "text": "Anesthesia permanently weakens the cough reflex."}]'::jsonb, '["c"]', 'Pulmonary hygiene is especially important after abdominal or thoracic surgery because pain inhibits deep breathing. Excess secretion production is associated with COPD, CF, and pneumonia.'),
  ('spirometry', 28, 'A client has been sedated and immobile in the intensive care unit for several days. The nurse understands that this client needs pulmonary hygiene because:', '[{"id": "a", "text": "Sedation causes secretions to become thinner"}, {"id": "b", "text": "Immobility increases the depth of each breath"}, {"id": "c", "text": "Sedation prevents any mucus from being produced"}, {"id": "d", "text": "Secretions pool in the dependent lung zones"}]'::jsonb, '["d"]', 'During prolonged immobility or sedation, secretions pool in dependent lung zones. This pooling, not thinning or reduced production, is why pulmonary hygiene is essential.'),
  ('spirometry', 29, 'The nurse is teaching a postoperative client the coughing and deep breathing technique. Which instruction is correct?', '[{"id": "a", "text": "\"Take 2 to 3 deep breaths, then cough forcefully.\""}, {"id": "b", "text": "\"Cough forcefully first, then take 10 deep breaths.\""}, {"id": "c", "text": "\"Take several shallow breaths, then cough gently.\""}, {"id": "d", "text": "\"Hold your breath for 30 seconds, then cough.\""}]'::jsonb, '["a"]', 'Coughing and deep breathing involves taking 2 to 3 deep breaths followed by a forceful cough to mobilize mucus. Coughing before the deep breaths reverses the correct order.'),
  ('spirometry', 30, 'A client is about to perform coughing and deep breathing exercises. Which position should the nurse help the client assume?', '[{"id": "a", "text": "Trendelenburg"}, {"id": "b", "text": "Semi-Fowler''s or sitting"}, {"id": "c", "text": "Prone"}, {"id": "d", "text": "Supine and flat"}]'::jsonb, '["b"]', 'Semi-Fowler''s or sitting is the optimal position for coughing and deep breathing because it reduces diaphragm compression. Trendelenburg is used for postural drainage of the lower lobes.'),
  ('spirometry', 31, 'A client 2 days after surgery reports shortness of breath, and the nurse hears secretions when the client breathes. Which action should the nurse take?', '[{"id": "a", "text": "Perform chest percussion over the sternum"}, {"id": "b", "text": "Place the client in Trendelenburg for the upper lobes"}, {"id": "c", "text": "Encourage the client to deep breathe and cough"}, {"id": "d", "text": "Instruct the client to exhale into the spirometer"}]'::jsonb, '["c"]', 'For shortness of breath with secretions, the nurse should encourage deep breathing and coughing. Percussion over the sternum must be avoided, and upper lobes drain in a sitting or high Fowler''s position.'),
  ('spirometry', 32, 'A nursing student asks the nurse to describe chest physiotherapy (CPT). Which description is accurate?', '[{"id": "a", "text": "Positioning the client so gravity drains lung segments"}, {"id": "b", "text": "Delivering aerosolized saline to thin secretions"}, {"id": "c", "text": "Removing secretions with a catheter and suction"}, {"id": "d", "text": "Percussion and vibration over the chest wall"}]'::jsonb, '["d"]', 'CPT is rhythmic percussion (clapping) and vibration over the chest wall to loosen secretions. Using gravity to drain lung segments describes postural drainage, a separate technique.'),
  ('spirometry', 33, 'A client with excess secretions is prescribed chest physiotherapy. When should the nurse schedule the treatment?', '[{"id": "a", "text": "Before meals"}, {"id": "b", "text": "Right after meals"}, {"id": "c", "text": "During meals"}, {"id": "d", "text": "Only at bedtime"}]'::jsonb, '["a"]', 'Chest physiotherapy should be performed before meals. Scheduling it right after or during meals does not follow this guideline.'),
  ('spirometry', 34, 'Chest physiotherapy is prescribed for several clients. For which client should the nurse question the prescription?', '[{"id": "a", "text": "A client with pneumonia and thick secretions"}, {"id": "b", "text": "A client with fractured ribs after a fall"}, {"id": "c", "text": "A client with cystic fibrosis"}, {"id": "d", "text": "A client with COPD and retained mucus"}]'::jsonb, '["b"]', 'CPT should be avoided over fractured ribs. Clients with pneumonia, cystic fibrosis, and COPD have excess secretions and impaired clearance, making them candidates for pulmonary hygiene.'),
  ('spirometry', 35, 'The nurse observes a nursing student performing chest physiotherapy on a client with pneumonia. Which action by the student requires correction?', '[{"id": "a", "text": "Scheduling the treatment before breakfast"}, {"id": "b", "text": "Giving the nebulizer treatment before CPT"}, {"id": "c", "text": "Percussing directly over the client''s spine"}, {"id": "d", "text": "Avoiding the area of a recent surgical wound"}]'::jsonb, '["c"]', 'Percussion must be avoided over bony prominences, the spine, the sternum, and recent surgical wounds. Scheduling before meals and giving a nebulizer first are correct.'),
  ('spirometry', 36, 'A 78-year-old client with pneumonia has thick secretions. Which additional history finding should cause the nurse to question a prescription for chest physiotherapy?', '[{"id": "a", "text": "Daily productive cough"}, {"id": "b", "text": "Recent nebulizer use"}, {"id": "c", "text": "Two days of bed rest"}, {"id": "d", "text": "Severe osteoporosis"}]'::jsonb, '["d"]', 'CPT should be avoided in clients with osteoporosis, along with fractured ribs, surgical wounds, and bleeding disorders. A productive cough and bed rest are reasons pulmonary hygiene is needed, not contraindications.'),
  ('spirometry', 37, 'A client is prescribed both a saline nebulizer treatment and chest physiotherapy this morning. Which approach by the nurse is best?', '[{"id": "a", "text": "Give the nebulizer treatment, then perform CPT"}, {"id": "b", "text": "Perform CPT, then give the nebulizer treatment"}, {"id": "c", "text": "Give both at the same time after breakfast"}, {"id": "d", "text": "Give the nebulizer at bedtime and CPT in the morning"}]'::jsonb, '["a"]', 'Nebulizer therapy is used before CPT or postural drainage for maximum effect. Performing CPT first or after breakfast does not follow the recommended order and timing.'),
  ('spirometry', 38, 'A client with thick secretions asks what the nebulizer treatment will do. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It removes mucus through a small catheter.\""}, {"id": "b", "text": "\"It delivers a fine mist to thin your mucus.\""}, {"id": "c", "text": "\"It uses clapping to loosen your mucus.\""}, {"id": "d", "text": "\"It positions you so mucus drains by gravity.\""}]'::jsonb, '["b"]', 'Nebulizer therapy delivers aerosolized medication or saline to loosen and thin secretions. Clapping describes CPT, and catheter removal describes suctioning.'),
  ('spirometry', 39, 'A client has secretions in the lower lobes of both lungs. Which position should the nurse use for postural drainage?', '[{"id": "a", "text": "High Fowler''s"}, {"id": "b", "text": "Sitting upright"}, {"id": "c", "text": "Trendelenburg"}, {"id": "d", "text": "Semi-Fowler''s"}]'::jsonb, '["c"]', 'Trendelenburg or modified Trendelenburg uses gravity to drain the basilar segments of the lower lobes. Sitting or high Fowler''s is used to drain the upper lobes.'),
  ('spirometry', 40, 'Postural drainage is prescribed for a client with secretions in the upper lobes. Which position should the nurse use?', '[{"id": "a", "text": "Trendelenburg"}, {"id": "b", "text": "Modified Trendelenburg"}, {"id": "c", "text": "Prone and flat"}, {"id": "d", "text": "Sitting or high Fowler''s"}]'::jsonb, '["d"]', 'Sitting or high Fowler''s position lets gravity drain the upper lung segments. Trendelenburg and modified Trendelenburg are used to drain the lower lobes.'),
  ('spirometry', 41, 'A client asks how postural drainage helps clear secretions. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Your position lets gravity drain specific parts of the lung.\""}, {"id": "b", "text": "\"A machine gently vibrates your chest to loosen mucus.\""}, {"id": "c", "text": "\"A thin tube is passed to suction mucus from your lungs.\""}, {"id": "d", "text": "\"Medicated mist is inhaled to thin and loosen mucus.\""}]'::jsonb, '["a"]', 'Postural drainage positions the client so gravity drains specific lung segments. Vibration over the chest wall describes CPT, a separate technique.'),
  ('spirometry', 42, 'The nurse is preparing to suction a client''s tracheostomy. Which sequence should the nurse follow?', '[{"id": "a", "text": "Suction, preoxygenate, then suction again"}, {"id": "b", "text": "Preoxygenate, suction, then oxygenate again"}, {"id": "c", "text": "Suction, then oxygenate only if SpO2 drops"}, {"id": "d", "text": "Oxygenate after suctioning but not before"}]'::jsonb, '["b"]', 'Suctioning follows the sequence of preoxygenate, suction, then oxygenate again. Suctioning before preoxygenating skips the required first step.'),
  ('spirometry', 43, 'The nurse is suctioning a client''s endotracheal tube. What is the maximum duration for each suction pass?', '[{"id": "a", "text": "20 to 30 seconds"}, {"id": "b", "text": "30 to 45 seconds"}, {"id": "c", "text": "Less than 15 seconds"}, {"id": "d", "text": "Up to 60 seconds"}]'::jsonb, '["c"]', 'Each suction pass should be limited to less than 15 seconds, with preoxygenation first. Passes of 20 seconds or longer exceed this limit.'),
  ('spirometry', 44, 'The nurse observes a newly hired nurse performing suctioning for several clients. Which action requires correction?', '[{"id": "a", "text": "Using sterile technique to suction a tracheostomy"}, {"id": "b", "text": "Using clean technique to suction the oral cavity"}, {"id": "c", "text": "Preoxygenating the client before each suction pass"}, {"id": "d", "text": "Using clean technique to suction a tracheostomy"}]'::jsonb, '["d"]', 'Suctioning a tracheostomy or endotracheal tube requires sterile technique, while oral suctioning uses clean technique. Clean technique for a tracheostomy must be corrected.'),
  ('spirometry', 45, 'The nurse prepares to suction an awake client with copious secretions. Which position is most appropriate?', '[{"id": "a", "text": "Semi-Fowler''s at 30 to 45 degrees"}, {"id": "b", "text": "Supine with the bed flat"}, {"id": "c", "text": "Trendelenburg"}, {"id": "d", "text": "Prone with the head turned"}]'::jsonb, '["a"]', 'Semi-Fowler''s at 30 to 45 degrees is used when suctioning an awake client because it reduces aspiration risk and opens the airway. Lying flat or head-down does not provide this protection.'),
  ('spirometry', 46, 'A client who had a stroke has oral secretions pooling in the mouth and is at risk for aspiration. Which nursing actions are most appropriate?', '[{"id": "a", "text": "Lower the head of the bed and perform CPT"}, {"id": "b", "text": "Elevate the head of the bed and suction orally"}, {"id": "c", "text": "Place in Trendelenburg and encourage coughing"}, {"id": "d", "text": "Lay the client flat and apply humidified oxygen"}]'::jsonb, '["b"]', 'For aspiration risk, the nurse should elevate the head of the bed and perform oral suctioning. Lowering the head of the bed or using Trendelenburg increases rather than reduces risk.'),
  ('spirometry', 47, 'A client is receiving mechanical ventilation in the intensive care unit. Which head-of-bed position should the nurse maintain to prevent ventilator-associated pneumonia (VAP)?', '[{"id": "a", "text": "Flat at 0 degrees"}, {"id": "b", "text": "Elevated 10 to 15 degrees"}, {"id": "c", "text": "Elevated 30 to 45 degrees"}, {"id": "d", "text": "Trendelenburg"}]'::jsonb, '["c"]', 'Keeping the head of the bed at 30 to 45 degrees in ventilated clients reduces ventilator-associated pneumonia. Flat or head-down positions do not meet this guideline.'),
  ('spirometry', 48, 'The nurse is reviewing oxygen orders for several clients. Which client''s oxygen setup most needs a humidifier added?', '[{"id": "a", "text": "A client receiving 1 L/min"}, {"id": "b", "text": "A client receiving 2 L/min"}, {"id": "c", "text": "A client receiving 3 L/min"}, {"id": "d", "text": "A client receiving 6 L/min"}]'::jsonb, '["d"]', 'Humidification is important when supplemental oxygen exceeds 4 L/min, so the client on 6 L/min needs a humidifier. The other flow rates are at or below 4 L/min.'),
  ('spirometry', 49, 'A client receiving humidified oxygen asks why water was added to the oxygen setup. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It keeps your airways moist so mucus does not thicken.\""}, {"id": "b", "text": "\"It delivers medicine deep into the lower airways.\""}, {"id": "c", "text": "\"It lowers the amount of oxygen that you receive.\""}, {"id": "d", "text": "\"It drains mucus from your lungs by using gravity.\""}]'::jsonb, '["a"]', 'Humidified air or oxygen keeps the airways moist to prevent secretions from thickening. Delivering medication describes nebulizer therapy, and gravity drainage describes postural drainage.'),
  ('spirometry', 50, 'A client 1 day after a cholecystectomy is using an incentive spirometer. Which client statement indicates understanding of its purpose?', '[{"id": "a", "text": "\"It will strengthen my muscles for breathing out.\""}, {"id": "b", "text": "\"It helps prevent pneumonia after my surgery.\""}, {"id": "c", "text": "\"It will deliver my breathing medicine to my lungs.\""}, {"id": "d", "text": "\"It suctions out mucus that I cannot cough up.\""}]'::jsonb, '["b"]', 'Incentive spirometry prevents post-operative pneumonia and atelectasis. It is an inhalation device, so it does not strengthen exhalation, deliver medication, or suction secretions.'),
  ('masks', 1, 'A client with COPD has an SpO₂ of 85% on room air. The provider prescribes oxygen that must be delivered at a precise, controlled concentration. Which device should the nurse obtain?', '[{"id": "a", "text": "Non-rebreather mask with a reservoir bag"}, {"id": "b", "text": "Simple face mask running at 10 L/min"}, {"id": "c", "text": "Venturi mask with a color-coded adaptor"}, {"id": "d", "text": "Partial rebreather mask with a reservoir bag"}]'::jsonb, '["c"]', 'The Venturi mask is the most precise oxygen delivery device and is best for COPD because controlled O₂ delivery avoids loss of hypoxic drive. A non-rebreather gives the highest O₂ without intubation, which is not the goal for this client.'),
  ('masks', 2, 'The nurse is titrating supplemental oxygen for a client with COPD. Which SpO₂ range should the nurse target?', '[{"id": "a", "text": "80%–84%"}, {"id": "b", "text": "88%–92%"}, {"id": "c", "text": "95%–97%"}, {"id": "d", "text": "98%–100%"}]'::jsonb, '["b"]', 'The target SpO₂ for a client with COPD is 88–92%, not the 95–100% used for other clients. Aiming for 95% or higher risks suppressing the hypoxic drive.'),
  ('masks', 3, 'A client with COPD who is receiving supplemental oxygen has an SpO₂ of 99%. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is the ideal target and the flow should be maintained"}, {"id": "b", "text": "It is below the target and the flow should be increased"}, {"id": "c", "text": "It indicates the need to switch to a non-rebreather mask"}, {"id": "d", "text": "It exceeds the target and may suppress the hypoxic drive"}]'::jsonb, '["d"]', 'For COPD, O₂ saturation above 94% should be avoided because high O₂ can suppress the hypoxic drive; the target is 88–92%. Maintaining 99% wrongly treats the client as if the goal were 95–100%.'),
  ('masks', 4, 'A client is receiving oxygen by nasal cannula at 5 L/min and reports a dry, irritated nose. Which equipment should the nurse add?', '[{"id": "a", "text": "A reservoir bag on the cannula"}, {"id": "b", "text": "A color-coded Venturi adaptor"}, {"id": "c", "text": "A one-way valve on the tubing"}, {"id": "d", "text": "A humidifier on the oxygen source"}]'::jsonb, '["d"]', 'Humidification should be added when nasal cannula flow exceeds 4 L/min. Reservoir bags belong to partial and non-rebreather masks, and color-coded adaptors belong to the Venturi mask.'),
  ('masks', 5, 'The nurse receives a prescription to apply a nasal cannula at 8 L/min for a client with mild hypoxia. What is the nurse''s best action?', '[{"id": "a", "text": "Clarify the prescription because the cannula maximum is 6 L/min"}, {"id": "b", "text": "Apply the cannula at 8 L/min with a humidifier attached"}, {"id": "c", "text": "Apply the cannula at 8 L/min without humidification added"}, {"id": "d", "text": "Apply a simple face mask at 4 L/min instead of the cannula"}]'::jsonb, '["a"]', 'Nasal cannula flow has a maximum of 6 L/min, so an 8 L/min prescription must be clarified. Substituting a simple mask at 4 L/min is unsafe because a simple mask needs at least 6 L/min to keep CO₂ from building up.'),
  ('masks', 6, 'A postoperative client is receiving oxygen by simple face mask. Which action by the unlicensed assistive personnel (UAP) requires the nurse to intervene?', '[{"id": "a", "text": "Setting the mask flow meter to 8 L/min"}, {"id": "b", "text": "Setting the mask flow meter to 10 L/min"}, {"id": "c", "text": "Setting the mask flow meter to 4 L/min"}, {"id": "d", "text": "Setting the mask flow meter to 12 L/min"}]'::jsonb, '["c"]', 'A simple mask requires a minimum of 6 L/min; below this, CO₂ builds up in the mask. Flows of 8–12 L/min fall within the simple mask range of 6–12 L/min.'),
  ('masks', 7, 'A nursing student asks why a simple face mask must never run below 6 L/min. Which response by the nurse is accurate?', '[{"id": "a", "text": "That flow keeps the reservoir bag one-third full"}, {"id": "b", "text": "That flow sets an exact FiO₂ through the adaptor"}, {"id": "c", "text": "That flow is the point where humidity is required"}, {"id": "d", "text": "That flow flushes exhaled CO₂ out of the mask"}]'::jsonb, '["d"]', 'The 6 L/min minimum for a simple mask is needed to flush CO₂ from the mask. Reservoir bags belong to rebreather masks, exact FiO₂ is set by Venturi adaptors, and humidification is tied to nasal cannula flow above 4 L/min.'),
  ('masks', 8, 'A client in the emergency department has severe hypoxia and is not intubated. Which device should the nurse apply to deliver the highest oxygen concentration?', '[{"id": "a", "text": "Non-rebreather mask"}, {"id": "b", "text": "Partial rebreather mask"}, {"id": "c", "text": "Venturi mask"}, {"id": "d", "text": "Simple face mask"}]'::jsonb, '["a"]', 'The non-rebreather mask delivers the highest O₂ without intubation (60–100%) and is used for emergency hypoxia. The partial rebreather delivers less, and the Venturi mask is chosen for precision rather than maximum concentration.'),
  ('masks', 9, 'The nurse checks a client who is wearing a non-rebreather mask. Which finding requires immediate correction?', '[{"id": "a", "text": "The reservoir bag collapses completely on inspiration"}, {"id": "b", "text": "The reservoir bag stays partly inflated on inspiration"}, {"id": "c", "text": "The one-way side valves are present and intact"}, {"id": "d", "text": "The flow meter is set at 15 L/min for the mask"}]'::jsonb, '["a"]', 'The non-rebreather reservoir bag must be kept inflated, so a bag that collapses completely is unsafe. Intact side valves and a flow of 15 L/min are correct for this mask.'),
  ('masks', 10, 'While checking a client''s non-rebreather mask, the nurse notes that one side flap valve has been torn off. What is the nurse''s best action?', '[{"id": "a", "text": "Leave the mask in place because one valve works"}, {"id": "b", "text": "Replace the mask so all side valves are intact"}, {"id": "c", "text": "Switch to a simple face mask at 4 L/min"}, {"id": "d", "text": "Lower the flow so the bag deflates fully"}]'::jsonb, '["b"]', 'All side flap valves on a non-rebreather must be kept intact, so the damaged mask should be replaced. A simple mask at 4 L/min is below its 6 L/min minimum, and the bag must not be allowed to deflate.'),
  ('masks', 11, 'The nurse is reviewing a client''s partial rebreather mask with a new graduate nurse. Which statement by the graduate is correct?', '[{"id": "a", "text": "The reservoir bag should fully deflate with each breath taken."}, {"id": "b", "text": "This mask gives the highest oxygen level without intubation."}, {"id": "c", "text": "This mask uses color-coded adaptors to set an exact FiO₂."}, {"id": "d", "text": "The reservoir bag should not fully deflate as the client inhales."}]'::jsonb, '["d"]', 'The partial rebreather''s reservoir bag should not fully deflate. The highest O₂ without intubation comes from the non-rebreather, and color-coded adaptors belong to the Venturi mask.'),
  ('masks', 12, 'The nurse explains to a client how oxygen reaches working muscle cells. Where does the exchange of O₂ and CO₂ between blood and tissue cells take place?', '[{"id": "a", "text": "Alveolar membrane"}, {"id": "b", "text": "Lungs, airways, and diaphragm"}, {"id": "c", "text": "Pulmonary capillaries only"}, {"id": "d", "text": "Systemic capillaries"}]'::jsonb, '["d"]', 'Internal respiration, the O₂/CO₂ exchange between blood and tissue cells, occurs at the systemic capillaries. The alveolar membrane is the site of external respiration between alveoli and pulmonary capillaries.'),
  ('masks', 13, 'The nurse is setting up a Venturi mask for a client. Which component determines the exact FiO₂ the client receives?', '[{"id": "a", "text": "The reservoir bag"}, {"id": "b", "text": "The one-way side valves"}, {"id": "c", "text": "The humidifier bottle"}, {"id": "d", "text": "The color-coded adaptor"}]'::jsonb, '["d"]', 'On a Venturi mask, color-coded adaptors dial the exact FiO₂, which makes it the most precise device. Reservoir bags and one-way valves are features of rebreather masks.'),
  ('masks', 14, 'A client with mild hypoxia needs supplemental oxygen and asks for the most comfortable option. Which device should the nurse anticipate?', '[{"id": "a", "text": "Non-rebreather mask"}, {"id": "b", "text": "Nasal cannula"}, {"id": "c", "text": "Bag valve mask"}, {"id": "d", "text": "Mechanical ventilator"}]'::jsonb, '["b"]', 'The nasal cannula is the most common and most comfortable device and works for mild hypoxia. The non-rebreather is reserved for emergency hypoxia, and the BVM is for resuscitation.'),
  ('masks', 15, 'A client with facial burns requires supplemental oxygen but cannot tolerate a tight-fitting mask. Which device is most appropriate?', '[{"id": "a", "text": "Non-rebreather mask"}, {"id": "b", "text": "Simple face mask"}, {"id": "c", "text": "Bag valve mask"}, {"id": "d", "text": "Face tent"}]'::jsonb, '["d"]', 'A face tent is used for clients who do not tolerate tight masks, such as those with facial injuries or burns. A BVM requires a proper tight mask seal, which this client cannot tolerate.'),
  ('masks', 16, 'A client with claustrophobia repeatedly pulls off a simple face mask, stating it feels suffocating. Which device should the nurse request instead?', '[{"id": "a", "text": "Partial rebreather mask"}, {"id": "b", "text": "Non-rebreather mask"}, {"id": "c", "text": "Face tent"}, {"id": "d", "text": "Venturi mask"}]'::jsonb, '["c"]', 'A face tent is indicated for clients who don''t tolerate tight masks, including those with claustrophobia. Partial rebreather, non-rebreather, and Venturi devices are all masks that cover the face.'),
  ('masks', 17, 'A client on the medical unit stops breathing and has no pulse. As CPR begins, which device should the nurse use to ventilate the client?', '[{"id": "a", "text": "Non-rebreather mask"}, {"id": "b", "text": "Bag valve mask"}, {"id": "c", "text": "High-flow nasal cannula"}, {"id": "d", "text": "Venturi mask"}]'::jsonb, '["b"]', 'The BVM is used in CPR and respiratory arrest and requires a tight seal. The non-rebreather is the device for emergency hypoxia, while the BVM is the device for resuscitation.'),
  ('masks', 18, 'Two nurses are ventilating a client with a bag valve mask before intubation. Which technique is preferred?', '[{"id": "a", "text": "One seals the mask while the other squeezes the bag"}, {"id": "b", "text": "One holds the mask loosely while the other squeezes"}, {"id": "c", "text": "One squeezes the bag while oxygen runs at 6 L/min"}, {"id": "d", "text": "One ventilates alone using a loose one-hand seal"}]'::jsonb, '["a"]', 'A BVM requires a proper mask seal, and the 2-person technique is preferred. A loose seal defeats ventilation, and the BVM runs at 15 L/min, not 6 L/min.'),
  ('masks', 19, 'A client is started on high-flow nasal cannula. Which statement by the nurse to the client''s family is accurate?', '[{"id": "a", "text": "The oxygen is heated and humidified to keep it comfortable."}, {"id": "b", "text": "The device needs a breathing tube placed before it works."}, {"id": "c", "text": "The device is limited to a maximum of 6 liters a minute."}, {"id": "d", "text": "The device gives two pressures for inhaling and exhaling."}]'::jsonb, '["a"]', 'High-flow nasal cannula delivers heated, humidified oxygen and is comfortable, at 40–60 L/min. The 6 L/min maximum applies to a standard nasal cannula, and two pressure levels describe BiPAP.'),
  ('masks', 20, 'A client''s respiratory status deteriorates, and the provider plans support with full control of respiratory rate, tidal volume, FiO₂, and PEEP. Which procedure should the nurse prepare for?', '[{"id": "a", "text": "Endotracheal intubation"}, {"id": "b", "text": "Venturi adaptor placement"}, {"id": "c", "text": "Face tent application"}, {"id": "d", "text": "Partial rebreather setup"}]'::jsonb, '["a"]', 'A ventilator provides maximum respiratory support with full control of RR, TV, FiO₂, and PEEP, and it requires intubation. Masks and face tents do not provide this level of control.'),
  ('masks', 21, 'A client with a tracheostomy is being weaned from the ventilator and is placed on a trach collar. Which intervention is essential?', '[{"id": "a", "text": "Keep a reservoir bag at least one-third full"}, {"id": "b", "text": "Ensure the delivered oxygen is humidified"}, {"id": "c", "text": "Apply a tight seal over the client''s face"}, {"id": "d", "text": "Attach one-way valves to the collar sides"}]'::jsonb, '["b"]', 'Trach devices such as the T-piece or collar use a blow-by method, need humidification, and are used during ventilator weaning. Reservoir bags and one-way valves are features of the non-rebreather mask.'),
  ('masks', 22, 'A client is diagnosed with sleep apnea and needs a device that keeps the airway open during sleep. Which device should the nurse plan to teach about?', '[{"id": "a", "text": "Continuous positive airway pressure (CPAP)"}, {"id": "b", "text": "Venturi mask with a color-coded adaptor"}, {"id": "c", "text": "Non-rebreather mask with a reservoir bag"}, {"id": "d", "text": "Trach collar with humidified oxygen"}]'::jsonb, '["a"]', 'CPAP provides continuous positive airway pressure for sleep apnea and keeps the airway open during sleep. A Venturi mask is chosen for precise O₂ delivery, as in COPD.'),
  ('masks', 23, 'A client with a heart failure (CHF) exacerbation is in respiratory distress. The provider wants non-invasive positive pressure support to prevent intubation. Which device should the nurse anticipate?', '[{"id": "a", "text": "CPAP"}, {"id": "b", "text": "Face tent"}, {"id": "c", "text": "BiPAP"}, {"id": "d", "text": "Mechanical ventilator"}]'::jsonb, '["c"]', 'BiPAP provides two pressure levels, is used for COPD and CHF, and prevents intubation. CPAP is the single-pressure device for sleep apnea, and a ventilator requires intubation.'),
  ('masks', 24, 'A client asks the nurse why BiPAP was chosen instead of CPAP. Which explanation is accurate?', '[{"id": "a", "text": "BiPAP keeps one continuous pressure through the breathing cycle."}, {"id": "b", "text": "BiPAP requires intubation to fully control the breathing rate."}, {"id": "c", "text": "BiPAP lowers the pressure during exhalation so exhaling is easier."}, {"id": "d", "text": "BiPAP sets the oxygen level with color-coded mask adaptors."}]'::jsonb, '["c"]', 'BiPAP has two pressure levels, and the lower exhalation pressure makes it easier to exhale. One continuous pressure level describes CPAP.'),
  ('masks', 25, 'Which statement by a nursing student about BiPAP settings indicates correct understanding?', '[{"id": "a", "text": "IPAP is the exhalation pressure and EPAP is the inhalation pressure."}, {"id": "b", "text": "IPAP and EPAP are two names for one continuous pressure level."}, {"id": "c", "text": "IPAP sets the rate, and EPAP sets the tidal volume delivered."}, {"id": "d", "text": "IPAP is the inhalation pressure and EPAP is the exhalation pressure."}]'::jsonb, '["d"]', 'BiPAP delivers two pressure levels: IPAP during inhalation and EPAP during exhalation. One continuous pressure level is the defining feature of CPAP.'),
  ('masks', 26, 'The nurse teaches a client who will use CPAP at home. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "The machine will take over my breathing for me."}, {"id": "b", "text": "The machine gives one steady pressure all night."}, {"id": "c", "text": "The pressure keeps my airway from collapsing."}, {"id": "d", "text": "I will still breathe on my own while using it."}]'::jsonb, '["a"]', 'With CPAP the patient breathes spontaneously; the device provides one continuous pressure that prevents airway collapse during sleep. Full control of breathing is provided by a ventilator, which requires intubation.'),
  ('masks', 27, 'A client with neuromuscular disease develops progressive respiratory muscle weakness. Which non-invasive device should the nurse anticipate?', '[{"id": "a", "text": "CPAP"}, {"id": "b", "text": "BiPAP"}, {"id": "c", "text": "Simple face mask"}, {"id": "d", "text": "Face tent"}]'::jsonb, '["b"]', 'BiPAP is indicated for COPD, CHF, and neuromuscular disease and can prevent intubation. CPAP''s single continuous pressure is used for sleep apnea.'),
  ('masks', 28, 'At sea level, atmospheric pressure is 760 mmHg and oxygen makes up 21% of the air. What partial pressure does oxygen exert?', '[{"id": "a", "text": "40 mmHg"}, {"id": "b", "text": "104 mmHg"}, {"id": "c", "text": "160 mmHg"}, {"id": "d", "text": "593 mmHg"}]'::jsonb, '["c"]', 'By Dalton''s law, O₂ at 21% of 760 mmHg exerts about 160 mmHg at sea level. A value of 593 mmHg is the partial pressure of nitrogen, and 104 mmHg is alveolar O₂.'),
  ('masks', 29, 'A client asks how the different gases in air add up to atmospheric pressure. The nurse explains that total pressure equals the sum of the partial pressures of all gases. Which law is the nurse describing?', '[{"id": "a", "text": "Dalton''s law"}, {"id": "b", "text": "Boyle''s law"}, {"id": "c", "text": "Henry''s law"}, {"id": "d", "text": "The Bohr effect"}]'::jsonb, '["a"]', 'Dalton''s law states that total pressure equals the sum of the partial pressures of all gases, each behaving independently. Boyle''s law describes the inverse pressure–volume relationship.'),
  ('masks', 30, 'The nurse explains that when the chest cavity enlarges during inspiration, pressure in the lungs falls and air flows in. Which law explains this mechanism?', '[{"id": "a", "text": "Dalton''s law"}, {"id": "b", "text": "Henry''s law"}, {"id": "c", "text": "Boyle''s law"}, {"id": "d", "text": "The Bohr effect"}]'::jsonb, '["c"]', 'Boyle''s law describes the inverse relationship between pressure and volume at constant temperature and is the basis of inspiration and expiration mechanics. Henry''s law concerns gas dissolving in liquid.'),
  ('masks', 31, 'The nurse explains that raising the partial pressure of inspired oxygen increases the amount of oxygen that dissolves in the blood. Which law supports this explanation?', '[{"id": "a", "text": "Boyle''s law"}, {"id": "b", "text": "Henry''s law"}, {"id": "c", "text": "Dalton''s law"}, {"id": "d", "text": "The Bohr effect"}]'::jsonb, '["b"]', 'Henry''s law states the amount of gas dissolved in a liquid is proportional to that gas''s partial pressure and is the basis of O₂ diffusion into blood. Dalton''s law addresses the sum of partial pressures.'),
  ('masks', 32, 'A client who recently traveled to a high-altitude city reports shortness of breath. Which explanation should the nurse provide?', '[{"id": "a", "text": "Higher air pressure forces excess oxygen into the blood."}, {"id": "b", "text": "Lower air pressure makes oxygen diffusion into blood harder."}, {"id": "c", "text": "More gas molecules per breath slow oxygen diffusion."}, {"id": "d", "text": "Higher air pressure at altitude collapses the alveoli."}]'::jsonb, '["b"]', 'Higher altitude means lower atmospheric pressure and fewer gas molecules, so O₂ diffusion into the bloodstream is harder. Altitude lowers, rather than raises, atmospheric pressure.'),
  ('masks', 33, 'A client who is moving to a mountain town at high altitude asks how the body will cope. Which response by the nurse is accurate?', '[{"id": "a", "text": "No change is needed because oxygen diffuses more easily."}, {"id": "b", "text": "Higher air pressure there makes extra oxygen unnecessary."}, {"id": "c", "text": "You may need time to acclimatize or supplemental oxygen."}, {"id": "d", "text": "More gas molecules there will improve oxygen diffusion."}]'::jsonb, '["c"]', 'Because O₂ diffusion is harder at altitude, the body requires acclimatization or supplemental O₂. Altitude has lower pressure and fewer gas molecules, not more.'),
  ('masks', 34, 'The PO₂ in the alveoli is 104 mmHg, and the PO₂ of blood entering the pulmonary capillaries is 40 mmHg. Which statement describes oxygen movement?', '[{"id": "a", "text": "From blood to alveoli, moving from high to low pressure"}, {"id": "b", "text": "From alveoli to blood, moving from high to low pressure"}, {"id": "c", "text": "From blood to alveoli, moving from low to high pressure"}, {"id": "d", "text": "No net movement occurs because the pressures balance"}]'::jsonb, '["b"]', 'O₂ diffuses from the alveoli (104 mmHg) into the blood (40 mmHg), moving from high to low partial pressure. Movement from blood to alveoli describes CO₂, not O₂.'),
  ('masks', 35, 'Blood returning from the tissues has a PCO₂ of 45 mmHg, and alveolar PCO₂ is 40 mmHg. Which statement describes carbon dioxide movement?', '[{"id": "a", "text": "From alveoli into blood, moving from high to low"}, {"id": "b", "text": "From alveoli into blood, moving from low to high"}, {"id": "c", "text": "No movement, because the gradient is too small"}, {"id": "d", "text": "From blood into alveoli, moving from high to low"}]'::jsonb, '["d"]', 'CO₂ diffuses from blood (45 mmHg) into the alveoli (40 mmHg), from high to low partial pressure. Alveoli-to-blood movement describes O₂ diffusion.'),
  ('masks', 36, 'A client''s arterial blood gas report includes a PaO₂ value. The nurse recognizes that PaO₂ directly measures which form of oxygen?', '[{"id": "a", "text": "Oxygen bound to hemoglobin"}, {"id": "b", "text": "Oxygen carried as bicarbonate"}, {"id": "c", "text": "Oxygen dissolved in plasma"}, {"id": "d", "text": "Oxygen bound as carbaminohemoglobin"}]'::jsonb, '["c"]', 'The 1.5% of O₂ dissolved in plasma is measured as PaO₂ on an ABG and directly reflects partial pressure. Hemoglobin-bound oxygen (98.5%) is oxyhemoglobin and is not what PaO₂ measures.'),
  ('masks', 37, 'A nursing student asks how most oxygen is carried in the blood. Which response by the nurse is correct?', '[{"id": "a", "text": "About 70% travels as bicarbonate"}, {"id": "b", "text": "About 1.5% is bound to hemoglobin"}, {"id": "c", "text": "About 98.5% is bound to hemoglobin"}, {"id": "d", "text": "About 98.5% is dissolved in plasma"}]'::jsonb, '["c"]', 'About 98.5% of O₂ is transported bound to hemoglobin as oxyhemoglobin, with only 1.5% dissolved in plasma. The 70% bicarbonate figure applies to CO₂ transport.'),
  ('masks', 38, 'While teaching about oxygen transport, the nurse is asked how many oxygen molecules a single hemoglobin molecule can carry. Which answer is correct?', '[{"id": "a", "text": "One"}, {"id": "b", "text": "Two"}, {"id": "c", "text": "Three"}, {"id": "d", "text": "Four"}]'::jsonb, '["d"]', 'Each hemoglobin molecule carries 4 O₂ molecules, which gives hemoglobin its efficient, large capacity for oxygen transport.'),
  ('masks', 39, 'A client has a high fever and acidosis from a severe infection. How do these conditions affect oxygen delivery to the tissues?', '[{"id": "a", "text": "Hemoglobin holds on to oxygen more tightly."}, {"id": "b", "text": "The O₂-Hb curve shifts toward the left."}, {"id": "c", "text": "Oxygen unloads more easily from hemoglobin."}, {"id": "d", "text": "Oxygen release to the tissues is unchanged."}]'::jsonb, '["c"]', 'Decreased pH and increased temperature shift the O₂-Hb dissociation curve to the right, so O₂ unloads more easily at the tissues. A left shift is the opposite of what these conditions cause.'),
  ('masks', 40, 'Which client condition increases the release of oxygen from hemoglobin to the tissues?', '[{"id": "a", "text": "Elevated blood pH"}, {"id": "b", "text": "Decreased CO₂ level"}, {"id": "c", "text": "Elevated body temperature"}, {"id": "d", "text": "Decreased body temperature"}]'::jsonb, '["c"]', 'Increased temperature, as with fever or active muscles, increases O₂ release from hemoglobin. It is a decreased pH (acidosis) and increased CO₂, not elevated pH or lower CO₂, that also promote release.'),
  ('masks', 41, 'A client is exercising vigorously. Which change in the working muscle tissue promotes oxygen release from hemoglobin?', '[{"id": "a", "text": "Increased tissue pH"}, {"id": "b", "text": "Increased CO₂ production"}, {"id": "c", "text": "Decreased tissue temperature"}, {"id": "d", "text": "Decreased CO₂ production"}]'::jsonb, '["b"]', 'Increased CO₂ from tissues producing waste increases O₂ release from hemoglobin. Exercising tissues develop a decreased pH, not an increased pH.'),
  ('masks', 42, 'A nursing student asks how most carbon dioxide is transported in the blood. Which response by the nurse is correct?', '[{"id": "a", "text": "As carbaminohemoglobin on hemoglobin"}, {"id": "b", "text": "Dissolved directly in the plasma"}, {"id": "c", "text": "As oxyhemoglobin in red blood cells"}, {"id": "d", "text": "As bicarbonate ions in the plasma"}]'::jsonb, '["d"]', 'CO₂ is primarily transported as bicarbonate (70%). Carbaminohemoglobin carries 20% and dissolved CO₂ only 10%.'),
  ('masks', 43, 'Inside red blood cells, carbonic anhydrase converts CO₂ and water so that HCO₃⁻ forms and moves into the plasma. This process is the basis of which system?', '[{"id": "a", "text": "The bicarbonate buffer system"}, {"id": "b", "text": "The surfactant system"}, {"id": "c", "text": "The Bohr effect"}, {"id": "d", "text": "Henry''s law of diffusion"}]'::jsonb, '["a"]', 'CO₂ entering RBCs is converted by carbonic anhydrase to H⁺ and HCO₃⁻, and HCO₃⁻ moving into plasma is the basis of the bicarbonate buffer system. The Bohr effect describes factors that increase O₂ release from hemoglobin.'),
  ('masks', 44, 'A client''s arterial blood gas shows a PaCO₂ of 52 mmHg. How should the nurse interpret this value?', '[{"id": "a", "text": "Above the normal range of 35–45 mmHg"}, {"id": "b", "text": "Within the normal range of 35–45 mmHg"}, {"id": "c", "text": "Below the normal range of 35–45 mmHg"}, {"id": "d", "text": "Within the normal range of 45–55 mmHg"}]'::jsonb, '["a"]', 'Normal PaCO₂ is 35–45 mmHg, so 52 mmHg is above normal. PaCO₂ measures the CO₂ dissolved in plasma.'),
  ('masks', 45, 'A nursing student asks how hemoglobin can carry carbon dioxide and oxygen at the same time. Which explanation is accurate?', '[{"id": "a", "text": "CO₂ binds the heme site after O₂ leaves it"}, {"id": "b", "text": "CO₂ binds the protein portion, not the heme"}, {"id": "c", "text": "CO₂ is converted into O₂ inside the cell"}, {"id": "d", "text": "CO₂ travels only dissolved in the plasma"}]'::jsonb, '["b"]', 'As carbaminohemoglobin, CO₂ binds the protein portion of hemoglobin rather than the heme, so it is compatible with simultaneous O₂ transport. CO₂ is also carried as bicarbonate and dissolved CO₂, not only in plasma.'),
  ('masks', 46, 'A nursing student asks which cells produce pulmonary surfactant. Which response by the nurse is correct?', '[{"id": "a", "text": "Type II pneumocytes"}, {"id": "b", "text": "Type I pneumocytes"}, {"id": "c", "text": "Red blood cells"}, {"id": "d", "text": "Pulmonary capillary cells"}]'::jsonb, '["a"]', 'Surfactant is produced by Type II pneumocytes, the alveolar epithelial cells. Red blood cells carry O₂ and CO₂ but do not produce surfactant.'),
  ('masks', 47, 'A neonate born prematurely develops respiratory distress syndrome (RDS). Which underlying cause should the nurse recognize?', '[{"id": "a", "text": "Excess surfactant in the alveoli"}, {"id": "b", "text": "Lack of surfactant in the alveoli"}, {"id": "c", "text": "Loss of the hypoxic drive"}, {"id": "d", "text": "Hemoglobin unable to carry oxygen"}]'::jsonb, '["b"]', 'Premature babies lack surfactant, which leads to RDS. Loss of hypoxic drive is a concern with high O₂ in COPD, not the cause of RDS.'),
  ('masks', 48, 'The nurse prepares to care for a preterm infant diagnosed with respiratory distress syndrome (RDS). Which treatment should the nurse anticipate?', '[{"id": "a", "text": "Venturi mask at the lowest FiO₂ setting only"}, {"id": "b", "text": "Exogenous surfactant with CPAP or ventilation"}, {"id": "c", "text": "Face tent oxygen without any other therapy"}, {"id": "d", "text": "Simple face mask at 4 L/min as sole therapy"}]'::jsonb, '["b"]', 'Treatment for RDS is exogenous surfactant administration plus CPAP or ventilation. Mask oxygen alone is not the listed treatment, and a simple mask below 6 L/min allows CO₂ buildup.'),
  ('masks', 49, 'A nurse is explaining how surfactant protects the lungs. Which statement best describes its function?', '[{"id": "a", "text": "It raises alveolar surface tension and keeps alveoli open"}, {"id": "b", "text": "It carries oxygen from the alveoli into the plasma"}, {"id": "c", "text": "It converts CO₂ into bicarbonate inside the alveoli"}, {"id": "d", "text": "It reduces alveolar surface tension and prevents collapse"}]'::jsonb, '["d"]', 'Surfactant reduces the surface tension of the alveoli, preventing alveolar collapse (atelectasis). Conversion of CO₂ to bicarbonate occurs in red blood cells via carbonic anhydrase.'),
  ('masks', 50, 'The nurse explains that oxygen and carbon dioxide are exchanged between the alveoli and the pulmonary capillaries. Which step of respiration is the nurse describing?', '[{"id": "a", "text": "External respiration"}, {"id": "b", "text": "Ventilation"}, {"id": "c", "text": "Gas transport"}, {"id": "d", "text": "Internal respiration"}]'::jsonb, '["a"]', 'External respiration is the O₂/CO₂ exchange between alveoli and pulmonary capillaries at the alveolar membrane. Internal respiration is the exchange between blood and tissue cells at systemic capillaries.'),
  ('physiology', 1, 'A postoperative client receiving IV opioids has a respiratory rate of 8 breaths/min. ABG results: pH 7.31, PaCO2 52 mmHg, HCO3 24 mEq/L. How should the nurse interpret these results?', '[{"id": "a", "text": "Metabolic acidosis"}, {"id": "b", "text": "Respiratory alkalosis"}, {"id": "c", "text": "Respiratory acidosis"}, {"id": "d", "text": "Metabolic alkalosis"}]'::jsonb, '["c"]', 'A pH below 7.35 with PaCO2 above 45 and a normal HCO3 is respiratory acidosis, and opioids with hypoventilation are listed causes. Metabolic acidosis would show a low HCO3 with a normal PaCO2.'),
  ('physiology', 2, 'A client having an anxiety attack is breathing rapidly. ABG results: pH 7.49, PaCO2 30 mmHg, HCO3 24 mEq/L. How should the nurse interpret these results?', '[{"id": "a", "text": "Respiratory alkalosis"}, {"id": "b", "text": "Metabolic alkalosis"}, {"id": "c", "text": "Respiratory acidosis"}, {"id": "d", "text": "Metabolic acidosis"}]'::jsonb, '["a"]', 'A pH above 7.45 with PaCO2 below 35 and a normal HCO3 is respiratory alkalosis, caused by hyperventilation and anxiety. Metabolic alkalosis would show a high HCO3 with a normal PaCO2.'),
  ('physiology', 3, 'A client with diabetic ketoacidosis (DKA) has these ABG results: pH 7.26, PaCO2 40 mmHg, HCO3 16 mEq/L. Which acid-base imbalance is present?', '[{"id": "a", "text": "Respiratory acidosis"}, {"id": "b", "text": "Metabolic alkalosis"}, {"id": "c", "text": "Respiratory alkalosis"}, {"id": "d", "text": "Metabolic acidosis"}]'::jsonb, '["d"]', 'A pH below 7.35 with HCO3 below 22 and a normal PaCO2 is metabolic acidosis, and DKA is a listed cause. Respiratory acidosis would show an elevated PaCO2 instead.'),
  ('physiology', 4, 'A client has been vomiting for 3 days. ABG results: pH 7.50, PaCO2 41 mmHg, HCO3 32 mEq/L. How should the nurse interpret these results?', '[{"id": "a", "text": "Respiratory alkalosis"}, {"id": "b", "text": "Metabolic alkalosis"}, {"id": "c", "text": "Metabolic acidosis"}, {"id": "d", "text": "Respiratory acidosis"}]'::jsonb, '["b"]', 'A pH above 7.45 with HCO3 above 26 and a normal PaCO2 is metabolic alkalosis, and vomiting is a listed cause. Respiratory alkalosis would show a PaCO2 below 35.'),
  ('physiology', 5, 'The nurse is reviewing assignments on a medical-surgical unit. Which client is at greatest risk for respiratory acidosis?', '[{"id": "a", "text": "A client receiving opioids who has slow, shallow breathing"}, {"id": "b", "text": "A client who is hyperventilating during an anxiety attack"}, {"id": "c", "text": "A client who has had severe diarrhea for several days"}, {"id": "d", "text": "A client who has been vomiting repeatedly since morning"}]'::jsonb, '["a"]', 'Hypoventilation and opioids are listed causes of respiratory acidosis. Anxiety-related hyperventilation causes respiratory alkalosis, diarrhea causes metabolic acidosis, and vomiting causes metabolic alkalosis.'),
  ('physiology', 6, 'Which client should the nurse identify as most likely to develop respiratory alkalosis?', '[{"id": "a", "text": "A client with chronic renal failure"}, {"id": "b", "text": "A client who overuses antacids"}, {"id": "c", "text": "A client with a high fever"}, {"id": "d", "text": "A client with COPD who retains CO2"}]'::jsonb, '["c"]', 'Fever, anxiety, and hyperventilation are listed causes of respiratory alkalosis. Renal failure causes metabolic acidosis, antacid overuse causes metabolic alkalosis, and COPD with CO2 retention causes respiratory acidosis.'),
  ('physiology', 7, 'A client with chronic renal failure has an arterial blood gas drawn. Which ABG pattern should the nurse expect?', '[{"id": "a", "text": "pH high, PaCO2 low, HCO3 normal"}, {"id": "b", "text": "pH low, PaCO2 normal, HCO3 low"}, {"id": "c", "text": "pH low, PaCO2 high, HCO3 normal"}, {"id": "d", "text": "pH high, PaCO2 normal, HCO3 high"}]'::jsonb, '["b"]', 'Renal failure is a cause of metabolic acidosis, which shows a pH below 7.35, a normal PaCO2, and HCO3 below 22. A low pH with high PaCO2 and normal HCO3 is respiratory acidosis.'),
  ('physiology', 8, 'A client reports taking large amounts of antacids every day for several months. The nurse should assess the client for which acid-base imbalance?', '[{"id": "a", "text": "Respiratory acidosis"}, {"id": "b", "text": "Metabolic acidosis"}, {"id": "c", "text": "Respiratory alkalosis"}, {"id": "d", "text": "Metabolic alkalosis"}]'::jsonb, '["d"]', 'Antacid overuse and vomiting are listed causes of metabolic alkalosis, which shows a pH above 7.45 and HCO3 above 26. Metabolic acidosis is linked to DKA, renal failure, and diarrhea.'),
  ('physiology', 9, 'A client with long-standing COPD has an elevated PaCO2 and an elevated HCO3 on an arterial blood gas. How should the nurse interpret the elevated HCO3?', '[{"id": "a", "text": "Kidneys retaining HCO3 to offset respiratory acidosis"}, {"id": "b", "text": "A separate metabolic acidosis from kidney failure"}, {"id": "c", "text": "Lungs blowing off CO2 to correct metabolic alkalosis"}, {"id": "d", "text": "Respiratory alkalosis caused by rapid breathing"}]'::jsonb, '["a"]', 'In COPD, chronic CO2 retention causes respiratory acidosis, and the kidney compensates by retaining HCO3; an increased HCO3 indicates compensated respiratory acidosis. Metabolic acidosis would show a decreased HCO3.'),
  ('physiology', 10, 'A client with COPD has chronic retention of carbon dioxide. Which acid-base imbalance does this retention produce?', '[{"id": "a", "text": "Respiratory alkalosis"}, {"id": "b", "text": "Metabolic acidosis"}, {"id": "c", "text": "Respiratory acidosis"}, {"id": "d", "text": "Metabolic alkalosis"}]'::jsonb, '["c"]', 'Chronic CO2 retention in COPD causes respiratory acidosis, and COPD is listed among its causes. Respiratory alkalosis results from blowing off CO2, the opposite direction.'),
  ('physiology', 11, 'A client is admitted after a spinal cord injury at the C3 level. Which assessment is the nurse''s priority?', '[{"id": "a", "text": "Lower extremity sensation and movement"}, {"id": "b", "text": "Respiratory rate, depth, and effort"}, {"id": "c", "text": "Presence and quality of bowel sounds"}, {"id": "d", "text": "Skin integrity over the sacrum"}]'::jsonb, '["b"]', 'The phrenic nerve arising from C3–C5 innervates the diaphragm, and its damage leads to diaphragm paralysis and respiratory failure. Breathing therefore takes priority over the other assessments.'),
  ('physiology', 12, 'The nurse is caring for several clients with spinal cord injuries. Which client is at greatest risk for loss of diaphragm function?', '[{"id": "a", "text": "A client with a T4 injury"}, {"id": "b", "text": "A client with a T10 injury"}, {"id": "c", "text": "A client with an L1 injury"}, {"id": "d", "text": "A client with a C4 injury"}]'::jsonb, '["d"]', 'The diaphragm is innervated by the phrenic nerve, which arises from C3–C5 ("C3, 4, 5 keeps the diaphragm alive"). Thoracic and lumbar injuries are below this level.'),
  ('physiology', 13, 'A client sustained damage to the phrenic nerve during a neck injury. Which complication should the nurse anticipate?', '[{"id": "a", "text": "Diaphragm paralysis leading to respiratory failure"}, {"id": "b", "text": "Loss of the basic breathing rhythm from the medulla"}, {"id": "c", "text": "Impaired diffusion of oxygen across the alveoli"}, {"id": "d", "text": "Kidney retention of bicarbonate in the blood"}]'::jsonb, '["a"]', 'The phrenic nerve supplies the diaphragm, so its damage causes diaphragm paralysis and respiratory failure. The basic breathing rhythm is set by the medulla oblongata, not the phrenic nerve.'),
  ('physiology', 14, 'While assessing a client, the nurse observes the sternocleidomastoid and scalene muscles contracting with each breath. How should the nurse interpret this finding?', '[{"id": "a", "text": "Normal quiet breathing at rest"}, {"id": "b", "text": "Efficient work by the diaphragm"}, {"id": "c", "text": "A sign of respiratory distress"}, {"id": "d", "text": "Expected compensation needing no follow-up"}]'::jsonb, '["c"]', 'The sternocleidomastoid and scalenes are accessory muscles, and accessory muscle use is always a sign of respiratory distress. The diaphragm, not the accessory muscles, does the work of normal breathing.'),
  ('physiology', 15, 'The nurse reviews assessment data for a client admitted with shortness of breath. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Respiratory rate of 18 breaths/min"}, {"id": "b", "text": "SaO2 of 97% on room air"}, {"id": "c", "text": "PaCO2 of 40 mmHg"}, {"id": "d", "text": "Use of neck muscles to breathe"}]'::jsonb, '["d"]', 'Use of accessory muscles such as the sternocleidomastoid and scalenes signals respiratory distress. A respiratory rate of 18, SaO2 of 97%, and PaCO2 of 40 are all within normal ranges.'),
  ('physiology', 16, 'A nursing student asks the nurse about the role of the diaphragm in breathing. Which statement about the diaphragm is accurate?', '[{"id": "a", "text": "It is an accessory muscle used only during distress"}, {"id": "b", "text": "It is the main breathing muscle, supplied by the phrenic nerve"}, {"id": "c", "text": "It is supplied by nerves arising from the lumbar spine"}, {"id": "d", "text": "It moves upward when it contracts during inhalation"}]'::jsonb, '["b"]', 'The diaphragm is the main muscle of breathing and is innervated by the phrenic nerve (C3–C5). It contracts and moves down during inhalation.'),
  ('physiology', 17, 'The nurse observes a client''s abdomen during quiet inhalation. Which diaphragm movement is occurring?', '[{"id": "a", "text": "It contracts and moves down"}, {"id": "b", "text": "It relaxes and moves up"}, {"id": "c", "text": "It contracts and moves up"}, {"id": "d", "text": "It relaxes and moves down"}]'::jsonb, '["a"]', 'During inhalation the diaphragm contracts and moves down, expanding the chest. It relaxes and moves up during exhalation.'),
  ('physiology', 18, 'Which sequence correctly describes what happens during a normal exhalation?', '[{"id": "a", "text": "Diaphragm contracts, chest expands, pressure falls, air flows out"}, {"id": "b", "text": "Diaphragm relaxes, chest expands, pressure falls, air flows in"}, {"id": "c", "text": "Diaphragm contracts, chest shrinks, pressure rises, air flows in"}, {"id": "d", "text": "Diaphragm relaxes, chest shrinks, pressure rises, air flows out"}]'::jsonb, '["d"]', 'In exhalation the diaphragm relaxes and moves up, the chest cavity decreases, pressure rises, and air is pushed out. Diaphragm contraction with chest expansion describes inhalation.'),
  ('physiology', 19, 'The nurse watches a client''s chest during a deep inspiration. Which movement of the rib cage should the nurse expect to see?', '[{"id": "a", "text": "The rib cage lowers and moves inward"}, {"id": "b", "text": "The rib cage stays fixed in position"}, {"id": "c", "text": "The rib cage lifts up and moves outward"}, {"id": "d", "text": "The rib cage lowers and moves outward"}]'::jsonb, '["c"]', 'During inhalation the rib cage lifts up and out as the chest cavity expands. The rib cage lowers and moves in during exhalation.'),
  ('physiology', 20, 'A client asks the nurse what makes air flow into the lungs during a breath. Which explanation is accurate?', '[{"id": "a", "text": "The chest cavity shrinks, creating positive pressure"}, {"id": "b", "text": "The chest cavity expands, creating negative pressure"}, {"id": "c", "text": "The diaphragm relaxes and pulls air upward"}, {"id": "d", "text": "Air moves from lower pressure to higher pressure"}]'::jsonb, '["b"]', 'During inhalation the chest cavity expands, creating negative pressure, and air rushes in from high to low pressure. A shrinking chest cavity with rising pressure pushes air out.'),
  ('physiology', 21, 'Applying Boyle''s law, as the volume of the thoracic cavity increases during inspiration, what happens to the pressure inside the lungs?', '[{"id": "a", "text": "It decreases, so air flows in"}, {"id": "b", "text": "It increases, so air flows in"}, {"id": "c", "text": "It decreases, so air flows out"}, {"id": "d", "text": "It increases, so air flows out"}]'::jsonb, '["a"]', 'Pressure times volume is constant, so increasing volume lowers pressure; external air pressure is then higher and air flows in. Rising pressure with decreasing volume describes expiration.'),
  ('physiology', 22, 'At the end of inspiration, a client''s diaphragm relaxes and lung volume decreases. Which outcome should the nurse predict?', '[{"id": "a", "text": "Lung pressure falls below outside pressure and air flows in"}, {"id": "b", "text": "Lung pressure stays equal to outside pressure and air stops"}, {"id": "c", "text": "Lung pressure rises above outside pressure and air flows out"}, {"id": "d", "text": "Lung pressure falls below outside pressure and air flows out"}]'::jsonb, '["c"]', 'Per Boyle''s law, when volume decreases pressure increases, making lung pressure higher than outside pressure so air flows out. Falling lung pressure occurs with increasing volume during inspiration.'),
  ('physiology', 23, 'A client in distress is taking very shallow breaths of about 150 mL each. The nurse recognizes which consequence of this breathing pattern?', '[{"id": "a", "text": "Each breath equals a normal tidal volume"}, {"id": "b", "text": "Shallow breaths improve alveolar gas exchange"}, {"id": "c", "text": "Shallow breaths deliver more air to alveoli"}, {"id": "d", "text": "Each breath mostly fills airways, missing alveoli"}]'::jsonb, '["d"]', 'Dead space is about 150 mL of air filling the airways that never reaches the alveoli, so breaths this small contribute little to gas exchange. A normal tidal volume is about 500 mL.'),
  ('physiology', 24, 'A nursing student states that oxygen and carbon dioxide are exchanged in the trachea and bronchi. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Gas exchange occurs in the trachea and bronchi.\""}, {"id": "b", "text": "\"Gas exchange occurs only in the alveoli.\""}, {"id": "c", "text": "\"Gas exchange occurs equally in all airways.\""}, {"id": "d", "text": "\"Gas exchange occurs mainly in the bronchi.\""}]'::jsonb, '["b"]', 'Gas exchange happens only in the alveoli, not in the airways. Air in the trachea and bronchi is dead space that does not participate in gas exchange.'),
  ('physiology', 25, 'As blood flows through the capillaries around the alveoli in a healthy client, in which direction does oxygen move?', '[{"id": "a", "text": "From the alveoli into the bloodstream"}, {"id": "b", "text": "From the bloodstream into the alveoli"}, {"id": "c", "text": "From the bronchi directly into the blood"}, {"id": "d", "text": "From the capillaries into the airways"}]'::jsonb, '["a"]', 'Oxygen moves from the alveoli into the bloodstream, while carbon dioxide moves the opposite way. Gas exchange does not occur in the bronchi or other airways.'),
  ('physiology', 26, 'Which pathway correctly describes how carbon dioxide produced by the body leaves a client''s body?', '[{"id": "a", "text": "Alveoli, then bloodstream, then tissues"}, {"id": "b", "text": "Airways, then bloodstream, then alveoli"}, {"id": "c", "text": "Bloodstream, then bronchi, then exhaled"}, {"id": "d", "text": "Bloodstream, then alveoli, then exhaled"}]'::jsonb, '["d"]', 'Carbon dioxide moves from the bloodstream into the alveoli and is then exhaled. It does not pass from the blood directly into the bronchi, because gas exchange occurs only in the alveoli.'),
  ('physiology', 27, 'The nurse explains how oxygen passes from the alveoli into the blood. Which statement best describes this movement?', '[{"id": "a", "text": "It is pumped across by diaphragm contraction"}, {"id": "b", "text": "It moves from lower to higher concentration"}, {"id": "c", "text": "It diffuses from higher to lower concentration"}, {"id": "d", "text": "It is pushed across by accessory muscle effort"}]'::jsonb, '["c"]', 'Gases move between the alveoli and blood by diffusion from high to low concentration. Movement from low to high concentration reverses the direction of diffusion.'),
  ('physiology', 28, 'A client has a normal tidal volume of 500 mL. Approximately how much of each breath reaches the alveoli to take part in gas exchange?', '[{"id": "a", "text": "About 650 mL"}, {"id": "b", "text": "About 350 mL"}, {"id": "c", "text": "About 150 mL"}, {"id": "d", "text": "About 500 mL"}]'::jsonb, '["b"]', 'About 150 mL of each breath fills the airways as dead space and never reaches the alveoli, so roughly 350 mL of a 500 mL tidal volume participates in gas exchange. 150 mL is the dead space itself, not the portion reaching alveoli.'),
  ('physiology', 29, 'While reviewing ventilation with a client''s family, the nurse describes the air that remains in the trachea and bronchi with each breath. Which term and description match this air?', '[{"id": "a", "text": "Dead space; air that does not take part in gas exchange"}, {"id": "b", "text": "Tidal volume; air exchanging gases in the alveoli"}, {"id": "c", "text": "Minute ventilation; total air moved each minute"}, {"id": "d", "text": "Tidal volume; air remaining after a full exhale"}]'::jsonb, '["a"]', 'Dead space is air filling the airways that never reaches the alveoli and does not participate in gas exchange. Tidal volume is the air moved in one normal breath, and minute ventilation is total air moved per minute.'),
  ('physiology', 30, 'A client has a tidal volume of 500 mL and a respiratory rate of 14 breaths/min. How should the nurse interpret the client''s minute ventilation?', '[{"id": "a", "text": "7 L/min, below the normal range"}, {"id": "b", "text": "0.7 L/min, below the normal range"}, {"id": "c", "text": "7 L/min, within the normal range"}, {"id": "d", "text": "70 L/min, above the normal range"}]'::jsonb, '["c"]', 'Minute ventilation equals TV × RR: 500 mL × 14 = 7,000 mL, or 7 L/min, which falls within the normal 6–8 L/min. It is not below normal.'),
  ('physiology', 31, 'A febrile client has a tidal volume of 500 mL and a respiratory rate of 30 breaths/min. How should the nurse interpret the client''s minute ventilation?', '[{"id": "a", "text": "15 L/min, within the normal range"}, {"id": "b", "text": "1.5 L/min, below the normal range"}, {"id": "c", "text": "6 L/min, within the normal range"}, {"id": "d", "text": "15 L/min, above the normal range"}]'::jsonb, '["d"]', '500 mL × 30 breaths/min = 15 L/min, which is above the normal minute ventilation of about 6–8 L/min. A value of 15 L/min is not within the normal range.'),
  ('physiology', 32, 'A client''s respiratory rate falls from 16 to 8 breaths/min while the tidal volume stays the same. What change in minute ventilation should the nurse predict?', '[{"id": "a", "text": "It increases because each breath is deeper"}, {"id": "b", "text": "It decreases because fewer breaths occur each minute"}, {"id": "c", "text": "It stays the same because tidal volume is unchanged"}, {"id": "d", "text": "It increases because more CO2 is being retained"}]'::jsonb, '["b"]', 'Minute ventilation is TV × RR, so halving the respiratory rate with the same tidal volume decreases minute ventilation. It cannot stay the same when one factor in the product falls.'),
  ('physiology', 33, 'An adult client''s respiratory rate is 10 breaths/min at rest. How should the nurse interpret this finding?', '[{"id": "a", "text": "Below the normal range"}, {"id": "b", "text": "Within the normal range"}, {"id": "c", "text": "Above the normal range"}, {"id": "d", "text": "At the upper limit of normal"}]'::jsonb, '["a"]', 'The normal respiratory rate is 12–20 breaths per minute, so 10 breaths/min is below normal. It is neither within nor above the range.'),
  ('physiology', 34, 'A client''s tidal volume is measured at 500 mL during quiet breathing. How should the nurse interpret this value?', '[{"id": "a", "text": "Much lower than a normal breath"}, {"id": "b", "text": "Much higher than a normal breath"}, {"id": "c", "text": "Consistent with a normal breath"}, {"id": "d", "text": "Equal to the normal dead space"}]'::jsonb, '["c"]', 'Tidal volume, the air moved in or out in one normal breath, is about 500 mL. Normal dead space is about 150 mL, not 500 mL.'),
  ('physiology', 35, 'A client''s arterial blood gas shows a PaO2 of 72 mmHg. How should the nurse interpret this value?', '[{"id": "a", "text": "Above the normal range"}, {"id": "b", "text": "Within the normal range"}, {"id": "c", "text": "At the upper limit of normal"}, {"id": "d", "text": "Below the normal range"}]'::jsonb, '["d"]', 'Normal arterial PaO2 is 80–100 mmHg, so 72 mmHg is below normal. It is not within or above the range.'),
  ('physiology', 36, 'A client''s arterial oxygen saturation (SaO2) is 91%. How should the nurse interpret this value?', '[{"id": "a", "text": "Within the normal range"}, {"id": "b", "text": "Below the normal range"}, {"id": "c", "text": "Above the normal range"}, {"id": "d", "text": "At the low end of normal"}]'::jsonb, '["b"]', 'Normal SaO2 is 95–100%, so 91% is below the normal range. It is not at the low end of normal because 95% is the lower limit.'),
  ('physiology', 37, 'The nurse reviews a client''s arterial blood gas results. Which value is within normal limits?', '[{"id": "a", "text": "PaO2 90 mmHg"}, {"id": "b", "text": "pH 7.32"}, {"id": "c", "text": "PaCO2 50 mmHg"}, {"id": "d", "text": "SaO2 90%"}]'::jsonb, '["a"]', 'Normal PaO2 is 80–100 mmHg, so 90 mmHg is normal. A pH of 7.32 is below 7.35, a PaCO2 of 50 is above 45, and an SaO2 of 90% is below 95%.'),
  ('physiology', 38, 'A client''s arterial pH is 7.47. How should the nurse interpret this value?', '[{"id": "a", "text": "Normal pH within range"}, {"id": "b", "text": "Acidic pH below range"}, {"id": "c", "text": "Alkaline pH above range"}, {"id": "d", "text": "Low-normal pH within range"}]'::jsonb, '["c"]', 'Normal blood pH is 7.35–7.45, so 7.47 is above range, indicating alkalosis. Acidosis is a pH below 7.35.'),
  ('physiology', 39, 'A client has a brainstem lesion involving the medulla oblongata. Which breathing function is most directly at risk?', '[{"id": "a", "text": "Fine-tuning of breathing depth"}, {"id": "b", "text": "Nerve supply to the diaphragm"}, {"id": "c", "text": "Diffusion of gases in the alveoli"}, {"id": "d", "text": "The basic rhythm of breathing"}]'::jsonb, '["d"]', 'The medulla oblongata sets the basic rhythm of breathing. Fine-tuning of rate and depth is the role of the pons, and the diaphragm is supplied by the phrenic nerve.'),
  ('physiology', 40, 'A client''s injury affects the brainstem structure that adjusts how fast and how deeply the client breathes. Which structure is involved?', '[{"id": "a", "text": "Medulla oblongata"}, {"id": "b", "text": "Pons"}, {"id": "c", "text": "Phrenic nerve"}, {"id": "d", "text": "Alveoli"}]'::jsonb, '["b"]', 'The pons fine-tunes the rate and depth of breathing. The medulla oblongata sets the basic rhythm, and the phrenic nerve supplies the diaphragm.'),
  ('physiology', 41, 'A client''s PaCO2 begins to rise during a period of breath-holding. Which response should the nurse expect from the brainstem?', '[{"id": "a", "text": "An increase in respiratory rate"}, {"id": "b", "text": "A decrease in respiratory rate"}, {"id": "c", "text": "No change until oxygen falls"}, {"id": "d", "text": "A pause in breathing"}]'::jsonb, '["a"]', 'The brainstem senses CO2 levels in the blood, and high CO2 triggers faster breathing. CO2, not oxygen, is the primary driver, so the response does not wait for oxygen to fall.'),
  ('physiology', 42, 'In a healthy client, which change in the blood is the primary stimulus that drives the respiratory rate?', '[{"id": "a", "text": "A falling oxygen level"}, {"id": "b", "text": "A rising pH level"}, {"id": "c", "text": "A rising carbon dioxide level"}, {"id": "d", "text": "A falling bicarbonate level"}]'::jsonb, '["c"]', 'CO2 levels, not O2, drive the respiratory rate in healthy patients; rising CO2 makes the client breathe faster. Falling oxygen is not the primary driver.'),
  ('physiology', 43, 'After a brisk walk, a healthy client''s elevated PaCO2 returns to normal. Which change in breathing should the nurse expect?', '[{"id": "a", "text": "The rate continues to increase"}, {"id": "b", "text": "The rhythm becomes irregular"}, {"id": "c", "text": "Breathing stops briefly"}, {"id": "d", "text": "Breathing slows back down"}]'::jsonb, '["d"]', 'The brainstem senses CO2; high CO2 causes faster breathing, and when CO2 returns to normal, breathing slows back down.'),
  ('physiology', 44, 'A client is hyperventilating during a panic attack. Which change in PaCO2 should the nurse anticipate?', '[{"id": "a", "text": "An increase to above 45 mmHg"}, {"id": "b", "text": "A decrease to below 35 mmHg"}, {"id": "c", "text": "No change from 35–45 mmHg"}, {"id": "d", "text": "An increase with a low pH"}]'::jsonb, '["b"]', 'Hyperventilation and anxiety cause respiratory alkalosis, in which PaCO2 falls below 35 mmHg and pH rises above 7.45. A PaCO2 above 45 with low pH reflects respiratory acidosis.'),
  ('physiology', 45, 'A client who received a large opioid dose is breathing 6 times per minute. Which change in PaCO2 should the nurse anticipate?', '[{"id": "a", "text": "A rise to above 45 mmHg"}, {"id": "b", "text": "A fall to below 35 mmHg"}, {"id": "c", "text": "No change from 35–45 mmHg"}, {"id": "d", "text": "A fall with a high pH"}]'::jsonb, '["a"]', 'Hypoventilation and opioids cause respiratory acidosis, in which PaCO2 rises above 45 mmHg and pH falls below 7.35. A low PaCO2 with high pH reflects respiratory alkalosis.'),
  ('physiology', 46, 'A client has had severe diarrhea for 4 days. The nurse should monitor the client for which acid-base imbalance?', '[{"id": "a", "text": "Respiratory alkalosis"}, {"id": "b", "text": "Metabolic alkalosis"}, {"id": "c", "text": "Respiratory acidosis"}, {"id": "d", "text": "Metabolic acidosis"}]'::jsonb, '["d"]', 'Diarrhea is a listed cause of metabolic acidosis, along with DKA and renal failure. Metabolic alkalosis is linked to vomiting and antacid overuse.'),
  ('physiology', 47, 'Two clients both have an arterial pH of 7.30. Which additional finding indicates a metabolic rather than a respiratory cause?', '[{"id": "a", "text": "PaCO2 above 45 with a normal HCO3"}, {"id": "b", "text": "PaCO2 below 35 with a normal HCO3"}, {"id": "c", "text": "HCO3 below 22 with a normal PaCO2"}, {"id": "d", "text": "HCO3 above 26 with a normal PaCO2"}]'::jsonb, '["c"]', 'Metabolic acidosis shows a pH below 7.35, a normal PaCO2, and HCO3 below 22. A PaCO2 above 45 with normal HCO3 indicates respiratory acidosis.'),
  ('physiology', 48, 'A client''s arterial pH is 7.48. Which additional finding indicates a respiratory rather than a metabolic cause?', '[{"id": "a", "text": "HCO3 above 26 with a normal PaCO2"}, {"id": "b", "text": "PaCO2 below 35 with a normal HCO3"}, {"id": "c", "text": "PaCO2 above 45 with a normal HCO3"}, {"id": "d", "text": "HCO3 below 22 with a normal PaCO2"}]'::jsonb, '["b"]', 'Respiratory alkalosis shows a pH above 7.45, PaCO2 below 35, and a normal HCO3. An HCO3 above 26 with normal PaCO2 indicates metabolic alkalosis.'),
  ('physiology', 49, 'The nurse explains to a client why oxygen can pass into the blood in the lungs. Which structural feature makes gas exchange possible?', '[{"id": "a", "text": "Alveoli are surrounded by capillaries"}, {"id": "b", "text": "Bronchi are lined with air sacs"}, {"id": "c", "text": "The trachea is surrounded by capillaries"}, {"id": "d", "text": "The diaphragm contains tiny air sacs"}]'::jsonb, '["a"]', 'Alveoli are tiny air sacs surrounded by capillaries, allowing oxygen to diffuse into the bloodstream. Gas exchange happens only in the alveoli, not in the trachea or bronchi.'),
  ('physiology', 50, 'The nurse explains dead space to a client with a respiratory disorder. Why does air that remains in the trachea and bronchi not oxygenate the blood?', '[{"id": "a", "text": "It moves from low to high concentration"}, {"id": "b", "text": "It is exhaled before reaching the trachea"}, {"id": "c", "text": "The bronchi exchange only carbon dioxide"}, {"id": "d", "text": "Gas exchange occurs only in the alveoli"}]'::jsonb, '["d"]', 'Gas exchange happens only in the alveoli, so air remaining in the airways is dead space that never participates in exchange. The bronchi do not exchange carbon dioxide either.'),
  ('effusion', 1, 'A client newly diagnosed with a pleural effusion asks what the condition is. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Air has collected in the space around the lung."}, {"id": "b", "text": "Fluid has filled the air sacs inside the lung."}, {"id": "c", "text": "Abnormal fluid has collected in the pleural space."}, {"id": "d", "text": "Mucus has blocked the large airways of the lung."}]'::jsonb, '["c"]', 'Pleural effusion is the abnormal accumulation of fluid in the pleural space between the visceral and parietal pleura. The fluid compresses the lung from outside rather than filling the lung itself.'),
  ('effusion', 2, 'The nurse is explaining normal pleural anatomy to a client. Approximately how much lubricating fluid is normally present in the pleural space?', '[{"id": "a", "text": "5–15 mL"}, {"id": "b", "text": "50–100 mL"}, {"id": "c", "text": "150–200 mL"}, {"id": "d", "text": "1,000–1,500 mL"}]'::jsonb, '["a"]', 'Normally only 5–15 mL of lubricating fluid is present in the pleural space. Any significant accumulation beyond this impairs lung expansion and gas exchange.'),
  ('effusion', 3, 'A client with heart failure undergoes thoracentesis for a pleural effusion. Which fluid characteristics does the nurse expect?', '[{"id": "a", "text": "Cloudy with immune cells and pus"}, {"id": "b", "text": "Cloudy and high in protein"}, {"id": "c", "text": "Clear, thin, and low in protein"}, {"id": "d", "text": "Thick, bloody, and high in protein"}]'::jsonb, '["c"]', 'Heart failure is the most common cause of transudative effusion, which is clear, thin, and low in protein. Cloudy, high-protein fluid with immune cells describes an exudate.'),
  ('effusion', 4, 'Which condition is the most common cause of a transudative pleural effusion?', '[{"id": "a", "text": "Pneumonia"}, {"id": "b", "text": "Tuberculosis"}, {"id": "c", "text": "Lung cancer"}, {"id": "d", "text": "Heart failure"}]'::jsonb, '["d"]', 'Heart failure is the most common cause of transudative effusion. Pneumonia, tuberculosis, and cancer are causes of exudative effusion.'),
  ('effusion', 5, 'A client with pneumonia develops a parapneumonic pleural effusion. The nurse anticipates that the pleural fluid will be:', '[{"id": "a", "text": "clear, thin, and low in protein"}, {"id": "b", "text": "cloudy and low in protein"}, {"id": "c", "text": "clear and high in protein"}, {"id": "d", "text": "cloudy and high in protein"}]'::jsonb, '["d"]', 'A parapneumonic effusion is exudative, and exudate is cloudy and high in protein and may contain immune cells, pus, or blood. Clear, thin, low-protein fluid describes a transudate.'),
  ('effusion', 6, 'The nurse is reviewing four clients with pleural effusions. Which client''s effusion is most likely exudative?', '[{"id": "a", "text": "A client with heart failure"}, {"id": "b", "text": "A client with liver cirrhosis"}, {"id": "c", "text": "A client with nephrotic syndrome"}, {"id": "d", "text": "A client with tuberculosis"}]'::jsonb, '["d"]', 'Tuberculosis is a cause of exudative effusion along with pneumonia and cancer. Heart failure, cirrhosis, and nephrotic syndrome cause transudative effusions.'),
  ('effusion', 7, 'Which client''s pleural effusion is most likely transudative?', '[{"id": "a", "text": "A client with nephrotic syndrome"}, {"id": "b", "text": "A client with pneumonia"}, {"id": "c", "text": "A client with breast cancer"}, {"id": "d", "text": "A client with tuberculosis"}]'::jsonb, '["a"]', 'Nephrotic syndrome is a cause of transudative effusion, along with heart failure and cirrhosis. Pneumonia, cancer, and tuberculosis cause exudative effusions.'),
  ('effusion', 8, 'The nurse is explaining how a transudative pleural effusion develops. Which statement by the nurse is accurate?', '[{"id": "a", "text": "Pressure or oncotic changes make fluid leak from vessels."}, {"id": "b", "text": "Cancer cells invade and damage the pleural membrane."}, {"id": "c", "text": "Infection inflames and disrupts the pleural membrane."}, {"id": "d", "text": "Pus from a lung infection drains into the pleural space."}]'::jsonb, '["a"]', 'In a transudative effusion, fluid leaks out of blood vessels because of pressure or oncotic changes, not infection. Disruption of the pleural membrane by inflammation, infection, or malignancy causes an exudate.'),
  ('effusion', 9, 'A client with lung cancer has an exudative pleural effusion. Which mechanism explains this type of effusion?', '[{"id": "a", "text": "Pressure changes push fluid out of blood vessels"}, {"id": "b", "text": "Oncotic changes let thin fluid leak from vessels"}, {"id": "c", "text": "Malignancy disrupts the pleural membrane"}, {"id": "d", "text": "Fluid overload from heart failure leaks out"}]'::jsonb, '["c"]', 'Exudative effusion develops when inflammation, infection, or malignancy disrupts the pleural membrane. Pressure or oncotic changes causing fluid to leak from vessels describe a transudate.'),
  ('effusion', 10, 'The nurse reviews transudative and exudative effusions with a nursing student. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "Exudate is typically caused by heart failure."}, {"id": "b", "text": "Exudate may contain immune cells."}, {"id": "c", "text": "Cirrhosis typically causes a transudate."}, {"id": "d", "text": "Transudate is usually clear fluid."}]'::jsonb, '["a"]', 'Heart failure causes a transudate; exudates are caused by infection or cancer. The other statements correctly describe clear transudate, immune cells in exudate, and cirrhosis as a transudate cause.'),
  ('effusion', 11, 'A client with a pleural effusion reports needing to sleep propped up on several pillows because breathing is hard when lying flat. The nurse recognizes this as:', '[{"id": "a", "text": "improvement related to fluid reabsorption"}, {"id": "b", "text": "pleuritic pain related to deep breathing"}, {"id": "c", "text": "orthopnea related to fluid shifting"}, {"id": "d", "text": "hyperresonance related to trapped air"}]'::jsonb, '["c"]', 'Orthopnea, difficulty breathing when lying flat, occurs in pleural effusion from fluid shifting. Pleuritic pain is sharp chest pain worsened by deep breathing or coughing, not positional dyspnea.'),
  ('effusion', 12, 'Which description of chest pain is consistent with a pleural effusion?', '[{"id": "a", "text": "Dull pain relieved by deep breathing"}, {"id": "b", "text": "Sharp pain that worsens with deep breaths"}, {"id": "c", "text": "Pressure that improves with coughing"}, {"id": "d", "text": "Mild ache unaffected by breathing"}]'::jsonb, '["b"]', 'Pleural effusion causes pleuritic chest pain that is sharp and worse with a deep breath or cough. Pain that is relieved by deep breathing or coughing reverses this pattern.'),
  ('effusion', 13, 'Which type of cough does the nurse expect in a client with a pleural effusion?', '[{"id": "a", "text": "Productive cough with thick sputum"}, {"id": "b", "text": "Dry, non-productive cough"}, {"id": "c", "text": "Cough with pink, frothy sputum"}, {"id": "d", "text": "Productive cough with purulent sputum"}]'::jsonb, '["b"]', 'Pleural effusion causes a dry, non-productive cough. Pink, frothy sputum is a sign of re-expansion pulmonary edema after too much fluid is removed too fast.'),
  ('effusion', 14, 'A client has diminished breath sounds and dullness to percussion over the left lower chest. Which condition does the nurse suspect?', '[{"id": "a", "text": "Left-sided pneumothorax"}, {"id": "b", "text": "Left-sided pleural effusion"}, {"id": "c", "text": "Right-sided pneumothorax"}, {"id": "d", "text": "Right-sided pleural effusion"}]'::jsonb, '["b"]', 'Diminished breath sounds with dull percussion on one side suggest pleural effusion on that side. Pneumothorax produces diminished sounds with hyperresonant percussion.'),
  ('effusion', 15, 'A client has diminished breath sounds on one side of the chest. Which percussion finding helps the nurse distinguish a pneumothorax from a pleural effusion?', '[{"id": "a", "text": "Hyperresonance suggests pleural effusion"}, {"id": "b", "text": "Hyperresonance suggests pneumothorax"}, {"id": "c", "text": "Dullness suggests pneumothorax"}, {"id": "d", "text": "Dullness rules out pleural effusion"}]'::jsonb, '["b"]', 'Pneumothorax presents with diminished sounds and hyperresonant percussion, while pleural effusion presents with diminished sounds and dullness. Dullness therefore points toward effusion, not pneumothorax.'),
  ('effusion', 16, 'When inspecting a client with a right-sided pleural effusion, which finding does the nurse expect?', '[{"id": "a", "text": "Decreased chest expansion on the right"}, {"id": "b", "text": "Equal chest expansion on both sides"}, {"id": "c", "text": "Increased chest expansion on the right"}, {"id": "d", "text": "Decreased chest expansion on the left"}]'::jsonb, '["a"]', 'Pleural effusion decreases chest expansion on the affected side, which is the right side here. Expansion is reduced, not increased, because fluid prevents the lung from fully expanding.'),
  ('effusion', 17, 'A client has a large left-sided pleural effusion. Which tracheal finding is the nurse most likely to note?', '[{"id": "a", "text": "Deviation toward the left"}, {"id": "b", "text": "Deviation that shifts with each breath"}, {"id": "c", "text": "Midline position that never changes"}, {"id": "d", "text": "Deviation toward the right"}]'::jsonb, '["d"]', 'In large effusions the trachea deviates away from the effusion, so a left-sided effusion shifts the trachea to the right. Deviation toward the left reverses the direction.'),
  ('effusion', 18, 'Which chest X-ray finding does the nurse expect to see reported for a client with a pleural effusion?', '[{"id": "a", "text": "Air outlining a collapsed lung apex"}, {"id": "b", "text": "Blunting of the costophrenic angle"}, {"id": "c", "text": "Fluid at the lung apex only"}, {"id": "d", "text": "Anechoic space beside the chest wall"}]'::jsonb, '["b"]', 'On chest X-ray, pleural effusion shows blunting of the costophrenic angle with fluid at the lung base. An anechoic (dark) space between lung and chest wall is an ultrasound finding.'),
  ('effusion', 19, 'An ultrasound is ordered before a client''s thoracentesis. The nurse understands that the main purpose of the ultrasound is to:', '[{"id": "a", "text": "rule out pneumothorax after the procedure"}, {"id": "b", "text": "determine whether the fluid is exudative"}, {"id": "c", "text": "guide the procedure and locate the fluid"}, {"id": "d", "text": "measure the protein and LDH levels"}]'::jsonb, '["c"]', 'Ultrasound is used to guide thoracentesis and visualize small effusions. Classifying fluid with protein and LDH is done through thoracentesis fluid analysis, and ruling out pneumothorax is the purpose of the post-procedure chest X-ray.'),
  ('effusion', 20, 'Which diagnostic test helps distinguish empyema from a simple pleural effusion and assess for loculations?', '[{"id": "a", "text": "Chest X-ray"}, {"id": "b", "text": "Ultrasound"}, {"id": "c", "text": "Baseline SpO2 measurement"}, {"id": "d", "text": "CT scan"}]'::jsonb, '["d"]', 'CT scan assesses extent, loculations, and malignancy, is more detailed than X-ray, and distinguishes empyema from effusion. Chest X-ray is the first-line imaging but is less detailed.'),
  ('effusion', 21, 'Pleural fluid from a client''s thoracentesis is sent to the laboratory. The nurse knows that Light''s criteria classify the fluid using which values?', '[{"id": "a", "text": "Protein and LDH levels"}, {"id": "b", "text": "Sodium and potassium levels"}, {"id": "c", "text": "Glucose and hemoglobin levels"}, {"id": "d", "text": "White blood cell and platelet counts"}]'::jsonb, '["a"]', 'Light''s criteria use protein and LDH levels to classify fluid as transudate or exudate. The other values are not part of these criteria.'),
  ('effusion', 22, 'A client''s pleural effusion is related to heart failure. Which treatment does the nurse anticipate to address the underlying cause?', '[{"id": "a", "text": "Antibiotics"}, {"id": "b", "text": "Pleurodesis"}, {"id": "c", "text": "Chemotherapy"}, {"id": "d", "text": "Furosemide"}]'::jsonb, '["d"]', 'Diuretics such as furosemide are used for heart failure-related effusion to reduce fluid overload and treat the underlying cause. Antibiotics are used for parapneumonic effusion or empyema.'),
  ('effusion', 23, 'A client with pneumonia has developed a parapneumonic pleural effusion. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Radiation to shrink a tumor"}, {"id": "b", "text": "Furosemide to reduce fluid overload"}, {"id": "c", "text": "Pleurodesis to fuse the pleura"}, {"id": "d", "text": "Antibiotics to treat the infection"}]'::jsonb, '["d"]', 'Antibiotics are used for parapneumonic effusion or empyema to treat the underlying infection. Furosemide is used for heart failure-related effusion.'),
  ('effusion', 24, 'A client''s pleural effusion reaccumulates rapidly after each thoracentesis. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Thoracentesis removing 3 L in one session"}, {"id": "b", "text": "Observation without any drainage"}, {"id": "c", "text": "Thoracentesis repeated every few hours"}, {"id": "d", "text": "Chest tube for continuous drainage"}]'::jsonb, '["d"]', 'A chest tube is used for a rapidly reaccumulating effusion and provides continuous drainage connected to a water-seal system. Removing 3 L at once exceeds the 1,500 mL limit for a single thoracentesis.'),
  ('effusion', 25, 'A client with a recurrent malignant pleural effusion is scheduled for pleurodesis and asks how it works. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "An irritant is instilled so the pleural surfaces fuse."}, {"id": "b", "text": "A needle drains the fluid, and it slowly stops forming."}, {"id": "c", "text": "A medication removes excess fluid from the bloodstream."}, {"id": "d", "text": "A tube drains the fluid continuously into a water seal."}]'::jsonb, '["a"]', 'In pleurodesis, a chemical irritant such as talc or bleomycin is instilled so the pleural surfaces fuse, leaving no space for fluid. Continuous drainage into a water seal describes a chest tube.'),
  ('effusion', 26, 'For which client does the nurse anticipate a pleurodesis procedure?', '[{"id": "a", "text": "A client with a recurrent malignant effusion"}, {"id": "b", "text": "A client with a parapneumonic effusion"}, {"id": "c", "text": "A client with an effusion from nephrotic syndrome"}, {"id": "d", "text": "A client with a first effusion from heart failure"}]'::jsonb, '["a"]', 'Pleurodesis is used for recurrent malignant effusion. Heart failure-related effusion is treated with diuretics, and parapneumonic effusion with antibiotics.'),
  ('effusion', 27, 'A client''s pleural effusion is caused by lymphoma. Which therapy targets the underlying cause of the effusion?', '[{"id": "a", "text": "Repeated thoracentesis"}, {"id": "b", "text": "Furosemide diuretic therapy"}, {"id": "c", "text": "Antibiotic therapy"}, {"id": "d", "text": "Chemotherapy or radiation"}]'::jsonb, '["d"]', 'Chemotherapy or radiation treats the underlying malignancy causing a cancer-related effusion. Thoracentesis provides symptomatic relief and diagnosis but does not treat the cause.'),
  ('effusion', 28, 'The nurse is preparing a client for a scheduled thoracentesis. Which action is a nursing responsibility before the procedure?', '[{"id": "a", "text": "Position the client flat and supine"}, {"id": "b", "text": "Confirm that informed consent has been obtained"}, {"id": "c", "text": "Wait to take vital signs until the needle is placed"}, {"id": "d", "text": "Label and send a fluid sample to the laboratory"}]'::jsonb, '["b"]', 'Before thoracentesis, informed consent must be obtained and baseline vitals documented. Labeling and sending fluid to the lab occurs after the procedure.'),
  ('effusion', 29, 'How should the nurse position a client for a thoracentesis?', '[{"id": "a", "text": "Supine with the head of the bed flat"}, {"id": "b", "text": "Prone with the arms at the sides"}, {"id": "c", "text": "Side-lying on the unaffected side"}, {"id": "d", "text": "Sitting upright, leaning forward over a table"}]'::jsonb, '["d"]', 'For thoracentesis, the client sits upright leaning forward over the bedside table, which opens the intercostal spaces. Lying flat is not the recommended position.'),
  ('effusion', 30, 'A client asks why they must lean forward over the bedside table during thoracentesis. The nurse explains that this position:', '[{"id": "a", "text": "opens the spaces between the ribs"}, {"id": "b", "text": "prevents re-expansion pulmonary edema"}, {"id": "c", "text": "moves the fluid away from the needle"}, {"id": "d", "text": "keeps the client from needing to cough"}]'::jsonb, '["a"]', 'Sitting upright and leaning forward opens the intercostal spaces for the procedure. Re-expansion pulmonary edema is prevented by limiting the volume of fluid removed, not by positioning.'),
  ('effusion', 31, 'Before a thoracentesis, the nurse reviews the client''s imaging. What is the main purpose of this step?', '[{"id": "a", "text": "To classify the fluid as an exudate"}, {"id": "b", "text": "To rule out a pneumothorax afterward"}, {"id": "c", "text": "To ensure the correct side is identified"}, {"id": "d", "text": "To measure the volume to be removed"}]'::jsonb, '["c"]', 'Imaging is verified before the procedure to ensure the correct side is identified. Ruling out pneumothorax is the purpose of the post-procedure chest X-ray.'),
  ('effusion', 32, 'Which data should the nurse document before a client''s thoracentesis begins?', '[{"id": "a", "text": "Pleural fluid protein level"}, {"id": "b", "text": "Post-procedure chest X-ray results"}, {"id": "c", "text": "Baseline vital signs and SpO2"}, {"id": "d", "text": "Total volume of fluid removed"}]'::jsonb, '["c"]', 'Baseline vital signs and SpO2 are documented before the procedure. Fluid analysis, the post-procedure X-ray, and the volume removed are obtained during or after the procedure.'),
  ('effusion', 33, 'The nurse is assisting with a client''s thoracentesis. Which principle must the nurse follow during the procedure?', '[{"id": "a", "text": "Clean technique is acceptable"}, {"id": "b", "text": "The client may cough freely"}, {"id": "c", "text": "Sterile technique is required"}, {"id": "d", "text": "Vital signs are checked only afterward"}]'::jsonb, '["c"]', 'Sterile technique is required during thoracentesis. The client must remain still without coughing, and vital signs are monitored continuously during the procedure.'),
  ('effusion', 34, 'During a thoracentesis, the client says, ''I feel like I''m going to cough.'' Which instruction from the nurse is most appropriate?', '[{"id": "a", "text": "Go ahead and cough as hard as you need to."}, {"id": "b", "text": "Try not to cough or move suddenly right now."}, {"id": "c", "text": "Lean back against the pillow and then cough."}, {"id": "d", "text": "Take a deep breath and bear down right now."}]'::jsonb, '["b"]', 'The client must remain still during thoracentesis and is instructed not to cough or move suddenly. Coughing or shifting position during the procedure goes against this instruction.'),
  ('effusion', 35, 'Which monitoring should the nurse perform while a thoracentesis is in progress?', '[{"id": "a", "text": "Temperature checks every 4 hours"}, {"id": "b", "text": "Vital signs only after the procedure"}, {"id": "c", "text": "Continuous BP, HR, SpO2, and RR"}, {"id": "d", "text": "Vital signs only if the client reports pain"}]'::jsonb, '["c"]', 'Vital signs, including BP, HR, SpO2, and RR, are monitored continuously during thoracentesis. Waiting until after the procedure would miss changes as fluid is removed.'),
  ('effusion', 36, 'During a thoracentesis, 1,500 mL of pleural fluid has been removed. Which statement reflects correct understanding of the next step?', '[{"id": "a", "text": "No more fluid should be removed at this sitting."}, {"id": "b", "text": "Another 1,500 mL may be removed if vitals are stable."}, {"id": "c", "text": "Removal may continue until no more fluid drains."}, {"id": "d", "text": "At least 3,000 mL must be removed for symptom relief."}]'::jsonb, '["a"]', 'No more than 1,500 mL should be removed at one sitting. Continuing to drain fluid raises the risk of re-expansion pulmonary edema.'),
  ('effusion', 37, 'The nurse explains to a client that the amount of fluid removed during thoracentesis is limited mainly to prevent which complication?', '[{"id": "a", "text": "Re-expansion pulmonary edema"}, {"id": "b", "text": "Hemothorax"}, {"id": "c", "text": "Infection at the puncture site"}, {"id": "d", "text": "Fusion of the pleural surfaces"}]'::jsonb, '["a"]', 'Removal is limited to 1,000–1,500 mL at one time to prevent re-expansion pulmonary edema. Fusion of the pleural surfaces is the intended effect of pleurodesis, not a thoracentesis complication.'),
  ('effusion', 38, 'Shortly after a large volume of pleural fluid is removed rapidly, a client develops respiratory distress and pink, frothy sputum. The nurse suspects:', '[{"id": "a", "text": "pneumothorax from lung puncture"}, {"id": "b", "text": "re-expansion pulmonary edema"}, {"id": "c", "text": "hemothorax from bleeding"}, {"id": "d", "text": "infection at the puncture site"}]'::jsonb, '["b"]', 'Re-expansion pulmonary edema occurs when too much fluid is removed too fast and causes pink, frothy sputum and respiratory distress. Hemothorax presents with bloody drainage and hypotension.'),
  ('effusion', 39, 'A chest X-ray is ordered after a client''s thoracentesis. The nurse explains to the client that its purpose is to:', '[{"id": "a", "text": "rule out a pneumothorax"}, {"id": "b", "text": "classify the fluid as exudate"}, {"id": "c", "text": "guide placement of the needle"}, {"id": "d", "text": "mark the site for the next procedure"}]'::jsonb, '["a"]', 'A chest X-ray after thoracentesis is ordered to rule out pneumothorax. Guiding needle placement is a pre-procedure role of ultrasound.'),
  ('effusion', 40, 'Which post-thoracentesis lung assessment is most appropriate?', '[{"id": "a", "text": "Auscultate both sides and compare"}, {"id": "b", "text": "Auscultate only the unaffected side"}, {"id": "c", "text": "Auscultate only the procedure side"}, {"id": "d", "text": "Defer auscultation until the next day"}]'::jsonb, '["a"]', 'After thoracentesis, lung sounds are auscultated bilaterally to check for improvement. Assessing only one side would not allow comparison.'),
  ('effusion', 41, 'The nurse assesses a client''s puncture site after thoracentesis. Which set of findings is the nurse checking for?', '[{"id": "a", "text": "Tidaling, bubbling, and drainage color"}, {"id": "b", "text": "Orthopnea, dry cough, and pleuritic pain"}, {"id": "c", "text": "Bleeding, hematoma, and subcutaneous emphysema"}, {"id": "d", "text": "Dullness, hyperresonance, and tracheal shift"}]'::jsonb, '["c"]', 'The puncture site is assessed for bleeding, hematoma, and subcutaneous emphysema. Tidaling and bubbling are features of a water-seal chest drainage system, not a puncture site.'),
  ('effusion', 42, 'One hour after a thoracentesis, which client statement should concern the nurse most?', '[{"id": "a", "text": "My breathing feels easier now."}, {"id": "b", "text": "I''m more short of breath than before."}, {"id": "c", "text": "My chest feels less tight than before."}, {"id": "d", "text": "I can take a deeper breath than before."}]'::jsonb, '["b"]', 'Dyspnea should improve after thoracentesis, and worsening dyspnea signals a complication. The other statements reflect the expected improvement.'),
  ('effusion', 43, 'A thoracentesis has been completed. What should the nurse do with the collected pleural fluid?', '[{"id": "a", "text": "Label it and send it to the lab"}, {"id": "b", "text": "Discard it once the volume is recorded"}, {"id": "c", "text": "Hold it until the X-ray is reviewed"}, {"id": "d", "text": "Return it to the provider to discard"}]'::jsonb, '["a"]', 'After the procedure, the fluid is labeled and sent to the lab for analysis, which helps determine whether it is a transudate or exudate. Discarding the fluid would prevent this analysis.'),
  ('effusion', 44, 'Thirty minutes after a thoracentesis, a client has sudden worsening dyspnea, absent breath sounds on the procedure side, and tracheal deviation. Which action should the nurse take?', '[{"id": "a", "text": "Encourage coughing and deep breathing"}, {"id": "b", "text": "Document these as expected findings"}, {"id": "c", "text": "Lay the client flat and recheck in 1 hour"}, {"id": "d", "text": "Call the provider and prepare for a chest tube"}]'::jsonb, '["d"]', 'Sudden worsening dyspnea, absent breath sounds, and tracheal deviation after thoracentesis indicate pneumothorax; the nurse calls the provider and prepares for a chest tube. These findings are a complication, not expected.'),
  ('effusion', 45, 'After a thoracentesis, a client has bloody drainage and becomes hypotensive. Which complication does the nurse suspect?', '[{"id": "a", "text": "Infection"}, {"id": "b", "text": "Transudative effusion"}, {"id": "c", "text": "Re-expansion pulmonary edema"}, {"id": "d", "text": "Hemothorax"}]'::jsonb, '["d"]', 'Bloody drainage with hypotension after thoracentesis suggests hemothorax. Re-expansion pulmonary edema presents with pink, frothy sputum and respiratory distress.'),
  ('effusion', 46, 'During a thoracentesis, a client''s blood pressure drops, but there is no bloody drainage. The nurse recognizes that this hypotension is most likely caused by:', '[{"id": "a", "text": "an infection at the puncture site"}, {"id": "b", "text": "a vasovagal response"}, {"id": "c", "text": "fluid overload from heart failure"}, {"id": "d", "text": "a pneumothorax from the needle"}]'::jsonb, '["b"]', 'Hypotension during thoracentesis can result from a vasovagal response, with risk increased when more than 1,500 mL is removed. Hemothorax would present with bloody drainage along with hypotension.'),
  ('effusion', 47, 'Three days after a thoracentesis, a client has a fever and purulent drainage at the puncture site. The nurse suspects:', '[{"id": "a", "text": "hemothorax"}, {"id": "b", "text": "infection"}, {"id": "c", "text": "pneumothorax"}, {"id": "d", "text": "re-expansion pulmonary edema"}]'::jsonb, '["b"]', 'Fever and purulent drainage at the site indicate infection. Hemothorax presents with bloody drainage and hypotension instead.'),
  ('effusion', 48, 'A client asks why a pleural effusion makes it hard to breathe. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Fluid fills the air sacs inside the lung."}, {"id": "b", "text": "Fluid presses on the lung from the outside."}, {"id": "c", "text": "Trapped air in the chest collapses the lung."}, {"id": "d", "text": "Mucus narrows the airways leading to the lung."}]'::jsonb, '["b"]', 'In pleural effusion, fluid in the pleural space squishes the lung from outside so it cannot fully expand. The fluid is outside the lung, not inside the air sacs.'),
  ('effusion', 49, 'A client with lupus develops a pleural effusion. The nurse anticipates the fluid will be classified as:', '[{"id": "a", "text": "transudative, from oncotic changes"}, {"id": "b", "text": "transudative, from heart failure"}, {"id": "c", "text": "exudative, from inflammation"}, {"id": "d", "text": "exudative, from heart failure"}]'::jsonb, '["c"]', 'Lupus is listed among causes of exudative effusion, which results from inflammation, infection, or malignancy disrupting the pleural membrane. Oncotic changes and heart failure produce transudates.'),
  ('effusion', 50, 'A client with liver cirrhosis develops a pleural effusion. Which type of effusion does the nurse expect?', '[{"id": "a", "text": "Exudative, with cloudy fluid"}, {"id": "b", "text": "Transudative, with clear fluid"}, {"id": "c", "text": "Transudative, with cloudy fluid"}, {"id": "d", "text": "Exudative, with high-protein fluid"}]'::jsonb, '["b"]', 'Cirrhosis is a liver cause of transudative effusion, which produces clear fluid. Cloudy fluid characterizes an exudate.'),
  ('pneumonia', 1, 'A client is admitted with pneumonia and has an SpO2 below the client''s baseline. The nurse explains that the low oxygen level is mainly caused by which process?', '[{"id": "a", "text": "Narrowing of the bronchioles from airway muscle spasm"}, {"id": "b", "text": "Inflamed alveoli filling with fluid or pus, reducing gas exchange"}, {"id": "c", "text": "Air trapped in the pleural space collapsing the lung"}, {"id": "d", "text": "A blood clot blocking flow through a pulmonary artery"}]'::jsonb, '["b"]', 'Pneumonia is an infection that inflames the alveoli so they fill with fluid or pus, which reduces oxygen exchange and causes hypoxia. The other mechanisms do not describe the fluid-filled alveoli that define pneumonia.'),
  ('pneumonia', 2, 'The nurse is planning care for a client with bacterial pneumonia. Which nursing problem reflects the core concern of this condition?', '[{"id": "a", "text": "Activity intolerance"}, {"id": "b", "text": "Deficient knowledge"}, {"id": "c", "text": "Impaired gas exchange"}, {"id": "d", "text": "Disturbed body image"}]'::jsonb, '["c"]', 'Fluid-filled alveoli in pneumonia directly impair gas exchange, leading to hypoxia. Activity intolerance may occur but is not the core physiologic problem.'),
  ('pneumonia', 3, 'A client develops pneumonia five days after admission for abdominal surgery. The nurse anticipates that this type of pneumonia will:', '[{"id": "a", "text": "Be harder to treat because it is often antibiotic-resistant"}, {"id": "b", "text": "Most likely be caused by Mycoplasma pneumoniae"}, {"id": "c", "text": "Typically present as a mild, dry, nonproductive cough"}, {"id": "d", "text": "Be treated primarily with an antiviral medication"}]'::jsonb, '["a"]', 'Pneumonia developing after more than 48 hours of hospitalization is hospital-acquired, which is harder to treat because the bacteria are often antibiotic-resistant. Mycoplasma causes atypical pneumonia in young adults in crowded settings.'),
  ('pneumonia', 4, 'A client admitted for hip surgery develops fever and a productive cough. For this pneumonia to be classified as hospital-acquired, the client must have been hospitalized for longer than:', '[{"id": "a", "text": "12 hours"}, {"id": "b", "text": "24 hours"}, {"id": "c", "text": "36 hours"}, {"id": "d", "text": "48 hours"}]'::jsonb, '["d"]', 'Hospital-acquired pneumonia occurs in clients hospitalized more than 48 hours, with surgery and a weak immune system as additional risk factors. Shorter time frames do not meet this definition.'),
  ('pneumonia', 5, 'The nurse is caring for an intubated client on a long ICU stay. Which intervention helps reduce the risk of ventilator-associated pneumonia?', '[{"id": "a", "text": "Keeping the head of the bed flat"}, {"id": "b", "text": "Providing regular oral care"}, {"id": "c", "text": "Restricting the client''s fluid intake"}, {"id": "d", "text": "Delaying antibiotics until cultures result"}]'::jsonb, '["b"]', 'Oral care for ventilated patients reduces VAP. The head of the bed should be elevated, not flat, to prevent aspiration in high-risk patients.'),
  ('pneumonia', 6, 'The nurse is reviewing assigned clients. Which client is at greatest risk for aspiration pneumonia?', '[{"id": "a", "text": "A 20-year-old college student living in a dormitory"}, {"id": "b", "text": "A 45-year-old with well-controlled asthma at home"}, {"id": "c", "text": "A 78-year-old with dysphagia following a stroke"}, {"id": "d", "text": "A 35-year-old recovering from an ankle fracture"}]'::jsonb, '["c"]', 'Aspiration pneumonia results from inhaling food, liquid, or vomit, and stroke and dysphagia are listed risk factors. A college student in crowded housing is at risk for atypical (walking) pneumonia instead.'),
  ('pneumonia', 7, 'A client with dementia and dysphagia is being fed lunch. Which nursing action best prevents aspiration pneumonia?', '[{"id": "a", "text": "Keep the head of the bed elevated"}, {"id": "b", "text": "Place the client supine after eating"}, {"id": "c", "text": "Lower the head of the bed during meals"}, {"id": "d", "text": "Have the client lie on the back to rest"}]'::jsonb, '["a"]', 'An elevated head of bed prevents aspiration in high-risk patients such as those with dementia or dysphagia. Lying flat or supine removes this protection.'),
  ('pneumonia', 8, 'A 19-year-old military recruit living in shared barracks has a dry cough, mild fever, headache, and fatigue but continues attending training. The nurse recognizes that the most likely causative organism is:', '[{"id": "a", "text": "Staphylococcus aureus"}, {"id": "b", "text": "Pseudomonas"}, {"id": "c", "text": "Pneumocystis jirovecii"}, {"id": "d", "text": "Mycoplasma pneumoniae"}]'::jsonb, '["d"]', 'Atypical (walking) pneumonia is caused by Mycoplasma pneumoniae and affects young adults in crowded settings such as college and the military, presenting with dry cough, mild fever, and fatigue. Pseudomonas is associated with HAP/VAP.'),
  ('pneumonia', 9, 'A client from home is diagnosed with community-acquired bacterial pneumonia. The nurse knows the sputum culture is most likely to grow which organism?', '[{"id": "a", "text": "Pseudomonas"}, {"id": "b", "text": "Streptococcus pneumoniae"}, {"id": "c", "text": "Pneumocystis jirovecii"}, {"id": "d", "text": "Respiratory syncytial virus"}]'::jsonb, '["b"]', 'Streptococcus pneumoniae is the number one cause of community-acquired pneumonia. Pseudomonas is associated with hospital-acquired and ventilator-associated pneumonia.'),
  ('pneumonia', 10, 'A client who has been on a ventilator in the ICU for 10 days develops ventilator-associated pneumonia. Which organism does the nurse associate with this type?', '[{"id": "a", "text": "Mycoplasma pneumoniae"}, {"id": "b", "text": "Pneumocystis jirovecii"}, {"id": "c", "text": "Pseudomonas"}, {"id": "d", "text": "Influenza virus"}]'::jsonb, '["c"]', 'Pseudomonas is a bacterial cause linked to HAP and VAP. Mycoplasma causes atypical pneumonia in young adults in crowded settings.'),
  ('pneumonia', 11, 'A client with AIDS is admitted with pneumonia. Which causative organism is most closely associated with this client''s immune status?', '[{"id": "a", "text": "Pneumocystis jirovecii"}, {"id": "b", "text": "Mycoplasma pneumoniae"}, {"id": "c", "text": "Respiratory syncytial virus"}, {"id": "d", "text": "Pseudomonas"}]'::jsonb, '["a"]', 'Pneumocystis jirovecii (PCP) is a fungal cause of pneumonia seen in patients with HIV/AIDS. Mycoplasma is associated with young adults in crowded settings, and Pseudomonas with HAP/VAP.'),
  ('pneumonia', 12, 'The nurse is assessing four clients with respiratory infections. Which client''s findings are most consistent with bacterial pneumonia?', '[{"id": "a", "text": "Dry, nonproductive cough with a mild fever"}, {"id": "b", "text": "Headache and fatigue while still ambulatory"}, {"id": "c", "text": "Low-grade fever and night sweats for weeks"}, {"id": "d", "text": "Fever, chills, and rust-colored sputum"}]'::jsonb, '["d"]', 'Bacterial pneumonia typically causes fever and chills with a productive cough, and rust-colored sputum is a classic sign. Dry cough with mild fever describes atypical/viral pneumonia, and persistent low-grade fever with night sweats suggests TB.'),
  ('pneumonia', 13, 'A client with bacterial pneumonia reports chest pain. Which description of the pain does the nurse expect?', '[{"id": "a", "text": "Dull pain that eases with deep breathing"}, {"id": "b", "text": "Sharp pain that worsens with breathing"}, {"id": "c", "text": "Burning pain that occurs after meals"}, {"id": "d", "text": "Aching pain present only while asleep"}]'::jsonb, '["b"]', 'Pleuritic chest pain in bacterial pneumonia is a sharp pain that worsens with breathing. Pain that eases with deep breathing does not match this pattern.'),
  ('pneumonia', 14, 'While auscultating the lungs of a client with bacterial pneumonia, which breath sounds does the nurse expect to hear?', '[{"id": "a", "text": "Clear breath sounds in all lobes"}, {"id": "b", "text": "Absent breath sounds on one side"}, {"id": "c", "text": "Crackles or rhonchi over affected areas"}, {"id": "d", "text": "Breath sounds that are clear after coughing"}]'::jsonb, '["c"]', 'Fluid in the alveoli creates crackles or rhonchi, a typical finding in bacterial pneumonia. Clear breath sounds would not be expected with fluid-filled alveoli.'),
  ('pneumonia', 15, 'An 82-year-old nursing home resident is newly confused and weak, is eating poorly, and has a temperature of 96.4°F (35.8°C). Which interpretation by the nurse is most accurate?', '[{"id": "a", "text": "These findings may indicate pneumonia"}, {"id": "b", "text": "Pneumonia is unlikely without a fever"}, {"id": "c", "text": "A low temperature rules out an infection"}, {"id": "d", "text": "Pneumonia requires a productive cough"}]'::jsonb, '["a"]', 'In elderly patients, confusion and weakness may indicate pneumonia, and they may have a low body temperature instead of fever. Absence of fever or classic symptoms does not rule out pneumonia in older adults.'),
  ('pneumonia', 16, 'The nurse is teaching the family of an older adult about pneumonia. Which finding should the nurse explain is often the first sign of pneumonia in older adults?', '[{"id": "a", "text": "High fever"}, {"id": "b", "text": "Rust-colored sputum"}, {"id": "c", "text": "Pleuritic chest pain"}, {"id": "d", "text": "New confusion"}]'::jsonb, '["d"]', 'In the elderly, confusion is the first sign of pneumonia, not fever. Older adults may have a low body temperature instead of fever.'),
  ('pneumonia', 17, 'A nursing student is discussing pneumonia in older adults. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"Older adults may have a low temperature instead of a fever.\""}, {"id": "b", "text": "\"An older adult with no fever is unlikely to have pneumonia.\""}, {"id": "c", "text": "\"Weakness and poor appetite can be signs of pneumonia.\""}, {"id": "d", "text": "\"Older adults may not show the classic symptoms.\""}]'::jsonb, '["b"]', 'Elderly patients may have a low body temperature instead of fever and may not have classic symptoms, so lack of fever does not make pneumonia unlikely. The other statements are accurate.'),
  ('pneumonia', 18, 'The provider suspects pneumonia in a client with fever and a productive cough. Which test is considered the gold standard for diagnosing pneumonia?', '[{"id": "a", "text": "Sputum culture"}, {"id": "b", "text": "Complete blood count"}, {"id": "c", "text": "Chest X-ray"}, {"id": "d", "text": "Arterial blood gas"}]'::jsonb, '["c"]', 'Chest X-ray is the gold standard for diagnosing pneumonia. A sputum culture identifies the causative bacteria but is not the diagnostic gold standard.'),
  ('pneumonia', 19, 'The nurse reviews the chest X-ray report of a client admitted with bacterial pneumonia. Which finding is expected?', '[{"id": "a", "text": "Consolidation or white areas in the lungs"}, {"id": "b", "text": "Cavitary lesions in the upper lobes"}, {"id": "c", "text": "Clear lung fields bilaterally"}, {"id": "d", "text": "An enlarged heart silhouette"}]'::jsonb, '["a"]', 'Chest X-ray in pneumonia shows consolidation or white areas representing fluid. Cavitary lesions in the upper lobes are characteristic of tuberculosis.'),
  ('pneumonia', 20, 'A client with pneumonia asks why blood cultures were drawn in addition to a sputum specimen. The nurse explains that blood cultures are used to:', '[{"id": "a", "text": "Measure how much oxygen is in the blood"}, {"id": "b", "text": "Check whether the infection spread to the blood"}, {"id": "c", "text": "Count white cells to confirm an infection"}, {"id": "d", "text": "Show areas of fluid within the lung tissue"}]'::jsonb, '["b"]', 'Blood cultures check whether the infection has spread to the bloodstream (bacteremia/sepsis). Counting white cells is the role of the CBC.'),
  ('pneumonia', 21, 'The provider wants to identify the specific bacteria causing a client''s pneumonia. Which specimen does the nurse anticipate collecting?', '[{"id": "a", "text": "Arterial blood gas"}, {"id": "b", "text": "Complete blood count"}, {"id": "c", "text": "Venous blood for antibodies"}, {"id": "d", "text": "Sputum for culture"}]'::jsonb, '["d"]', 'A sputum culture identifies the bacteria causing pneumonia. The CBC shows elevated WBCs as an infection indicator but does not identify the organism.'),
  ('pneumonia', 22, 'The nurse reviews laboratory results for a client with bacterial pneumonia. Which result is consistent with this diagnosis?', '[{"id": "a", "text": "Decreased white blood cell count"}, {"id": "b", "text": "Elevated PaO2 on arterial blood gas"}, {"id": "c", "text": "Elevated white blood cell count"}, {"id": "d", "text": "Normal chest X-ray findings"}]'::jsonb, '["c"]', 'An elevated WBC count on the CBC is an indicator of infection. In severe pneumonia the ABG shows a low, not elevated, PaO2.'),
  ('pneumonia', 23, 'A client with severe pneumonia is short of breath and restless. Which arterial blood gas finding does the nurse expect?', '[{"id": "a", "text": "Low PaO2"}, {"id": "b", "text": "High PaO2"}, {"id": "c", "text": "Normal PaO2"}, {"id": "d", "text": "PaO2 above baseline"}]'::jsonb, '["a"]', 'The ABG in pneumonia shows a low PaO2 in severe hypoxia, because fluid-filled alveoli reduce oxygen exchange. A high or normal PaO2 would not reflect severe hypoxia.'),
  ('pneumonia', 24, 'A client is admitted with community-acquired bacterial pneumonia. A sputum specimen was sent to the lab 1 hour ago, and an IV antibiotic has been prescribed. What should the nurse do?', '[{"id": "a", "text": "Hold the antibiotic until culture results return"}, {"id": "b", "text": "Give the antibiotic now without waiting for results"}, {"id": "c", "text": "Hold the antibiotic until the CBC results return"}, {"id": "d", "text": "Give only the antipyretic until results are known"}]'::jsonb, '["b"]', 'Antibiotics for bacterial pneumonia should be started as soon as possible without waiting for culture results. Holding the antibiotic for lab results delays needed treatment.'),
  ('pneumonia', 25, 'A newly hired nurse is caring for a client with bacterial pneumonia. Which statement by the new nurse indicates a need for further teaching?', '[{"id": "a", "text": "\"I will place the client in high Fowler''s position.\""}, {"id": "b", "text": "\"I will encourage the client to cough and deep breathe.\""}, {"id": "c", "text": "\"I will reassess lung sounds after each treatment.\""}, {"id": "d", "text": "\"I will hold the antibiotic until the culture is final.\""}]'::jsonb, '["d"]', 'Antibiotics should be started as soon as possible; the nurse should not wait for full culture results. High Fowler''s positioning, coughing and deep breathing, and reassessing lung sounds are all priority interventions.'),
  ('pneumonia', 26, 'A client is diagnosed with community-acquired bacterial pneumonia. Which medication does the nurse anticipate will be prescribed to treat the infection?', '[{"id": "a", "text": "Oseltamivir"}, {"id": "b", "text": "Guaifenesin"}, {"id": "c", "text": "Azithromycin"}, {"id": "d", "text": "Acetaminophen"}]'::jsonb, '["c"]', 'Bacterial CAP is treated with antibiotics such as azithromycin, doxycycline, or levofloxacin. Oseltamivir is an antiviral for influenza, and guaifenesin only loosens mucus.'),
  ('pneumonia', 27, 'A client develops bacterial pneumonia while on a ventilator in the ICU. Which medication regimen does the nurse anticipate?', '[{"id": "a", "text": "Vancomycin and piperacillin-tazobactam"}, {"id": "b", "text": "Oseltamivir and acetaminophen"}, {"id": "c", "text": "Guaifenesin and normal saline"}, {"id": "d", "text": "Azithromycin and guaifenesin"}]'::jsonb, '["a"]', 'Bacterial HAP/VAP is treated with broad-spectrum antibiotics such as vancomycin and piperacillin-tazobactam (Zosyn). Azithromycin is listed for community-acquired pneumonia.'),
  ('pneumonia', 28, 'A client is diagnosed with viral pneumonia caused by influenza. Which medication does the nurse anticipate to treat the underlying infection?', '[{"id": "a", "text": "Levofloxacin"}, {"id": "b", "text": "Oseltamivir"}, {"id": "c", "text": "Vancomycin"}, {"id": "d", "text": "Doxycycline"}]'::jsonb, '["b"]', 'Viral (influenza) pneumonia is treated with antivirals such as oseltamivir (Tamiflu). The other choices are antibiotics used for bacterial pneumonia.'),
  ('pneumonia', 29, 'A client with pneumonia asks why guaifenesin was prescribed. The nurse explains that this medication is given to:', '[{"id": "a", "text": "Reduce the fever"}, {"id": "b", "text": "Kill the bacteria"}, {"id": "c", "text": "Loosen the mucus"}, {"id": "d", "text": "Prevent dehydration"}]'::jsonb, '["c"]', 'Guaifenesin is an expectorant used to loosen mucus. Fever is managed with acetaminophen, and IV fluids prevent dehydration.'),
  ('pneumonia', 30, 'A client with pneumonia has a temperature of 102.4°F (39.1°C). Which prescribed PRN medication should the nurse give for fever management?', '[{"id": "a", "text": "Guaifenesin"}, {"id": "b", "text": "Oseltamivir"}, {"id": "c", "text": "Levofloxacin"}, {"id": "d", "text": "Acetaminophen"}]'::jsonb, '["d"]', 'Antipyretics such as acetaminophen (Tylenol) are used for fever management in pneumonia. Guaifenesin is an expectorant that loosens mucus.'),
  ('pneumonia', 31, 'A client with pneumonia is receiving IV lactated Ringer''s solution. The client asks why the IV is needed. The nurse explains that the IV fluid is mainly given to:', '[{"id": "a", "text": "Prevent dehydration"}, {"id": "b", "text": "Treat the infection"}, {"id": "c", "text": "Lower the fever"}, {"id": "d", "text": "Deliver oxygen"}]'::jsonb, '["a"]', 'IV fluids such as NS or LR are given to prevent dehydration. Infection is treated with antibiotics, and fever with acetaminophen.'),
  ('pneumonia', 32, 'A client with pneumonia has worsening hypoxia. Which sequence reflects the stepwise escalation of oxygen delivery for this client?', '[{"id": "a", "text": "Mask, then nasal cannula, then high-flow"}, {"id": "b", "text": "Nasal cannula, then mask, then high-flow"}, {"id": "c", "text": "High-flow, then mask, then nasal cannula"}, {"id": "d", "text": "Nasal cannula, then high-flow, then mask"}]'::jsonb, '["b"]', 'Oxygen for hypoxia in pneumonia is escalated from nasal cannula to mask to high-flow. The other sequences reverse or scramble this order.'),
  ('pneumonia', 33, 'A client with pneumonia is dyspneic and anxious. In which position should the nurse place the client?', '[{"id": "a", "text": "Supine"}, {"id": "b", "text": "Trendelenburg"}, {"id": "c", "text": "High Fowler''s"}, {"id": "d", "text": "Flat side-lying"}]'::jsonb, '["c"]', 'High Fowler''s position keeps the client upright for easier breathing. Flat positions do not promote easier breathing.'),
  ('pneumonia', 34, 'A client with pneumonia has thick secretions that are difficult to cough up. The nurse encourages increased fluid intake and explains that this will:', '[{"id": "a", "text": "Lower the client''s body temperature"}, {"id": "b", "text": "Replace the need for antibiotics"}, {"id": "c", "text": "Raise the client''s oxygen saturation"}, {"id": "d", "text": "Help thin and mobilize secretions"}]'::jsonb, '["d"]', 'Increasing fluid intake helps thin and mobilize secretions. Fluids do not replace antibiotics, which should be started as soon as possible.'),
  ('pneumonia', 35, 'The nurse teaches a client with pneumonia to use an incentive spirometer. Which statement by the client shows understanding of its purpose?', '[{"id": "a", "text": "\"It helps keep my lungs from collapsing.\""}, {"id": "b", "text": "\"It works as a medicine to loosen mucus.\""}, {"id": "c", "text": "\"It measures the oxygen level in my blood.\""}, {"id": "d", "text": "\"It treats the bacteria causing my infection.\""}]'::jsonb, '["a"]', 'Incentive spirometer use prevents atelectasis (lung collapse). Loosening mucus is the role of the expectorant guaifenesin.'),
  ('pneumonia', 36, 'The nurse has administered a scheduled antibiotic and assisted a client with pneumonia with coughing and deep breathing. Which action best evaluates the effect of treatment?', '[{"id": "a", "text": "Review the admission chest X-ray report"}, {"id": "b", "text": "Reassess the client''s lung sounds"}, {"id": "c", "text": "Ask about the client''s smoking history"}, {"id": "d", "text": "Check the client''s admission weight"}]'::jsonb, '["b"]', 'Lung sounds should be reassessed after treatment to check for improvement. The admission X-ray reflects status before treatment and cannot show the response.'),
  ('pneumonia', 37, 'A client has been receiving treatment for bacterial pneumonia. Which set of findings indicates the client''s respiratory status is improving?', '[{"id": "a", "text": "New crackles in both lung bases and rising RR"}, {"id": "b", "text": "Increasing rust-colored sputum and new confusion"}, {"id": "c", "text": "Clearer breath sounds, higher SpO2, and lower RR"}, {"id": "d", "text": "Falling SpO2 despite an increase in oxygen flow"}]'::jsonb, '["c"]', 'Respiratory status is monitored through SpO2, breath sounds, and respiratory rate, so clearer breath sounds with improved SpO2 and RR show improvement. Falling SpO2 despite more oxygen signals worsening, possibly ARDS.'),
  ('pneumonia', 38, 'The nurse is teaching staff on a medical unit how to prevent the spread of pneumonia. Which measure should the nurse identify as the number one infection control measure?', '[{"id": "a", "text": "Smoking cessation"}, {"id": "b", "text": "Incentive spirometry"}, {"id": "c", "text": "Elevating the head of bed"}, {"id": "d", "text": "Hand washing"}]'::jsonb, '["d"]', 'Hand washing is the #1 infection control measure for preventing pneumonia. Smoking cessation and HOB elevation are prevention measures but are not the primary infection control measure.'),
  ('pneumonia', 39, 'A client recovering from pneumonia smokes one pack of cigarettes per day and asks why quitting matters. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Smoking damages your lungs'' defense mechanisms.\""}, {"id": "b", "text": "\"Smoking makes antibiotics completely ineffective.\""}, {"id": "c", "text": "\"Smoking is the main cause of aspiration pneumonia.\""}, {"id": "d", "text": "\"Smoking only matters if you are older than 65.\""}]'::jsonb, '["a"]', 'Smoking cessation is part of pneumonia prevention because smoking damages lung defense mechanisms. Aspiration pneumonia is linked to stroke, dementia, and dysphagia rather than smoking.'),
  ('pneumonia', 40, 'An older adult with COPD asks how often to receive the flu vaccine to help prevent influenza pneumonia. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Once in your lifetime\""}, {"id": "b", "text": "\"Every year\""}, {"id": "c", "text": "\"Every 5 years\""}, {"id": "d", "text": "\"Only when you have symptoms\""}]'::jsonb, '["b"]', 'An annual flu shot is recommended to prevent influenza pneumonia. A single lifetime dose or dosing every 5 years would not follow the annual schedule.'),
  ('pneumonia', 41, 'A client with pneumonia has blood cultures that return positive for bacteria. The nurse recognizes that the client is at risk for which life-threatening complication?', '[{"id": "a", "text": "Pleural effusion"}, {"id": "b", "text": "Lung abscess"}, {"id": "c", "text": "Sepsis"}, {"id": "d", "text": "Atelectasis"}]'::jsonb, '["c"]', 'Blood cultures check whether infection has spread to the bloodstream, and sepsis occurs when infection spreads to the bloodstream. Pleural effusion is fluid around the lungs, not infection in the blood.'),
  ('pneumonia', 42, 'While assessing a client with pneumonia, the nurse percusses a dull sound over the right lower lung field. Which complication should the nurse suspect?', '[{"id": "a", "text": "ARDS"}, {"id": "b", "text": "Sepsis"}, {"id": "c", "text": "Lung abscess"}, {"id": "d", "text": "Pleural effusion"}]'::jsonb, '["d"]', 'Pleural effusion is fluid building up around the lungs and produces dull percussion. Sepsis is infection spreading to the bloodstream and is not identified by percussion.'),
  ('pneumonia', 43, 'A client with severe pneumonia has a falling SpO2 even though the oxygen has been escalated to high-flow delivery. Which complication should the nurse suspect?', '[{"id": "a", "text": "ARDS"}, {"id": "b", "text": "Lung abscess"}, {"id": "c", "text": "Pleural effusion"}, {"id": "d", "text": "Atelectasis"}]'::jsonb, '["a"]', 'Severe pneumonia can progress to ARDS, and worsening hypoxia despite oxygen therapy is the warning sign. A lung abscess is a pocket of pus, and pleural effusion is identified by dull percussion.'),
  ('pneumonia', 44, 'A client''s imaging shows that pneumonia has led to a lung abscess. The nurse explains to the client that a lung abscess is:', '[{"id": "a", "text": "Fluid collecting around the lungs"}, {"id": "b", "text": "A pocket of pus within the lung"}, {"id": "c", "text": "Infection spreading into the blood"}, {"id": "d", "text": "Severe failure of both lungs"}]'::jsonb, '["b"]', 'A lung abscess is a pocket of pus in the lung. Fluid around the lungs describes pleural effusion, and infection in the blood describes sepsis.'),
  ('pneumonia', 45, 'A client has received antibiotics for presumed pneumonia but still has a cough, night sweats, and weight loss several weeks later. What is the nurse''s priority action?', '[{"id": "a", "text": "Continue the current antibiotic and recheck in 1 week"}, {"id": "b", "text": "Place the client on droplet precautions in a semi-private room"}, {"id": "c", "text": "Place the client on airborne precautions with an N95 mask"}, {"id": "d", "text": "Provide an incentive spirometer and encourage fluids"}]'::jsonb, '["c"]', 'A pneumonia patient with persistent symptoms despite antibiotics should be suspected of TB and isolated immediately with airborne precautions (N95 mask, negative-pressure room). TB requires airborne, not droplet, precautions.'),
  ('pneumonia', 46, 'The nurse reviews chest X-ray reports for two clients with productive coughs. Which finding suggests tuberculosis rather than pneumonia?', '[{"id": "a", "text": "Consolidation in the lower lobes"}, {"id": "b", "text": "White areas representing fluid"}, {"id": "c", "text": "Fluid filling the alveoli diffusely"}, {"id": "d", "text": "Cavitary lesions in the upper lobes"}]'::jsonb, '["d"]', 'TB shows cavitary lesions in the upper lobes on X-ray, whereas pneumonia shows consolidation (white areas). Fluid-filled alveoli and white areas are pneumonia findings.'),
  ('pneumonia', 47, 'A client is being evaluated for a respiratory infection. Which finding is more suggestive of tuberculosis than of pneumonia?', '[{"id": "a", "text": "Night sweats and weight loss"}, {"id": "b", "text": "Acute high fever and chills"}, {"id": "c", "text": "Acute wet, productive cough"}, {"id": "d", "text": "Rust-colored sputum production"}]'::jsonb, '["a"]', 'Night sweats and weight loss are classic findings of TB but are uncommon in pneumonia. Acute high fever and an acute, wet cough are characteristic of pneumonia.'),
  ('pneumonia', 48, 'The nurse is comparing pneumonia and tuberculosis. Which client presentation is most consistent with pneumonia?', '[{"id": "a", "text": "Low-grade fever that has persisted for weeks"}, {"id": "b", "text": "Acute high fever with a wet, productive cough"}, {"id": "c", "text": "Cough for more than 3 weeks with hemoptysis"}, {"id": "d", "text": "Classic night sweats with ongoing weight loss"}]'::jsonb, '["b"]', 'Pneumonia causes an acute high fever and an acute, wet or productive cough. A persistent low-grade fever and a chronic cough over 3 weeks with hemoptysis point to TB.'),
  ('pneumonia', 49, 'The nurse at a community clinic is screening clients for pneumonia risk. Which client has the most risk factors for community-acquired pneumonia?', '[{"id": "a", "text": "A healthy 25-year-old nonsmoker who jogs"}, {"id": "b", "text": "A 30-year-old with a recent ankle sprain"}, {"id": "c", "text": "A 72-year-old smoker with COPD and diabetes"}, {"id": "d", "text": "A 40-year-old with seasonal allergies"}]'::jsonb, '["c"]', 'Risk factors for community-acquired pneumonia include smoking, COPD, diabetes, older age, and immunocompromise. The other clients have none of these listed risk factors.'),
  ('pneumonia', 50, 'A client with pneumonia avoids coughing because of chest discomfort. The nurse explains that coughing and deep breathing are encouraged mainly to:', '[{"id": "a", "text": "Lower the client''s fever"}, {"id": "b", "text": "Reduce the need for oxygen"}, {"id": "c", "text": "Shorten the antibiotic course"}, {"id": "d", "text": "Prevent mucus buildup"}]'::jsonb, '["d"]', 'Coughing and deep breathing are encouraged to prevent mucus buildup. Fever is managed with antipyretics such as acetaminophen.'),
  ('pe', 1, 'A nurse is teaching a group of students about pulmonary embolism (PE). Which type of embolus should the nurse identify as the most common?', '[{"id": "a", "text": "Fat embolus"}, {"id": "b", "text": "Air embolus"}, {"id": "c", "text": "Blood clot (thromboembolus)"}, {"id": "d", "text": "Amniotic fluid embolus"}]'::jsonb, '["c"]', 'A blood clot (thromboembolism) is the most common type of embolus. Air embolism is described as rare, and fat embolism is linked mainly to long bone fractures.'),
  ('pe', 2, 'A client on prolonged bed rest after abdominal surgery suddenly develops shortness of breath and sharp chest pain. The nurse suspects a pulmonary embolism. Where did the embolus most likely originate?', '[{"id": "a", "text": "A fat globule from bone marrow"}, {"id": "b", "text": "Air drawn in through an IV line"}, {"id": "c", "text": "A clot formed in the left atrium"}, {"id": "d", "text": "A deep vein thrombosis that broke off"}]'::jsonb, '["d"]', 'The most common embolus is a blood clot that originates from a DVT, breaks off, and travels to the lungs; post-surgery immobility and prolonged bed rest are triggers. Fat emboli are linked to long bone fractures, and air emboli to IV or central lines.'),
  ('pe', 3, 'A client with a fractured femur becomes short of breath. Which assessment finding is the classic sign that suggests a fat embolism?', '[{"id": "a", "text": "Petechial rash on the chest and axillae"}, {"id": "b", "text": "Barrel chest with pursed-lip breathing"}, {"id": "c", "text": "Swelling and redness of one calf"}, {"id": "d", "text": "Bilateral pitting edema of the ankles"}]'::jsonb, '["a"]', 'A petechial rash on the chest and axillae is the classic sign of fat embolism. Barrel chest and pursed-lip breathing are features absent in PE and linked to COPD.'),
  ('pe', 4, 'A nurse is reviewing the histories of four clients. Which client is at greatest risk for a fat embolism?', '[{"id": "a", "text": "A client with a central line being inserted"}, {"id": "b", "text": "A client with a long bone fracture"}, {"id": "c", "text": "A client taking oral contraceptives"}, {"id": "d", "text": "A client on a long international flight"}]'::jsonb, '["b"]', 'Long bone fractures are a trigger for fat embolism. Central line insertion is linked to air embolism, and oral contraceptives and long flights are risk factors for blood clots.'),
  ('pe', 5, 'A client arrives in the emergency department with a fractured femur. Which action by the nurse helps manage the risk of fat embolism?', '[{"id": "a", "text": "Place the client in Trendelenburg position"}, {"id": "b", "text": "Encourage early ambulation on the leg"}, {"id": "c", "text": "Immobilize the fracture immediately"}, {"id": "d", "text": "Delay oxygen until symptoms appear"}]'::jsonb, '["c"]', 'Treatment for fat embolism includes immobilizing fractures immediately along with supportive oxygen. Trendelenburg positioning is used for air embolism.'),
  ('pe', 6, 'A nurse is caring for several clients. Which situation places a client at the greatest risk for an air embolism?', '[{"id": "a", "text": "Insertion of a central venous line"}, {"id": "b", "text": "Repair of a hip fracture"}, {"id": "c", "text": "Prolonged bed rest after surgery"}, {"id": "d", "text": "Fracture of a long bone"}]'::jsonb, '["a"]', 'Air embolism occurs when air enters the venous system, often from IV line air or central line insertion. Long bone fractures are linked to fat embolism, and bed rest and hip fractures are linked to blood clots.'),
  ('pe', 7, 'During central line insertion, a client suddenly becomes dyspneic, and the nurse suspects an air embolism. In which position should the nurse immediately place the client?', '[{"id": "a", "text": "Right side with the head elevated"}, {"id": "b", "text": "Head of bed elevated 30–45°"}, {"id": "c", "text": "Prone with the bed flat"}, {"id": "d", "text": "Left side with the head down and feet up"}]'::jsonb, '["d"]', 'For air embolism, the client is placed in Trendelenburg (head down, feet up) on the left side. Elevating the head of the bed 30–45° is used for suspected PE except when it is an air embolism.'),
  ('pe', 8, 'A client receiving IV therapy develops sudden dyspnea, and the nurse suspects an air embolism. Which sequence of actions is correct?', '[{"id": "a", "text": "Stop the infusion, notify the physician, give O₂, then position"}, {"id": "b", "text": "Position in left lateral Trendelenburg, stop the infusion, notify the physician, give O₂"}, {"id": "c", "text": "Notify the physician, give O₂, position, then stop the infusion"}, {"id": "d", "text": "Give O₂, stop the infusion, position, then notify the physician"}]'::jsonb, '["b"]', 'For air embolism during IV therapy, the nurse immediately positions the client in left lateral Trendelenburg, then stops the infusion, notifies the physician, and administers oxygen. The other sequences delay the positioning step.'),
  ('pe', 9, 'A nursing student asks why a client with an air embolism is placed on the left side with the head down. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It moves the air into the lungs so it can be exhaled.\""}, {"id": "b", "text": "\"It helps the air dissolve faster into the bloodstream.\""}, {"id": "c", "text": "\"It traps the air in the right atrium away from the lungs.\""}, {"id": "d", "text": "\"It raises blood pressure so the heart can push the air out.\""}]'::jsonb, '["c"]', 'Left lateral Trendelenburg traps air in the right atrium to prevent it from entering the pulmonary circulation. Moving air into the lungs is the opposite of the goal.'),
  ('pe', 10, 'A client 2 days after knee surgery reports sudden shortness of breath, and the nurse suspects a pulmonary embolism from a DVT. In which position should the nurse place the client?', '[{"id": "a", "text": "Head of bed elevated 30–45°"}, {"id": "b", "text": "Left lateral Trendelenburg"}, {"id": "c", "text": "Flat supine with legs elevated"}, {"id": "d", "text": "Prone with the head turned"}]'::jsonb, '["a"]', 'For suspected PE, the head of the bed is elevated 30–45° unless the cause is an air embolism. Left lateral Trendelenburg is reserved for air embolism.'),
  ('pe', 11, 'A nurse is reviewing Virchow''s triad with a group of students. Which risk factor is an example of stasis?', '[{"id": "a", "text": "Pregnancy"}, {"id": "b", "text": "A long airplane flight"}, {"id": "c", "text": "An indwelling IV catheter"}, {"id": "d", "text": "Active cancer"}]'::jsonb, '["b"]', 'Stasis includes prolonged immobility, long flights, bed rest, and post-surgical states. Pregnancy and cancer represent hypercoagulability, and an IV catheter represents endothelial injury.'),
  ('pe', 12, 'A client''s history is reviewed for pulmonary embolism risk. Which finding represents the hypercoagulability component of Virchow''s triad?', '[{"id": "a", "text": "Recent trauma to the leg"}, {"id": "b", "text": "Prolonged bed rest"}, {"id": "c", "text": "An indwelling IV catheter"}, {"id": "d", "text": "Use of oral contraceptives"}]'::jsonb, '["d"]', 'Hypercoagulability includes clotting disorders, pregnancy, oral contraceptives (OCP), and cancer. Trauma and IV catheters represent endothelial injury, and bed rest represents stasis.'),
  ('pe', 13, 'Which factor in a hospitalized client represents the endothelial injury component of Virchow''s triad?', '[{"id": "a", "text": "Pregnancy"}, {"id": "b", "text": "An indwelling IV catheter"}, {"id": "c", "text": "Prolonged bed rest"}, {"id": "d", "text": "A clotting disorder"}]'::jsonb, '["b"]', 'Endothelial injury includes IV catheters, surgery, trauma, and infections. Pregnancy and clotting disorders represent hypercoagulability, and bed rest represents stasis.'),
  ('pe', 14, 'A nurse is assessing four clients on a medical-surgical unit. Which client has the most risk factors for pulmonary embolism?', '[{"id": "a", "text": "A 28-year-old who ambulates the halls hourly"}, {"id": "b", "text": "A 35-year-old admitted for observation"}, {"id": "c", "text": "A 68-year-old with obesity and a hip fracture"}, {"id": "d", "text": "A 40-year-old who is drinking fluids well"}]'::jsonb, '["c"]', 'Additional PE risk factors include fractures (especially hip/femur), obesity, and age over 60. Early ambulation and adequate hydration are prevention measures rather than risks.'),
  ('pe', 15, 'A client is 2 days postoperative after hip surgery. Which cluster of findings should the nurse recognize as most consistent with a pulmonary embolism?', '[{"id": "a", "text": "Gradually worsening dyspnea, dull chest ache, and barrel chest"}, {"id": "b", "text": "Sharp pleuritic chest pain, sudden dyspnea, and a sense of doom"}, {"id": "c", "text": "Slowly increasing cough, pursed-lip breathing, and fatigue"}, {"id": "d", "text": "Dull chest pressure, gradual dyspnea, and normal oxygen levels"}]'::jsonb, '["b"]', 'The PE hallmark is sharp chest pain plus dyspnea plus a "sense of impending doom." Gradual worsening, dull or absent pain, barrel chest, and pursed-lip breathing point toward COPD.'),
  ('pe', 16, 'A nurse is assessing a client with a suspected pulmonary embolism. Which finding does the nurse expect?', '[{"id": "a", "text": "Barrel-shaped chest"}, {"id": "b", "text": "Pursed-lip breathing"}, {"id": "c", "text": "Bloody sputum"}, {"id": "d", "text": "Dull or absent chest pain"}]'::jsonb, '["c"]', 'Hemoptysis (bloody sputum) is a classic PE symptom. PE does not present with a barrel chest or pursed-lip breathing, and PE pain is sharp rather than dull or absent.'),
  ('pe', 17, 'A client with a long history of COPD is admitted with increased shortness of breath. Which finding should make the nurse suspect a pulmonary embolism rather than a COPD exacerbation?', '[{"id": "a", "text": "Decreased oxygen saturation"}, {"id": "b", "text": "Rapid respiratory rate"}, {"id": "c", "text": "Shortness of breath"}, {"id": "d", "text": "Sharp chest pain"}]'::jsonb, '["d"]', 'PE presents with sharp chest pain, while COPD pain is typically absent or dull. Shortness of breath, decreased oxygen saturation, and tachypnea occur in both conditions.'),
  ('pe', 18, 'A nurse is comparing pulmonary embolism with COPD. Which finding occurs in both conditions and therefore does not help distinguish them?', '[{"id": "a", "text": "Tachypnea"}, {"id": "b", "text": "Sharp chest pain"}, {"id": "c", "text": "Barrel chest"}, {"id": "d", "text": "Sudden onset"}]'::jsonb, '["a"]', 'Both PE and COPD present with shortness of breath, decreased oxygen, and tachypnea. Sharp chest pain and sudden onset point to PE, and barrel chest is absent in PE.'),
  ('pe', 19, 'A client is admitted with shortness of breath. Which assessment finding is more consistent with COPD than with pulmonary embolism?', '[{"id": "a", "text": "Hemoptysis"}, {"id": "b", "text": "Sense of impending doom"}, {"id": "c", "text": "Sudden onset of dyspnea"}, {"id": "d", "text": "Pursed-lip breathing"}]'::jsonb, '["d"]', 'PE does not present with a barrel chest or pursed-lip breathing. Hemoptysis, a sense of impending doom, and sudden dyspnea are classic PE findings.'),
  ('pe', 20, 'A client with suspected pulmonary embolism has an elevated D-dimer. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"The high result suggests a clot is breaking down.\""}, {"id": "b", "text": "\"My high D-dimer confirms that I have a PE.\""}, {"id": "c", "text": "\"I may still need another test to diagnose a PE.\""}, {"id": "d", "text": "\"This test is sensitive but not very specific.\""}]'::jsonb, '["b"]', 'D-dimer has high sensitivity but low specificity, so a positive result does not confirm PE. An elevated level suggests clot breakdown, and further testing such as CT pulmonary angiography is needed.'),
  ('pe', 21, 'A provider suspects pulmonary embolism. Which diagnostic test does the nurse anticipate as the gold standard for diagnosis?', '[{"id": "a", "text": "CT pulmonary angiography"}, {"id": "b", "text": "D-dimer level"}, {"id": "c", "text": "12-lead ECG"}, {"id": "d", "text": "Coagulation panel"}]'::jsonb, '["a"]', 'CT pulmonary angiography (CTPA) is the gold standard because it visualizes clots in the pulmonary arteries directly. A D-dimer is sensitive but not specific, and a coagulation panel guides anticoagulation.'),
  ('pe', 22, 'A client with chronic renal disease and a contrast allergy is suspected of having a pulmonary embolism. Which diagnostic test does the nurse anticipate?', '[{"id": "a", "text": "CT pulmonary angiography"}, {"id": "b", "text": "Ventilation/perfusion (V/Q) scan"}, {"id": "c", "text": "Repeat D-dimer every hour"}, {"id": "d", "text": "Arterial blood gas only"}]'::jsonb, '["b"]', 'A V/Q scan is used when CT is contraindicated, such as with allergy or renal disease. CT pulmonary angiography is the usual gold standard but is contraindicated for this client.'),
  ('pe', 23, 'A provider orders PT/INR and PTT for a client newly diagnosed with pulmonary embolism. The nurse understands the main purpose of these tests is to:', '[{"id": "a", "text": "Confirm the location of the clot"}, {"id": "b", "text": "Rule out pulmonary embolism"}, {"id": "c", "text": "Guide anticoagulant selection and dosing"}, {"id": "d", "text": "Measure the level of hypoxemia"}]'::jsonb, '["c"]', 'The coagulation panel guides anticoagulation therapy selection and dosing. Clot location is confirmed by CT pulmonary angiography, and hypoxemia is measured by ABG.'),
  ('pe', 24, 'A client in the early stage of a pulmonary embolism is breathing rapidly. Which arterial blood gas pattern does the nurse expect?', '[{"id": "a", "text": "Decreased PaO₂, decreased PaCO₂, respiratory alkalosis"}, {"id": "b", "text": "Decreased PaO₂, increased PaCO₂, respiratory acidosis"}, {"id": "c", "text": "Increased PaO₂, decreased PaCO₂, metabolic alkalosis"}, {"id": "d", "text": "Normal PaO₂, increased PaCO₂, metabolic acidosis"}]'::jsonb, '["a"]', 'Early PE produces a decreased PaO₂ and a decreased PaCO₂ from hyperventilation, causing respiratory alkalosis. An increased PaCO₂ with acidosis is the reverse pattern.'),
  ('pe', 25, 'A nurse reviews the ECG of a client with a suspected pulmonary embolism. Which statement about ECG findings in PE is accurate?', '[{"id": "a", "text": "Sinus bradycardia is the most expected rhythm"}, {"id": "b", "text": "The S1Q3T3 pattern is present in most clients"}, {"id": "c", "text": "A normal sinus rhythm rules out the diagnosis"}, {"id": "d", "text": "Sinus tachycardia is the most expected rhythm"}]'::jsonb, '["d"]', 'Sinus tachycardia is the expected ECG finding in PE. The S1Q3T3 pattern is classic but uncommon, so it is not present in most clients.'),
  ('pe', 26, 'A client with a pulmonary embolism is receiving oxygen therapy. Which oxygen saturation reading indicates the therapy is meeting the treatment goal?', '[{"id": "a", "text": "88%"}, {"id": "b", "text": "90%"}, {"id": "c", "text": "96%"}, {"id": "d", "text": "92%"}]'::jsonb, '["c"]', 'Oxygen therapy for PE aims to maintain SpO₂ above 94%, so 96% meets the goal. Readings of 92% or lower fall below the target.'),
  ('pe', 27, 'A client who had hip surgery yesterday suddenly reports sharp chest pain and says, "I can''t catch my breath." Which action should the nurse take first?', '[{"id": "a", "text": "Notify the physician immediately"}, {"id": "b", "text": "Administer high-flow oxygen"}, {"id": "c", "text": "Establish IV access"}, {"id": "d", "text": "Prepare for a CT scan"}]'::jsonb, '["b"]', 'The first action for suspected PE is to administer oxygen, then notify the physician. IV access and preparing for CT come after oxygen and notification.'),
  ('pe', 28, 'A nurse is caring for a client with a suspected pulmonary embolism from a DVT. Which sequence of nursing actions is correct?', '[{"id": "a", "text": "Notify the physician, give oxygen, establish IV access, elevate the HOB"}, {"id": "b", "text": "Establish IV access, elevate the HOB, give oxygen, notify the physician"}, {"id": "c", "text": "Elevate the HOB, establish IV access, notify the physician, give oxygen"}, {"id": "d", "text": "Give oxygen, notify the physician, elevate the HOB, establish IV access"}]'::jsonb, '["d"]', 'Priority actions for suspected PE are high-flow oxygen immediately, STAT physician notification, HOB elevation of 30–45°, and then IV access to prepare for anticoagulation. The other sequences delay oxygen.'),
  ('pe', 29, 'A nurse has applied high-flow oxygen, notified the physician, and elevated the head of the bed for a client with a suspected pulmonary embolism. Which action should the nurse take next?', '[{"id": "a", "text": "Establish IV access to prepare for anticoagulation"}, {"id": "b", "text": "Reposition the client in left lateral Trendelenburg"}, {"id": "c", "text": "Assist the client to ambulate to reduce stasis"}, {"id": "d", "text": "Remove oxygen to obtain a room-air saturation"}]'::jsonb, '["a"]', 'After oxygen, physician notification, and HOB elevation, the nurse establishes IV access and prepares for anticoagulation. Left lateral Trendelenburg is only for air embolism.'),
  ('pe', 30, 'A client is diagnosed with a pulmonary embolism from a DVT. Which anticoagulant does the nurse anticipate administering first for immediate effect?', '[{"id": "a", "text": "Oral warfarin"}, {"id": "b", "text": "IV heparin"}, {"id": "c", "text": "Oral DOAC"}, {"id": "d", "text": "IV tPA"}]'::jsonb, '["b"]', 'IV heparin is given first for immediate anticoagulation and then bridged to warfarin or a DOAC for long-term therapy. tPA is a thrombolytic reserved for hemodynamic instability.'),
  ('pe', 31, 'A client with a pulmonary embolism who has started warfarin asks why the heparin infusion is still running. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Heparin should have been stopped when warfarin started.\""}, {"id": "b", "text": "\"Heparin is continued only until the first warfarin dose.\""}, {"id": "c", "text": "\"Heparin overlaps warfarin for a minimum of 5 days.\""}, {"id": "d", "text": "\"Heparin is continued for life along with warfarin.\""}]'::jsonb, '["c"]', 'Heparin is given first and bridges to warfarin with an overlap of at least 5 days. Stopping heparin when warfarin starts would not provide this overlap.'),
  ('pe', 32, 'A client is receiving warfarin after a pulmonary embolism. Which INR value indicates that therapy is in the therapeutic range?', '[{"id": "a", "text": "1.0"}, {"id": "b", "text": "1.5"}, {"id": "c", "text": "4.0"}, {"id": "d", "text": "2.5"}]'::jsonb, '["d"]', 'The therapeutic INR for warfarin is 2.0–3.0, so 2.5 is therapeutic. Values of 1.0 and 1.5 are below the range, and 4.0 is above it.'),
  ('pe', 33, 'A nurse reviews INR results for four clients taking warfarin for pulmonary embolism. Which result should the nurse report because it is outside the therapeutic range?', '[{"id": "a", "text": "1.3"}, {"id": "b", "text": "2.2"}, {"id": "c", "text": "2.6"}, {"id": "d", "text": "2.9"}]'::jsonb, '["a"]', 'The therapeutic INR for warfarin is 2.0–3.0, so 1.3 is outside the range and should be reported. The other values fall within the therapeutic range.'),
  ('pe', 34, 'A client with a massive pulmonary embolism becomes hypotensive and shows signs of shock. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Inserting an IVC filter"}, {"id": "b", "text": "Starting oral warfarin alone"}, {"id": "c", "text": "Administering a thrombolytic (tPA)"}, {"id": "d", "text": "Scheduling surgical embolectomy first"}]'::jsonb, '["c"]', 'Thrombolytics (tPA) are indicated for hemodynamic instability such as hypotension or shock. Surgical embolectomy is a last resort, and an IVC filter is for recurrent DVT/PE when anticoagulation is contraindicated.'),
  ('pe', 35, 'A client has had recurrent DVTs and a pulmonary embolism, and anticoagulation is contraindicated. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Placement of an IVC filter"}, {"id": "b", "text": "Long-term IV heparin"}, {"id": "c", "text": "High-dose warfarin"}, {"id": "d", "text": "Left lateral Trendelenburg"}]'::jsonb, '["a"]', 'An IVC filter is used for recurrent DVT/PE when anticoagulation is contraindicated. Heparin and warfarin are anticoagulants, which this client cannot receive.'),
  ('pe', 36, 'A nurse is reviewing interventions for massive pulmonary embolism. Which intervention is considered a last resort?', '[{"id": "a", "text": "Thrombolytic therapy"}, {"id": "b", "text": "IV heparin infusion"}, {"id": "c", "text": "High-flow oxygen"}, {"id": "d", "text": "Surgical embolectomy"}]'::jsonb, '["d"]', 'Surgical embolectomy is a last-resort intervention for massive PE. Thrombolytics are used for hemodynamic instability, and heparin and oxygen are standard first-line treatments.'),
  ('pe', 37, 'A client with a pulmonary embolism is receiving IV fluids. The nurse understands that the purpose of the IV fluids is to:', '[{"id": "a", "text": "Dissolve the clot in the pulmonary artery"}, {"id": "b", "text": "Support the client''s hemodynamics"}, {"id": "c", "text": "Lower the client''s INR value"}, {"id": "d", "text": "Reduce the client''s pleuritic chest pain"}]'::jsonb, '["b"]', 'IV fluids are given in PE to support hemodynamics. Clots are treated with anticoagulants or thrombolytics, and pleuritic chest pain is treated with pain management.'),
  ('pe', 38, 'A client is 1 day postoperative after abdominal surgery. Which nursing action best helps prevent DVT and pulmonary embolism?', '[{"id": "a", "text": "Keeping the client on strict bed rest"}, {"id": "b", "text": "Restricting oral fluid intake"}, {"id": "c", "text": "Promoting early ambulation"}, {"id": "d", "text": "Keeping the legs crossed in bed"}]'::jsonb, '["c"]', 'Early ambulation after surgery prevents DVT and PE. Bed rest causes stasis, and restricting fluids works against the recommendation for adequate hydration.'),
  ('pe', 39, 'A nurse is teaching a postoperative client how to prevent DVT and pulmonary embolism. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will wear my compression devices while in bed.\""}, {"id": "b", "text": "\"I will limit my fluids so my blood stays thin.\""}, {"id": "c", "text": "\"I will get up and walk as soon as I am allowed.\""}, {"id": "d", "text": "\"I will take my low-molecular-weight heparin.\""}]'::jsonb, '["b"]', 'Adequate hydration is part of DVT and PE prevention, so limiting fluids is incorrect. Sequential compression devices, early ambulation, and LMWH prophylaxis are correct prevention measures.'),
  ('pe', 40, 'A client recovering from a DVT is planning a 12-hour international flight. Which statement by the client indicates understanding of prevention teaching?', '[{"id": "a", "text": "\"I will stay seated the entire flight to rest my legs.\""}, {"id": "b", "text": "\"I will stand and walk about once every hour.\""}, {"id": "c", "text": "\"I will avoid drinking any fluids during the flight.\""}, {"id": "d", "text": "\"I will stand up and walk once at the halfway point.\""}]'::jsonb, '["b"]', 'Clients should avoid prolonged immobility and, on long flights, stand and walk hourly. Remaining seated or walking only once allows stasis, and avoiding fluids conflicts with adequate hydration.'),
  ('pe', 41, 'A client is admitted for hip surgery and is at risk for DVT. Which medication does the nurse anticipate for prophylaxis?', '[{"id": "a", "text": "Thrombolytic (tPA)"}, {"id": "b", "text": "Corticosteroid"}, {"id": "c", "text": "Low-molecular-weight heparin"}, {"id": "d", "text": "Supplemental oxygen"}]'::jsonb, '["c"]', 'Low-molecular-weight heparin (LMWH) prophylaxis is a DVT/PE prevention measure. Thrombolytics are reserved for massive PE with hemodynamic instability.'),
  ('pe', 42, 'A client 2 days after abdominal surgery grips the nurse''s arm and says, "I feel like something terrible is about to happen." The client also reports sharp chest pain. How should the nurse interpret this?', '[{"id": "a", "text": "Expected postoperative anxiety needing reassurance"}, {"id": "b", "text": "A sign of gradually worsening chronic lung disease"}, {"id": "c", "text": "Pulmonary embolism until proven otherwise"}, {"id": "d", "text": "A normal reaction to postoperative pain medication"}]'::jsonb, '["c"]', 'A "sense of impending doom" with sharp chest pain after recent surgery or immobility is pulmonary embolism until proven otherwise. Dismissing it as anxiety would delay care, and gradual worsening suggests COPD.'),
  ('pe', 43, 'A nursing student asks how a pulmonary embolism leads to low oxygen levels. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Fluid leaks into the air sacs and prevents oxygen exchange.\""}, {"id": "b", "text": "\"Blocked pulmonary arteries reduce blood flow and gas exchange.\""}, {"id": "c", "text": "\"Narrowed airways trap air in the lungs and reduce exhalation.\""}, {"id": "d", "text": "\"Weak breathing muscles reduce the amount of air inhaled.\""}]'::jsonb, '["b"]', 'PE is a blockage of the pulmonary arteries that impairs blood flow to the lungs, decreases gas exchange, and causes hypoxemia and right heart strain. The other explanations do not describe a blockage of the pulmonary arteries.'),
  ('pe', 44, 'A client with a fractured tibia becomes confused and hypoxic, and the nurse notes petechiae across the chest and axillae. Which type of embolism does the nurse suspect?', '[{"id": "a", "text": "Air embolism"}, {"id": "b", "text": "Blood clot embolism"}, {"id": "c", "text": "COPD exacerbation"}, {"id": "d", "text": "Fat embolism"}]'::jsonb, '["d"]', 'Fat embolism, triggered by long bone fractures, presents with a petechial rash on the chest and axillae plus altered mental status and hypoxia. Air emboli are linked to IV and central lines.'),
  ('pe', 45, 'A nurse is reviewing positioning for clients with different types of pulmonary embolism. Which statement by a new nurse indicates a need for further teaching?', '[{"id": "a", "text": "\"A client with an air embolism goes on the left side, head down.\""}, {"id": "b", "text": "\"A client with a clot-related PE has the HOB raised 30–45°.\""}, {"id": "c", "text": "\"A client with an air embolism has the infusion stopped.\""}, {"id": "d", "text": "\"A client with a clot-related PE is placed in Trendelenburg.\""}]'::jsonb, '["d"]', 'Trendelenburg is reserved for air embolism; a client with a clot-related PE has the HOB elevated 30–45°. The other statements correctly describe positioning and stopping the air source.'),
  ('pe', 46, 'A nurse is assessing a client with a pulmonary embolism. Which vital sign changes does the nurse expect?', '[{"id": "a", "text": "Bradycardia and bradypnea"}, {"id": "b", "text": "Tachycardia and tachypnea"}, {"id": "c", "text": "Bradycardia and tachypnea"}, {"id": "d", "text": "Tachycardia and bradypnea"}]'::jsonb, '["b"]', 'Classic PE symptoms include tachycardia and tachypnea along with decreased oxygen saturation. A slow heart rate or slow breathing is not an expected PE finding.'),
  ('pe', 47, 'A nurse is admitting two clients with shortness of breath. Which history most strongly suggests a pulmonary embolism?', '[{"id": "a", "text": "Dyspnea that has gradually worsened over several months"}, {"id": "b", "text": "Dyspnea with a dull chest ache and pursed-lip breathing"}, {"id": "c", "text": "Sudden dyspnea that began after a week of immobility"}, {"id": "d", "text": "Chronic dyspnea with a barrel chest and no chest pain"}]'::jsonb, '["c"]', 'Sudden onset shortness of breath with recent immobility or surgery should raise suspicion for PE. Gradual worsening, dull or absent pain, pursed-lip breathing, and barrel chest point toward COPD.'),
  ('pe', 48, 'A nurse is reviewing treatments for different types of emboli. Which treatment is correctly matched to the embolism type?', '[{"id": "a", "text": "Blood clot embolism: heparin followed by warfarin"}, {"id": "b", "text": "Air embolism: heparin followed by warfarin"}, {"id": "c", "text": "Blood clot embolism: left lateral Trendelenburg"}, {"id": "d", "text": "Fat embolism: left lateral Trendelenburg"}]'::jsonb, '["a"]', 'Blood clot (DVT-PE) is treated with anticoagulants (heparin to warfarin), oxygen, fluids, and thrombolytics if massive. Left lateral Trendelenburg is the key treatment for air embolism, not blood clot or fat embolism.'),
  ('pe', 49, 'A client with a suspected pulmonary embolism is very anxious and restless and has an oxygen saturation lower than baseline. On auscultation, which lung finding does the nurse expect?', '[{"id": "a", "text": "Crackles"}, {"id": "b", "text": "Clear sounds throughout"}, {"id": "c", "text": "Absent breath sounds bilaterally"}, {"id": "d", "text": "Stridor over the trachea"}]'::jsonb, '["a"]', 'Crackles (rales) on auscultation are among the classic PE symptoms, along with restlessness, anxiety, and decreased oxygen saturation. Clear lungs or bilateral absent breath sounds are not listed as PE findings.'),
  ('pe', 50, 'A client with a suspected pulmonary embolism has been placed on high-flow oxygen while awaiting a CT scan. How often should the nurse monitor the client''s vital signs?', '[{"id": "a", "text": "Continuously"}, {"id": "b", "text": "Every 4 hours"}, {"id": "c", "text": "Once per shift"}, {"id": "d", "text": "Every 8 hours"}]'::jsonb, '["a"]', 'Priority nursing actions for suspected PE include monitoring vital signs continuously. Intermittent checks every few hours or once per shift do not meet this priority.'),
  ('sleep_apnea', 1, 'A client''s sleep study shows that the airway repeatedly closes during sleep while breathing effort continues. Which type of sleep apnea does this indicate?', '[{"id": "a", "text": "Central, because the brain fails to signal breathing"}, {"id": "b", "text": "Mixed, because only central features are present"}, {"id": "c", "text": "Obstructive, because the airway closes despite effort"}, {"id": "d", "text": "Central, because the airway is physically blocked"}]'::jsonb, '["c"]', 'In obstructive sleep apnea the airway physically collapses or is blocked during sleep despite breathing effort. In central sleep apnea the brain fails to signal the breathing muscles, so no effort is made.'),
  ('sleep_apnea', 2, 'A sleep study shows breathing pauses during which the client makes no effort to breathe. The nurse recognizes this pattern as which type of sleep apnea?', '[{"id": "a", "text": "Obstructive, because the tongue falls back and blocks the airway"}, {"id": "b", "text": "Obstructive, because throat muscles relax despite breathing effort"}, {"id": "c", "text": "Central, because the brain fails to signal the breathing muscles"}, {"id": "d", "text": "Mixed, because the airway collapses while effort continues"}]'::jsonb, '["c"]', 'Central sleep apnea occurs when the brain fails to send proper signals to the breathing muscles, so no effort is made to breathe. Obstructive apnea involves airway collapse despite breathing effort.'),
  ('sleep_apnea', 3, 'The nurse reviews the histories of four clients. Which client has the greatest risk for central sleep apnea?', '[{"id": "a", "text": "A client with enlarged tonsils and a deviated septum"}, {"id": "b", "text": "A client with a small jaw and a crowded oropharynx"}, {"id": "c", "text": "A client with heart failure who takes daily opioids"}, {"id": "d", "text": "A client with an 18-inch neck who snores loudly"}]'::jsonb, '["c"]', 'Central sleep apnea is associated with heart failure, opioid use, and brainstem disorders. Enlarged tonsils, a small jaw, and a large neck are risk factors for airway narrowing in obstructive sleep apnea.'),
  ('sleep_apnea', 4, 'A client''s polysomnography shows some episodes of airway obstruction and other episodes with no breathing effort. Which type of sleep apnea should the nurse expect to be diagnosed?', '[{"id": "a", "text": "Obstructive sleep apnea alone"}, {"id": "b", "text": "Central sleep apnea alone"}, {"id": "c", "text": "Central apnea from airway collapse"}, {"id": "d", "text": "Mixed sleep apnea"}]'::jsonb, '["d"]', 'Mixed sleep apnea is a combination of obstructive and central features. Airway collapse is an obstructive feature, not a central one.'),
  ('sleep_apnea', 5, 'A client newly diagnosed with obstructive sleep apnea asks what causes the breathing pauses. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The brain stops sending signals, so no breathing effort is made."}, {"id": "b", "text": "The throat muscles tighten and squeeze the airway closed at night."}, {"id": "c", "text": "The breathing muscles stop moving while the airway stays open."}, {"id": "d", "text": "Throat muscles relax and the tongue falls back to block the airway."}]'::jsonb, '["d"]', 'In OSA, throat muscles relax and the tongue or soft tissue falls back to block the airway. Absence of brain signals with no breathing effort describes central sleep apnea.'),
  ('sleep_apnea', 6, 'A client with sleep apnea asks why they wake briefly many times each night. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Blood oxygen rises during each pause, causing restless awakening."}, {"id": "b", "text": "Nighttime urination is the only cause of the frequent awakenings."}, {"id": "c", "text": "Snoring noise alone wakes you; oxygen levels stay normal at night."}, {"id": "d", "text": "Blood oxygen falls during each pause, prompting arousal to breathe."}]'::jsonb, '["d"]', 'During each apneic episode hypoxemia (low blood oxygen) develops, causing a brief arousal to restore breathing. Oxygen falls rather than rises during apneas.'),
  ('sleep_apnea', 7, 'The nurse is screening clients for obstructive sleep apnea. Which finding should the nurse identify as a risk factor?', '[{"id": "a", "text": "A man with a neck circumference of 18 inches"}, {"id": "b", "text": "A woman with a neck circumference of 14 inches"}, {"id": "c", "text": "A man with a body mass index of 23"}, {"id": "d", "text": "A woman who sleeps on her side every night"}]'::jsonb, '["a"]', 'A large neck circumference, more than 17 inches in men or 16 inches in women, is a risk factor for OSA. A 14-inch neck in a woman is below the 16-inch threshold, and side-lying sleep helps reduce apneas.'),
  ('sleep_apnea', 8, 'The nurse is assessing a client with untreated obstructive sleep apnea. Which finding should the nurse expect?', '[{"id": "a", "text": "Irritability and difficulty concentrating"}, {"id": "b", "text": "Elevated mood and increased libido"}, {"id": "c", "text": "Feeling refreshed after a night''s sleep"}, {"id": "d", "text": "Sharper memory than in previous years"}]'::jsonb, '["a"]', 'Additional OSA symptoms include difficulty concentrating, memory problems, mood swings, irritability, and decreased libido. Clients typically remain tired despite a full night of sleep.'),
  ('sleep_apnea', 9, 'A client with a body mass index of 38 asks why weight affects sleep apnea. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Fat deposits widen the airway during sleep."}, {"id": "b", "text": "Extra weight inflames the airway like smoke."}, {"id": "c", "text": "Fat deposits narrow the airway during sleep."}, {"id": "d", "text": "Extra weight blocks brain signals to breathe."}]'::jsonb, '["c"]', 'Obesity with a BMI over 35 is a risk factor because fat deposits narrow the airway. Airway inflammation is the mechanism linked to smoking.'),
  ('sleep_apnea', 10, 'A client is referred for loud snoring. Which assessment finding increases the client''s risk for obstructive sleep apnea?', '[{"id": "a", "text": "Enlarged tonsils"}, {"id": "b", "text": "Neck of 14 inches in a man"}, {"id": "c", "text": "Body mass index of 22"}, {"id": "d", "text": "Age of 32 years"}]'::jsonb, '["a"]', 'Physical airway abnormalities that raise OSA risk include enlarged tonsils, deviated septum, and retrognathia. A 14-inch neck in a man is below the 17-inch threshold for increased risk.'),
  ('sleep_apnea', 11, 'A client asks whether gender affects the risk of developing obstructive sleep apnea. Which response by the nurse is correct?', '[{"id": "a", "text": "Females are affected two to three times more than males."}, {"id": "b", "text": "Gender has no effect on the risk for sleep apnea."}, {"id": "c", "text": "Males are affected two to three times more than females."}, {"id": "d", "text": "Males and females are affected at an equal rate."}]'::jsonb, '["c"]', 'Male gender is a risk factor, with males affected 2–3 times more than females. Gender is also part of the STOP-BANG screening.'),
  ('sleep_apnea', 12, 'A client with obstructive sleep apnea asks why drinking alcohol in the evening makes symptoms worse. Which response by the nurse is accurate?', '[{"id": "a", "text": "Alcohol inflames the airway lining like smoke."}, {"id": "b", "text": "Alcohol relaxes the airway muscles even more."}, {"id": "c", "text": "Alcohol narrows the airway with fat deposits."}, {"id": "d", "text": "Alcohol raises the blood oxygen during sleep."}]'::jsonb, '["b"]', 'Excess alcohol use relaxes airway muscles more, worsening apnea. Airway inflammation is the mechanism linked to smoking, and fat deposits relate to obesity.'),
  ('sleep_apnea', 13, 'A client with obstructive sleep apnea who smokes asks how quitting would help. Which response by the nurse is accurate?', '[{"id": "a", "text": "Quitting increases airway muscle laxity."}, {"id": "b", "text": "Quitting reduces airway inflammation."}, {"id": "c", "text": "Quitting has no effect on sleep apnea."}, {"id": "d", "text": "Quitting relaxes the throat muscles."}]'::jsonb, '["b"]', 'Smoking cessation is a lifestyle modification that reduces airway inflammation. Relaxed throat muscles cause the obstruction in OSA, so relaxing them would not help.'),
  ('sleep_apnea', 14, 'Which client report most strongly suggests obstructive sleep apnea?', '[{"id": "a", "text": "Waking refreshed with no snoring noticed by a bed partner"}, {"id": "b", "text": "Loud snoring and daytime fatigue despite a full night of sleep"}, {"id": "c", "text": "Trouble falling asleep but alert and focused during the day"}, {"id": "d", "text": "Quiet sleep with an occasional brief nap on weekends"}]'::jsonb, '["b"]', 'Daytime fatigue plus loud snoring are the classic OSA clues, with tiredness despite a full night of sleep. Waking refreshed without snoring does not fit OSA.'),
  ('sleep_apnea', 15, 'A client''s STOP-BANG screening score is 5. What is the nurse''s most appropriate action?', '[{"id": "a", "text": "Reassure the client that risk is low"}, {"id": "b", "text": "Refer the client for a sleep study"}, {"id": "c", "text": "Recommend a sleep aid at bedtime"}, {"id": "d", "text": "Repeat the screening in one year"}]'::jsonb, '["b"]', 'A STOP-BANG score of 3 or more indicates high risk for OSA and warrants referral for a sleep study. Sleep aids worsen OSA and should be avoided.'),
  ('sleep_apnea', 16, 'A 56-year-old man with a BMI of 37 reports loud snoring. He denies daytime tiredness, has normal blood pressure, has no observed apneas, and his neck measures 16 inches. How should the nurse interpret his STOP-BANG screening?', '[{"id": "a", "text": "High risk, with a score of 4"}, {"id": "b", "text": "Low risk, with a score of 2"}, {"id": "c", "text": "Low risk, with a score of 1"}, {"id": "d", "text": "High risk, with a score of 7"}]'::jsonb, '["a"]', 'He scores for snoring, BMI over 35, age over 50, and male gender, for a total of 4; a score of 3 or more is high risk. His 16-inch neck does not exceed the 17-inch threshold for men, so it does not add a point.'),
  ('sleep_apnea', 17, 'A client with suspected obstructive sleep apnea reports headaches on waking most mornings. The nurse recognizes these headaches are most likely related to which cause?', '[{"id": "a", "text": "Excess oxygen during sleep"}, {"id": "b", "text": "Low carbon dioxide at night"}, {"id": "c", "text": "Too much deep, restful sleep"}, {"id": "d", "text": "Nocturnal hypoxemia and hypercapnia"}]'::jsonb, '["d"]', 'Morning headaches in OSA result from nocturnal hypoxemia and hypercapnia. Oxygen falls rather than rises during apneic episodes.'),
  ('sleep_apnea', 18, 'The nurse is completing a focused assessment on a client with obstructive sleep apnea. Which additional symptom should the nurse expect?', '[{"id": "a", "text": "Increased sexual desire"}, {"id": "b", "text": "Frequent urination at night"}, {"id": "c", "text": "Improved short-term memory"}, {"id": "d", "text": "Calm and stable mood"}]'::jsonb, '["b"]', 'Nocturia is an additional symptom of OSA, along with decreased libido, memory problems, and mood swings. Increased libido and improved memory are the opposite of expected findings.'),
  ('sleep_apnea', 19, 'A client with a high STOP-BANG score asks which test will confirm the diagnosis of sleep apnea. Which test is considered the gold standard?', '[{"id": "a", "text": "Overnight pulse oximetry at home"}, {"id": "b", "text": "A home sleep apnea test"}, {"id": "c", "text": "Polysomnography in a sleep lab"}, {"id": "d", "text": "A repeat STOP-BANG screening"}]'::jsonb, '["c"]', 'Polysomnography is the gold standard, with overnight monitoring of breathing, SpO₂, EEG, heart rate, and eye/limb movements in a sleep lab. Overnight oximetry is supportive but not definitive.'),
  ('sleep_apnea', 20, 'A client''s polysomnography report shows an apnea-hypopnea index (AHI) of 12 events per hour. How should the nurse interpret this result?', '[{"id": "a", "text": "Normal because the AHI is lower than 15"}, {"id": "b", "text": "Normal because the AHI is lower than 30"}, {"id": "c", "text": "Inconclusive until overnight oximetry is done"}, {"id": "d", "text": "Consistent with OSA because the AHI exceeds 5"}]'::jsonb, '["d"]', 'An AHI of more than 5 events per hour indicates OSA, so 12 events per hour is consistent with the diagnosis. Overnight oximetry is only supportive and is not needed to confirm a polysomnography result.'),
  ('sleep_apnea', 21, 'The nurse is reviewing sleep apnea testing options. For which client is a home sleep apnea test (HSAT) most appropriate?', '[{"id": "a", "text": "A client with uncomplicated suspected OSA"}, {"id": "b", "text": "A client who needs the most complete study"}, {"id": "c", "text": "A client who needs EEG brain-wave monitoring"}, {"id": "d", "text": "A client who needs limb movement monitoring"}]'::jsonb, '["a"]', 'The HSAT is a portable test that is less comprehensive than polysomnography and is used for uncomplicated suspected OSA. EEG and eye/limb movement monitoring are part of polysomnography in a sleep lab.'),
  ('sleep_apnea', 22, 'Overnight pulse oximetry for a client shows repeated drops in SpO₂. The client asks whether this confirms sleep apnea. Which response by the nurse is best?', '[{"id": "a", "text": "It confirms the diagnosis, so no more tests are needed."}, {"id": "b", "text": "It rules out sleep apnea because dips are normal."}, {"id": "c", "text": "It is the gold standard test for sleep apnea."}, {"id": "d", "text": "It supports the diagnosis but is not definitive."}]'::jsonb, '["d"]', 'Overnight oximetry is supportive but not definitive; it may show repeated SpO₂ dips. Polysomnography, not oximetry, is the gold standard.'),
  ('sleep_apnea', 23, 'A client with obesity and newly diagnosed obstructive sleep apnea asks which lifestyle change will help the most. Which response by the nurse is best?', '[{"id": "a", "text": "Sleep in the supine position"}, {"id": "b", "text": "Take a sleep aid at bedtime"}, {"id": "c", "text": "Vary bedtimes to sleep longer"}, {"id": "d", "text": "Lose weight"}]'::jsonb, '["d"]', 'Weight loss is the most impactful intervention for obese clients with OSA. Supine sleeping worsens OSA, and sleep aids worsen apnea.'),
  ('sleep_apnea', 24, 'A hospitalized client with obstructive sleep apnea is observed having apneic episodes while sleeping supine. Which nursing action is most appropriate?', '[{"id": "a", "text": "Give the prescribed as-needed sedative"}, {"id": "b", "text": "Keep the client flat on the back"}, {"id": "c", "text": "Remove the client''s CPAP mask"}, {"id": "d", "text": "Reposition the client to a side-lying position"}]'::jsonb, '["d"]', 'Side-lying positioning helps reduce apneic episodes, while the supine position worsens OSA. Sedatives are CNS depressants that worsen apnea.'),
  ('sleep_apnea', 25, 'The nurse teaches a client about lifestyle changes for obstructive sleep apnea. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will sleep flat on my back to keep my airway open."}, {"id": "b", "text": "I will avoid alcohol in the hours before I go to bed."}, {"id": "c", "text": "I will keep a regular sleep schedule during the week."}, {"id": "d", "text": "I will put on my CPAP every night before I fall asleep."}]'::jsonb, '["a"]', 'Clients should sleep on their side; the supine position worsens OSA. Limiting alcohol, keeping a regular sleep schedule, and nightly CPAP use are correct.'),
  ('sleep_apnea', 26, 'The nurse is teaching a client with obstructive sleep apnea about evening habits. Which instruction is accurate?', '[{"id": "a", "text": "Avoid alcohol and sedatives in the 3–4 hours before bed."}, {"id": "b", "text": "Limit alcohol only in the first hour after waking up."}, {"id": "c", "text": "Take a sedative before bed to help deepen your sleep."}, {"id": "d", "text": "Have one drink at bedtime to relax before sleeping."}]'::jsonb, '["a"]', 'Clients should limit alcohol and sedatives, especially in the 3–4 hours before bed. Sedatives and alcohol are CNS depressants that worsen apnea.'),
  ('sleep_apnea', 27, 'A client''s polysomnography confirms obstructive sleep apnea. Which treatment should the nurse anticipate as first-line?', '[{"id": "a", "text": "Uvulopalatopharyngoplasty (UPPP)"}, {"id": "b", "text": "Mandibular advancement surgery"}, {"id": "c", "text": "Repeated overnight pulse oximetry"}, {"id": "d", "text": "Continuous positive airway pressure (CPAP)"}]'::jsonb, '["d"]', 'CPAP is the first-line and #1 treatment for OSA. Surgical options such as UPPP are reserved for anatomical causes.'),
  ('sleep_apnea', 28, 'A client starting CPAP asks how the machine works. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It alternates two pressures to breathe for you at night."}, {"id": "b", "text": "It delivers steady air pressure that splints the airway open."}, {"id": "c", "text": "It moves your tongue and jaw forward to keep them in place."}, {"id": "d", "text": "It removes extra tissue from the back of your throat."}]'::jsonb, '["b"]', 'CPAP delivers steady, constant air pressure through a mask and acts as a pneumatic splint to keep the airway open during sleep. Repositioning the tongue and jaw describes an oral appliance.'),
  ('sleep_apnea', 29, 'When planning teaching for a client starting CPAP for obstructive sleep apnea, which topic is the nurse''s highest priority?', '[{"id": "a", "text": "Choosing a sleep aid to help with comfort"}, {"id": "b", "text": "Sleeping supine while wearing the mask"}, {"id": "c", "text": "Using CPAP only on very tiring days"}, {"id": "d", "text": "Using CPAP every night as prescribed"}]'::jsonb, '["d"]', 'CPAP compliance is the #1 intervention for OSA, and nightly adherence is required. Sleep aids worsen OSA, and supine sleeping worsens apnea.'),
  ('sleep_apnea', 30, 'The nurse evaluates a client''s understanding of home CPAP therapy. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I only need to wear it on nights when I feel very tired."}, {"id": "b", "text": "I will check the fit of my mask before bed each night."}, {"id": "c", "text": "I will clean my mask and tubing on a regular schedule."}, {"id": "d", "text": "I will wear it every night, even when I am traveling."}]'::jsonb, '["a"]', 'Most patients need nightly CPAP use, and compliance is the key challenge. Checking mask fit and following a cleaning schedule are part of CPAP teaching.'),
  ('sleep_apnea', 31, 'A client using CPAP for obstructive sleep apnea has a reddened area on the bridge of the nose. Which action should the nurse take first?', '[{"id": "a", "text": "Tighten the straps to stop any air leaks"}, {"id": "b", "text": "Stop CPAP and advise sleeping supine"}, {"id": "c", "text": "Assess the mask fit and the skin integrity"}, {"id": "d", "text": "Document it as an expected finding only"}]'::jsonb, '["c"]', 'The nurse should assess mask fit and skin integrity because the nasal bridge is prone to pressure injuries. Assessing fit and skin comes before any strap or therapy change, and stopping CPAP conflicts with required nightly adherence.'),
  ('sleep_apnea', 32, 'The nurse is preparing to apply CPAP to four clients with obstructive sleep apnea. For which client should the nurse question the use of CPAP?', '[{"id": "a", "text": "A client who is alert and snores loudly"}, {"id": "b", "text": "A client with a body mass index of 38"}, {"id": "c", "text": "A client who is actively vomiting"}, {"id": "d", "text": "A client with poorly controlled hypertension"}]'::jsonb, '["c"]', 'CPAP is contraindicated in unconscious or vomiting patients because of aspiration risk. Obesity and hypertension are common in OSA and are not contraindications.'),
  ('sleep_apnea', 33, 'A client who had facial surgery yesterday is found to have a cerebrospinal fluid (CSF) leak. The client uses CPAP at home for obstructive sleep apnea. Which action should the nurse take?', '[{"id": "a", "text": "Apply CPAP at the usual home setting"}, {"id": "b", "text": "Apply CPAP at a higher pressure setting"}, {"id": "c", "text": "Hold the CPAP and notify the provider"}, {"id": "d", "text": "Apply CPAP with the client lying supine"}]'::jsonb, '["c"]', 'CPAP is contraindicated in patients with a CSF leak or recent facial surgery, so it should be held. Supine positioning also worsens OSA.'),
  ('sleep_apnea', 34, 'A client reports difficulty exhaling against CPAP pressure and wants to stop treatment. Which device should the nurse anticipate the provider will consider?', '[{"id": "a", "text": "CPAP at a higher constant pressure"}, {"id": "b", "text": "BiPAP with a lower exhalation pressure"}, {"id": "c", "text": "CPAP with tighter mask straps"}, {"id": "d", "text": "Overnight pulse oximetry alone"}]'::jsonb, '["b"]', 'BiPAP is more comfortable for patients who struggle to exhale against CPAP pressure because exhalation pressure is lower. Raising the constant CPAP pressure would make exhaling harder.'),
  ('sleep_apnea', 35, 'A client is diagnosed with central sleep apnea. Which treatment should the nurse anticipate?', '[{"id": "a", "text": "CPAP"}, {"id": "b", "text": "Custom oral appliance"}, {"id": "c", "text": "BiPAP"}, {"id": "d", "text": "Nasal septum repair"}]'::jsonb, '["c"]', 'BiPAP is used in central sleep apnea, respiratory failure, and obesity hypoventilation syndrome. CPAP is the first-line treatment for obstructive sleep apnea, and septum repair addresses anatomical causes.'),
  ('sleep_apnea', 36, 'A client with obstructive sleep apnea is admitted with a COPD exacerbation and needs non-invasive ventilation. Which device should the nurse anticipate?', '[{"id": "a", "text": "BiPAP"}, {"id": "b", "text": "CPAP"}, {"id": "c", "text": "Custom oral appliance"}, {"id": "d", "text": "Overnight pulse oximetry"}]'::jsonb, '["a"]', 'BiPAP is also used for COPD exacerbations as non-invasive ventilation. CPAP is the first-line treatment for OSA but is not the device named for COPD exacerbations.'),
  ('sleep_apnea', 37, 'Which statement about BiPAP pressure settings is accurate?', '[{"id": "a", "text": "Inhalation pressure (IPAP) is higher than exhalation pressure (EPAP)."}, {"id": "b", "text": "Exhalation pressure (EPAP) is higher than inhalation pressure (IPAP)."}, {"id": "c", "text": "Inhalation and exhalation pressures are always set at equal levels."}, {"id": "d", "text": "Positive pressure is delivered only during the exhalation phase."}]'::jsonb, '["a"]', 'BiPAP delivers higher pressure during inhalation (IPAP) and lower pressure during exhalation (EPAP). A single steady pressure describes CPAP.'),
  ('sleep_apnea', 38, 'A client with mild obstructive sleep apnea refuses any treatment that requires wearing a mask. Which treatment should the nurse expect to be discussed?', '[{"id": "a", "text": "BiPAP with a full face mask"}, {"id": "b", "text": "A custom-fitted oral appliance"}, {"id": "c", "text": "CPAP with tighter mask straps"}, {"id": "d", "text": "Sleeping in the supine position"}]'::jsonb, '["b"]', 'Oral appliances are used for mild-moderate OSA or patients who cannot tolerate CPAP; they reposition the tongue and jaw forward. BiPAP still requires a mask, and supine sleeping worsens OSA.'),
  ('sleep_apnea', 39, 'A client scheduled for uvulopalatopharyngoplasty (UPPP) asks what the surgery does. Which response by the nurse is accurate?', '[{"id": "a", "text": "It removes excess throat tissue to enlarge the airway."}, {"id": "b", "text": "It moves the tongue and jaw forward with a device."}, {"id": "c", "text": "It straightens a deviated nasal septum to open it."}, {"id": "d", "text": "It delivers steady air pressure during your sleep."}]'::jsonb, '["a"]', 'UPPP removes excess throat tissue, including the uvula, soft palate, and tonsils, to enlarge the airway. Moving the tongue and jaw forward describes an oral appliance.'),
  ('sleep_apnea', 40, 'A client''s obstructive sleep apnea is attributed to a deviated nasal septum. Which surgical procedure addresses this cause?', '[{"id": "a", "text": "Nasal septum repair"}, {"id": "b", "text": "Mandibular advancement surgery"}, {"id": "c", "text": "Tonsillectomy"}, {"id": "d", "text": "Uvulopalatopharyngoplasty"}]'::jsonb, '["a"]', 'Surgical options for anatomical causes include nasal septum repair for a deviated septum. UPPP removes throat tissue such as the uvula, soft palate, and tonsils.'),
  ('sleep_apnea', 41, 'A client''s hypertension remains poorly controlled despite three medications, and the bed partner reports loud snoring. The nurse suspects untreated OSA. Which mechanism links the two?', '[{"id": "a", "text": "Nocturnal hypoxemia suppresses the sympathetic system."}, {"id": "b", "text": "OSA causes the blood pressure to fall during sleep."}, {"id": "c", "text": "Nocturnal hypoxemia activates the sympathetic system."}, {"id": "d", "text": "Snoring raises blood oxygen and then blood pressure."}]'::jsonb, '["c"]', 'Hypertension in untreated OSA is often resistant to medication because nocturnal hypoxemia activates the sympathetic nervous system. Oxygen falls, not rises, during apneas.'),
  ('sleep_apnea', 42, 'The nurse is teaching a client about complications of untreated obstructive sleep apnea. Which complication should the nurse include?', '[{"id": "a", "text": "Persistent hypotension"}, {"id": "b", "text": "Atrial fibrillation"}, {"id": "c", "text": "Improved insulin sensitivity"}, {"id": "d", "text": "Lower pulmonary pressures"}]'::jsonb, '["b"]', 'Untreated OSA can lead to hypertension, arrhythmias (especially AFib), stroke, and heart failure. OSA worsens insulin resistance and is associated with pulmonary hypertension.'),
  ('sleep_apnea', 43, 'A client with long-standing untreated obstructive sleep apnea develops pulmonary hypertension. The nurse understands this complication resulted from which cause?', '[{"id": "a", "text": "Chronic nocturnal hypoxemia"}, {"id": "b", "text": "Excess oxygen during sleep"}, {"id": "c", "text": "Low blood pressure at night"}, {"id": "d", "text": "Repeated nighttime urination"}]'::jsonb, '["a"]', 'Pulmonary hypertension develops from chronic nocturnal hypoxemia in untreated OSA. Oxygen levels drop, not rise, during apneic episodes.'),
  ('sleep_apnea', 44, 'A client with untreated obstructive sleep apnea asks why the risk of stroke is higher. Which response by the nurse is accurate?', '[{"id": "a", "text": "Low nighttime blood pressure reduces blood flow to the brain."}, {"id": "b", "text": "Excess oxygen at night damages the blood vessels of the brain."}, {"id": "c", "text": "Morning headaches alone cause blood clots to form in the brain."}, {"id": "d", "text": "Hypoxia, atrial fibrillation, and hypertension combine to raise it."}]'::jsonb, '["d"]', 'Stroke risk in OSA comes from hypoxia, atrial fibrillation, and hypertension combined. OSA causes hypertension, not low blood pressure.'),
  ('sleep_apnea', 45, 'A client with type 2 diabetes and untreated obstructive sleep apnea has rising blood glucose levels. Which explanation should the nurse provide?', '[{"id": "a", "text": "OSA improves insulin resistance."}, {"id": "b", "text": "OSA has no link to diabetes."}, {"id": "c", "text": "OSA lowers glucose during sleep."}, {"id": "d", "text": "OSA worsens insulin resistance."}]'::jsonb, '["d"]', 'Untreated OSA worsens insulin resistance, which explains the rising glucose. Type 2 diabetes is listed among the systemic consequences of untreated OSA.'),
  ('sleep_apnea', 46, 'A postoperative client with obstructive sleep apnea is receiving opioid analgesia. Which assessment is the nurse''s priority?', '[{"id": "a", "text": "Neck circumference and body mass index"}, {"id": "b", "text": "SpO₂, respiratory rate, and level of consciousness"}, {"id": "c", "text": "STOP-BANG score and snoring history"}, {"id": "d", "text": "Daytime mood, memory, and libido"}]'::jsonb, '["b"]', 'The nursing priority is to monitor for hypoxia by checking SpO₂, respiratory rate, and level of consciousness, especially because opioids worsen apnea. Screening data do not address the immediate risk.'),
  ('sleep_apnea', 47, 'The nurse reviews the plan of care for a client with obstructive sleep apnea. Which prescription should the nurse clarify with the provider?', '[{"id": "a", "text": "Nightly CPAP at the prescribed setting"}, {"id": "b", "text": "A sedative sleep aid at bedtime"}, {"id": "c", "text": "Side-lying positioning during sleep"}, {"id": "d", "text": "A referral to a weight-loss program"}]'::jsonb, '["b"]', 'CNS depressants such as sedatives worsen apnea and should be avoided in OSA. Nightly CPAP, side-lying positioning, and weight loss are recommended interventions.'),
  ('sleep_apnea', 48, 'A client with obstructive sleep apnea is prescribed a muscle relaxant for a back strain. Which nursing action is most appropriate?', '[{"id": "a", "text": "Give the drug at bedtime so the client sleeps more deeply"}, {"id": "b", "text": "Review the drug with the provider, since it can worsen OSA"}, {"id": "c", "text": "Give the drug and stop CPAP since sleep will be deeper"}, {"id": "d", "text": "Give the drug and place the client supine for comfort"}]'::jsonb, '["b"]', 'Many common medications, including muscle relaxants and sleep aids, worsen OSA, so medications should be reviewed. Stopping CPAP or positioning supine would further worsen apnea.'),
  ('sleep_apnea', 49, 'A hospitalized older adult with untreated obstructive sleep apnea reports severe daytime sleepiness and shows mild cognitive impairment. Which nursing intervention is the priority?', '[{"id": "a", "text": "Encourage walking alone during the night"}, {"id": "b", "text": "Give a sedative to improve nighttime sleep"}, {"id": "c", "text": "Implement fall-risk safety measures"}, {"id": "d", "text": "Position the client supine to rest well"}]'::jsonb, '["c"]', 'Excessive daytime sleepiness and cognitive impairment increase fall risk, so safety measures are needed. Sedatives worsen apnea, and supine positioning worsens OSA.'),
  ('sleep_apnea', 50, 'A client with untreated obstructive sleep apnea drives a delivery truck and reports dozing off during the day. Which teaching is most important?', '[{"id": "a", "text": "Recommend alcohol at night to sleep better"}, {"id": "b", "text": "Discuss the risks of driving while fatigued"}, {"id": "c", "text": "Suggest a sleep aid before long work shifts"}, {"id": "d", "text": "Advise sleeping supine to rest more deeply"}]'::jsonb, '["b"]', 'Nurses should educate clients with OSA about the risks of driving when fatigued. Alcohol and sleep aids worsen apnea, and supine positioning worsens OSA.'),
  ('trach', 1, 'A nursing student asks how a tracheostomy differs from an endotracheal (ET) tube. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A tracheostomy is placed through the nose and rests above the vocal cords.\""}, {"id": "b", "text": "\"A tracheostomy enters the trachea through the neck and bypasses the upper airway.\""}, {"id": "c", "text": "\"A tracheostomy is placed through the mouth and is secured at the lips.\""}, {"id": "d", "text": "\"A tracheostomy passes through the mouth and keeps the upper airway in use.\""}]'::jsonb, '["b"]', 'Unlike an ET tube, which is inserted through the mouth or nose, a tracheostomy goes directly through the neck into the trachea and bypasses the upper airway entirely. Mouth or nose placement describes an ET tube.'),
  ('trach', 2, 'The nurse is reviewing clients in the intensive care unit. Which client is most likely to need a tracheostomy because of prolonged ventilation?', '[{"id": "a", "text": "A client extubated 6 hours after an elective surgical procedure"}, {"id": "b", "text": "A client on 2 L/min nasal cannula who is alert and coughing effectively"}, {"id": "c", "text": "A client ventilated for 1 day after surgery who is now awake and following commands"}, {"id": "d", "text": "A client who has required mechanical ventilation for the past 16 days"}]'::jsonb, '["d"]', 'Mechanical ventilation lasting longer than 10–14 days is an indication for tracheostomy. The other clients have short or no ventilation needs and can clear their own airways.'),
  ('trach', 3, 'Which client condition is an indication for tracheostomy to protect the airway?', '[{"id": "a", "text": "Severe facial trauma sustained in a motor vehicle crash"}, {"id": "b", "text": "A productive cough that the client clears independently"}, {"id": "c", "text": "Alert mental status with an open, unobstructed upper airway"}, {"id": "d", "text": "A brief period of oxygen use after a minor outpatient procedure"}]'::jsonb, '["a"]', 'Airway-protection indications include upper airway obstruction, severe facial trauma or burns, and inability to clear secretions. A client who clears secretions independently with an open upper airway does not meet these indications.'),
  ('trach', 4, 'A client receiving mechanical ventilation is at high risk for aspiration. Which type of tracheostomy tube does the nurse expect this client to have?', '[{"id": "a", "text": "An uncuffed tube with no balloon around it"}, {"id": "b", "text": "A tube with the obturator left inside it"}, {"id": "c", "text": "A cuffed tube with an inflatable balloon"}, {"id": "d", "text": "A fenestrated tube with the cuff deflated"}]'::jsonb, '["c"]', 'A cuffed tube has an inflatable balloon that seals the airway below the stoma, preventing air leak and protecting the airway in ventilated clients with aspiration risk. An uncuffed tube has no seal and is used for clients breathing independently with low aspiration risk.'),
  ('trach', 5, 'A school-age child with a long-term tracheostomy breathes independently and has a low risk of aspiration. Which tube type is most consistent with this child''s needs?', '[{"id": "a", "text": "Cuffed tube to seal the airway below the stoma"}, {"id": "b", "text": "Uncuffed tube with no balloon and no seal"}, {"id": "c", "text": "Cuffed tube kept inflated above 20 mmHg"}, {"id": "d", "text": "Tube with the obturator kept in place"}]'::jsonb, '["b"]', 'Uncuffed tubes have no balloon and no seal and are used for clients breathing independently with low aspiration risk; they are often used in pediatrics. Cuffed tubes are for ventilated clients or those at aspiration risk.'),
  ('trach', 6, 'A client with a fenestrated tracheostomy tube asks what the openings in the tube are for. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"They let the cuff inflate more evenly against the trachea.\""}, {"id": "b", "text": "\"They let the obturator lock into place during insertion.\""}, {"id": "c", "text": "\"They let secretions drain out of the stoma onto the dressing.\""}, {"id": "d", "text": "\"They let air pass through your vocal cords so you can speak.\""}]'::jsonb, '["d"]', 'A fenestrated tube has holes in the outer cannula above the cuff that allow air to pass through the vocal cords, enabling speech when the cuff is deflated and the inner cannula is removed or a speaking valve is added.'),
  ('trach', 7, 'A client with a non-fenestrated tracheostomy tube writes, "Will I ever be able to talk with this tube?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Speech is not possible unless a speaking valve is added externally.\""}, {"id": "b", "text": "\"Speech is possible once the obturator is placed inside the tube.\""}, {"id": "c", "text": "\"Speech is possible as soon as the cuff is inflated fully.\""}, {"id": "d", "text": "\"Speech is possible because the tube has openings above the cuff.\""}]'::jsonb, '["a"]', 'A non-fenestrated tube has no holes in the outer cannula, so there is no speech unless a speaking valve is added externally. Openings above the cuff describe a fenestrated tube.'),
  ('trach', 8, 'A client asks how the tracheostomy tube can be cleaned without taking the whole tube out of the neck. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The outer cannula is removed and cleaned while the inner cannula stays in place.\""}, {"id": "b", "text": "\"The obturator is removed and cleaned each day to keep the airway open.\""}, {"id": "c", "text": "\"The inner cannula is removed and cleaned while the outer cannula stays in place.\""}, {"id": "d", "text": "\"The entire tube is removed and cleaned each day by the nurse.\""}]'::jsonb, '["c"]', 'The inner cannula is a removable tube inside the outer cannula that can be removed and cleaned or replaced without disturbing the outer cannula. The outer cannula keeps the stoma patent and should not be removed without a physician order except in an emergency.'),
  ('trach', 9, 'The charge nurse observes a newly hired nurse performing routine tracheostomy care for a stable client. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Removing the inner cannula to clean it with normal saline"}, {"id": "b", "text": "Removing the outer cannula to clean it during routine care"}, {"id": "c", "text": "Keeping the obturator and spare tubes at the bedside"}, {"id": "d", "text": "Suctioning the tracheostomy before beginning the care"}]'::jsonb, '["b"]', 'The outer cannula keeps the stoma patent and should not be removed without a physician order except in an emergency. Removing the inner cannula for cleaning, keeping the obturator at bedside, and suctioning before care are all correct actions.'),
  ('trach', 10, 'Immediately after a tracheostomy tube is placed at the bedside, the nurse notices the obturator is still inside the tube. Which action is appropriate?', '[{"id": "a", "text": "Leave the obturator in until the stoma matures at 72 hours"}, {"id": "b", "text": "Leave the obturator in to stabilize the tube during transport"}, {"id": "c", "text": "Leave the obturator in until the first tracheostomy care"}, {"id": "d", "text": "Remove the obturator at once because it blocks the airway"}]'::jsonb, '["d"]', 'The obturator is a rounded guide used for insertion only and must be removed immediately after insertion because it blocks the airway. Leaving it in place for any period obstructs breathing.'),
  ('trach', 11, 'The nurse is preparing the room for a client returning from tracheostomy placement. Which emergency equipment must be kept at the bedside at all times?', '[{"id": "a", "text": "The obturator, a same-size spare tube, and a tube one size smaller"}, {"id": "b", "text": "The obturator only, with spare tubes stored in the supply room"}, {"id": "c", "text": "A spare tube one size larger and a pair of suture scissors"}, {"id": "d", "text": "A same-size spare tube, with the obturator stored in central supply"}]'::jsonb, '["a"]', 'The obturator and a spare tracheostomy tube of the same size plus one size smaller must be at the bedside at all times for emergency reinsertion after accidental decannulation. Storing any of these items away from the bedside delays emergency reinsertion.'),
  ('trach', 12, 'A client had a tracheostomy placed 36 hours ago. Which technique should the nurse use when providing tracheostomy care?', '[{"id": "a", "text": "Clean technique, because the stoma is already established"}, {"id": "b", "text": "Clean technique, because sterile technique is only for home care"}, {"id": "c", "text": "Sterile technique, because the new stoma is a fresh wound"}, {"id": "d", "text": "Sterile technique only for cleaning the inner cannula"}]'::jsonb, '["c"]', 'Sterile technique is required for new tracheostomy care within the first 72 hours because the stoma is a fresh wound with high infection risk. Clean technique is acceptable only for established tracheostomies at home.'),
  ('trach', 13, 'The nurse is teaching the caregiver of a client who has had a tracheostomy for two years and will receive care at home. Which caregiver statement indicates understanding of the technique to use?', '[{"id": "a", "text": "\"I must use sterile technique at home because the stoma is a fresh wound.\""}, {"id": "b", "text": "\"Clean technique is acceptable at home because the stoma is established.\""}, {"id": "c", "text": "\"Sterile technique is only needed at home during the first year.\""}, {"id": "d", "text": "\"Clean technique is acceptable at home within the first 72 hours.\""}]'::jsonb, '["b"]', 'Clean technique is acceptable for established tracheostomy care at home because the stoma is chronic with lower infection risk. Sterile technique is required for new tracheostomies within the first 72 hours.'),
  ('trach', 14, 'The nurse is about to perform routine tracheostomy care and hears gurgling secretions in the client''s tube. Which action should the nurse perform first?', '[{"id": "a", "text": "Suction the tracheostomy to clear secretions"}, {"id": "b", "text": "Remove the inner cannula and clean it"}, {"id": "c", "text": "Clean the stoma site with saline gauze"}, {"id": "d", "text": "Change the tracheostomy ties"}]'::jsonb, '["a"]', 'Secretions are cleared first by suctioning the tracheostomy before care, not after. Removing the inner cannula, cleaning the stoma, and changing ties follow suctioning.'),
  ('trach', 15, 'The nurse is cleaning the stoma site of a client with a tracheostomy. Which technique is correct?', '[{"id": "a", "text": "Use dry gauze in a circular motion toward the stoma"}, {"id": "b", "text": "Use saline-soaked gauze in a motion toward the stoma"}, {"id": "c", "text": "Use saline-soaked gauze and leave the site moist"}, {"id": "d", "text": "Use saline-soaked gauze in a circular motion away from the stoma"}]'::jsonb, '["d"]', 'The stoma is cleaned with NS-soaked gauze in a circular motion away from the stoma, and the site is then dried well. Wiping toward the stoma or leaving the site moist is incorrect.'),
  ('trach', 16, 'The nurse is changing the tracheostomy ties for a client. Which approach is correct?', '[{"id": "a", "text": "Remove both old ties, then quickly secure the new ones"}, {"id": "b", "text": "Remove the old ties after the dressing change, then apply new ones"}, {"id": "c", "text": "Secure the new ties before removing the old ones"}, {"id": "d", "text": "Leave the tube unsecured briefly while cleaning under the ties"}]'::jsonb, '["c"]', 'New ties are secured before the old ties are removed, one side at a time, so the tracheostomy is never left unsecured. Removing old ties first leaves the tube unsecured.'),
  ('trach', 17, 'After securing new tracheostomy ties, the nurse checks their tightness. Which finding indicates the ties are correctly secured?', '[{"id": "a", "text": "No space remains between the ties and the neck"}, {"id": "b", "text": "One finger fits between the ties and the neck"}, {"id": "c", "text": "Three fingers fit between the ties and the neck"}, {"id": "d", "text": "A full hand fits between the ties and the neck"}]'::jsonb, '["b"]', 'Trach ties should allow one finger-width of space between the tie and the neck. No space is too tight, and more than a finger-width is too loose.'),
  ('trach', 18, 'The nurse is planning routine tracheostomy care for a hospitalized client. Which sequence of steps is correct?', '[{"id": "a", "text": "Remove inner cannula, clean stoma, change ties, then suction"}, {"id": "b", "text": "Clean stoma, suction, change ties, then remove inner cannula"}, {"id": "c", "text": "Change ties, clean stoma, suction, then remove inner cannula"}, {"id": "d", "text": "Suction, remove inner cannula, clean stoma, then change ties"}]'::jsonb, '["d"]', 'Routine care begins with suctioning to clear secretions, followed by removing and cleaning the inner cannula, cleaning the stoma site, and changing the ties. Suctioning after care reverses the required order.'),
  ('trach', 19, 'During tracheostomy care, the nurse removes a reusable inner cannula. How should the nurse clean it?', '[{"id": "a", "text": "Clean it with normal saline and a brush, then rinse thoroughly"}, {"id": "b", "text": "Wipe only the outside with dry gauze, then reinsert it"}, {"id": "c", "text": "Leave it out until the next shift so it can air dry"}, {"id": "d", "text": "Clean the outer cannula in place instead of the inner one"}]'::jsonb, '["a"]', 'The inner cannula is removed and cleaned with NS and a brush and rinsed thoroughly, or a disposable cannula is replaced. The outer cannula should not be disturbed during routine care.'),
  ('trach', 20, 'A client with a tracheostomy has thick secretions. The nurse ensures that humidification is in place. What is the primary purpose of this action?', '[{"id": "a", "text": "To keep the cuff pressure below 20 mmHg"}, {"id": "b", "text": "To allow the client to speak with the tube"}, {"id": "c", "text": "To prevent thick secretions and mucus plugs"}, {"id": "d", "text": "To keep the stoma site dry between dressings"}]'::jsonb, '["c"]', 'Humidification prevents secretion thickening and mucus plugs. It does not regulate cuff pressure or allow speech.'),
  ('trach', 21, 'The nurse assesses a client with a tracheostomy. Which finding indicates that the client needs suctioning?', '[{"id": "a", "text": "Clear breath sounds with SpO2 at the client''s baseline"}, {"id": "b", "text": "Audible gurgling with respiratory rate rising from 18 to 28"}, {"id": "c", "text": "Effective coughing that clears secretions independently"}, {"id": "d", "text": "Heart rate of 76/min while resting comfortably in bed"}]'::jsonb, '["b"]', 'Signs that suctioning is needed include audible crackles, gurgling, or secretion sounds and an increased respiratory rate or labored breathing. A client who clears secretions by coughing does not show a need for suctioning.'),
  ('trach', 22, 'The nurse is preparing to suction a client''s tracheostomy. Which action should the nurse take before inserting the catheter?', '[{"id": "a", "text": "Apply continuous suction to the catheter for 15 seconds"}, {"id": "b", "text": "Set the suction to continuous before advancing the catheter"}, {"id": "c", "text": "Remove the oxygen source so the catheter passes easily"}, {"id": "d", "text": "Give 100% oxygen for 30–60 seconds"}]'::jsonb, '["d"]', 'The client is hyperoxygenated with 100% O2 for 30–60 seconds before suctioning. Suction is not applied during catheter insertion.'),
  ('trach', 23, 'The nurse is inserting a sterile suction catheter into a client''s tracheostomy. Which technique is correct?', '[{"id": "a", "text": "Advance the catheter with suction off"}, {"id": "b", "text": "Advance the catheter with continuous suction on"}, {"id": "c", "text": "Advance the catheter with intermittent suction on"}, {"id": "d", "text": "Advance the catheter with suction on until secretions appear"}]'::jsonb, '["a"]', 'The catheter is inserted without suction active, and suction is applied only while withdrawing. Applying suction during insertion in any form is incorrect.'),
  ('trach', 24, 'While suctioning a tracheostomy, how far should the nurse advance the catheter?', '[{"id": "a", "text": "Past the point of resistance by about 1 cm"}, {"id": "b", "text": "Only 1 cm beyond the tip of the tracheostomy tube"}, {"id": "c", "text": "Until resistance is felt, then withdraw 1 cm"}, {"id": "d", "text": "Firmly through any resistance until secretions return"}]'::jsonb, '["c"]', 'The catheter is advanced gently until resistance is felt and then withdrawn 1 cm before suction is applied. Pushing past or through resistance is incorrect.'),
  ('trach', 25, 'The charge nurse observes a nurse suctioning a client''s tracheostomy. Which action by the nurse requires correction?', '[{"id": "a", "text": "Giving 100% oxygen for 45 seconds before suctioning"}, {"id": "b", "text": "Applying suction for 15 seconds during each pass"}, {"id": "c", "text": "Resting 45 seconds between suction passes"}, {"id": "d", "text": "Rotating the catheter while withdrawing it"}]'::jsonb, '["b"]', 'Each suction pass is limited to less than 10 seconds to prevent hypoxia, so a 15-second pass requires correction. Hyperoxygenating for 30–60 seconds, resting 30–60 seconds between passes, and rotating during withdrawal are correct.'),
  ('trach', 26, 'A client still has secretions after the first suction pass. How long should the nurse wait before performing a second pass?', '[{"id": "a", "text": "No wait; begin the second pass immediately"}, {"id": "b", "text": "Wait about 5 seconds"}, {"id": "c", "text": "Wait about 15 seconds"}, {"id": "d", "text": "Wait 30–60 seconds to reoxygenate"}]'::jsonb, '["d"]', 'The nurse rests 30–60 seconds between passes to reoxygenate the client. Shorter or no rest periods do not allow reoxygenation.'),
  ('trach', 27, 'The nurse has completed three suction passes on a client''s tracheostomy, and some secretions remain. Which action is appropriate?', '[{"id": "a", "text": "End this suctioning episode and reoxygenate the client"}, {"id": "b", "text": "Perform a fourth pass right away to clear remaining secretions"}, {"id": "c", "text": "Continue passes until the catheter returns completely clear"}, {"id": "d", "text": "Extend the next pass to 20 seconds to remove more secretions"}]'::jsonb, '["a"]', 'A maximum of 3 passes is performed per suctioning episode, followed by reoxygenation and monitoring of SpO2 recovery. Additional or longer passes exceed the limits that prevent hypoxia.'),
  ('trach', 28, 'After advancing the suction catheter to the correct depth, how should the nurse withdraw it?', '[{"id": "a", "text": "Withdraw it without suction, then reinsert with suction"}, {"id": "b", "text": "Hold it still at the deepest point with suction on"}, {"id": "c", "text": "Apply suction while rotating the catheter during withdrawal"}, {"id": "d", "text": "Apply suction only after the catheter has fully exited"}]'::jsonb, '["c"]', 'Suction is applied while withdrawing, and the catheter is rotated as it is pulled out. Holding the catheter still with suction on or suctioning only after removal is incorrect.'),
  ('trach', 29, 'During tracheostomy suctioning, a client''s heart rate drops suddenly from 92/min to 48/min and the client reports feeling faint. Which action should the nurse take?', '[{"id": "a", "text": "Complete the full pass, then reassess the heart rate"}, {"id": "b", "text": "Stop suctioning because of a vagal response"}, {"id": "c", "text": "Perform a second pass quickly to finish clearing secretions"}, {"id": "d", "text": "Continue suctioning because this is an expected finding"}]'::jsonb, '["b"]', 'Suctioning can stimulate the vagus nerve, causing sudden bradycardia, hypotension, or syncope; the nurse monitors heart rate and stops if it drops significantly. Continuing or repeating passes worsens the response.'),
  ('trach', 30, 'The nurse has finished suctioning a client''s tracheostomy for gurgling and a low SpO2. Which finding best indicates that suctioning was effective?', '[{"id": "a", "text": "Respiratory rate rises and the breathing becomes labored"}, {"id": "b", "text": "Heart rate drops suddenly and the client feels faint"}, {"id": "c", "text": "SpO2 falls further and secretions remain visible in the tube"}, {"id": "d", "text": "SpO2 recovers and gurgling sounds are no longer heard"}]'::jsonb, '["d"]', 'After suctioning, the client is reoxygenated and SpO2 recovery is monitored; resolution of gurgling secretion sounds shows secretions were cleared. A sudden heart rate drop indicates a vagal response, not effectiveness.'),
  ('trach', 31, 'The nurse measures the cuff pressure of a client''s tracheostomy tube at 32 mmHg. How should the nurse interpret this finding?', '[{"id": "a", "text": "The pressure is within the recommended range"}, {"id": "b", "text": "The pressure is too low and will cause an air leak"}, {"id": "c", "text": "The pressure is too high and risks tracheal mucosal ischemia"}, {"id": "d", "text": "The pressure is ideal for preventing aspiration and should stay"}]'::jsonb, '["c"]', 'Tracheostomy cuff pressure should be below 20 mmHg; over-inflation leads to tracheal mucosal ischemia and then stenosis or necrosis. A pressure of 32 mmHg exceeds this limit.'),
  ('trach', 32, 'A client has had a cuffed tracheostomy tube for several weeks. Which nursing action helps prevent tracheomalacia?', '[{"id": "a", "text": "Keeping cuff pressure below 20 mmHg and weaning the cuff when possible"}, {"id": "b", "text": "Keeping the cuff at the highest pressure the client can tolerate"}, {"id": "c", "text": "Increasing cuff pressure whenever secretions increase in the tube"}, {"id": "d", "text": "Keeping the cuff fully inflated at all times without weaning"}]'::jsonb, '["a"]', 'Tracheomalacia is airway collapse from prolonged cuff pressure, so cuff pressure is maintained below 20 mmHg and the cuff is weaned when possible. Higher or continuous cuff pressure increases the risk.'),
  ('trach', 33, 'A client with a cuffed tracheostomy tube has a new order for a Passy-Muir speaking valve. Which action must the nurse take before applying the valve?', '[{"id": "a", "text": "Inflate the cuff to just under 20 mmHg"}, {"id": "b", "text": "Deflate the cuff completely"}, {"id": "c", "text": "Deflate the cuff halfway"}, {"id": "d", "text": "Insert the obturator into the tube"}]'::jsonb, '["b"]', 'The cuff must be completely deflated before applying a PMV; if the cuff is inflated, the client cannot exhale and develops respiratory distress. Partial deflation does not meet this requirement.'),
  ('trach', 34, 'Minutes after a Passy-Muir valve is placed on a client''s tracheostomy hub, the client develops respiratory distress. Which finding most likely explains the distress?', '[{"id": "a", "text": "The client has a fenestrated outer cannula"}, {"id": "b", "text": "Speech therapy evaluated the client earlier"}, {"id": "c", "text": "The ties allow one finger-width of slack"}, {"id": "d", "text": "The tracheostomy cuff is still inflated"}]'::jsonb, '["d"]', 'If the cuff is inflated when a PMV is applied, the client cannot exhale, causing respiratory distress. A fenestrated tube actually supports PMV use by allowing air to pass.'),
  ('trach', 35, 'The nurse is teaching a client about a newly prescribed Passy-Muir valve. Which explanation of how the valve works is accurate?', '[{"id": "a", "text": "\"Air flows in through the trach and out through your mouth and nose.\""}, {"id": "b", "text": "\"Air flows in through your mouth and out through the valve on the trach.\""}, {"id": "c", "text": "\"Air flows both in and out through the valve on the trach.\""}, {"id": "d", "text": "\"Air flow stops at the valve so your vocal cords can vibrate.\""}]'::jsonb, '["a"]', 'The PMV is a one-way valve on the trach hub: air flows in through the trach and out through the mouth and nose, allowing speech. Reversing the airflow or blocking it does not describe the valve.'),
  ('trach', 36, 'A client is being evaluated for a Passy-Muir valve trial. Which tube characteristic is required for the valve to be used?', '[{"id": "a", "text": "A cuff inflated to seal the airway below the stoma"}, {"id": "b", "text": "A non-fenestrated tube with the cuff kept inflated"}, {"id": "c", "text": "A fenestrated tube or adequate space around the tube"}, {"id": "d", "text": "An obturator kept in the tube to direct the airflow"}]'::jsonb, '["c"]', 'PMV use requires a fenestrated tube or adequate space around the tube for air to pass, with the cuff completely deflated. An inflated cuff prevents exhalation.'),
  ('trach', 37, 'A client''s tracheostomy tube becomes dislodged 24 hours after placement. Which action should the nurse take?', '[{"id": "a", "text": "Cover the stoma with sterile gauze and ventilate with a BVM at the nose and mouth"}, {"id": "b", "text": "Reinsert the tube right away using the obturator and the same-size spare tube"}, {"id": "c", "text": "Insert the spare tube that is one size smaller into the stoma right away"}, {"id": "d", "text": "Hold the dislodged tube against the stoma until the physician arrives"}]'::jsonb, '["a"]', 'Within 72 hours the stoma is not mature and the track may close quickly, so the nurse does not attempt reinsertion without the physician; the stoma is covered with sterile gauze, a BVM is used at the nose and mouth, and Rapid Response is called. Reinsertion with the obturator is for a mature stoma after 72 hours.'),
  ('trach', 38, 'A client whose tracheostomy was placed 10 days ago coughs forcefully, and the tube comes out completely. Which action should the nurse take first?', '[{"id": "a", "text": "Cover the stoma and wait for the physician to reinsert the tube"}, {"id": "b", "text": "Attempt reinsertion with the obturator and the spare tube"}, {"id": "c", "text": "Apply a dry dressing and document the event in the chart"}, {"id": "d", "text": "Reinsert the original tube without using the obturator"}]'::jsonb, '["b"]', 'After 72 hours the stoma is mature and stable, so the nurse attempts reinsertion using the obturator with the spare tube. Waiting for the physician without attempting reinsertion is the approach for a stoma less than 72 hours old.'),
  ('trach', 39, 'The nurse is reinserting a tracheostomy tube for a client whose tube dislodged on postoperative day 9 and meets resistance. Which action should the nurse take?', '[{"id": "a", "text": "Apply firm, steady pressure to advance the tube"}, {"id": "b", "text": "Remove the obturator and push the tube in harder"}, {"id": "c", "text": "Twist the tube forcefully until it passes the resistance"}, {"id": "d", "text": "Stop, cover the stoma, use a BVM, and call Rapid Response"}]'::jsonb, '["d"]', 'A tube is never forced if resistance is felt; if it cannot be reinserted, the nurse covers the stoma, uses a BVM, and calls Rapid Response. Any forceful advancement is unsafe.'),
  ('trach', 40, 'A client with a tracheostomy suddenly cannot breathe or be ventilated, SpO2 is dropping rapidly, and the nurse suspects a mucus plug. Which action should the nurse take first?', '[{"id": "a", "text": "Change the entire tracheostomy tube"}, {"id": "b", "text": "Deflate the cuff and apply a speaking valve"}, {"id": "c", "text": "Remove the inner cannula"}, {"id": "d", "text": "Increase the oxygen flow and reassess in 15 minutes"}]'::jsonb, '["c"]', 'For a suspected trach obstruction, the nurse first removes the inner cannula, then attempts to suction; the entire tube is changed only if it remains obstructed. Changing the whole tube first skips the initial steps.'),
  ('trach', 41, 'A client with a suspected mucus plug remains unable to be ventilated after the nurse removes the inner cannula and attempts to suction. Which action should the nurse take next?', '[{"id": "a", "text": "Reinsert the inner cannula and repeat suctioning every 15 minutes"}, {"id": "b", "text": "Change the entire tracheostomy tube and call Rapid Response"}, {"id": "c", "text": "Inflate the cuff above 20 mmHg to improve ventilation"}, {"id": "d", "text": "Apply a speaking valve to redirect air through the mouth"}]'::jsonb, '["b"]', 'If the airway remains obstructed after removing the inner cannula and suctioning, the entire tracheostomy tube is changed and Rapid Response is called. Repeating suctioning later delays relief of the obstruction.'),
  ('trach', 42, 'A client with a tracheostomy has redness and warmth around the stoma, purulent drainage on the dressing, and a fever. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Obtaining a culture of the stoma drainage"}, {"id": "b", "text": "Inflating the cuff above 20 mmHg"}, {"id": "c", "text": "Removing the outer cannula for cleaning"}, {"id": "d", "text": "Applying a speaking valve to the tube"}]'::jsonb, '["a"]', 'Redness, warmth, purulent drainage, and fever indicate stoma infection, which is managed with culture, antibiotics, and wound care. The outer cannula should not be removed without a physician order except in an emergency.'),
  ('trach', 43, 'Several hours after tracheostomy placement, the nurse notes a large amount of bright red blood around the stoma. Which action should the nurse take?', '[{"id": "a", "text": "Document it as an expected finding after surgery"}, {"id": "b", "text": "Remove the outer cannula to look for the source"}, {"id": "c", "text": "Reassess the site at the next scheduled care time"}, {"id": "d", "text": "Notify the provider and apply pressure to the site"}]'::jsonb, '["d"]', 'A small amount of bleeding is normal initially, but large or bright red bleeding is abnormal and requires notifying the provider, applying pressure, and checking clotting. Treating it as expected delays care.'),
  ('trach', 44, 'The nurse palpates the neck of a client with a new tracheostomy and finds puffy skin that crackles under the fingertips. How should the nurse interpret this finding?', '[{"id": "a", "text": "Infection of the stoma site"}, {"id": "b", "text": "Tracheal stenosis from the tube"}, {"id": "c", "text": "Air under the skin (subcutaneous emphysema)"}, {"id": "d", "text": "Expected minor bleeding after placement"}]'::jsonb, '["c"]', 'Puffy, crackling skin around the neck or chest indicates subcutaneous emphysema, which is air under the skin; the nurse notifies the provider and monitors the airway. Infection presents with redness, warmth, purulent drainage, and fever.'),
  ('trach', 45, 'A client whose tracheostomy was removed several weeks ago reports increasing shortness of breath, and the nurse hears stridor that has worsened over time. Which complication does the nurse suspect?', '[{"id": "a", "text": "Stoma site infection"}, {"id": "b", "text": "Tracheal stenosis"}, {"id": "c", "text": "Subcutaneous emphysema"}, {"id": "d", "text": "Abnormal bleeding"}]'::jsonb, '["b"]', 'Progressive stridor and dyspnea after decannulation or over time indicate tracheal stenosis, a late complication that requires an ENT consult. Subcutaneous emphysema presents as puffy, crackling skin.'),
  ('trach', 46, 'A client with a tracheostomy develops coughing, a fever, and a drop in SpO2 after tube feedings. Which nursing action is appropriate?', '[{"id": "a", "text": "Lay the client flat after each feeding"}, {"id": "b", "text": "Inflate the cuff to above 20 mmHg"}, {"id": "c", "text": "Increase the rate of the tube feeding"}, {"id": "d", "text": "Elevate the head of the bed"}]'::jsonb, '["d"]', 'Coughing, fever, and decreased SpO2 after feeds suggest aspiration, which is managed by evaluating swallow, elevating the HOB, and deflating the cuff properly. Over-inflating the cuff risks tracheal injury.'),
  ('trach', 47, 'The nurse is teaching a client who will go home with a tracheostomy. Which client statement indicates understanding of how to keep secretions manageable?', '[{"id": "a", "text": "\"I will drink plenty of fluids to keep my secretions thin.\""}, {"id": "b", "text": "\"I will limit my fluids so I make less mucus each day.\""}, {"id": "c", "text": "\"I will turn off my humidifier so mucus does not build up.\""}, {"id": "d", "text": "\"I will only drink fluids when my secretions look thick.\""}]'::jsonb, '["a"]', 'Clients are taught to drink plenty of fluids to keep secretions thin and to use a humidifier at home to prevent mucus thickening. Limiting fluids or stopping humidification would thicken secretions.'),
  ('trach', 48, 'The nurse is reviewing home care with a client who has a permanent tracheostomy. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will use a shower shield when I bathe.\""}, {"id": "b", "text": "\"I will use a humidifier in my home.\""}, {"id": "c", "text": "\"I can swim if I keep my head above water.\""}, {"id": "d", "text": "\"I will cover my stoma with loose fabric.\""}]'::jsonb, '["c"]', 'Clients must never submerge in water or swim, and they should avoid direct water into the stoma by using a shower shield. Using a humidifier and covering the stoma with loose breathable fabric are correct.'),
  ('trach', 49, 'The nurse is preparing the caregiver of a client with a tracheostomy for discharge. Which caregiver statement indicates understanding of emergency preparedness?', '[{"id": "a", "text": "\"If the tube comes out, I will wait for the home nurse''s next visit.\""}, {"id": "b", "text": "\"Only the doctor can reinsert the tube, so I do not need training.\""}, {"id": "c", "text": "\"I will keep the spare tube in the car in case we need it.\""}, {"id": "d", "text": "\"I need to know how to reinsert the tube and when to call 911.\""}]'::jsonb, '["d"]', 'Caregivers must receive emergency replacement training and know how to reinsert the tube and when to call 911. Waiting for a later visit or declining training leaves the client without emergency airway support.'),
  ('trach', 50, 'A client with a permanent tracheostomy asks how to protect the stoma when going out in public. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Leave the stoma uncovered so air can flow freely.\""}, {"id": "b", "text": "\"Cover the stoma with loose, breathable fabric.\""}, {"id": "c", "text": "\"Cover the stoma with an airtight plastic dressing.\""}, {"id": "d", "text": "\"Wear a tight collar that presses over the stoma.\""}]'::jsonb, '["b"]', 'Clients are taught to cover the stoma with loose breathable fabric in public and avoid dust and pollen near the stoma. An airtight or tight covering would block the airway.'),
  ('tb', 1, 'A client with suspected active tuberculosis is being admitted. Which room assignment is most appropriate?', '[{"id": "a", "text": "A negative-pressure isolation room with the door closed"}, {"id": "b", "text": "A private room with the door left open for observation"}, {"id": "c", "text": "A semi-private room with the privacy curtain drawn"}, {"id": "d", "text": "A standard room shared with another client with TB"}]'::jsonb, '["a"]', 'TB requires airborne precautions, including a negative-pressure isolation room whose door must remain closed at all times. An open door or a semi-private room does not meet airborne precaution requirements.'),
  ('tb', 2, 'The nurse is preparing to enter the room of a client with active pulmonary tuberculosis. Which personal protective equipment is required?', '[{"id": "a", "text": "A surgical mask"}, {"id": "b", "text": "An N95 respirator"}, {"id": "c", "text": "Gloves only"}, {"id": "d", "text": "A face shield only"}]'::jsonb, '["b"]', 'An N95 respirator is required for all healthcare workers entering the room of a client with TB. A surgical mask is worn by the patient when leaving the room, not by staff entering.'),
  ('tb', 3, 'A client with a cough lasting 4 weeks, night sweats, and weight loss arrives on the medical unit with suspected active TB. What is the nurse''s first action?', '[{"id": "a", "text": "Collect a sputum specimen for culture"}, {"id": "b", "text": "Administer the first doses of RIPE therapy"}, {"id": "c", "text": "Initiate airborne precautions"}, {"id": "d", "text": "Teach the client about medication adherence"}]'::jsonb, '["c"]', 'For active TB, initiating airborne precautions with an N95 and a negative-pressure room is the first action. Sputum collection and starting RIPE follow in the priority order.'),
  ('tb', 4, 'A client with suspected active TB has been placed in airborne isolation. The provider prescribes sputum cultures and the RIPE regimen. Which action should the nurse take next?', '[{"id": "a", "text": "Give the RIPE doses, then collect the sputum"}, {"id": "b", "text": "Start RIPE and collect sputum in 1 week"}, {"id": "c", "text": "Hold both until the chest X-ray is read"}, {"id": "d", "text": "Collect the sputum, then give the RIPE doses"}]'::jsonb, '["d"]', 'Sputum culture must be collected before starting antibiotics, then the RIPE regimen is started as ordered. Giving RIPE first reverses the required order.'),
  ('tb', 5, 'A client with active TB in airborne isolation must be transported to radiology. Which action should the nurse take?', '[{"id": "a", "text": "Place a surgical mask on the client"}, {"id": "b", "text": "Have the client wear an N95 respirator"}, {"id": "c", "text": "Transport the client without a mask"}, {"id": "d", "text": "Cancel all tests until cultures are negative"}]'::jsonb, '["a"]', 'The patient wears a surgical mask when leaving the room. The N95 respirator is required for healthcare workers entering the room.'),
  ('tb', 6, 'A nursing student is preparing to care for a client with active TB. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"The door to the client''s room must stay closed.\""}, {"id": "b", "text": "\"TB spreads by large droplets, so a surgical mask is enough.\""}, {"id": "c", "text": "\"The client wears a surgical mask when leaving the room.\""}, {"id": "d", "text": "\"I will teach the client proper cough etiquette.\""}]'::jsonb, '["b"]', 'TB is transmitted by airborne droplet nuclei, not large droplets, and staff must wear an N95 respirator. The other statements reflect correct airborne precautions and teaching.'),
  ('tb', 7, 'The charge nurse is making room assignments. Which client requires airborne precautions?', '[{"id": "a", "text": "A client with influenza"}, {"id": "b", "text": "A client with meningitis"}, {"id": "c", "text": "A client with active pulmonary TB"}, {"id": "d", "text": "A client with latent TB infection"}]'::jsonb, '["c"]', 'Active TB requires airborne precautions with an N95 mask and a negative-pressure room. Influenza and meningitis use droplet precautions, and latent TB is not contagious.'),
  ('tb', 8, 'A client has a positive IGRA, a normal chest X-ray, no symptoms, and a negative sputum culture. The client asks whether family members can catch TB. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"You are contagious and need airborne isolation.\""}, {"id": "b", "text": "\"You have active TB and need treatment today.\""}, {"id": "c", "text": "\"You must avoid all contact until cultures turn positive.\""}, {"id": "d", "text": "\"You have latent TB, which is not contagious.\""}]'::jsonb, '["d"]', 'Latent TB has no symptoms, a normal chest X-ray, and a negative sputum culture, and it is not contagious. Active TB is contagious, symptomatic, and has an abnormal X-ray and positive culture.'),
  ('tb', 9, 'A client is diagnosed with latent TB infection. Which treatment plan does the nurse anticipate?', '[{"id": "a", "text": "Isoniazid for 6 to 9 months"}, {"id": "b", "text": "RIPE therapy for 6 to 12 months"}, {"id": "c", "text": "No treatment unless symptoms appear"}, {"id": "d", "text": "Isoniazid for 2 weeks only"}]'::jsonb, '["a"]', 'Latent TB is treated with INH for 6–9 months to prevent reactivation. RIPE for 6–12 months is the regimen for active TB.'),
  ('tb', 10, 'A client with a 2-month history of cough, night sweats, and weight loss has a chest X-ray. Which finding is consistent with active TB?', '[{"id": "a", "text": "A normal chest X-ray"}, {"id": "b", "text": "Upper lobe infiltrates and cavitations"}, {"id": "c", "text": "Clear lungs with no infiltrates"}, {"id": "d", "text": "Lower lobe changes with no cavities"}]'::jsonb, '["b"]', 'Active TB shows an abnormal chest X-ray with upper lobe infiltrates and cavitations. A normal chest X-ray is the finding in latent TB.'),
  ('tb', 11, 'A client asks why TB most often affects the top of the lungs. The nurse explains that the primary infection site is the lung apex because this area:', '[{"id": "a", "text": "Has the lowest oxygen level"}, {"id": "b", "text": "Has the most lymph nodes"}, {"id": "c", "text": "Has a high-oxygen environment"}, {"id": "d", "text": "Clears secretions the fastest"}]'::jsonb, '["c"]', 'Mycobacterium tuberculosis is an aerobic bacillus whose primary infection site is the lung apex, a high-O2 environment. A low-oxygen area would not favor this aerobic organism.'),
  ('tb', 12, 'A client being treated for pulmonary TB asks whether the infection can affect other parts of the body. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It stays confined to the lungs.\""}, {"id": "b", "text": "\"It can spread only to lymph nodes.\""}, {"id": "c", "text": "\"It affects only the upper airway.\""}, {"id": "d", "text": "\"It can reach the brain, spine, and kidneys.\""}]'::jsonb, '["d"]', 'TB can disseminate to the brain, spine, kidneys, joints, and lymph nodes. It is not confined to the lungs or limited to the lymph nodes alone.'),
  ('tb', 13, 'A community health nurse is assessing clients for TB risk. Which client has the greatest risk for TB?', '[{"id": "a", "text": "A 50-year-old in a homeless shelter who injects drugs"}, {"id": "b", "text": "A 30-year-old office worker with no medical history"}, {"id": "c", "text": "A 25-year-old athlete who lives alone in a house"}, {"id": "d", "text": "A 40-year-old with seasonal allergies and no travel"}]'::jsonb, '["a"]', 'Tight living quarters such as homeless shelters and substance abuse such as IV drug use are TB risk factors. The other clients have none of the listed risk factors.'),
  ('tb', 14, 'The nurse is reviewing clients for TB risk related to immune system compromise. Which client is in this risk category?', '[{"id": "a", "text": "A client who works in a bank office"}, {"id": "b", "text": "A client taking immunosuppressants after a transplant"}, {"id": "c", "text": "A client with a recently healed ankle fracture"}, {"id": "d", "text": "A client who exercises daily at a local gym"}]'::jsonb, '["b"]', 'Immune system compromise, including organ transplant and immunosuppressant use, increases TB risk. The other clients do not have a listed immune-related risk.'),
  ('tb', 15, 'A clinic nurse is planning TB screening. Which client should be screened with a PPD or IGRA annually?', '[{"id": "a", "text": "A healthy 30-year-old with no risk factors"}, {"id": "b", "text": "A 28-year-old who lives alone and works remotely"}, {"id": "c", "text": "A client with HIV who lives in a homeless shelter"}, {"id": "d", "text": "A 35-year-old with no exposures or travel history"}]'::jsonb, '["c"]', 'High-risk patients should be screened with PPD or IGRA annually, and HIV and homeless shelter living are TB risk factors. The other clients have no listed risk factors.'),
  ('tb', 16, 'The nurse is assessing a client with suspected active TB. Which group of findings does the nurse expect?', '[{"id": "a", "text": "Sudden high fever and rust-colored sputum"}, {"id": "b", "text": "Acute wet cough that began 2 days ago"}, {"id": "c", "text": "Weight gain and increased energy levels"}, {"id": "d", "text": "Cough over 3 weeks, night sweats, weight loss"}]'::jsonb, '["d"]', 'TB signs include an extended cough persisting more than 3 weeks, classic night sweats, and extreme weight loss. An acute cough of 2 days does not match the persistent TB cough.'),
  ('tb', 17, 'A client with active TB has the temperature checked each shift. Which fever pattern does the nurse expect?', '[{"id": "a", "text": "Low-grade fever with chills"}, {"id": "b", "text": "High fever above 104°F"}, {"id": "c", "text": "No temperature changes"}, {"id": "d", "text": "Fever only after meals"}]'::jsonb, '["a"]', 'TB causes a slight, low-grade fever with chills. A very high fever does not match the TB pattern.'),
  ('tb', 18, 'A client is being discharged on TB treatment. Which finding should the nurse instruct the client to report immediately?', '[{"id": "a", "text": "Orange-colored urine"}, {"id": "b", "text": "Coughing up blood"}, {"id": "c", "text": "Orange-tinged sweat"}, {"id": "d", "text": "Weight gain on the new diet"}]'::jsonb, '["b"]', 'Clients should report worsening cough, hemoptysis, fever, or weight loss immediately. Orange body fluids from rifampin are expected and not harmful.'),
  ('tb', 19, 'The nurse is preparing to administer a Mantoux (PPD) tuberculin skin test. Which technique is correct?', '[{"id": "a", "text": "1 mL injected subcutaneously"}, {"id": "b", "text": "0.1 mL injected intramuscularly"}, {"id": "c", "text": "0.1 mL injected intradermally"}, {"id": "d", "text": "0.5 mL injected intradermally"}]'::jsonb, '["c"]', 'The PPD/Mantoux test is an intradermal 0.1 mL injection read at 48–72 hours. Other routes and volumes do not match this technique.'),
  ('tb', 20, 'A client receives a PPD skin test on Monday morning. When should the nurse instruct the client to return to have the test read?', '[{"id": "a", "text": "Monday evening, after 12 hours"}, {"id": "b", "text": "Tuesday morning, after 24 hours"}, {"id": "c", "text": "The following Monday, after 1 week"}, {"id": "d", "text": "Wednesday or Thursday, at 48–72 hours"}]'::jsonb, '["d"]', 'The PPD is read at 48–72 hours. Reading at 12 or 24 hours is too early, and 1 week is too late.'),
  ('tb', 21, 'The nurse is reading a client''s PPD test at 60 hours and sees a large area of redness surrounding a smaller raised, hardened area. How should the nurse measure the result?', '[{"id": "a", "text": "Measure only the hardened area with a ruler"}, {"id": "b", "text": "Measure only the area of redness with a ruler"}, {"id": "c", "text": "Add the redness and the hardened area together"}, {"id": "d", "text": "Estimate the size of the redness by inspection"}]'::jsonb, '["a"]', 'The PPD is interpreted by measuring induration (hardness), not redness, using a ruler across the forearm. Measuring or including redness gives an inaccurate reading.'),
  ('tb', 22, 'A client who is HIV-positive has a PPD induration of 6 mm at 48 hours. How should the nurse interpret this result?', '[{"id": "a", "text": "Negative, because it is less than 10 mm"}, {"id": "b", "text": "Positive for this client''s risk group"}, {"id": "c", "text": "Negative, because it is less than 15 mm"}, {"id": "d", "text": "Inconclusive, so the test must be repeated"}]'::jsonb, '["b"]', 'For HIV-positive clients, an induration of 5 mm or more is positive, so 6 mm is positive. The 10 mm and 15 mm cutoffs apply to other risk groups.'),
  ('tb', 23, 'A healthy 32-year-old client with no known risk factors has a PPD induration of 12 mm. How should the nurse interpret this result?', '[{"id": "a", "text": "Positive, because it is at least 10 mm"}, {"id": "b", "text": "Positive, because it is at least 5 mm"}, {"id": "c", "text": "Negative, because it is below 15 mm"}, {"id": "d", "text": "Positive, and RIPE should begin now"}]'::jsonb, '["c"]', 'For healthy individuals with no known risk factors, a positive PPD requires an induration of 15 mm or more, so 12 mm is negative. The 10 mm and 5 mm cutoffs apply to higher-risk groups.'),
  ('tb', 24, 'A client who immigrated 2 years ago from a region with high TB rates has a PPD induration of 11 mm. How should the nurse interpret this result?', '[{"id": "a", "text": "Negative, because it is below 15 mm"}, {"id": "b", "text": "Negative, because the move was over 1 year ago"}, {"id": "c", "text": "Inconclusive, so the test must be repeated"}, {"id": "d", "text": "Positive for this client''s risk group"}]'::jsonb, '["d"]', 'Recent immigrants (within the past 5 years) have a positive PPD at 10 mm or more, so 11 mm is positive. The 15 mm cutoff applies only to healthy individuals with no risk factors.'),
  ('tb', 25, 'A client who injects drugs and has no other risk factors has a PPD induration of 8 mm. How should the nurse interpret this result?', '[{"id": "a", "text": "Negative, since this group requires 10 mm"}, {"id": "b", "text": "Positive, since this group requires 5 mm"}, {"id": "c", "text": "Positive, since any induration is positive"}, {"id": "d", "text": "Negative, since this group requires 15 mm"}]'::jsonb, '["a"]', 'IV drug users are in the 10 mm or greater group, so 8 mm is negative. The 5 mm cutoff applies to groups such as HIV-positive or immunosuppressed clients.'),
  ('tb', 26, 'The nurse is reviewing PPD results for four clients. Which client''s result should be interpreted as positive?', '[{"id": "a", "text": "A healthy client with no risk factors and 10 mm"}, {"id": "b", "text": "A kidney transplant recipient with 6 mm"}, {"id": "c", "text": "A client who injects drugs with 7 mm"}, {"id": "d", "text": "A recent immigrant with 9 mm"}]'::jsonb, '["b"]', 'Organ transplant recipients and immunosuppressed clients are positive at 5 mm or more, so 6 mm is positive. IV drug users and recent immigrants need 10 mm, and healthy clients need 15 mm.'),
  ('tb', 27, 'A client''s PPD is read as positive. The client asks, "Does this mean I have active TB?" Which response by the nurse is best?', '[{"id": "a", "text": "\"Yes, you will be placed in isolation now.\""}, {"id": "b", "text": "\"Yes, you will start RIPE therapy today.\""}, {"id": "c", "text": "\"Not necessarily; an X-ray and sputum test are next.\""}, {"id": "d", "text": "\"No, a positive test means you are immune.\""}]'::jsonb, '["c"]', 'A positive PPD does not mean active TB; follow-up with a chest X-ray and sputum culture is needed. Assuming active TB from the skin test alone is incorrect.'),
  ('tb', 28, 'A client who was born in another country received the BCG vaccine as a child and now needs TB screening. Which test does the nurse anticipate?', '[{"id": "a", "text": "A repeat PPD in 2 weeks"}, {"id": "b", "text": "A PPD read at 24 hours"}, {"id": "c", "text": "A PPD with a larger dose"}, {"id": "d", "text": "An IGRA blood test"}]'::jsonb, '["d"]', 'The BCG vaccine causes a false-positive PPD, so IGRA is used instead in vaccinated patients. Any form of PPD testing would still be affected by the prior BCG.'),
  ('tb', 29, 'A client asks about the QuantiFERON-TB Gold blood test that was ordered. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"It requires only a single visit.\""}, {"id": "b", "text": "\"You must return in 48–72 hours.\""}, {"id": "c", "text": "\"Your BCG vaccine will affect it.\""}, {"id": "d", "text": "\"It is less specific than a PPD.\""}]'::jsonb, '["a"]', 'The IGRA is a blood test requiring a single visit; it is not affected by BCG and is more specific than the PPD. Returning at 48–72 hours applies to reading a PPD.'),
  ('tb', 30, 'A client who has been taking high-dose immunosuppressant medications for months has a PPD induration of 0 mm. How should the nurse interpret this result?', '[{"id": "a", "text": "It rules out TB infection"}, {"id": "b", "text": "It may be a false-negative result"}, {"id": "c", "text": "It is a false positive from BCG"}, {"id": "d", "text": "It confirms the client has latent TB"}]'::jsonb, '["b"]', 'Immunosuppression is a cause of a false-negative PPD, so a negative result does not rule out TB in this client. BCG causes false-positive, not false-negative, results.'),
  ('tb', 31, 'A client had close contact with a person with active TB 3 weeks ago, and the client''s PPD is negative. The nurse understands that this result:', '[{"id": "a", "text": "Proves that no infection occurred"}, {"id": "b", "text": "Is a false positive caused by BCG"}, {"id": "c", "text": "May be false-negative in the window period"}, {"id": "d", "text": "Shows the client is immune to TB"}]'::jsonb, '["c"]', 'Recent TB infection within less than 8 weeks (the window period) can cause a false-negative PPD. A negative test during this period does not prove that no infection occurred.'),
  ('tb', 32, 'The provider needs the most definitive test to diagnose a client''s TB. Which test does the nurse anticipate?', '[{"id": "a", "text": "PPD skin test"}, {"id": "b", "text": "IGRA blood test"}, {"id": "c", "text": "Chest X-ray"}, {"id": "d", "text": "Sputum culture"}]'::jsonb, '["d"]', 'Sputum culture is the gold standard and most definitive diagnostic test for TB. A positive PPD does not mean active TB and requires follow-up testing.'),
  ('tb', 33, 'The nurse is teaching a client how to collect sputum specimens for TB culture. Which instruction is correct?', '[{"id": "a", "text": "Collect a morning sample on 3 consecutive days"}, {"id": "b", "text": "Collect a single sample at any convenient time"}, {"id": "c", "text": "Collect 3 samples during the same afternoon"}, {"id": "d", "text": "Collect 1 evening sample each week for 3 weeks"}]'::jsonb, '["a"]', 'Sputum culture requires 3 morning samples on 3 consecutive days. A single sample or same-day samples do not meet this requirement.'),
  ('tb', 34, 'A client''s acid-fast bacilli (AFB) sputum smear returns positive. Which interpretation by the nurse is correct?', '[{"id": "a", "text": "Drug susceptibility has now been confirmed"}, {"id": "b", "text": "The client is likely to be contagious"}, {"id": "c", "text": "The client most likely has latent TB"}, {"id": "d", "text": "The result is a false positive from BCG"}]'::jsonb, '["b"]', 'A positive AFB smear means the client is likely contagious. Species and drug susceptibility are confirmed by culture, not by the smear.'),
  ('tb', 35, 'A client with a positive AFB smear asks why a sputum culture is also needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The culture is quicker and cheaper than the smear.\""}, {"id": "b", "text": "\"The smear shows which drugs will work against TB.\""}, {"id": "c", "text": "\"The culture confirms the species and drug susceptibility.\""}, {"id": "d", "text": "\"The culture is needed only if the smear is negative.\""}]'::jsonb, '["c"]', 'Sputum culture confirms the species and drug susceptibility, though results take weeks. The AFB smear is the rapid, inexpensive test but does not determine drug susceptibility.'),
  ('tb', 36, 'The nurse is teaching a client who is starting rifampin. Which instruction should the nurse include?', '[{"id": "a", "text": "\"Stop the drug if your urine turns orange.\""}, {"id": "b", "text": "\"Orange urine means your liver is failing.\""}, {"id": "c", "text": "\"Drink less fluid to prevent orange urine.\""}, {"id": "d", "text": "\"Your body fluids may turn orange; it is harmless.\""}]'::jsonb, '["d"]', 'Rifampin turns body fluids orange, which is expected and not harmful, and the patient should be warned in advance. Stopping the drug for orange urine is not indicated.'),
  ('tb', 37, 'A client who takes oral contraceptives is starting rifampin for active TB. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Use condoms because rifampin weakens birth control.\""}, {"id": "b", "text": "\"Stop your birth control pills while on rifampin.\""}, {"id": "c", "text": "\"Rifampin makes your birth control pills stronger.\""}, {"id": "d", "text": "\"No change is needed in your birth control method.\""}]'::jsonb, '["a"]', 'Rifampin decreases birth control effectiveness, so the nurse should advise condom use. Assuming no change is needed ignores this interaction.'),
  ('tb', 38, 'A client with latent TB is starting isoniazid (INH). Which supplement does the nurse anticipate will be prescribed with it?', '[{"id": "a", "text": "Vitamin K (phytonadione)"}, {"id": "b", "text": "Vitamin B6 (pyridoxine)"}, {"id": "c", "text": "Vitamin C (ascorbic acid)"}, {"id": "d", "text": "Vitamin B12 (cobalamin)"}]'::jsonb, '["b"]', 'Vitamin B6 (pyridoxine) is always given with INH to prevent peripheral neuropathy. The other vitamins are not part of TB treatment.'),
  ('tb', 39, 'A client receiving RIPE therapy for 2 months reports numbness and tingling in both feet. Which medication is most likely responsible?', '[{"id": "a", "text": "Rifampin"}, {"id": "b", "text": "Ethambutol"}, {"id": "c", "text": "Isoniazid"}, {"id": "d", "text": "Pyrazinamide"}]'::jsonb, '["c"]', 'Isoniazid (INH) causes peripheral neuropathy, which is why vitamin B6 is given. Ethambutol causes optic neuritis, and pyrazinamide raises uric acid.'),
  ('tb', 40, 'A client taking ethambutol reports blurred vision and difficulty telling red from green. What is the nurse''s priority action?', '[{"id": "a", "text": "Reassure the client this is expected"}, {"id": "b", "text": "Recheck vision at the next monthly visit"}, {"id": "c", "text": "Give an extra dose of vitamin B6"}, {"id": "d", "text": "Notify the provider immediately"}]'::jsonb, '["d"]', 'Blurred vision or trouble distinguishing colors on ethambutol indicates optic neuritis, so the provider must be notified immediately and the drug stopped. Waiting for the next monthly check delays action.'),
  ('tb', 41, 'The nurse is planning monitoring for a client receiving ethambutol. Which assessment should be performed monthly?', '[{"id": "a", "text": "Visual acuity testing"}, {"id": "b", "text": "Audiometric testing"}, {"id": "c", "text": "Serum uric acid level"}, {"id": "d", "text": "Peripheral sensation check"}]'::jsonb, '["a"]', 'Ethambutol can cause optic neuritis, so monthly visual acuity checks are required. Audiometric testing is used for streptomycin ototoxicity.'),
  ('tb', 42, 'A client is receiving pyrazinamide as part of RIPE therapy. Which laboratory value specifically related to this drug should the nurse monitor?', '[{"id": "a", "text": "Serum glucose level"}, {"id": "b", "text": "Serum uric acid level"}, {"id": "c", "text": "Audiometric results"}, {"id": "d", "text": "Visual acuity scores"}]'::jsonb, '["b"]', 'Pyrazinamide increases uric acid and can cause gout, so uric acid levels are monitored along with LFTs. Visual acuity is monitored for ethambutol.'),
  ('tb', 43, 'A client with TB reports new ringing in the ears and some difficulty hearing. The nurse suspects an adverse effect of which medication?', '[{"id": "a", "text": "Rifampin"}, {"id": "b", "text": "Ethambutol"}, {"id": "c", "text": "Streptomycin"}, {"id": "d", "text": "Isoniazid"}]'::jsonb, '["c"]', 'Streptomycin causes ototoxicity with hearing loss and tinnitus, and audiometric testing is used to monitor it. Ethambutol affects vision rather than hearing.'),
  ('tb', 44, 'The nurse is reviewing discharge teaching with a client receiving RIPE therapy. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will avoid drinking alcohol during treatment.\""}, {"id": "b", "text": "\"I will wear a surgical mask in public for now.\""}, {"id": "c", "text": "\"I will eat high-protein, high-calorie meals.\""}, {"id": "d", "text": "\"I will take an herbal supplement for my liver.\""}]'::jsonb, '["d"]', 'Clients on TB therapy should avoid alcohol and hepatotoxic substances, including herbal supplements and excess acetaminophen. Avoiding alcohol, wearing a mask in public, and eating a high-protein, high-calorie diet are correct.'),
  ('tb', 45, 'A client is receiving isoniazid (INH) for latent TB. Which laboratory tests should the nurse monitor regularly throughout treatment?', '[{"id": "a", "text": "Liver function tests"}, {"id": "b", "text": "Serum uric acid levels"}, {"id": "c", "text": "Audiometric tests"}, {"id": "d", "text": "Visual acuity tests"}]'::jsonb, '["a"]', 'INH can cause hepatotoxicity, so liver function tests are monitored regularly throughout latent TB treatment. Uric acid is monitored for pyrazinamide.'),
  ('tb', 46, 'A client on TB therapy for 2 months says, "I feel much better, so I''m going to stop taking these pills." Which response by the nurse is best?', '[{"id": "a", "text": "\"That is fine once your cough has resolved.\""}, {"id": "b", "text": "\"Missed doses can lead to drug-resistant TB.\""}, {"id": "c", "text": "\"You may stop if your skin test is negative.\""}, {"id": "d", "text": "\"You may skip doses on days you feel well.\""}]'::jsonb, '["b"]', 'Strict medication adherence is the biggest education point because missed doses lead to MDR-TB (drug-resistant TB). Stopping when symptoms improve risks resistance.'),
  ('tb', 47, 'A client newly diagnosed with active TB asks how long RIPE therapy will last. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"About 10 days\""}, {"id": "b", "text": "\"About 6 weeks\""}, {"id": "c", "text": "\"6 to 12 months\""}, {"id": "d", "text": "\"2 to 3 years\""}]'::jsonb, '["c"]', 'RIPE therapy for active TB lasts 6–12 months total. A course of days or weeks is far too short.'),
  ('tb', 48, 'The nurse is evaluating four clients in airborne isolation for active TB, each of whom has taken effective anti-TB medications. Which client meets the criteria for discontinuing isolation?', '[{"id": "a", "text": "1 week of medication, 1 negative culture, improved symptoms"}, {"id": "b", "text": "4 weeks of medication, 3 negative cultures, worsening cough"}, {"id": "c", "text": "4 weeks of medication, 1 negative culture, improved symptoms"}, {"id": "d", "text": "4 weeks of medication, 3 negative cultures, improved symptoms"}]'::jsonb, '["d"]', 'All three criteria must be met: a course of effective anti-TB medications, 3 consecutive negative sputum cultures on separate days, and clinical improvement. A worsening cough or a single negative culture means the criteria are not yet met.'),
  ('tb', 49, 'A client with active TB has lost 15 lb (6.8 kg) over 2 months. Which diet should the nurse recommend?', '[{"id": "a", "text": "High-protein, high-calorie"}, {"id": "b", "text": "Low-calorie, high-fiber"}, {"id": "c", "text": "Low-protein, low-fat"}, {"id": "d", "text": "Clear liquids only"}]'::jsonb, '["a"]', 'A high-protein, high-calorie diet is recommended to combat the weight loss of TB. Low-calorie or restricted diets would worsen wasting.'),
  ('tb', 50, 'A client diagnosed with active TB lives with a spouse and two teenage children. Which action regarding the household contacts is appropriate?', '[{"id": "a", "text": "Screen only the contacts who have symptoms"}, {"id": "b", "text": "Screen all of them with a PPD or IGRA"}, {"id": "c", "text": "Start all of them on RIPE therapy now"}, {"id": "d", "text": "Screen them only if the client worsens"}]'::jsonb, '["b"]', 'All exposed household contacts should be screened with PPD or IGRA. Limiting screening to symptomatic contacts would miss latent infection, which has no symptoms.')
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale)
  JOIN _resp_seed_map m USING (source_key)
 CROSS JOIN _resp_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _resp_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Respiratory seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
